INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(1, 'Thi thử trắc nghiệm ôn tập Kỹ thuật an toàn lao động online - Đề #12', 'Toán', 35, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Toán. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1, 'Những yếu tố có hại nào dưới đây có nguy cơ gây bệnh nghề nghiệp trong lao động, sản xuất?', 'SINGLE_CHOICE', '{"A": "Các yếu tố vì khí hậu xấu; chiếu sáng không hợp lý; tiếng ồn và rung động; các loại bụi.", "B": "Bức xạ và phóng xạ; các hóa chất độc; vi sinh vật có hại; các yếu tố về cường ñộ lao động, tư thế lao động không hợp lý.", "C": "Những hóa chất độc; nổ vật lý; nổ hoá học; vật rơi, đổ, sập; những yếu tố vi khí hậu xấu; vi sinh vật có hại; chiếu sáng không hợp lý; tiếng ồn và rung động.", "D": "Cả a và b."}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(2, 'Phân xưởng chật chội và việc sắp xếp nơi làm việc lộn xộn, mất trật tự ngăn nắp là các tác hại liên quan đến:', 'SINGLE_CHOICE', '{"A": "Công nghệ sản xuất", "B": "Điều kiện vệ sinh và an toàn lao động", "C": "Tổ chức lao động", "D": "Cả a, b đều sai"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(3, 'Thiếu thiết bị thông gió, chống bụi, chống nóng, chống tiếng ồn, chống hơi khí độc là các tác hại liên quan đến:', 'SINGLE_CHOICE', '{"A": "Công nghệ sản xuất", "B": "Điều kiện vệ sinh và an toàn lao động", "C": "Chất lượng sản phẩm", "D": "Tổ chức lao động"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(4, 'Có bao nhiêu bệnh nghề nghiệp đã được nhà nước công nhận bảo hiểm:', 'SINGLE_CHOICE', '{"A": "21 bệnh", "B": "28 bệnh", "C": "32 bệnh", "D": "34 bệnh"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(5, 'Hãy nêu các biện pháp cơ bản nhằm khắc phục điều kiện vi khí hậu xấu trong lao động sản xuất:', 'SINGLE_CHOICE', '{"A": "Cơ giới hóa, tự động hóa; bố trí mặt bằng nhà xưởng, đường đi lại và vận chuyển...; sắp xếp nguyên vật liệu, bán thành phẩm và thành phẩm... hợp lý đảm bảo sự di chuyển dễ dàng của các loại máy móc, phương tiện.", "B": "Biện pháp giảm bức xạ, áp dụng thông gió và điều hòa không khí; làm lán để chống gió lạnh, che nắng, che mưa khi làm việc ngoài trời.", "C": "Áp dụng thông gió và điều hòa không khí; vệ sinh nơi làm việc, bảo đảm diện tích nơi làm việc, khoảng cách không gian cần thiết cho mỗi người lao động.", "D": "Áp dụng thông gió và điều hòa không khí; trang bị đầy đủ các phương tiện bảo vệ cá nhân; làm lán để chống lạnh, che nắng, che mưa khi làm việc ngoài trời."}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(6, 'Hãy nêu các biện pháp cơ bản để chống bụi trong lao động sản xuất:', 'SINGLE_CHOICE', '{"A": "Áp dụng các biện pháp cách ly, giảm thiểu tiếng ồn, rung động hoặc các biện pháp giảm tiếng ồn lan truyền, trồng cây xanh. Sử dụng đầy đủ các phương tiện bảo vệ cá nhân.", "B": "Áp dụng các biện pháp làm giảm phát sinh bụi từ nguồn gây bụi; phun nước (dạng sương) làm giảm lượng bụi trong không khí; dùng các thiết bị hút bụi; tăng cường vệ sinh công nghiệp. Sử dụng đầy đủ phương tiện bảo vệ cá nhân.", "C": "Áp dụng các biện pháp làm giảm nguồn gây bụi; phun nước làm giảm lượng bụi trong không khí; dùng các thiết bị hút bụi; tăng cường vệ sinh công nghiệp.", "D": "Phun nước làm giảm lượng bụi trong không khí; dùng các thiết bị hút bụi; tăng cường vệ sinh công nghiệp, đặc biệt là quan tâm đến các bụi dễ gây ra cháy nổ."}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(7, 'Hãy nêu các biện pháp cơ bản để chống ồn và rung trong lao động sản xuất:', 'SINGLE_CHOICE', '{"A": "Cơ giới hóa, tự động hóa; áp dụng thông gió và điều hòa không khí; trang bị đầy đủ các phương tiện bảo vệ cá nhân", "B": "Đảm bảo khoảng cách quy định từ nguồn ồn đến nơi người lao động làm việc, giảm ngay tiếng ồn từ nguồn gây ồn và sử dụng đầy đủ các phương tiện, bảo vệ cá nhân", "C": "Xử lý chất thải và nước thải; tổ chức thời giờ làm việc và nghỉ ngơi; áp dụng các biện pháp chăm sóc sức khỏe người lao động, bồi dưỡng, điều dưỡng...phục hồi sức khoẻ", "D": "Đảm bảo khoảng cách quy định từ nguồn ồn đến nơi người lao động làm việc, giảm ngay tiếng ồn từ nguồn gây ồn, áp dụng các biện pháp cách ly, triệt tiêu tiếng ồn, rung hoặc các biện pháp giảm tiếng ồn lan truyền, trồng cây xanh..."}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(8, 'Hãy nêu một số biện pháp tổ chức sản xuất, tổ chức lao động đảm bảo an toàn vệ sinh lao động, phòng chống bệnh nghề nghiệp:', 'SINGLE_CHOICE', '{"A": "Bố trí mặt bằng nhà xưởng, đường đi lại và vận chuyển...; sắp xếp nguyên vật liệu, bán thành phẩm và thành phẩm... hợp lý", "B": "Vệ sinh nơi làm việc, cần bảo đảm diện tích nơi làm việc, khoảng cách không gian cần thiết cho mỗi người lao động", "C": "Xử lý chất thải và nước thải; tổ chức thời giờ làm việc và nghỉ ngơi; chăm sóc sức khỏe người lao động, thực hiện chế độ bồi dưỡng, điều dưỡng", "D": "Cả a, b và c"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(9, 'Hãy nêu các yếu tố liên quan, chi phối nhiều đến tâm lý, sinh lý người lao động trong lao động sản xuất:', 'SINGLE_CHOICE', '{"A": "Tổ chức thời giờ làm việc và nghỉ ngơi; chăm sóc sức khỏe người lao động, thực hiện chế độ bồi dưỡng, điều dưỡng... Sử dụng đúng và đầy đủ trang bị phương tiện bảo vệ cá nhân", "B": "Máy móc thiết bị phải phù hợp với cơ thể của người lao động, không đòi hỏi người lao động làm việc quá căng thẳng, nhịp độ quá khẩn trương và thực hiện những thao tác gò bó kéo dài", "C": "Máy móc thiết bị phải phù hợp với nhân trắc của người lao động, tạo điều kiện để người lao động yên tâm công tác, gắn bó với công việc, nâng cao năng suất, chất lượng sản phẩm", "D": "Cả a và c"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(10, 'Các biện pháp phòng chống vi khí hậu xấu là:', 'SINGLE_CHOICE', '{"A": "Tổ chức sản xuất lao động hợp lý, phòng hộ cá nhân", "B": "Quy hoạch nhà xưởng và các thiết bị, thông gió, làm nguội vật liệu", "C": "Thiết bị và quá trình công nghệ", "D": "Tất cả các câu đều đúng"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(11, 'Tiếng ồn cơ khí phát sinh trong môi trường lao động là:', 'SINGLE_CHOICE', '{"A": "Trục động cơ bị rơ mòn, độ cứng vững của hệ thống công nghệ kém", "B": "Quá trình gia công rèn, dập", "C": "Khí không khí chuyển động với tốc độ cao (động cơ phản lực)", "D": "Tiếng nổ hoặc xung động do nhiên liệu cháy gây ra"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(12, 'Tiếng ồn cơ khí phát sinh tại các xưởng:', 'SINGLE_CHOICE', '{"A": "Xưởng dệt, may", "B": "Xưởng lắp ráp điện tử", "C": "Xưởng khoan, tiện, phay...", "D": "Tất cả đều đúng"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(13, 'Các phương án giảm ảnh hưởng của tiếng ồn tới người lao động là:', 'SINGLE_CHOICE', '{"A": "Hiện đại hóa thiết bị, hoàn thiện quá trình công nghệ", "B": "Cách ly khu vực có nguồn ồn", "C": "Sử dụng bịt tai và nút tai chống ồn", "D": "Cả a, b và c đều đúng"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(14, 'Biện pháp giảm rung cho thiết bị máy móc là:', 'SINGLE_CHOICE', '{"A": "Gia cố móng thiết bị", "B": "Cân bằng cho thiết bị", "C": "Lắp lò xo giảm chấn", "D": "Cả a, b và c đều đúng"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(15, 'Những hạt bụi nào vào phổi nhiều nhất và gây hại nhiều hơn:', 'SINGLE_CHOICE', '{"A": "bụi dưới 5 μm", "B": "Hạt bụi thô", "C": "Bụi trên 10μm", "D": "Cả a và b đều đúng"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(16, 'Các biện pháp phòng chống bụi hiệu quả là:', 'SINGLE_CHOICE', '{"A": "Thay đổi công nghệ sản xuất", "B": "Thay đổi nguyên vật liệu", "C": "Tổ chức hút và xử lý bụi", "D": "Tất cả đều đúng"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(17, 'Thiết bị lọc bụi nào dưới đây sử dụng nguyên lý trọng lực để lắng bụi:', 'SINGLE_CHOICE', '{"A": "Thiết bị lọc bụi quán tính", "B": "Lọc bụi tĩnh điện", "C": "Lọc bụi tay áo", "D": "Lọc bụi bằng lưới lọc"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(18, 'Mục đích của việc đảm bảo ánh sáng trong lao động là:', 'SINGLE_CHOICE', '{"A": "Phân biệt được các chi tiết cần thao tác", "B": "Giữ được khả năng làm việc lâu hơn và không bị mệt mỏi", "C": "Cả a, b đều đúng", "D": "Cả a, b đều sai"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(19, 'Để hạn chế tác động của điện từ trường, người ta thường dùng các biện pháp nào sau đây:', 'SINGLE_CHOICE', '{"A": "Dùng các màn chắn bằng những kim loại có độ dẫn điện cao", "B": "Nối đất vỏ máy", "C": "Cả a và b đều đúng", "D": "Cả a và b đều sai"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(20, 'Hãy nêu các hình thức phân loại các thiết bị tín hiệu, báo hiệu được áp dụng để phòng ngừa tai nạn lao động:', 'SINGLE_CHOICE', '{"A": "Tín hiệu ánh sáng; tín hiệu màu sắc; tín hiệu âm thanh và dấu hiệu an toàn", "B": "Dấu hiệu an toàn; dấu hiệu nguy hiểm; tín hiệu ánh sáng; tín hiệu âm thanh; cảnh báo an toà", "C": "Tín hiệu màu sắc; tín hiệu bằng còi, chuông", "D": "Cả b và c"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(21, 'Hãy nêu định nghĩa về tín hiệu, báo hiệu:', 'SINGLE_CHOICE', '{"A": "Là phương tiện báo cho người lao động biết trước các yếu tố có hại và hướng dẫn biện pháp thực hiện để tránh bị ảnh hưởng của các yếu tố có hại sức khỏe người lao động", "B": "Là phương tiện nhắc nhở người lao động và hướng dẫn biện pháp thực hiện để tránh bị ảnh hưởng của các yếu tố nguy hiểm", "C": "Là phương tiện báo cho người lao động biết trước mối nguy hiểm để ngăn ngừa tai nạn lao động", "D": "Cả a và b"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(22, 'Hãy nêu mục đích của việc sử dụng tín hiệu màu sắc trong việc phòng tránh tai nạn lao động:', 'SINGLE_CHOICE', '{"A": "Dùng để báo hiệu cho mọi người biết các mối nguy hiểm cũng như biết tình trạng hoạt động của máy móc, thiết bị", "B": "Hướng dẫn quy trình vận hành, thao tác và sửa chữa bảo dưỡng thiết bị, máy móc, dây chuyền sản xuất cho người lao động", "C": "Giúp người lao động phân biệt được công dụng của các chi tiết, bộ phận trong hệ thống điều khiển, các loại đường ống công nghệ, các loại chai chứa khí, các dây dẫn trong hệ thống điện...", "D": "Cả a, b và c"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(23, 'Hãy nêu mục đích của việc sử dụng tín hiệu âm thanh trong việc phòng tránh tai nạn lao động:', 'SINGLE_CHOICE', '{"A": "Dùng để báo hiệu cho người lao động biết các mối nguy hiểm cũng như biết tình trạng hoạt động của máy móc, thiết bị khi mở máy hay khi gặp sự cố...", "B": "Giúp người lao động phân biệt được tình trạng của các chi tiết, bộ phận trong hệ thống điều khiển, các loại đường ống công nghệ, các loại chai chứa khí, các dây dẫn trong hệ thống điện...", "C": "Hướng dẫn quy trình vận hành, thao tác và sửa chữa bảo dưỡng thiết bị, máy móc, dây chuyền sản xuất cho người lao động", "D": "Cả a và c"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(24, 'Hãy nêu khái niệm khoảng cách an toàn để phòng tránh tai nạn lao động:', 'SINGLE_CHOICE', '{"A": "Là khoảng không gian lớn nhất giữa người lao động và các loại phương tiện, thiết bị, hoặc khoảng cách lớn nhất giữa phương tiện, thiết bị với nhau để không bị tác động xấu của các yếu tố sản xuất", "B": "Là khoảng không gian nhỏ nhất giữa người lao động và các loại phương tiện, thiết bị, hoặc khoảng cách nhỏ nhất giữa phương tiện, thiết bị với nhau để không bị tác động xấu của các yếu tố sản xuất", "C": "Là khoảng cách để báo cho người lao động biết trước mối nguy hiểm và hướng dẫn biện pháp thực hiện để tránh bị ảnh hưởng của các yếu tố nguy hiểm", "D": "Là khoảng không gian nhỏ nhất giữa người lao động và các loại phương tiện, thiết bị để không bị tác động xấu của các yếu tố sản xuất"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(25, 'Nguyên tắc và tiêu chuẩn để bố trí số lượng cán bộ kiểm tra kỹ thuật ATVSLĐ là dựa vào:', 'SINGLE_CHOICE', '{"A": "Dựa vào tính chất sản xuất", "B": "Điều kiện lao động phức tạp dễ xảy ra tai nạn lao động", "C": "Cả a và b đều đúng", "D": "Cả a và b đều sai"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(26, 'Nhiệm vụ của tổ chức chuyên trách kiểm tra kỹ thuật an toàn là:', 'SINGLE_CHOICE', '{"A": "Giúp giám đốc xí nghiệm tổ chức chỉ đạo việc thực hiện công tác ATVSLĐ", "B": "Kiểm tra, giám sát việc thực hiện quy phạm quy trì về kỹ thuật an toàn, ngăn chặn kịp thời tai nạn lao động", "C": "Cả a và b đều đúng", "D": "Cả a và b đề sai"}', 'A', '', 1);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
