(3, 'Thi thử trắc nghiệm ôn tập An toàn điện online - Đề #23', 'Toán', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Toán. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(51, 'Người vào trạm biến áp một mình phải có:', 'SINGLE_CHOICE', '{"A": "Bậc 4 an toàn điện.", "B": "Bậc 5 an toàn điện.", "C": "Bậc 5 an toàn điện, đồng thời phải có tên trong danh sách đã được lãnh đạo đơn vị quản lý vận hành duyệt.", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(52, 'Quy định về bậc an toàn tối thiểu khi vào trạm biến áp làm việc:', 'SINGLE_CHOICE', '{"A": "Nhân viên đơn vị công tác vào trạm làm việc phải có bậc 2 an toàn điện trở lên, nếu làm công việc ở thiết bị điện thì người chỉ huy trực tiếp phải có bậc 4 an toàn điện trở lên (trừ những công việc nề, mộc, cơ khí ở nhà máy điện, trạm điện và người chỉ", "B": "Nhân viên đơn vị công tác phải có từ bậc 2 an toàn điện trở lên, nhóm trưởng phải có bậc 3 an toàn điện trở lên.", "C": "Không quy định.", "D": "Cả a, b và c đều sai."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(53, 'Khi làm công việc sửa chữa, lắp đặt thiết bị hoặc điều chỉnh rơle, đồng hồ ở các TBA thì:', 'SINGLE_CHOICE', '{"A": "Cho phép một người thực hiện.", "B": "Phải có hai người thực hiện.", "C": "Phải có hai người thực hiện; những người này chỉ được làm việc trong phạm vi cho phép và đảm bảo khoảng cách đến phần có điện theo quy định tại Khoản 2, Điều 9 trong Quy trình an toàn điện.", "D": "Cả a, b và c đều sai."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(54, 'Khi vào trạm biến áp làm việc, người làm nhiệm vụ kiểm tra các thiết bị điện hạ áp phải có:', 'SINGLE_CHOICE', '{"A": "Bậc 3 an toàn điện trở lên.", "B": "Bậc 4 an toàn điện trở lên.", "C": "Bậc 5 an toàn điện.", "D": "Cả a, b và c đều sai."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(55, 'Người đi kiểm tra hoặc ghi chỉ số đồng hồ điện một mình ở TBA phải:', 'SINGLE_CHOICE', '{"A": "Không được vượt qua rào chắn hoặc tự ý sửa chữa, lắp đặt thiết bị.", "B": "Nếu thấy có tồn tại cần khắc phục ngay, cho phép vượt qua rào chắn để làm việc.", "C": "Có thể tự sửa chữa, lắp đặt thiết bị ngòai nhiệm vụ được phân công.", "D": "Cả a, b và c."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(56, 'Khi công tác trong trạm trong điều kiện bình thường, quy định nào sau đây đúng:', 'SINGLE_CHOICE', '{"A": "Cho phép làm việc trên thiết bị đã cắt điện nhưng chưa tiếp đất.", "B": "Cho phép làm việc trên thiết bị đang vận hành bị mất điện hoặc thiết bị dự phòng trong trạm.", "C": "Cấm làm việc ở thiết bị đang vận hành bị mất điện, hoặc đã cắt điện nhưng chưa tiếp đất, hoặc thiết bị dự phòng đặt trong trạm có thể được khôi phục bất cứ lúc nào.", "D": "Cấm làm việc ở thiết bị đang vận hành bị mất điện và đã cắt điện nhưng chưa tiếp đất, hoặc thiết bị dự phòng đặt trong trạm có thể được khôi phục bất cứ lúc nào."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(57, 'Nếu mở cửa lưới kiểm tra thiết bị đang vận hành trong trạm, quy định nào sau đây đúng:', 'SINGLE_CHOICE', '{"A": "Chỉ cần một người.", "B": "Phải có hai người bậc 3 an toàn điện trở lên. Khi có giông sét không được kiểm tra các trạm ngoài trời.", "C": "Phải có hai người, người giám sát phải có bậc 4 an toàn điện trở lên, người kiểm tra bậc 3 an toàn điện trở lên và phải quan sát kỹ phần mang điện để đảm bảo khoảng cách an toàn. Khi có giông sét không được kiểm tra các trạm ngoài trời.", "D": "Cả a, b và c đều sai."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(58, 'Biện pháp an toàn khi làm việc ở TBA, quy định nào sau đây đúng:', 'SINGLE_CHOICE', '{"A": "Người vào trạm biến áp một mình phải có bậc 5 an toàn điện, đồng thời phải có tên trong danh sách đã được lãnh đạo đơn vị quản lý vận hành duyệt.", "B": "Người đi kiểm tra hoặc ghi chỉ số đồng hồ điện một mình không được vượt qua rào chắn hoặc tự ý sửa chữa, lắp đặt thiết bị.", "C": "Cấm dẫn người lạ vào trạm, đối với những người vào tham quan, nghiên cứu phải do lãnh đạo đơn vị quản lý vận hành (hoặc kỹ thuật viên) hướng dẫn. Vào trạm làm việc, tham quan đều phải tôn trọng nội quy trạm, những người vào lần đầu phải được hướng dẫn", "D": "Cả a, b và c."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(59, 'Căn cứ vào mức độ nguy hiểm, làm việc với thiết bị điện cao áp, những công việc làm không cắt điện được chia thành:', 'SINGLE_CHOICE', '{"A": "Hai loại chủ yếu: (1) Những việc làm bên ngoài rào chắn hoặc ngoài khoảng cách an toàn với thiết bị đang có điện. (2) Những việc làm ở gần hoặc trên các bộ phận và thiết bị đang có điện nhưng không có khả năng che chắn, gây nguy hiểm cho người làm việc", "B": "Hai loại: (1) Làm việc có điện. (2) Làm việc có cắt điện một phần.", "C": "Không phân loại.", "D": "Cả a, b và c đều sai."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(60, 'Làm việc với thiết bị điện cao áp không cắt điện, những công việc cho phép mở cửa lưới an toàn khi thiết bị vẫn có điện phải có phiếu công tác và đảm bảo khoảng cách an toàn&nbsp; theo quy định, bao gồm:', 'SINGLE_CHOICE', '{"A": "Lấy mẫu dầu MBA (chú ý kiểm tra tiếp đất vỏ máy trước); Tiến hành lọc dầu ở những MBA lớn đang vận hành; Kiểm tra độ rung của thanh cái bằng sào thao tác; Đo dòng điện bằng am-pe kìm; Lau sứ cách điện từ 35kV trở xuống bằng dụng cụ chuyên dùng đã được", "B": "Tháo dây trung tính MBA để củng cố và sửa chữa tiếp đất; Điều chỉnh nấc phân áp MBA", "C": "Cả a và b.", "D": "Theo a, nhưng chỉ được tiến hành khi các bộ phận mang điện ở phía trước mặt hay ở phía trên đầu, người làm việc phải đứng trên nền nhà hoặc giàn giáo chắc chắn, cấm người làm việc đứng lom khom."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(61, 'Khi sử dụng kìm đo cường độ dòng điện phải thực hiện theo những quy định nào sau đây là đúng?', 'SINGLE_CHOICE', '{"A": "Người sử dụng đồng hồ kiểu kìm để đo cường độ dòng điện phải được huấn luyện về cách đo", "B": "Nếu đo ở thiết bị điện cao áp thì phải được huấn luyện về cách đọc chỉ số, giám sát an toàn, do hai người có bậc an toàn điện từ bậc 4 trở lên và thực hiện theo phiếu công tác", "C": "Chỉ được dùng ampe kìm để đo dòng điện ở thiết bị điện cao áp từ 22kV trở xuống và phải có ampe mét lắp ngay trên kìm", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(62, 'Khi dùng ampe kìm để đo dòng điện ở thiết bị điện cao áp thì thực hiện như thế nào là đúng:', 'SINGLE_CHOICE', '{"A": "Chỉ đo thiết bị điện cao áp phải từ 22kV trở xuống và phải có ampe mét lắp ngay trên kìm", "B": "Khi đo phải sử dụng găng tay cách điện, ủng cách điện (hoặc ghế cách điện tương ứng với cấp điện áp của thiết bị)", "C": "Vị trí đo phải thuận tiện và khoảng cách giữa các pha không dưới 0,25m", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(63, 'Khi đo dòng điện ở thiết bị điện hạ áp thì thực hiện như thế nào là đúng:', 'SINGLE_CHOICE', '{"A": "Được phép đo ở trường hợp ampe mét đặt riêng, người đo không cần mang thiết bị an toàn", "B": "Nếu đo trên cột thì phải tuân theo quy định làm việc trên cao của quy trình an toàn điện", "C": "Khi đo phải đứng trên nền nhà hoặc giá đỡ chắc chắn, không đứng trên thang di động để đo", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(64, 'Khi đo cường độ dòng điện, người sử dụng ampe kìm để đo phải như thế nào?', 'SINGLE_CHOICE', '{"A": "Có trình độ bậc 3 an toàn điện trở lên", "B": "Phải được huấn luyện về cách đo", "C": "Đo xong, kìm đo điện phải để trong hộp và bảo quản nơi khô ráo", "D": "Cả b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(65, 'Nếu sử dụng ampe kìm để đo dòng điện ở thiết bị điện hạ áp thì phải thực hiện như thế nào là đúng:', 'SINGLE_CHOICE', '{"A": "Phải có lệnh công tác", "B": "Phải có phiếu công tác", "C": "Chỉ cần ghi sổ nhật ký vận hành", "D": "Cả a, b và c đều sai"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(66, 'Nếu sử dụng ampe kìm để đo dòng điện ở thiết bị điện cao áp thì phải thực hiện như thế nào là đúng:', 'SINGLE_CHOICE', '{"A": "Phải có lệnh công tác", "B": "Phải có phiếu công tác", "C": "Chỉ cần ghi sổ nhật ký vận hành", "D": "Cả a, b và c đều sai"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(67, 'Khi dùng ampe kìm để đo dòng điện thiết bị điện hạ áp thì phải có trang bị an toàn như thế nào?', 'SINGLE_CHOICE', '{"A": "Dùng găng cách điện", "B": "Người đo không cần mang trang bị an toàn", "C": "Dùng găng cách điện, ủng cách điện hoặc ghế cách điện phù hợp cấp điện áp", "D": "Cả a, b và c đều sai"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(68, 'Khi dùng ampe kìm để đo dòng điện thiết bị điện cao áp thì phải có trang bị an toàn như thế nào?', 'SINGLE_CHOICE', '{"A": "Sào cách điện và găng cách điện", "B": "Người đo không cần mang thiết bị an toàn", "C": "Dùng găng cách điện, ủng cách điện hoặc ghế cách điện phù hợp cấp điện áp", "D": "Cả a, b và c đều sai"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(69, 'Cách điện của ampe kìm đo ở thiết bị điện cao áp phải đảm bảo yêu cầu gì?', 'SINGLE_CHOICE', '{"A": "Không quy định", "B": "Đang trong thời hạn thử nghiệm", "C": "Có độ dài của cán phù hợp khoảng cách an toàn", "D": "Cả b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(70, 'Khi đo dòng điện ở thiết bị điện hạ áp, được phép đo ở trường hợp nào sau đây?', 'SINGLE_CHOICE', '{"A": "Phải có ampe mét đặt liền kìm đo", "B": "Phải có đồng hồ ampe đấu cố định ở tủ điện", "C": "Được phép đo ở trường hợp ampe mét đặt riêng", "D": "Cả a, b và c."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(71, 'Những biện pháp an toàn khác khi làm việc với thiết bị điện được quy định.', 'SINGLE_CHOICE', '{"A": "Cho phép làm việc trên các dàn giáo tạm thời hoặc trên thang di động khi bên dưới có thiết bị có điện cao áp nhưng phải đảm bảo khoảng cách an toàn. Cho phép làm việc ở đoạn cáp ngầm hay dây dẫn nổi không phải làm tiếp đất nếu đoạn cáp ngầm hay dây dẫn", "B": "Cấm làm việc trên các dàn giáo tạm thời hoặc trên thang di động khi bên dưới có thiết bị có điện cao áp (mặc dù đã đảm bảo khoảng cách an toàn). Cấm làm việc ở đoạn cáp ngầm hay dây dẫn nổi không làm tiếp đất.", "C": "Theo a, nhưng phải được người cho phép vào làm việc đồng ý.", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(72, 'Những công việc phải cắt điện nhưng cho phép không nối đất:', 'SINGLE_CHOICE', '{"A": "Đo, kiểm tra điện trở nối đất, đo các thông số của thiết bị mà bắt buộc phải không được tiếp đất, củng cố lại tiếp đất của thiết bị hoặc của hệ thống nối đất toàn trạm thì được phép tạm thời tháo gỡ dây nối đất trong thời gian tiến hành các công việc n", "B": "Theo a, nhưng phải có Phiếu công tác và ghi rõ tháo nối đất nào, do nhân viên vận hành nào thực hiện.", "C": "Theo a, chỉ thực hiện đối với điện áp 35kV trở xuống nhưng phải có Phiếu công tác và ghi rõ tháo nối đất nào, do nhân viên vận hành nào thực hiện.", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(73, 'Khi tiến hành công việc trên máy cắt có bộ điều khiển từ xa, quy định nào sau đây đúng:', 'SINGLE_CHOICE', '{"A": "Có lệnh cho phép tách máy cẳt khỏi vận hành của cấp điều độ có quyền điều khiển.", "B": "Thực hiện theo Phiếu công tác.", "C": "Cắt nguồn điều khiển máy cắt; Cắt các cầu dao cách ly trước và sau máy cắt; Treo biển báo: “Cấm đóng điện! Có người đang làm việc” vào khóa điều khiển máy cắt.", "D": "Thực hiện theo cả a, b và c."}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(74, 'Làm việc trên máy cắt, khi tiến hành thử, điều chỉnh việc đóng, cắt máy cắt, quy định nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Người chỉ huy trực tiếp được phép cấp điện vào nguồn điều khiển.", "B": "Người chỉ huy trực tiếp được phép cấp điện vào nguồn điều khiển, nhưng phải được sự đồng ý của nhân viên vận hành.", "C": "Nhân viên đơn vị công tác được phép cấp điện vào nguồn điều khiển mà không cần có lệnh của người chỉ huy trực tiếp hoặc sự đồng ý của nhân viên vận hành.", "D": "Cả a, b và c"}', 'A', '', 3);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(75, 'Làm việc trên máy cắt, quy định nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Cho phép lau sứ cách điện bằng thiết bị chuyên dùng ở các máy cắt đang vận hành.", "B": "Cho phép sửa chữa ở các máy cắt đang vận hành.", "C": "Cấm sửa chữa ở các máy cắt đang vận hành (kể cả việc lau sứ cách điện bằng thiết bị chuyên dùng).", "D": "Cả a, b và c đều sai"}', 'A', '', 3);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(4, 'Đề thi thử THPT QG năm 2022 môn Toán online - Đề thi của Trường THPT Văn Lang', 'Toán', 90, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Toán. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(76, 'Cho hình chóp S.ABCD có đáy ABCD là hình vuông cạnh a. Tính chiều cao h của hình chóp S. ABCD, biết thể tích khối chóp S.ABCD&nbsp; là a3.', 'SINGLE_CHOICE', '{"A": "h = a", "B": "h = 2a", "C": "h = 3a", "D": "h = 4a"}', 'A', 'Ta có: \({V_{S.ABCD}} = \dfrac{1}{3}.h.{S_{ABCD}}\)Khi đó ta có: \(h = \dfrac{{3{V_{S.ABCD}}}}{{{S_{ABCD}}}} = \dfrac{{3{a^3}}}{{{a^2}}} = 3a.\)Chọn đáp án C.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(77, 'Hình hộp chữ nhật có ba kích thước là 3; 4; 12. Bán kính mặt cầu ngoại tiếp của hình hộp chữ nhật là', 'SINGLE_CHOICE', '{"A": "10", "B": "$\\dfrac{{13}}{2}$", "C": "13", "D": "5"}', 'B', 'Ta có tâm của mặt cầu ngoại tiếp hình hộp chữ nhật trùng với tâm đối xứng của hình hộp. Như hình lập phương ABCD.A’B’C’D’ có tâm là I, là trung điểm của AC’, bán kính&nbsp;\(r = \dfrac{{AC''}}{2}\)Tam giác A''C''A vuông tại A'', áp dụng định lí (P) ta được:\(AC'' = \sqrt {AA{''^2} + A''{C^2}}&nbsp; \)\(\,= \sqrt {{c^2} + A''C{''^2}} \,\,\,\,(1)\)Mặt khác tam giác A''D''C'' vuông tại D'', áp dụng định lí (P) ta được:\(A''C'' = \sqrt {A''D{''^2} + D''C{''^2}} \)\(\, = \sqrt {{a^2} + {b^2}} \,\,\,\,(2)\)Từ (1) và (2) ta có: \(r = \dfrac{1}{2}.\sqrt {{a^2} + {b^2} + {c^2}} \)Áp dụng: \(a = 3;b = 4;c = 12\) ta được: \(r = \dfrac{1}{2}\sqrt {{3^2} + {4^2} + {{12}^2}}&nbsp; = \dfrac{{13}}{2}\)Chọn B.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(78, 'Chọn mệnh đề đúng :', 'SINGLE_CHOICE', '{"A": "${\\log _a}1 = 1$", "B": "${\\log _a}a = a$", "C": "${\\log _a}1 = a$", "D": "${\\log _a}a = 1$"}', 'A', 'Ta có: \({\log _a}a = 1\)&nbsp;là mệnh đề đúng.Chọn đáp án D.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(79, 'Tập hợp các điểm biểu diễn số phức z thỏa mãn $|z - 2i| = 4$ là:', 'SINGLE_CHOICE', '{"A": "Đường tròn tâm I(1 ; - 2), bán kính R = 4.", "B": "Đường tròn tâm I(1 ; 2), bán kính R = 4.", "C": "Đường tròn tâm I(0 ; 2), bán kính R = 4.", "D": "Đường tròn tâm I(0 ; -2), bán kính R = 4."}', 'A', '$27', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(80, 'Cho hình chóp S.ABCD có đáy ABCD là hình bình hành và có thể tích bằng 1. Trên cạnh SC lấy điểm E sao cho SE = 2EC. Tính thể tích V của khối tứ diện SEBD.', 'SINGLE_CHOICE', '{"A": "$V = \\dfrac{1}{3}$", "B": "$V = \\dfrac{1}{6}$", "C": "$V = \\dfrac{1}{{12}}$", "D": "$V = \\dfrac{2}{3}$"}', 'A', 'Ta có:\(\dfrac{{{V_{S.BED}}}}{{{V_{S.BCD}}}} = \dfrac{{SE}}{{SC}} = \dfrac{2}{3}\)\(\dfrac{{{V_{S.BCD}}}}{{{V_{S.ABCD}}}} = \dfrac{1}{2}\)\( \Rightarrow {V_{S.BED}} = \dfrac{2}{3}.\dfrac{1}{2}{V_{S.ABCD}} = \dfrac{1}{3}\)Chọn đáp án A.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(81, 'Tổng của hai số phức ${z_1} = 2 + 3i\,,\,\,{z_2} = 5 - 6i$ là:', 'SINGLE_CHOICE', '{"A": "7 – 3i.", "B": "7 + 3i.", "C": "– 3 +9i.", "D": "3 + 9i."}', 'A', '\({z_1} + {z_2} = 2 + 3i + 5 - 6i = 7 - 3i\).Chọn A', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(82, 'Hình chóp S.ABC có đáy là tam giác vuông tại A, cạnh AB = a, BC = 2a, chiều cao $SA = a\sqrt 6 $. Thể tích của khối chóp là:', 'SINGLE_CHOICE', '{"A": "$V = \\dfrac{{{a^3}\\sqrt 2 }}{2}$", "B": "$V = \\dfrac{{{a^3}\\sqrt 6 }}{3}$", "C": "$V = \\dfrac{{{a^3} }}{2}$", "D": "$V = 2{a^3}\\sqrt 6 $"}', 'A', 'Áp dụng định lý Py – ta- go ta có:\(AC = \sqrt {B{C^2} - A{B^2}} \)\(\;\;\;\;\;\; = \sqrt {4{a^2} - {a^2}}&nbsp; = a\sqrt 3 \)\( \Rightarrow {S_{ABC}} = \dfrac{1}{2}AB.AC = \dfrac{1}{2}a.a\sqrt 3 \)\(\, = \dfrac{{{a^2}\sqrt 3 }}{2}\)Khi đó:\({V_{S.ABC}} = \dfrac{1}{3}SA.{S_{ABC}} \)\(\,= \dfrac{1}{3}a\sqrt 6 .\dfrac{{{a^2}\sqrt 3 }}{2} = \dfrac{{{a^3}\sqrt 2 }}{2}\)Chọn đáp án A.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(83, 'Cho hình chóp S. ABCD có đáy là hình chữ nhật với Ab = a, AD = 2a, SA vuông góc với mặt đáy và $SA = a\sqrt 3 $. Thể tích khối chóp S.ABC bằng:', 'SINGLE_CHOICE', '{"A": "$V = \\dfrac{{2{a^3}\\sqrt 3 }}{3}$", "B": "$V = \\dfrac{{{a^3}\\sqrt 3 }}{3}$", "C": "$V = {a^3}\\sqrt 3 $", "D": "$V = 2{a^3}\\sqrt 3 $"}', 'A', 'Ta có:\({S_{ABC}} = \dfrac{1}{2}AB.BC = \dfrac{1}{2}a.2a = {a^2}\)Khi đó\({V_{S.ABC}} = \dfrac{1}{3}SA.{S_{ABC}} = \dfrac{1}{3}.a\sqrt 3 .{a^2} \)\(\,= \dfrac{{{a^3}\sqrt 3 }}{3}\)Chọn đáp án B.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(84, 'Cho khối chóp S.ABC có đáy ABC là tam giác đều cạnh 2a. Cạnh bên SC vuông góc với mặt phẳng đáy và SC = a. Thể tích V của khối chóp S.ABC là:', 'SINGLE_CHOICE', '{"A": "$V = 2{a^3}\\sqrt 3 $", "B": "$V = \\dfrac{{{a^3}\\sqrt 3 }}{4}$", "C": "$V = \\dfrac{{{a^3}\\sqrt 3 }}{3}$", "D": "$V = {a^3}\\sqrt 3 $"}', 'A', 'Ta có: \({S_{ABC}} = \dfrac{1}{2}.a\sqrt 3 .2a = {a^2}\sqrt 3 \)Khi đó \({V_{S.ABC}} = \dfrac{1}{3}.SC.{S_{ABC}} \)\(\,= \dfrac{1}{3}.{a^2}\sqrt 3 .a = \dfrac{{{a^3}\sqrt 3 }}{3}\)Chọn đáp án C.', 4);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(85, 'Cho hàm số y=f(x) xác định trên đoạn [a ; b]. Điều kiện đủ để hàm số nghịch biến trên đoạn [a ; b ] là', 'SINGLE_CHOICE', '{"A": "f(x) liên tục trên [a; b] và f’(x) < 0 với mọi $x \\in (a;b)$.", "B": "f(x) liên tục trên (a ; b) và f’(x) > 0 với mọi $x \\in [a;b]$.", "C": "$f''(x) \\le 0$ với mọi $x \\in [a;b]$", "D": "$f''(x) \\ge 0$ với mọi $x \\in [a;b]$."}', 'A', 'Nếu&nbsp;f(x) liên tục trên [a; b] và f’(x) &lt; 0 với mọi \(x \in (a;b)\) thì&nbsp;hàm số nghịch biến trên đoạn [a ; b ].', 4);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(5, 'Thi thử trắc nghiệm ôn tập Kiểm toán căn bản - Đề #8', 'Toán', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Toán. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(86, 'Sau khi đơn vị được kiểm toán phát hành báo cáo tài chính, kiểm toán viên phát hiện những sự kiện ảnh hưởng trọng yếu tới báo cáo tài chính, thảo luận với thủ trưởng đơn vị, có ý kiến không đồng ý. Kiểm toán viên phải thông báo đến ai về những hành động mà kiểm toán viên thực hiện để ngăn ngừa khả năng sử dụng một báo cáo tài chính đã phát hành có chứa sai phạm trọng yếu chưa được phát hiện: (CM 700)', 'SINGLE_CHOICE', '{"A": "Kế toán trưởng của đơn vị được kiểm toán", "B": "Cơ quan chức năng", "C": "Người có trách nhiệm cao nhất tại đơn vị", "D": "Công an kinh tế"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(87, 'Người nhận báo cáo kiểm toán về báo cáo tài chính là:', 'SINGLE_CHOICE', '{"A": "Hội đồng quản trị", "B": "Giám đốc", "C": "Cổ đông đơn vị được kiểm toán", "D": "Tất cả các đáp án trên"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(88, 'Thuật ngữ ngoại trừ được sử dụng trong:', 'SINGLE_CHOICE', '{"A": "Ý kiến chấp nhận toàn phần", "B": "Ý kiến chấp nhận từng phần", "C": "Ý kiến từ chối", "D": "Ý kiến không chấp nhận"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(89, 'Kiểm toán viên phải mô tả rõ ràng trong báo cáo kiểm toán về báo cáo tài chính những lý do dẫn đến ý kiến:', 'SINGLE_CHOICE', '{"A": "Ý kiến chấp nhận từng phần", "B": "Ý kiến từ chối", "C": "Ý kiến không chấp nhận", "D": "Tất cả các đáp án trên"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(90, 'Theo IPAC của IFAC thì báo cáo kiểm toán về báo cáo tài chính được trình bày như thế nào:', 'SINGLE_CHOICE', '{"A": "Bằng miệng hoặc bằng văn bản", "B": "Bằng miệng", "C": "Bằng văn bản và tuân thủ các quy định về nội dung và hình thức.", "D": "Bằng văn bản"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(91, 'Trong báo cáo kiểm toán về báo cáo tài chính phải có chữ ký của:', 'SINGLE_CHOICE', '{"A": "Kiểm toán viên chịu trách nhiệm kiểm toán", "B": "Giám đốc (hay người được ủy quyền) của công ty kiểm toán chịu trách nhiệm phát hành báo cáo kiểm toán về báo cáo tài chính", "C": "Giám đốc của đơn vị được kiểm toán", "D": "Cả A và B"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(92, 'Ý kiến tùy thuộc của kiểm toán viên thường liên quan đến các sự kiện xảy ra ở quá khứ.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(93, 'Ý kiến của kiểm toán viên đưa ra trên báo cáo kiểm toán về báo cáo tài chính là sự đảm bảo tuyệt đối rằng không có bất kỳ sự sai sót nào trên báo cáo tài chính đã được kiểm toán.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', 'Vì chỉ đảm bảo báo cáo tài chính đã phản ánh trung thực và hợp lý trên khía cạnh trọng yếu, có thể có những sai sót nhưng là không trọng yếu', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(94, 'Thư quản lý nhất thiết phải đính kèm báo cáo kiểm toán về báo cáo tài chính.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(95, 'Sau khi báo cáo tài chính được công bố phát hiện ra những sự kiện ảnh hưởng trọng yếu đối với báo cáo tài chính vào thời điểm ký báo cáo tài chính, kiểm toán viên sẽ không phải chịu bất cứ trách nhiệm nào.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', 'Về mặt hình thức thì kiểm toán viên không phải chịu trách nhiệm nhưng thực chất kiểm toán viên vẫn phải cân nhắc việc phát hành lại báo cáo kiểm toán về báo cáo tài chính và điều này cần được thảo luận với thủ trưởng đơn vị.', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(96, 'Yếu tố tùy thuộc là yếu tố trọng yếu có ảnh hưởng nghiêm trọng tới báo cáo tài chính.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', 'Vì yếu tố tùy thuộc là yếu tố trọng yếu nhưng không chắc chắn, thường liên quan đến những sự kiện xảy ra trong tương lai nằm ngoài tầm kiểm soát của đơn vị và kiểm toán viên nên không biết mức độ nghiêm trọng của nó đối với báo cáo tài chính.', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(97, 'Số hiệu báo cáo kiểm toán về báo cáo tài chính là số hiệu phát hành báo cáo kiểm toán về báo cáo tài chính của công ty kiểm toán theo từng cuộc kiểm toán.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(98, 'Kiểm toán viên có thể đưa ra ý kiến chấp nhận toàn phần trong trường hợp báo cáo tài chính được kiểm toán có những sai sót nhưng đã được kiểm toán viên phát hiện và đơn vị đã điều chỉnh theo ý kiến của kiểm toán viên.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(99, 'Trong trường hợp có từ hai công ty kiểm toán cùng thực hiện cuộc kiểm toán thì báo cáo kiểm toán về báo cáo tài chính phải được ký bởi giám đốc hoặc người ủy quyền của cả hai công ty kiểm toán theo đúng thủ tục.', 'SINGLE_CHOICE', '{"A": "Đúng", "B": "Sai", "C": "", "D": ""}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(100, 'Điều nào sau đây không phải là lý do chính của việc kiểm toán báo cáo tài chính:', 'SINGLE_CHOICE', '{"A": "Do mâu thuẫn quyền lợi giữa nhà quản lý của đơn vị được kiểm toán với kiểm toán viên độc lập.", "B": "Sự phức tạp của các vấn đề lien quan đến kế toán và trình bày báo cáo tài chính", "C": "Người sử dụng báo cáo tài chính khó khăn trong việc tiếp cận các thong tin tại đơn vị được kiểm toán", "D": "Tác động của báo cáo tài chính đến quá trình ra quyết định của người sử dụng"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(101, 'Dấu hiệu khác nhau cơ bản giữa kiểm toán nhà nước, kiểm toán độc lập, kiểm toán nội bộ là:', 'SINGLE_CHOICE', '{"A": "Phương pháp sử dụng để kiểm toán", "B": "Phạm vi hoạt động và mục đích của kiểm toán", "C": "Các chuẩn mực kiểm toán được áp dụng", "D": "Không có sự khác nhau"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(102, 'Lĩnh vực đặc trưng nhất của Kiểm toán Nhà nước là:', 'SINGLE_CHOICE', '{"A": "Kiểm toán tuân thủ", "B": "Kiểm toán hoạt động", "C": "Kiểm toán tài chính", "D": "Lĩnh vực khác"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(103, 'Kiểm toán nội trực thuộc:', 'SINGLE_CHOICE', '{"A": "Bộ tài chính", "B": "Chính phủ", "C": "Quốc hội", "D": "Doanh nghiệp, công ty"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(104, 'Lĩnh vực kiểm toán nội bộ quan tâm:', 'SINGLE_CHOICE', '{"A": "Kiểm toán tuân thủ", "B": "Kiểm toán hoạt động", "C": "Kiểm toán báo cáo tài chính", "D": "Cả ba nội dung trên"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(105, 'Phương pháp phân tích tổng quát nên thực hiện vào giai đoạn nào của cuộc kiểm toán:', 'SINGLE_CHOICE', '{"A": "Giai đoạn chuẩn bị", "B": "Giai đoạn kết thúc", "C": "Giai đoạn thực hiện kiểm toán", "D": "Cả 3 giai đoạn"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(106, 'Một ý kiến chấp nhận từng phần có ngoại trừ của kiểm toán viên được đưa ra khi bị giới hạn về phạm vi kiểm toán cần được giải thích trên:', 'SINGLE_CHOICE', '{"A": "Thuyết minh báo cáo tài chính", "B": "Báo cáo kiểm toán", "C": "Cả báo cáo kiểm toán và thuyết minh báo cáo tài chính", "D": "Cả báo cáo kế toán và báo cáo tài chính"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(107, 'Một công ty khách hàng trong năm đã thay đổi phương pháp kế toán làm ảnh hưởng trọng yếu tới một số lượng lớn các khoản mục trên báo cáo tài chính. Kiểm toán viên khi đó nên:', 'SINGLE_CHOICE', '{"A": "Đưa ra ý kiến trái ngược và giải thích lý do", "B": "Đưa ra ý kiến từ chối và nêu lý do", "C": "Đưa ra ý kiến chấp nhận từng phần (loại ý kiến ngoại trừ)", "D": "Đưa ra ý kiến chấp nhận toàn phần"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(108, 'Báo cáo kiểm toán là hình thức biểu hiện trực tiếp của:', 'SINGLE_CHOICE', '{"A": "Chức năng kiểm toán", "B": "Thư hẹn kiểm toán", "C": "Kết luận kiểm toán", "D": "Câu a và b đúng"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(109, 'Khi phạm vi kiểm toán bị giới hạn nghiêm trọng hay số liệu của doanh nghiệp mập mờ (không chắc chắn) ở mức độ lớn, thì kiểm toán viên nên đưa ra loại ý kiến:', 'SINGLE_CHOICE', '{"A": "Chấp nhận toàn bộ", "B": "Loại trừ (chấp nhận từng phần)", "C": "Từ chối", "D": "Trái ngược"}', 'A', '', 5);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(110, 'Lý do chính của kiểm toán báo cáo tài chính là:', 'SINGLE_CHOICE', '{"A": "Nhằm đáp ứng yêu cầu của pháp luật", "B": "Để đảm bảo rằng không có những sai lệch trong báo cáo tài chính", "C": "Cung cấp cho người sử dụng một sự đảm bảo hợp lý về tính trung thực và hợp lý của báo cáo tài chính", "D": "Làm giảm trách nhiệm của nhà quản lý đối với báo cáo tài chính"}', 'A', '', 5);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(6, 'Đề thi thử giữa học kỳ 2 môn Lịch Sử lớp 11 online - Mã đề 05', 'Lịch Sử', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Lịch Sử. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(111, 'Hình thức đấu tranh chủ yếu của nhân dân Ấn Độ chống lại chính sách cai trị hà khắc của thực dân Anh trong những năm 1918 -1929 là', 'SINGLE_CHOICE', '{"A": "Bạo lực cách mạng.", "B": "đấu tranh vũ trang.", "C": "đấu tranh chính trị.", "D": "hòa bình, không bạo lực."}', 'D', 'Xuất phát từ đặc điểm lịch sử của Ấn Độ, Đảng Quốc đại đứng đầu là M. Gandi lãnh đạo nhân dân đấu tranh chống chủ nghĩa thực dân bằng biện pháp hòa bình, không sử dụng bạo lực.&nbsp;Phong trào này được đông đảo các tầng lớp nhân dân Ấn Độ hưởng ứng.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(112, 'Sự thành lập Đảng Cộng sản Ấn Độ (tháng 12-1925) có tác động như thế nào đến phong trào độc lập dân tộc ở Ấn Độ', 'SINGLE_CHOICE', '{"A": "Khẳng định phong trào đấu tranh theo biện pháp hòa bình là đúng", "B": "Thúc đẩy làn sóng đấu tranh chống thực dân Anh", "C": "Khẳng định giai cấp công nhân trở thành lực lượng lãnh đạo phong trào", "D": "Tạo điều kiện để chủ nghĩa Mác được truyền bá sâu rộng vào Ấn Độ"}', 'B', 'Sự thành lập Đảng Cộng sản Ấn Độ (tháng 12-1925) đã gió phần thúc đẩy làn sóng chống thực dân Anh của nhân dân Ấn Độ.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(113, 'Nhân tố nào sau đây là yếu tố quyết định sự ra đời của Đảng Cộng sản Ấn Độ (tháng 12-1925)?', 'SINGLE_CHOICE', '{"A": "Sự trưởng thành của giai cấp công nhân và phong trào công nhân", "B": "Chủ nghĩa Mác được truyền bá sâu rộng vào Ấn Độ", "C": "Phong trào dân tộc dân chủ ở Ấn Độ theo con đường cách mạng vô sản có bước phát triển", "D": "Phong trào đấu tranh theo khuynh hướng tư sản dần suy yếu"}', 'A', 'Từ đầu những năm 20 của thế kỉ XX, ở Ấn Độ đã xuất hiện những nhóm cộng sản đầu tiên. Cùng với sự trưởng thành của giai cấp công nhân và phong trào công nhân, tháng 12-1925 Đảng Cộng sản Ấn Độ được thành lập.=&gt; Sự trưởng thành của giai cấp công nhân và phong trào công nhân là yếu tố quyết định sự ra đời của Đảng Cộng sản Ấn Độ.Chọn AChú ý khi giải:Cũng giống như Ấn Độ, ở Việt Nam, phong trào công nhân cũng là một nhân tố đưa đến sự thành lập Đảng. Tuy nhiên, ngoài nhân tố trên còn có phong trào yêu nước và chủ nghĩa Mác – Lê-nin mới dẫn tới sự ra đời của Đảng Cộng sản Việt Nam.', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(114, 'Trong năm 1930, những Đảng cộng sản nào đã lần lượt ra đời ở khu vực Đông Nam Á?', 'SINGLE_CHOICE', '{"A": "Đảng cộng sản Việt Nam, Mã Lai, Xiêm, Phi-lip-pin", "B": "Đảng cộng sản Việt Nam, In-đô-nê-xi-a, Xiêm", "C": "Đảng cộng sản Việt Nam, Lào, Cam-pu-chia, In-đô-nê-xi-a", "D": "Đảng cộng sản Việt Nam, Phi-lip-pin, Xin-ga-po"}', 'A', 'Từ thập niên 20, giai cấp vô sản trẻ tuổi ở Đông Nam Á cũng bắt đầu trưởng thành. Một số Đảng cộng sản được thành lập, đầu tiên là Đảng cộng sản In-đô-nê-xi-a (5-1920), tiếp theo trong năm 1930, các đảng công sản ra đời ở Việt Nam, Mã Lai, Xiêm, Phi-lip-pin.Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(115, 'Cuộc khởi nghĩa chống Pháp nào ở Lào, kéo dài suốt hơn 30 năm đầu thế kỉ XX?', 'SINGLE_CHOICE', '{"A": "Khởi nghĩa Ong Kẹo", "B": "Khởi nghĩa Commađam", "C": "Khởi nghĩa Ong Kẹo và Commađam", "D": "Khởi nghĩa Chậu Pachay"}', 'C', 'Ỏ Lào, cuộc khởi nghĩa Ong Kẹo và Commađam nổ ra từ năm 1901, tiếp diễn trong hơn 30 năm đầu thế kỉ XX.Chọn C', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(116, 'Cơ sở nào đưa đến sự phát triển của khuynh hướng dân chủ tư sản trong phong trào độc lập dân tộc ở Đông Nam Á sau Chiến tranh thế giới thứ nhất?', 'SINGLE_CHOICE', '{"A": "Sự ra đời của giai cấp tư sản dân tộc.", "B": "Sự phát triển của nền kinh tế tư bản chủ nghĩa.", "C": "Ảnh hưởng của cách mạng tháng Mười Nga.", "D": "Ảnh hưởng của các cuộc cải cách chính trị ở khu vực"}', 'B', 'Trong và sau chiến tranh thế giới thứ nhất, các nước đế quốc tăng cường đầu tư khai thác thuộc địa.&nbsp;Phương thức sản xuất tư bản chủ nghĩa được du nhập đã thúc đẩy nền kinh tế tư bản chủ nghĩa ở khu vực Đông Nam Á phát triển. Đây chính là cơ sở để dẫn tới sự phân hóa giai cấp và sự phát triển của khuynh hướng dân chủ tư sản trong phong trào độc lập dân tộc ở Đông Nam Á sau chiến tranh thế giới thứ nhấtChọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(117, 'Hội nghị Muy-nich với sự tham gia của các quốc gia nào sau đây?', 'SINGLE_CHOICE', '{"A": "Anh, Pháp, Nhật, Italia.", "B": "Liên Xô, Mỹ, Anh, Pháp.", "C": "Đức, Áo, Hung, Bỉ.", "D": "Anh, Pháp, Đức, Italia."}', 'D', 'Ngày 29/9/1938, Hội nghị Muy-ních được triệu tập với sự tham gia của người đứng đầu các chính phủ Anh, Pháp, Đức, Italia.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(118, 'Nhật Hoàng tuyên bố đầu hàng đồng minh vào ngày tháng năm nào?', 'SINGLE_CHOICE', '{"A": "15/08/1945.", "B": "30/08/1945.", "C": "25/08/1945.", "D": "05/08/1945."}', 'A', 'Ngày 15/8/1945, Nhật Hoàng tuyên bố đầu hàng đồng minh không điều kiện.Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(119, 'Anh và Pháp phải chịu một phần trách nhiệm về sự bùng nổ cuộc Chiến tranh thế giới thứ hai (1939 - 1945) vì:', 'SINGLE_CHOICE', '{"A": "thực hiện chính sách nhượng bộ phát xít.", "B": "không tham gia khối Đồng minh chống phát xít.", "C": "thực hiện chính sách hòa bình, trung lập.", "D": "ngăn cản việc thành lập liên minh chống phát xít."}', 'A', 'Anh và Pháp phải chịu một phần trách nhiệm về sự bùng nổ cuộc Chiến tranh thế giới thứ hai (1939 - 1945) vì: thực hiện chính sách nhượng bộ phát xít. Điều này được thể hiện rõ trong Hội nghị Muy-ních.Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(120, 'Nguyên nhân chủ yếu dẫn đến hai cuộc chiến tranh thế giới trong thế kỉ XX là do', 'SINGLE_CHOICE', '{"A": "cuộc khủng hoảng kinh tế thế giới diễn ra trầm trọng.", "B": "âm mưu muốn bá chủ thế giới của Đức và Nhật Bản.", "C": "mâu thuẫn giữa các nước đế quốc xung quanh về vấn đề thuộc địa.", "D": "các nước Anh, Pháp, Mĩ dung dưỡng, nhượng bộ với phát xít."}', 'C', 'Nguyên nhân chủ yếu dẫn đến hai cuộc chiến tranh thế giới trong thế kỉ XX là do mâu thuẫn giữa các nước đế quốc xung quanh về vấn đề thuộc địa.Chọn C', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(121, 'Nguyên nhân nào thúc đẩy các quốc gia trên thế giới hình thành liên minh chống phát xít?', 'SINGLE_CHOICE', '{"A": "Do uy tín của Liên Xô đã tập hợp được các nước khác.", "B": "Do hành động xâm lược, bành trướng của phe phát xít khiến thế giới lo ngại.", "C": "Do Anh, Mĩ đều thua nhiều trận trên chiến trường.", "D": "Do nhân dân các nước trên thế giới đoàn kết."}', 'B', '- Đáp án A loại vì đây chỉ là 1 trong các nguyên nhân thúc đẩy sự hợp tác giữa các nước lớn chống lại phe phát xít.- Đáp án B đúng vì hành động xâm lược của phe phát xít đã làm cho các nước lo ngại. Cụ thể là Anh, Pháp sau đó có Mĩ đã bắt tay với Liên Xô để cùng chống lại các nước phát xít.- Đáp án C loại vì lúc này Anh chưa thất bại trên chiến trường (Anh có ưu thế về hải quân, không quân và có sự viện trợ của Mĩ nên kế hoạch đổ bộ lên nước Anh của quân Đức không thực hiện được).- Đáp án D loại vì thực tế chiến trường cho thấy chỉ có một số nước lớn tham chiến.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(122, 'Cuộc chiến đấu chống thực dân Pháp của quân dân Việt Nam ở mặt trận Đà Nẵng (1858)', 'SINGLE_CHOICE', '{"A": "Bước đầu làm thất bại kế hoạch đánh nhanh thắng nhanh của Pháp.", "B": "Buộc pháp phải lập tức chuyển hướng tiến công cửa biển Thuận An.", "C": "Làm phá sản hoàn toàn kế hoạch đánh nhanh thắng nhanh của Pháp.", "D": "Buộc pháp phải lập tức thực hiện kế hoạch tấn công bắc kì."}', 'A', 'Cuộc chiến đấu chống thực dân Pháp của quân dân Việt Nam ở mặt trận Đà Nẵng (1858) đã bước đầu làm thất bại kế hoạch đánh nhanh thắng nhanh của Pháp.Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(123, 'Trước khi thực dân Pháp xâm lược (1858), Việt Nam là một quốc gia', 'SINGLE_CHOICE', '{"A": "dân chủ, có chủ quyền.", "B": "độc lập, có chủ quyền.", "C": "độc lập trong Liên bang Đông Dương.", "D": "tự do trong Liên bang Đông Dương."}', 'B', 'Trước khi thực dân Pháp xâm lược (1858), Việt Nam là một quốc gia độc lập, có chủ quyền.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(124, 'Nước tư bản nào đã liên quân với Pháp để tấn công Đà Nẵng vào 1858?', 'SINGLE_CHOICE', '{"A": "Anh.", "B": "Bồ Đào Nha.", "C": "Tây Ban Nha.", "D": "Hà Lan."}', 'C', 'Sau nhiều lần đưa quân đến khiêu khích, chiều 31 – 8 – 1858 liên quân Pháp – Tây Ban Nha với khoảng 30000 binh lính và sĩ quan, bố trí trên 14 chiến thuyền kéo tới dàn trận trước cửa biển Đà Nẵng.Chọn C', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(125, 'Thực dân Pháp đã chiếm gọn ba tỉnh miền Tây Nam Kì (1867) mà không tốn một viên đạn vì', 'SINGLE_CHOICE', '{"A": "thực dân Pháp tấn công bất ngờ.", "B": "nhân dân không ủng hộ triều đình chống Pháp.", "C": "quân đội triều đình trang bị vũ khí quá kém.", "D": "triều đình bạc nhược, thiếu kiên quyết chống Pháp."}', 'D', 'Lợi dụng sự bạc nhược, thiếu kiên quyết của triều đình Huế, Pháp đã chiếm trọn 3 tỉnh miền Tây Nam Kì (Vĩnh Long, An Giang, Hà Tiên) mà không tốn một viên đạn.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(126, 'Vì sao thực dân Pháp chiếm được 3 tỉnh miền Tây Nam Kì năm 1867 một cách nhanh chóng?', 'SINGLE_CHOICE', '{"A": "Triều đình bạc nhược, thiếu kiên quyết chống Pháp.", "B": "Thực dân Pháp tấn công bất ngờ.", "C": "Nhân dân không ủng hộ triều đình chống Pháp.", "D": "Quân đội triều đình trang bị vũ khí quá kém."}', 'A', '- Đáp án A lựa chọn vì nếu triều đình cùng nhân dân ta kiến quyết chống Pháp thì đã không bỏ lỡ cơ hội đánh thắng Pháp hoàn toàn.- Đáp án B loại vì việc thực dân Pháp tấn công bất ngờ chỉ là 1 yếu tố khách quan, nó không quyết định việc 3 tỉnh miền Tây nhanh chóng bị đánh chiếm.- Đáp án C loại vì nhân dân muốn cùng triều đình chống Pháp nhưng triều đình vì quyền lợi giai cấp mà từng bước quay lưng lại với cuộc kháng chiến của nhân dân.- Đáp án D loại vì trang bị vũ khí yếu kém chỉ là 1 yếu tố khách quan, nó cũng có ảnh hưởng nhưng không phải yếu tố quyết định. Thực tế, từ 1858 – 1862, vũ khí của triều đình và nhân dân thô sơ nhưng vẫn khiến cho quân Pháp nhiều phen hoang mang. Kế hoạch đánh nhanh thắng nhanh của chúng đã bị phá sản và phải chuyển sang kế hoạch chinh phục từng gói nhở. Chính sự bạc nhược của triều đình mà quân Pháp đã nhanh chóng chiếm được 3 tỉnh miền Tây Nam Kì năm 1867 chỉ trong vòng 5 ngày.Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(127, 'Đâu không phải là hành động của nhân dân Bắc Kì khi Gác-ni-ê đưa quân tấn công Bắc Kì lần thứ nhất năm 1873?', 'SINGLE_CHOICE', '{"A": "Đốt kho thuốc súng của Pháp.", "B": "Bất hợp tác với Pháp.", "C": "Bỏ thuốc độc vào các giếng nước uống.", "D": "Tìm cách thỏa hiệp với Pháp."}', 'D', 'Nội dung đáp án D không phải là hành động của nhân dân Bắc Kì khi Gác-ni-ê đưa quân tấn công Bắc Kì lần thứ nhất năm 1873.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(128, 'Hiệp ước nào đánh dấu việc triều đình nhà Nguyễn chính thức thừa nhận sáu tỉnh Nam Kì là đất thuộc Pháp?', 'SINGLE_CHOICE', '{"A": "Hiệp ước Hácmăng.", "B": "Hiệp ước Giáp Tuất.", "C": "Hiệp ước Patơnốt.", "D": "Hiệp ước Nhâm Tuất."}', 'B', 'Với Hiệp ước Giáp Tuất (1874), triều đình nhà Nguyễn chính thức thừa nhận sáu tỉnh Nam Kì là đất thuộc Pháp.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(129, 'Thất bại tại trận Cầu Giấy lần thứ hai (19/5/1883) đã khiến thực dân Pháp', 'SINGLE_CHOICE', '{"A": "Càng củng cố dã tâm xâm chiếm hoàn toàn Việt Nam.", "B": "Hoang mang lo sợ và tìm cách thương thuyết để rút khỏi Bắc Kỳ.", "C": "Cầu cứu sự chi viện của triều đình Mãn Thanh.", "D": "Quyết định đánh thẳng vào Huế để kết thúc chiến tranh."}', 'A', 'Sau thất bại tại trận Cầu Giấy lần thứ hai (19/5/1883), khác với lần trước, thực dân Pháp càng củng cố dã tâm xâm chiếm toàn bộ Việt NamChọn A&nbsp;', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(130, 'Chọn đáp án đúng để sắp xếp các Hiệp ước mà triều đình nhà Nguyễn kí với thực dân Pháp theo trình tự thời gian1. Hiệp ước Hác – măng.2. Hiệp ước Nhâm Tuất.3. Hiệp ước Pa - tơ – nốt.4. Hiệp ước Giáp Tuất.', 'SINGLE_CHOICE', '{"A": "2 – 4 – 1 – 3.", "B": "2 – 3 – 1 - 4.", "C": "3 - 2 - 4 - 1.", "D": "1 - 2 - 3 - 4."}', 'A', '2. Hiệp ước Nhâm Tuất (1862).4. Hiệp ước Giáp Tuất (1874).1. Hiệp ước Hác – măng (1883).3. Hiệp ước Pa - tơ – nốt (1884).Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(131, 'Câu nói của Nguyễn Trung Trực “Bao giờ người Tây nhổ hết cỏ nước Nam thì mới hết người Nam đánh Tây” thể hiện điều gì?', 'SINGLE_CHOICE', '{"A": "Ý chí độc lập, tự chủ của dân tộc Việt Nam.", "B": "Quyết tâm đánh Pháp của nhân dân Việt Nam.", "C": "Lòng căm thù giặc sâu sắc của nhân dân Việt Nam.", "D": "Tinh thần đoàn kết chống ngoại xâm của nhân dân Việt Nam."}', 'B', 'Khi bị giặc bắt đem đi hành hình, Nguyễn Trung Trực đã khảng khái nói: “Bao giờ người Tây nhổ hết cỏ nước Nam thì mới hết người Nam đánh Tây”.&nbsp;Câu nói này thể hiện quyết tâm đánh Pháp không chỉ của riêng Nguyễn Trung Trực mà nó còn đại diện cho quyết tâm của toàn thể nhân dân Việt Nam.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(132, 'Cuộc khởi nghĩa tiêu biểu nhất trong phong trào Cần vương là', 'SINGLE_CHOICE', '{"A": "khởi nghĩa Bãi Sậy.", "B": "khởi nghĩa Hùng Lĩnh.", "C": "khởi nghĩa Ba Đình.", "D": "khởi nghĩa Hương Khê."}', 'D', 'Cuộc khởi nghĩa tiêu biểu nhất trong phong trào Cần Vương là cuộc khởi nghĩa Hương Khê, bởi vì:- Quy mô, địa bàn hoạt động rộng lớn, gồm 4 tỉnh bắc Trung Kì: Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình.- Trình độ tổ chức quy củ: gồm 15 quân thứ, mỗi quân thứ có từ 100 đến 500 người do các tướng lĩnh tài ba chỉ huy.- Thời gian tồn tại dài nhất trong các cuộc khởi nghĩa của phong trào Cần Vương, 10 năm từ năm 1885 đến năm 1896.- Khởi nghĩa thất bại đánh dấu mốc kết thúc của phong trào đấu tranh chống Pháp dưới ngọn cờ Cần vương.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(133, 'Nét nổi bật của phong trào Cần vương ở giai đoạn hai (1888 – 1896) là gì ?', 'SINGLE_CHOICE', '{"A": "Đặt dưới sự chỉ huy thống nhất của triều đình kháng chiến.", "B": "Đặt dưới sự chỉ huy gián tiếp của triều đình kháng chiến.", "C": "Không có sự chỉ huy của triều đình, các cuộc khởi nghĩa nổ ra lẻ tẻ.", "D": "Phong trào phát triển theo chiều sâu, quy tụ thành những trung tâm lớn."}', 'D', 'Nét nổi bật của phong trào Cần Vương ở giai đoạn hai (1888 – 1896) là: Phong trào phát triển theo chiều sâu, quy tụ thành những trung tâm lớn.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(134, 'Nhận xét nào dưới đây phản ánh đúng tính chất của phong trào Cần vương (1885 – 1896) ở Việt Nam?', 'SINGLE_CHOICE', '{"A": "Phong trào đấu tranh có tính chất cải lương.", "B": "Yêu nước nhưng không mang tính cách mạng.", "C": "Phong trào đấu tranh tự phát, không có tổ chức.", "D": "Phong trào yêu nước và mang tính cách mạng."}', 'B', '- Đáp án B phản ánh đúng tính chất của phong trào Cần vương vì:+ Nhiệm vụ: chống Pháp, giải phóng dân tộc, xây dựng chế độ phong kiến với vua hiền, tôi giỏi.+ Lãnh đạo: giai đoạn 1885 - 1888 là vua Hàm Nghi, Tôn Thất Thuyết; giai đoạn 1888 - 1896 là văn thân, sĩ phu yêu nước tiến bộ.+ Khuynh hướng: phong kiến.→ Mang tính yêu nước nhưng không mang tính cách mạng.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(135, 'Điểm chung và cũng là ưu điểm lớn nhất của phong trào yêu nước chống Pháp cuối thế kỉ XIX là', 'SINGLE_CHOICE', '{"A": "Tập hợp đông đảo các giai cấp tầng lớp trong xã hội.", "B": "Khởi nghĩa vũ trang theo phạm trù phong kiến.", "C": "Xác định đúng đối tượng đấu tranh là thực dân Pháp.", "D": "Làm chậm quá trình xâm lược Việt Nam của Pháp."}', 'C', '- Đáp án A loại vì đây là điểm chung nhưng không phải ưu điểm lớn nhất.- Đáp án B loại vì phong trào nông dân Yên Thế không theo phạm trù phong kiến.- Đáp án C chọn vì lúc này phong trào đấu tranh đều xác định là chống Pháp.- Đáp án D loại vì với Hiệp ước Pa tơ nốt năm 1884 giữa triều đình nhà Nguyễn và thực dân Pháp thì thực dân Pháp đã cơ bản hoàn thành công cuộc xâm lược Việt Nam. Phong trào yêu nước chống Pháp cuối thế kỉ XIX đã làm chậm quá trình bình định Việt Nam của thực dân Pháp.Chọn C', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(136, 'Chủ nghĩa Mác –Lê nin được truyền bá, phát triển nhanh chóng và sâu rộng ở Trung Quốc sau sự kiện nào?', 'SINGLE_CHOICE', '{"A": "Phong trào Đồng minh hội.", "B": "Phong trào Nghĩa hòa đoàn.", "C": "Cách mạng Tân Hợi 1911.", "D": "Phong trào Ngũ Tứ 1919."}', 'D', 'Từ sau phong trào Ngũ Tứ, chủ nghĩa Mác –Lê nin được truyền bá, phát triển nhanh chóng và sâu rộng ở Trung Quốc.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(137, 'Phong trào Ngũ tứ năm 1919 ở Trung Quốc là phong trào đấu tranh của', 'SINGLE_CHOICE', '{"A": "học sinh, sinh viên, công nhân.", "B": "giai cấp nông dân, công nhân.", "C": "giai cấp tư sản, tiểu tư sản.", "D": "giai cấp tiểu tư sản, nông dân."}', 'A', 'Phong trào Ngũ tứ năm 1919 ở Trung Quốc là phong trào đấu tranh của học sinh, sinh viên, công nhân.Chọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(138, 'Phong trào Ngũ tứ (1919) đã khắc phục được hạn chế lớn nhất của các phong trào đấu tranh ở Trung Quốc giai đoạn trước là', 'SINGLE_CHOICE', '{"A": "Có sự tham gia đông đảo của các tầng lớp nhân dân.", "B": "Có sự lãnh đạo của một chính đảng thống nhất.", "C": "Kết hợp cả chống đế quốc và chống phong kiến tay sai.", "D": "Diễn ra trên quy mô rộng lớn, có sự thống nhất."}', 'C', 'Hạn chế lớn nhất của các phong trào đấu tranh ở Trung Quốc giai đoạn trước là không có sự kết hợp giữa nhiệm vụ chống đế quốc và chống phong kiến tay sai. Đến phong trào Ngũ tứ hạn chế này đã được khắc phục khi kết hợp đồng thời cả 2 nhiệm vụ phản đế và phản phong, giương cao khẩu hiệu “Trung Quốc của người Trung Quốc”,&nbsp;“giết hết bọn giặc bán nước”,&nbsp;….Chọn C', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(139, 'Mục tiêu đấu tranh của giai cấp tư sản dân tộc ở các nước Đông Nam Á giữa hai cuộc chiến tranh thế giới (1918 –1939) là', 'SINGLE_CHOICE', '{"A": "quyền tự do, dân chủ, cơm áo, hòa bình.", "B": "đánh đổ đế quốc, giải phóng dân tộc.", "C": "đòi các nước đế quốc trao trả độc lập.", "D": "đòi tự do kinh doanh, tự chủ chính trị."}', 'D', 'Mục tiêu đấu tranh của giai cấp tư sản dân tộc ở các nước Đông Nam Á giữa hai cuộc chiến tranh thế giới (1918 –1939) là đấu tranh đòi quyền tự do kinh doanh, tự chủ chính trị.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(140, 'Tình hình chính trị ở các nước Đông Nam Á sau chiến tranh thế giới thứ nhất có điểm chung nào?', 'SINGLE_CHOICE', '{"A": "Chế độ quân chủ chuyên chế vẫn tồn tại", "B": "Chính quyền thực dân khống chế về chính trị", "C": "Các nước giành quyền tự chủ trong chừng mực nhất định", "D": "Nền thống trị thực dân bị sụp đổ hoàn toàn"}', 'B', 'Về chính trị: mặc dù thể chế ở các nước khác nhau nhưng đều có điểm chung là do chính quyền thực dân khống chế. Toàn bộ quyền hành đều tập trung trong tay một đại diện của chính quyền thuộc địa hay chịu ảnh hưởng của các nước TB thực dânChọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(141, 'Nhân tố nào quy định phong trào đấu tranh chống Pháp của nhân dân Lào và Campuchia sau Chiến tranh thế giới thứ nhất chưa giành được thắng lợi?', 'SINGLE_CHOICE', '{"A": "Phong trào còn mang tính tự phát", "B": "Không lôi kéo được đông đảo nhân dân lao động tham gia", "C": "Nội bộ những người lãnh đạo có sự chia rẽ, mất đoàn kết", "D": "Sự xung đột gay gắt giữa hai dân tộc Campuchia và Lào"}', 'A', 'Sau chiến tranh thế giới thứ nhất, mặc dù diễn ra sôi nổi, quyết liệt nhưng phong trào&nbsp;đấu tranh chống Pháp của nhân dân Lào và Campuchia chưa giành được thắng lợi là do phong trào còn mang tính tự phát nên thực dân Pháp dễ dàng tập trung lực lượng để đàn ápChọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(142, 'Chiến tranh thế giới thứ hai không diễn ra ở châu lục nào?&nbsp;', 'SINGLE_CHOICE', '{"A": "Châu Âu.", "B": "Châu Á.", "C": "Châu Mĩ.", "D": "Châu Phi."}', 'C', 'Chiến tranh thứ hai diễn ra ở Đông và Nam Âu (châu Âu), Bắc Phi (châu Phi), Thái Bình Dương (châu Á).Chọn C', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(143, 'Hậu quả của Đệ Nhị thế chiến đối với con người kinh khủng như thế nào?', 'SINGLE_CHOICE', '{"A": "1 triệu người chết, 500.000 người bị thương.", "B": "60 triệu người chết, 90 triệu người bị thương.", "C": "120 triệu người chết, 5 triệu người bị thương.", "D": "Hàng vạn người chết và bị thương."}', 'B', 'Hậu quả của Đệ Nhị thế chiến đối với con người là vô cùng nặng nề: 60 triệu người chết, 90 triệu người bị thương.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(144, 'Vì sao nước Mĩ không bị Chiến tranh thế giới thứ hai tàn phá?', 'SINGLE_CHOICE', '{"A": "Mĩ không tham gia vào cuộc chiến tranh.", "B": "Mĩ tham gia chiến tranh một cách khôn ngoan.", "C": "Mĩ tham gia chiến tranh muộn hơn các nước.", "D": "Chiến tranh đã không xảy ra trên đất Mĩ."}', 'D', 'Nước Mĩ không bị Chiến tranh thế giới thứ hai tàn phá vì cuộc chiến tranh đã không xảy ra trên đất Mĩ.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(145, 'Liên Xô đã có thái độ như thế nào với các nước phát xít?', 'SINGLE_CHOICE', '{"A": "Coi chủ nghĩa phát xít là kẻ thù nguy hiểm và ngay lập tức tuyên chiến với phát xít Đức.", "B": "Coi chủ nghĩa phát xít là đối tác trong cuộc chiến chống các nước đế quốc Anh, Pháp, Mĩ.", "C": "Lo sợ chủ nghĩa phát xít là kẻ thù nguy hiểm nên nhân nhượng với các nước phát xít.", "D": "Coi chủ nghĩa phát xít là kẻ thù nguy hiểm nên chủ trương liên kết với các nước Anh, Pháp để chống phát xít và nguy cơ chiến tranh."}', 'D', '- Đáp án A loại vì lúc này Liên Xô chưa tuyên chiến ngay lập tức với Đức mà đàm phán với Đức để tránh 1 cuộc chiến tranh và bảo vệ lợi ích quốc gia trong tình thế bị các nước tư bản cô lập.- Đáp án B loại vì không có hoạt động nào chứng tỏ Liên Xô coi chủ nghĩa phát xít là đối tác.- Đáp án C loại vì chỉ có Anh, Pháp nhân nhượng Đức trong Hội nghị Muy-ních.- Đáp án D đúng vì với các hoạt động xâm lược của phe phát xít, Liên Xô đã coi chủ nghĩa phát xít là kẻ thù nguy hiểm nên chủ trương liên kết với các nước Anh, Pháp để chống phát xít và nguy cơ chiến tranh.Chọn D', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(146, 'Yếu tố nào không tác động đến sự hình thành khối Đồng minh chống phát xít trong Chiến tranh thế giới thứ hai (1939-1945)?', 'SINGLE_CHOICE', '{"A": "Sự thay đổi thái độ của các chính phủ Anh, Mĩ.", "B": "Chiến thắng Xtalingrat của nhân dân Liên Xô.", "C": "Sự kiện Liên Xô tham chiến.", "D": "Hành động xâm lược của phe phát xít."}', 'B', '- Các đáp án A. C, D: đều là nguyên nhân dẫn đến hình thành khối đồng minh chống phát xít trong Chiến tranh thế giới thứ hai. (sgk 11 trang 97).- Đáp án B: (sgk 11 trang 97): Xét về mặt thời gian, khối đồng minh chống phát xít được hình thành vào tháng 1-1942, trong khi đó chiến thắng Xtalingrat diễn ra sau (11/1942 đến 2/1943).=&gt; Chiến thắng Xtaligrat của nhân dân Liên Xô không phải nhân tố tác động đến sự hình thành của khối Đồng minh chống phát xít trong Chiến tranh thế giới thứ hai (1939 – 1945).Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(147, 'Cuối thế kỉ XIX, trước nguy cơ xâm lược của các nước tư bản phương Tây, triều đình nhà Nguyễn đã thi hành chính sách nào?', 'SINGLE_CHOICE', '{"A": "Tự do tôn giáo.", "B": "Bế quan tỏa cảng.", "C": "Cải cách văn hóa.", "D": "Cải cách, mở cửa."}', 'B', 'Cuối thế kỉ XIX, trước nguy cơ xâm lược của các nước tư bản phương Tây, triều đình nhà Nguyễn đã thi hành chính sách “Bế quan tỏa cảng”.Chọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(148, 'Sau khi ký hiệp ước Nhâm Tuất 1862, triều đình Huế đã có hành động gì?', 'SINGLE_CHOICE', '{"A": "Đàn áp cuộc kháng chiến chống pháp của nhân dân Nam Kì.", "B": "Ra lệnh giải tán nghĩa binh chống pháp ở ba tỉnh miền Đông Nam Kì.", "C": "Tập trung binh lực sẵn sàng giúp thực dân pháp đàn áp nhân dân.", "D": "Giúp Pháp đàn áp cuộc kháng chiến của nhân dân ba tỉnh Nam Kì."}', 'B', 'Thực hiện những điều đã cam kết với Pháp trong hiệp ước 1862, triều đình Huế ra lệnh giải tán nghĩa binh chống Pháp ở các tỉnh Gia Định, Định Tường, Biên HòaChọn B', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(149, 'Khi quân Pháp bị sa lầy ở Đà Nẵng và Gia Định (1858-1860), thái độ của triều đình nhà Nguyễn là gì?', 'SINGLE_CHOICE', '{"A": "Phân hoá theo tư tưởng chủ hoà.", "B": "Không có hành động đối phó nào.", "C": "Phân hoá theo tư tưởng chủ chiến.", "D": "Tiếp tục chờ đợi quân pháp suy yếu hơn."}', 'A', 'Pháp bị sa lầy ở cả hai mặt trận ( Đà Nẵng và Gia Định) rơi vào tình thế tiến thoái lưỡng nan. Lúc này trong triều đình Nhà Nguyễn có sự phân hóa, tu tưởng chủ hòa lan ra làm lòng người li tánChọn A', 6);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(150, 'Người đã kháng lệnh triều đình, phất cao ngọn cờ “Bình Tây Đại nguyên soái”, lãnh đạo nghĩa quân chống Pháp là ai?', 'SINGLE_CHOICE', '{"A": "Nguyễn Tri Phương.", "B": "Nguyễn Trung Trực.", "C": "Phạm Văn Nghị.", "D": "Trương Định."}', 'D', 'Được sự ủng hộ của nhân dân, Trương Định đã phất cao lá cờ “Bình Tây Đại nguyên soái”, hoạt động của nghĩa quân đã củng cố niềm tin cho dân chúng, khiến bọn cướp nước và bán nước phải run sợ.Chọn D', 6);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(7, 'Đề thi thử giữa học kỳ 2 môn Vật Lý lớp 11 online - Mã đề 09', 'Vật Lý', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Vật Lý. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(151, 'Từ thông qua khung dây có diện tích S đặt trong từ trường đều đạt giá trị cực đại khi', 'SINGLE_CHOICE', '{"A": "các đường sức từ vuông góc với mặt phẳng khung dây", "B": "các đường sức từ song song với mặt phẳng khung dây.", "C": "các đường sức từ hợp với mặt phẳng khung dây góc 0o", "D": "các đường sức từ hợp với mặt phẳng khung dây góc 40o"}', 'A', 'Ta thấy từ thông: Φ = B.S.cosα cực đại khi cosα = 1 ↔ α = 0.Khi đó pháp tuyến&nbsp;n của mặt phẳng khung dây và véc tơ cảm ứng từ&nbsp;B.tức là các đường sức từ vuông góc với mặt phẳng khung dây.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(152, 'Phát biểu nào sau đây&nbsp;không&nbsp;đúng với định luật Len-xơ về chiều dòng điện cảm ứng ?', 'SINGLE_CHOICE', '{"A": "Nếu từ thông ban đầu qua mạch kín tăng thì từ trường cảm ứng ngược chiều từ trường ban đầu. Từ trường cảm ứng sẽ cùng chiều từ trường ban đầu nếu từ thông qua mạch kín giảm.", "B": "Dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho từ trường cảm ứng có tác dụng chống lại sự biến thiên của từ thông ban đầu qua mạch kín.", "C": "Khi từ thông qua mạch kín biến thiên do kết quả của một chuyển động nào đó thì từ trường cảm ứng có tác dụng chống lại chuyển động nói trên.", "D": "Từ trường của dòng điện cảm ứng luôn ngược chiều với từ trường ngoài sinh ra dòng điện cảm ứng."}', 'A', 'Chiều dòng điện cảm ứng – Định luật Lenxơ:Dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho từ trường của cảm ứng có tác dụng chống lại sự biến thiên của từ thông ban đầu qua mạch kín.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(153, 'Trường hợp nào sau đây từ thông qua vòng dây dẫn (C) biến thiên?', 'SINGLE_CHOICE', '{"A": "Vòng dây (C) đứng yên, nam châm chuyển động xuống dưới.", "B": "Nam châm và vòng dây dẫn (C) cùng chuyển động đều từ dưới lên trên với vận tốc v.", "C": "Nam châm và vòng dây dẫn (C) cùng chuyển động đều từ trên xuống dưới với vận tốc v.", "D": "Nam châm và vòng dây dẫn (C) đứng yên."}', 'A', 'Khi vòng dây (C) đứng yên, nam châm chuyển động xuống dưới thì số đường sức từ xuyên qua vòng dây thay đổi do đó từ thông qua vòng dây biến thiên, trong khung giây', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(154, 'Một khung dây có diện tích S được đặt song song với đường sức của từ trường đều có cảm ứng từ B. Qua khung dây một góc 90o&nbsp;thì từ thông qua khung sẽ', 'SINGLE_CHOICE', '{"A": "tăng thêm một lượng B.S", "B": "giảm đi một lượng B.S", "C": "tăng thêm một lượng 2B.S", "D": "giảm đi một lượng 2B.S"}', 'A', 'Lúc đầu khung dây đặt song song với đường sức từ: α = 90oSuy ra: Φ1&nbsp;= BScos90o&nbsp;= 0 WbKhi khung dây quay một góc 90o: α = 90o; Φ2&nbsp;= B.S.cos0o&nbsp;= B.STừ thông tăng thêm một lượng: ∆Φ = Φ2&nbsp;- Φ1&nbsp;= B.S. (Wb).', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(155, 'Trong hình a, nam châm đang chuyển động đến gần vòng dây dẫn kín, hình b vòng dây dẫn kín đang chuyển động đến gần nam châm. Dòng điện cảm ứng xuất hiện trên hai vòng dây dẫn kín có chiều', 'SINGLE_CHOICE', '{"A": "cùng chiều kim đồng hồ", "B": "ngược chiều kim đồng hồ", "C": "ngược chiều kim đồng hồ ở hình a, cùng chiều kim đồng hồ ở hình b", "D": "cùng chiều kim đồng hồ ở hình a, ngược chiều kim đồng hồ ở hình b"}', 'A', 'Trong cả hai trường hợp ở hình a, b, từ thông qua khung dẫn đều tăng. Theo định luật Len-xơ, chiều của véctơ cảm ứng từ ngược với ngược với chiều từ trường ban đầu.Áp dụng quy tắc nắm bàn tay phải ta xác định được chiều của dòng điện cảm ứng qua mỗi vòng dây như hình vẽ.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(156, 'Cảm ứng từ tại một điểm trong từ trường thì', 'SINGLE_CHOICE', '{"A": "Cùng hướng với hướng của từ trường tại điểm đó", "B": "Cùng hướng với lực từ tác dụng lên phần tử dòng điện đặt tại điểm đó", "C": "Có độ lớn tỉ lệ nghịch với độ lớn của lực từ tác dụng lên phần tử dòng điện đặt tạo điểm đó.", "D": "Có độ lớn tỉ lệ với cường độ của phần tử dòng điện đặt tại điểm đó"}', 'A', 'Tại mỗi điểm trong không gian có từ trường xác định một véctơ cảm ứng từ&nbsp;B luôn có hướng trùng với hướng của từ trường;', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(157, 'Điều nào sau đây là không đúng? Cảm ứng từ tại mỗi điểm trong từ trường', 'SINGLE_CHOICE', '{"A": "Tiếp tuyến với đường sức từ tại điểm đó", "B": "Cùng hướng với hướng của từ trường tại điểm đó", "C": "Đặc trưng cho khả năng tác dụng lực từ tại điểm đó là mạnh hay yếu", "D": "Có phương vuông góc với trục của kim nam châm thử nằm cân bằng tại điểm đó"}', 'A', 'Cảm ứng từ tại mỗi điểm trong từ trường luôn tiếp tuyến với đường sức từ tại điểm đó, có hướng trùng với hướng của từ trường tại điểm đó. Nó đặc trưng cho khả năng tác dụng lực từ tại điểm đó là mạnh hay yếu.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(158, 'Một phần tử dòng điện đặt vào trong một từ trường đều, lực từ tác dụng lên phần tử dòng điện có độ lớn nhỏ nhất khi', 'SINGLE_CHOICE', '{"A": "phần tử dòng điện nằm vuông góc với các đường sức từ", "B": "phần tử dòng điện nằm song song với các đường sức từ", "C": "phần tử dòng điện hợp với từ trường góc 45o", "D": "Tất cả đều đúng"}', 'A', 'Lực từ&nbsp;F&nbsp;tác dụng lên phần tử dòng điện I.l&nbsp;đặt trong từ trường đều, tại đó cảm ứng từ là&nbsp;B&nbsp;:- Có điểm đặt tại trung điểm của l;- Có phương vuông góc với&nbsp;l&nbsp;và&nbsp;B;- Có chiều tuân theo qui tắc bàn tay trái;- Có độ lớn: F = B.I.l.sinα với α là hợp bởi của véctơ&nbsp;B&nbsp;và chiều của IDo vậy F nhỏ nhất khi α = 0o&nbsp;hoặc 180o, tức là khi đó phần tử dòng điện nằm song song với các đường sức từ.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(159, 'Cảm ứng từ tại một điểm trong từ trường của dòng điện trong một dây dẫn&nbsp;không&nbsp;phụ thuộc vào', 'SINGLE_CHOICE', '{"A": "cường độ dòng điện", "B": "hình dạng của dây dẫn", "C": "môi trường xung quanh dây dẫn", "D": "tiết diện của dây dẫn"}', 'A', 'Cảm ứng từ&nbsp;B tại một điểm M* Tỉ lệ với cường độ dòng điện I gây ra từ trường;* Phụ thuộc dạng hình học của dây dẫn;* Phụ thuộc vào vị trí của điểm M;* Phụ thuộc vào môi trường xung quanh.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(160, 'Cảm ứng từ tại một điểm trong từ trường của dòng điện thẳng, rất dài không thay đổi khi điểm đó dịch chuyển', 'SINGLE_CHOICE', '{"A": "song song với dòng điện", "B": "vuông góc với dòng điện", "C": "trên một đường sức từ", "D": "trên một mặt trụ"}', 'A', 'Do vậy để cảm ứng từ không đổi khi điểm M dịch chuyển thì điểm M phải dịch chuyển theo đường song song với dòng điện.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(161, 'Trong hình vẽ, mũi tên nào đúng hướng của từ trường tạo ra bởi dòng điện trong ống dây thẳng, dài?', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "3", "D": "4"}', 'A', 'Véc tơ cảm ứng từ&nbsp;B do dòng điện chạy trong ống dây dài ở trong lòng ống dây (nơi có từ trường đều) có:Điểm đặt: tại điểm ta xét;Phương: song song với trục của ống dây;Chiều: xác định theo qui tắc nắm tay phải hoặc vào Nam ra Bắc.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(162, 'Khi một electron được bắn vào một từ trường đều theo phương vuông góc với các đường sức của từ trường. Đại lượng của electron không thay đổi theo thời gian là', 'SINGLE_CHOICE', '{"A": "vận tốc", "B": "gia tốc", "C": "động lượng", "D": "động năng"}', 'A', 'Khi một electron được bắn vào một từ trường đều theo phương vuông góc với các đường sức của từ trường thì các electron chuyển động tròn đều với véc tơ vận tốc&nbsp;v luôn thay đổi về hướng nhưng độ lớn không thay đổi, do đó động năng của electron không thay đổi.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(163, 'Một electron được bắn vào trong một từ trường đều theo phương vuông góc với các đường sức của từ trường. Quỹ đạo của electron trong từ trường là', 'SINGLE_CHOICE', '{"A": "một đường tròn", "B": "một đường parabon", "C": "một nửa đường thẳng", "D": "một đường elip"}', 'A', 'Một electron được bắn vào trong một từ trường đều theo phương vuông góc với các đường sức của từ trường nên lực Lo-ren-xơ luôn vuông góc với vận tốc&nbsp;v.Nếu bỏ qua tác dụng của trọng lực thì electron sẽ chuyển động theo quỹ đạo tròn trong từ trường.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(164, 'Một hạt mang điện chuyển động trên mặt phẳng (P) vuông góc với đường sức của một từ trường đều. Lực Lo-ren-xơ tác dụng lên hạt mang điện có', 'SINGLE_CHOICE', '{"A": "phương vuông góc với mặt phẳng (P)", "B": "độ lớn tỉ lệ với điện tích của hạt mang điện", "C": "chiều không phụ thuộc vào điện tích của hạt mang điện", "D": "độ lớn tỉ lệ nghịch với tốc độ của hạt mang điện"}', 'A', 'Lực Lo-ren-xơ do từ trường của cảm ứng từ&nbsp;B tác dụng nên một hạt điện tích q0&nbsp;chuyển động với vận tốc&nbsp;v:- Phương: vuông góc với&nbsp;v và&nbsp;B.- Chiều: tuân theo quy tắc bàn tay trái, phụ thuộc vào điện tích của hạt mang điện.- Độ lớn: f = |q0|.v.B.sinα. Trong đó α là góc tạo bởi&nbsp;v và&nbsp;B', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(165, 'Phát biểu nào sau đây&nbsp;không&nbsp;đúng khi nói về từ thông ?', 'SINGLE_CHOICE', '{"A": "Biểu thức định nghĩa của từ thông là Φ = B.S.cosα", "B": "Đơn vị của từ thông là vêbe (Wb)", "C": "Từ thông là một đại lượng đại số", "D": "Từ thông là một đại lượng có hướng."}', 'A', 'Từ thông qua diện tích S đặt trong từ trường đều: Φ = B.S.cosαTrong đó&nbsp;a&nbsp;là góc hợp bởi pháp tuyến&nbsp;n&nbsp;của mặt phẳng khung dây và véc tơ cảm ứng từ&nbsp;B.Đơn vị từ thông là vêbe (Wb): 1 Wb = 1 T.m2.Như vậy ta nhận thấy từ thông là một đại lượng đại số, vô hướng.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(166, 'Phát biểu nào về từ thông sau đây&nbsp;không&nbsp;đúng?', 'SINGLE_CHOICE', '{"A": "Từ thông là một đại lượng vô hướng", "B": "Từ thông qua mặt phẳng khung dây bằng 0 khi khung dây dẫn đặt trong từ trường có các đường sức từ song song với mặt phẳng khung dây", "C": "Từ thông qua một mặt kín luôn khác 0", "D": "Từ thông qua một mặt kín có thể bằng 0 hoặc khác 0"}', 'A', 'Từ thông qua diện tích S đặt trong từ trường đều: Φ = B.S.cosαTrong đó&nbsp;a&nbsp;là góc hợp bởi pháp tuyến&nbsp;n&nbsp;của mặt phẳng khung dây và véc tơ cảm ứng từ&nbsp;B→.Khi α = 90o&nbsp;thì Φ = 0. Do đó phát biểu C là sai.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(167, 'Đơn vị của từ thông có thể là', 'SINGLE_CHOICE', '{"A": "tesla trên mét (T/m)", "B": "tesla nhân với mét (T.m)", "C": "tesla trên mét bình phương (T/m2)", "D": "tesla nhân mét bình phương (T.m2)"}', 'A', 'Từ thông qua diện tích S đặt trong từ trường đều.Đơn vị từ thông là vêbe (Wb): 1 Wb = 1 T.m2.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(168, 'Cho một khung dây có điện tích S đặt trong từ trường đều, cảm ứng từ B, α là góc hợp bởi và pháp tuyến của mặt phẳng khung dây. Công thức tính từ thông qua S là:', 'SINGLE_CHOICE', '{"A": "Φ = B.S.cosα", "B": "Φ = B.S.sinα", "C": "Φ = B.S", "D": "Φ = B.S.tanα"}', 'A', 'Từ thông qua diện tích S đặt trong từ trường đều: Φ = B.S.cosαTrong đó&nbsp;a&nbsp;là góc hợp bởi pháp tuyến&nbsp;n&nbsp;của mặt phẳng khung dây và véc tơ cảm ứng từ&nbsp;B.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(169, 'Từ thông qua khung dây có diện tích S đặt trong từ trường đều đạt giá trị cực đại khi', 'SINGLE_CHOICE', '{"A": "các đường sức từ vuông góc với mặt phẳng khung dây", "B": "các đường sức từ song song với mặt phẳng khung dây", "C": "các đường sức từ hợp với mặt phẳng khung dây góc 0o", "D": "các đường sức từ hợp với mặt phẳng khung dây góc 40o"}', 'A', 'Ta thấy từ thông: Φ = B.S.cosα cực đại khi cosα = 1 ↔ α = 0.Khi đó pháp tuyến&nbsp;n&nbsp;của mặt phẳng khung dây và véc tơ cảm ứng từ&nbsp;B.tức là các đường sức từ vuông góc với mặt phẳng khung dây.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(170, 'Phát biểu nào sau đây&nbsp;không&nbsp;đúng với định luật Len-xơ về chiều dòng điện cảm ứng ?', 'SINGLE_CHOICE', '{"A": "Nếu từ thông ban đầu qua mạch kín tăng thì từ trường cảm ứng ngược chiều từ trường ban đầu. Từ trường cảm ứng sẽ cùng chiều từ trường ban đầu nếu từ thông qua mạch kín giảm.", "B": "Dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho từ trường cảm ứng có tác dụng chống lại sự biến thiên của từ thông ban đầu qua mạch kín.", "C": "Khi từ thông qua mạch kín biến thiên do kết quả của một chuyển động nào đó thì từ trường cảm ứng có tác dụng chống lại chuyển động nói trên.", "D": "Từ trường của dòng điện cảm ứng luôn ngược chiều với từ trường ngoài sinh ra dòng điện cảm ứng."}', 'A', 'Chiều dòng điện cảm ứng – Định luật Lenxơ:Dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho từ trường của cảm ứng có tác dụng chống lại sự biến thiên của từ thông ban đầu qua mạch kín.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(171, 'Trường hợp nào sau đây từ thông qua vòng dây dẫn (C) biến thiên?&nbsp;', 'SINGLE_CHOICE', '{"A": "Vòng dây (C) đứng yên, nam châm chuyển động xuống dưới.", "B": "Nam châm và vòng dây dẫn (C) cùng chuyển động đều từ dưới lên trên với vận tốc v.", "C": "Nam châm và vòng dây dẫn (C) cùng chuyển động đều từ trên xuống dưới với vận tốc v.", "D": "Nam châm và vòng dây dẫn (C) đứng yên."}', 'A', 'Khi vòng dây (C) đứng yên, nam châm chuyển động xuống dưới thì số đường sức từ xuyên qua vòng dây thay đổi do đó từ thông qua vòng dây biến thiên, trong khung giây', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(172, 'Một khung dây hình tròn có diện tích S = 2cm2&nbsp;đặt trong từ trường có cảm ứng từ B = 5.10-2T, các đường sức từ vuông góc với mặt phẳng khung dây. Từ thông qua mặt phẳng khung dây là', 'SINGLE_CHOICE', '{"A": "10-1Wb", "B": "10-2Wb", "C": "10-3Wb", "D": "10-5Wb"}', 'A', 'Các đường sức từ vuông góc với mặt phẳng khung dây.Từ thông qua mặt phẳng khung dây là:Φ = B.S.cosα = 5.10-2.2.10-4.cos0º = 10-5Wb.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(173, 'Một khung dây hình vuông, cạnh dài 4cm, đặt trong từ trường đều có cảm ứng từ B = 2.10-5T, các đường sức từ hợp với pháp tuyến của mặt phẳng khung dây góc 60o. Từ thông qua mặt phẳng khung dây là', 'SINGLE_CHOICE', '{"A": "1,6.10-6Wb", "B": "1,6.10-8Wb", "C": "3,2.10-8Wb", "D": "3,2.10-6Wb"}', 'A', 'Các đường sức từ hợp với pháp tuyến của mặt phẳng khung dây góc 60o&nbsp;nên:Khung dây hình vuông, cạnh dài 4cm có diện tích: S = 0,042&nbsp;= 1,6.10-3&nbsp;m2.Từ thông qua mặt phẳng khung dây là: Φ = B.S.cosα = 2.10-5.1,6.10-3.cos60o&nbsp;= 1,6.10-8Wb', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(174, 'Một khung dây hình vuông có cạnh dài 5cm, đặt trong từ trường đều có cảm ứng từ B = 4.10-5T, mặt phẳng khung dây tạo với các đường sức từ một góc 30o. Từ thông qua mặt phẳng khung dây nhận giá trị nào sau đây?', 'SINGLE_CHOICE', '{"A": "5.10-8Wb", "B": "5.10-6Wb", "C": "8,5.10-8Wb", "D": "8,5.10-6Wb"}', 'A', 'Mặt phẳng khung dây tạo với các đường sức từ một góc 30o&nbsp;nên:Khung dây hình vuông, cạnh dài 5cm có diện tích: S = 0,052&nbsp;= 2,5.10-3&nbsp;m2.Từ thông qua mặt phẳng khung dây là: Φ = B.S.cosα = 4.10-5.2,5.10-3.cos60o&nbsp;= 5.10-8Wb', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(175, 'Khi cho nam châm chuyển động qua một mạch kín, trong mạch xuất hiện dòng điện cảm ứng. Điện năng của dòng điện được chuyển hoá từ', 'SINGLE_CHOICE', '{"A": "hoá năng", "B": "quang năng", "C": "cơ năng", "D": "nhiệt năng"}', 'A', 'Khi cho nam châm chuyển động qua một mạch kín, trong mạch xuất hiện dòng điện cảm ứng. Cơ năng chuyển hoá thành điện năng của dòng điện.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(176, 'Một nam châm thẳng có từ trường hướng vào lòng ống dây. Trong trường hợp nào dưới đây suất điện động trong ống dây lớn nhất?', 'SINGLE_CHOICE', '{"A": "Nam châm tiến lại gần ống dây với tốc độ v", "B": "Ống dây tiến lại gần nam châm với tốc đọ v", "C": "Nam châm và ống dây tiến ra xa với tốc độ v", "D": "Nam châm và ống dây tiến lại gần nhau với tốc độ v"}', 'A', 'Nam châm và ống dây tiến lại gần nhau với tốc độ v, nghĩa là chúng chuyển động ngược chiều nhau, do đó vận tốc tương đối của chúng là 2v làm từ thông biến thiên nhanh nhất, suất điện động trong ống dây lớn nhất.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(177, 'Hệ số tự cảm (độ tự cảm) của ống dây có ý nghĩa vật lí gì?', 'SINGLE_CHOICE', '{"A": "cho biết số vòng dây của ống dây là lớn hay nhỏ", "B": "cho biết thế tích của ống dây là lớn hơn hay nhỏ", "C": "cho biết từ trường sinh ra là lớn hay nhỏ khi có dòng điện di qua", "D": "cho biết từ thông qua ống dây là lớn hay nhỏ khi có dòng điện đi qua"}', 'A', 'Hệ số tự cảm (độ tự cảm) của ống dây có ý nghĩa vật lí: cho biết từ thông qua ống dây là lớn hay nhỏ khi có dòng điện đi qua.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(178, 'Nhận xét nào sau đây là đúng về suất điện động tự cảm?', 'SINGLE_CHOICE', '{"A": "Suất điện động tự cảm có độ lớn tỉ lệ với độ biến thiên của cường độ dòng điện trong mạch.", "B": "Suất điện động tự cảm có độ lớn tỉ lệ với thời gian dòng điện chạy trong mạch", "C": "Suất điện động tự cảm có độ lớn tỉ lệ với tốc độ biến thiên của cường độ dòng điện trong mạch", "D": "Suất điện động tự cảm của ống dây không phụ thuộc vào độ tự cảm của ống dây"}', 'A', 'Suất điện động tự cảm có độ lớn tỉ lệ với tốc độ biến thiên cường độ dòng điện trong mạch', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(179, 'Trong thí nghiệm về hiện tượng tự cảm và ngắt mạch, người ta đưa lõi sắt vào trong lòng ống dây để', 'SINGLE_CHOICE', '{"A": "tăng điện trở của ống dây", "B": "tăng cường độ dòng điện qua ống dây", "C": "làm cho bóng đèn mắc trong mạch không bị cháy", "D": "tăng độ tự cảm của ống dây"}', 'A', 'Khi ta đưa lõi sắt vào trong lòng ống dây thì độ tự cảm của ống dây tăng lên.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(180, 'Đơn vị của độ tự cảm là', 'SINGLE_CHOICE', '{"A": "vôn (V)", "B": "henry (H)", "C": "tesla (T)", "D": "vêbe (Wb)."}', 'A', 'L (H - Henry): độ tự cảm của (C), phụ thuộc vào cấu tạo và kích thước của (C).', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(181, 'Kết luận nào sau đây là&nbsp;đúng về hiện tượng tự cảm?', 'SINGLE_CHOICE', '{"A": "Hiện tượng tự cảm không phải là hiện tượng cảm ứng điện từ.", "B": "Hiện tượng tự cảm không xảy ra ở các mạch điện xoay chiều.", "C": "Hiện tượng tự cảm là hiện tượng cảm ứng điện từ xảy ra trong một mạch có dòng điện mà sự biến thiên từ thông qua mạch được gây ra bởi sự biến thiên của cường độ dòng điện trong mạch.", "D": "Hiện tượng tự cảm là hiện tượng cảm ứng điện từ xảy ra trong một mạch có dòng điện mà sự biến thiên từ thông qua mạch được gây ra bởi sự biến thiên của từ trường bên ngoài mạch điện."}', 'A', 'Hiện tượng tự cảm là hiện tượng cảm ứng điện từ xảy ra trong một mạch có dòng điện mà sự biến thiên từ thông qua mạch được gây ra bởi sự biến thiên của cường độ dòng điện trong mạch.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(182, 'Khi nói về chiết suất của môi trường. Phát biểu nào sau đây là đúng?', 'SINGLE_CHOICE', '{"A": "Chiết suất tỉ đối của môi trường chiết quang lớn hơn so với môi trường chiết quang nhỏ thì nhỏ hơn đơn vị.", "B": "Môi trường chiết quang kém có chiết suất tuyệt đối nhỏ hơn 1.", "C": "Chiết suất tỉ đối của môi trường 2 so với môi trường 1 bằng tỉ số chiết suất tuyệt đối n2 của môi trường 2 với chiết suất tuyệt đối n1 của môi trường 1", "D": "Chiết suất tỉ đối của 2 môi trường luôn lớn hơn đơn vị vì tốc độ ánh sáng trong chân không là tốc độ lớn nhất"}', 'A', 'Chiết suất tỉ đối (n21) của môi trường 2 so với môi trường 1 bằng tỉ số chiết suất tuyệt đối n2&nbsp;của môi trường 2 với chiết suất tuyệt đối n1&nbsp;của môi trường 1.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(183, 'Nước và thuỷ tinh có chiết suất lần lượt là n1&nbsp;và n2. Chiết suất tỉ đối giữa thuỷ tinh và nước là', 'SINGLE_CHOICE', '{"A": "n21 = n1/n2", "B": "n21 = n2/n1", "C": "n21 = n2 - n1", "D": "n12 = n1 - n2"}', 'A', 'Chiết suất tỉ đối giữa thuỷ tinh và nước là: n21&nbsp;= n2/n1', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(184, 'Khi chiếu ánh sáng từ không khí vào nước thì', 'SINGLE_CHOICE', '{"A": "góc khúc xạ luôn nhỏ hơn góc tới", "B": "góc khúc xạ luôn lớn hơn góc tới", "C": "góc khúc xạ luôn bằng góc tới", "D": "khi góc tới tăng thì góc khúc xạ giảm."}', 'A', 'Khi chiếu ánh sáng từ không khí vào nước thì n1&nbsp;= 1, n2&nbsp;&gt; n1&nbsp;nên n21&nbsp;&gt; 1.Nên sini &gt; sinr ↔ i &gt; r. Vậy tia khúc xạ bị lệch gần pháp tuyến hơn tia tới', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(185, 'Chiếu một tia sáng đơn sắc đi từ không khí vào môi trường có chiết suất n với góc tới i. Tia phản xạ vuông góc với tia khúc xạ. Hệ thức nào sau đây là đúng?', 'SINGLE_CHOICE', '{"A": "sini = n", "B": "sini = 1/n", "C": "tani = n", "D": "tani = 1/n"}', 'A', 'Ta có: sini = n.sinr, mà sinr = cosi (do tia phản xạ vuông góc với tia khúc xạ nên i + r = 90o)', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(186, 'Chiếu một tia sáng đơn sắc đi từ không khí vào môi trường có chiết suất n với góc tới i có tani = n. Mối quan hệ giữa tia phản xạ và tia khúc xạ nào sau đây là đúng?', 'SINGLE_CHOICE', '{"A": "song song", "B": "hợp với nhau góc 60o", "C": "vuông góc", "D": "hợp với nhau góc 30o"}', 'A', 'Ta có: sini = n.sinrSuy ra sinr = cosi ↔ i + r = 90o, do vậy tia phản xạ vuông góc với tia khúc xạ.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(187, 'Khi nói về hiện tượng phản xạ toàn phần. Phát biểu nào sau đây sai?', 'SINGLE_CHOICE', '{"A": "Khi có phản xạ toàn phần thì hầu như toàn bộ ánh sáng phản xạ trở lại môi trường chứa chùm ánh sáng tới.", "B": "Phản xạ toàn phần chỉ xảy ra khi ánh sáng đi từ môi trường chiết quang hơn sang môi trường kém chiết quang hơn.", "C": "Phản xạ toàn phần xảy ra khi góc tới lớn hơn góc giới hạn phản xạ toàn phần", "D": "Góc giới hạn của phản xạ toàn phần được xác định bằng tỉ số chiết suất giữa môi trường chiết quang kém với môi trường chiết quang hơn."}', 'A', 'Điều kiện xảy ra phản xạ toàn phần+ Ánh sáng truyền từ môi trường chiết quang hơn sang môi trường chiết quang kém.+ Góc tới i phải lớn hơn hoặc bằng góc giới hạn.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(188, 'Chiếu một chùm tia sáng tới mặt phân cách giữa hai môi trường trong suốt. Khi xảy ra hiện tượng phản xạ toàn phần thì', 'SINGLE_CHOICE', '{"A": "cường độ ánh sáng của chùm khúc xạ gần bằng cường độ sáng của chùm tới", "B": "Cường độ ánh sáng của chùm tia phản xạ gần bằng cường độ sáng của chùm tới.", "C": "cường độ sáng của chùm tia phản xạ lớn hơn cường độ sáng của chùm tia tới", "D": "cường độ sáng của chùm tia tới, chùm tia phản xạ và chùm tia khúc xạ bằng nhau"}', 'A', 'Khi xảy ra hiện tượng phản xạ toàn phần thì cường độ ánh sáng của chùm tia phản xạ gần bằng cường độ sáng của chùm tới.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(189, 'Điều kiện cần để xảy ra hiện tượng phản xạ toàn phần nào sau đây là đúng?', 'SINGLE_CHOICE', '{"A": "Tia sáng tới đi từ môi trường có chiết suất nhỏ sang môi trường có chiết suất lớn hơn.", "B": "Tia sáng tới đi từ môi trường có chiết suất lớn hơn đến mặt phân cách với môi trường có chiết suất nhỏ hơn.", "C": "Tia sáng tới phải đi vuông góc với mặt phân cách giữa hai môi trường trong suốt", "D": "Tia sáng tới phải đi song song với mặt phân cách giữa hai môi trường trong suốt"}', 'A', 'Điều kiện xảy ra phản xạ toàn phần+ Ánh sáng truyền từ môi trường chiết quang hơn sang môi trường chiết quang kém.+ Góc tới i phải lớn hơn hoặc bằng góc giới hạn.', 7);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(190, 'Chọn câu sai? Từ trường tồn tại ở gần', 'SINGLE_CHOICE', '{"A": "một nam châm", "B": "một thanh thủy tinh được nhiễm điện do cọ xát", "C": "dây dẫn có dòng điện", "D": "chùm tia điện tử"}', 'A', 'Từ trường tồn tại ở quanh nam châm và quanh dòng điện.', 7);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(8, 'Đề thi thử THPT QG năm 2021 môn Vật Lý online - Đề thi của Trường THPT Tiên Du', 'Vật Lý', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Vật Lý. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(191, 'Trong dao động cưỡng bức, khi xảy ra hiện tượng cộng hưởng thì', 'SINGLE_CHOICE', '{"A": "tần số ngoại lực bằng tần số dao động riêng.", "B": "tần số ngoại lực lớn hơn tần số dao động riêng.", "C": "tần số ngoại lực nhỏ hơn tần số dao động riêng.", "D": "tần số ngoại lực rất lớn so với tần số dao động riêng."}', 'A', 'Khi xảy ra hiện tượng cộng hưởng, tần số ngoại lực bằng tần số dao động riêng.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(192, 'Trong dao động tắt dần chậm đại lượng không đổi theo thời gian là', 'SINGLE_CHOICE', '{"A": "tốc độ cực đại", "B": "chu kì", "C": "cơ năng", "D": "biên độ"}', 'A', 'Dao động tắt dần có chu kì không đổi theo thời gian.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(193, 'Véc tơ vận tốc của một vật dao động điều hòa luôn', 'SINGLE_CHOICE', '{"A": "hướng về vị trí cân bằng.", "B": "ngược hướng chuyển động.", "C": "hướng ra xa vị trí cân bằng.", "D": "cùng hướng chuyển động."}', 'A', 'Vận tốc của vật dao động điều hòa luôn cùng hướng chuyển động.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(194, 'Con lắc đơn có cấu tạo gồm', 'SINGLE_CHOICE', '{"A": "một khung dây tròn móc vào một cái đinh.", "B": "một vật nặng treo vào một sợi dây nhẹ, không dãn vào một điểm cố định.", "C": "một vật nặng gắn với đầu một lò xo có đầu kia cố định.", "D": "một vật nặng gắn với một thanh kim loại có khối lượng."}', 'A', 'Cấu tạo con lắc đơn gồm: một vật nặng treo vào một sợi dây nhẹ, không dãn vào một điểm cố định.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(195, 'Nguyên nhân gây ra dao động tắt dần của con lắc lò xo dao động trên mặt phẳng nằm ngang là', 'SINGLE_CHOICE', '{"A": "do trọng lực tác dụng lên vật.", "B": "do phản lực cản mặt phẳng ngang.", "C": "do ma sát giữa vật và mặt phẳng ngang.", "D": "do lực đàn hồi cản lò xo."}', 'A', 'Nguyên nhân gây ra dao động tắt dần của con lắc lò xo trên mặt phẳng ngang là do ma sát giữa vật và mặt phẳng ngang.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(196, 'Một con lắc lò xo đang dao động điều hòa, đại lượng nào sau đây của con lắc được bảo toàn?', 'SINGLE_CHOICE', '{"A": "Động năng.", "B": "Cơ năng và thế năng.", "C": "Động năng và thế năng.", "D": "Cơ năng."}', 'A', 'Trong dao động điều hòa của con lắc lò xo, cơ năng luôn được bảo toàn.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(197, 'Dao động của đồng hồ quả lắc là:&nbsp; &nbsp;', 'SINGLE_CHOICE', '{"A": "dao động cưỡng bức.", "B": "dao động tự do.", "C": "dao động duy trì.", "D": "dao động tắt dần."}', 'A', 'Dao động của đồng hồ quả lắc là dao động duy trì.', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(198, 'Một vật dao động điều hoà với biên độ A tần số góc ω, gia tốc cực đại là', 'SINGLE_CHOICE', '{"A": "$2\\omega A$", "B": "$\\omega A$", "C": "${{\\omega }^{2}}{{A}^{2}}$", "D": "${{\\omega }^{2}}A$"}', 'A', 'Gia tốc cực đại của dao động điều hòa: \({{a}_{\max }}={{\omega }^{2}}A\)', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(199, 'Một vật nhỏ dao động điều hòa có biên độ A. Quãng đường mà vật đi được trong 1 chu kì là:', 'SINGLE_CHOICE', '{"A": "4A.", "B": "A.", "C": "3A.", "D": "2A."}', 'A', 'Quãng đường vật đi được trong 1 chu kì là: \(S=4A\)', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(200, 'Có hai con lắc đơn mà độ dài của chúng khác nhau 22cm, dao động ở cùng một nơi. Trong cùng một khoảng thời gian, con lắc thứ nhất thực hiện được 30 dao động toàn phần, con lắc thứ hai thực hiện được 36 dao động toàn phần. Độ dài của các con lắc nhận giá trị nào sau đây:', 'SINGLE_CHOICE', '{"A": "${{l}_{1}}=78cm;{{l}_{2}}=110cm$", "B": "${{l}_{1}}=72cm;{{l}_{2}}=50cm$", "C": "${{l}_{1}}=50cm;{{l}_{2}}=72cm$", "D": "${{l}_{1}}=88cm;{{l}_{2}}=110cm$"}', 'A', '$27', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(201, 'Hai con lắc đơn giống hệt nhau mà các vật nhỏ mang điện tích như nhau, được treo ở một nơi trên mặt đất. Trong mỗi vùng không gian chứa mỗi con lắc có một điện trường đều. Hai điện trường này có cùng cường độ nhưng các đường sức vuông góc với nhau. Giữ hai con lắc ở vị trí các dây treo có phương thẳng đứng rồi thả nhẹ thì chúng dao động điều hòa trong cùng một mặt phẳng với biên độ góc ${{8}^{0}}$ và có chu kì tương ứng là ${{T}_{1}}$ và ${{T}_{2}}={{T}_{1}}+0,25s$. Giá trị của ${{T}_{2}}$ là', 'SINGLE_CHOICE', '{"A": "1,974s", "B": "2,274s", "C": "1,895s", "D": "1,645s"}', 'A', '$29', 8);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(202, 'Hai vật A và B có cùng khối lượng 0,5kg và có kích thước nhỏ được nối với nhau bởi sợi dây mảnh nhẹ dài 15cm, hai vật được treo vào lò xo có độ cứng $k=100N/m$ tại nơi có gia tốc trọng trường $g=10m/{{s}^{2}}$. Lấy ${{\pi }^{2}}=10$. Khi hệ vật và lò xo đang ở vị trí cân bằng người ta đốt sợi dây nối hai vật và vật B sẽ rơi tự do còn vật A sẽ dao động điều hòa. Lần đầu tiên vật A lên đến vị trí cao nhất thì khoảng cách giữa hai vật bằng bao nhiêu? Biết rằng độ cao đủ lớn.', 'SINGLE_CHOICE', '{"A": "50cm.", "B": "45cm.", "C": "40cm.", "D": "35cm."}', 'A', '$2a', 8);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(9, 'Thi thử tốt nghiệp THPT quốc gia môn Lịch Sử online - Đề thi của trường THPT Quang Bình năm 2022', 'Lịch Sử', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Lịch Sử. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(203, 'Ở Việt Nam, những giai cấp nào sau đây mới ra đời từ cuộc khai thác thuộc địa lần thứ hai (1919 - 1929) của thực dân Pháp?&nbsp;', 'SINGLE_CHOICE', '{"A": "Công nhân", "B": "Sĩ phu yêu nước", "C": "Dân chủ tiến bộ", "D": "Tư sản và tiểu tư sản"}', 'D', 'A loại&nbsp;và công nhận ra đời trong cuộc khai thác thuộc địa lần thứ nhất.B loại&nbsp;vì sĩ phu yêu nước không phải là giai cấp và đã có từ trước trong xã hội Việt Nam.C loại&nbsp;vì không có giai cấp nào là giai cấp dân chủ tiến bộ.D chọn&nbsp;vì trong cuộc khai thác thuộc địa lần thứ nhất, tư sản và tiểu tư sản mới chỉ là tầng lớp. Đến cuộc khai thác thuộc địa lần thứ hai thì tư sản và tiểu tư sản đã trở thành giai cấp.&nbsp;Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(204, 'Trong thời kỳ 1945 - 1946, để xây dựng và củng cố chính quyền cách mạng, Chính phủ và Quốc hội nước Việt Nam Dân chủ Cộng hòa đã thực hiện biện pháp nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Tổ chức Đại hội chiến sĩ thi đua và cán bộ gương mẫu toàn quốc", "B": "Tổ chức kháng chiến chống thực dân Pháp xâm lược ở miền Bắc", "C": "Ban hành Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa", "D": "Nhân nhượng quân Trung Hoa Dân quốc về kinh tế"}', 'C', 'Trong thời kỳ 1945 - 1946, để xây dựng và củng cố chính quyền cách mạng, Chính phủ và Quốc hội nước Việt Nam Dân chủ Cộng hòa đã thực hiện biện pháp ban hành Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa.&nbsp;Chọn C', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(205, 'Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam (đầu năm 1930) xác định nhân tố quyết định thắng lợi của cách mạng Việt Nam là&nbsp;', 'SINGLE_CHOICE', '{"A": "khối liên minh công - nông", "B": "sự đoàn kết với cách mạng thế giới", "C": "sự lãnh đạo của Đảng Cộng sản Việt Nam", "D": "khối đoàn kết của toàn dân tộc"}', 'C', 'A, D loại&nbsp;vì không phải là nhân tố quyết định thắng lợi của cách mạng Việt Nam.B loại&nbsp;vì là yếu tố khách quan không mang tính quyết định.C chọn&nbsp;vì sự lãnh đạo của Đảng Cộng sản Việt Nam là nhân tố quyết định thắng lợi của cách mạng Việt NamChọn C', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(206, 'Trong quá trình chuẩn bị tiến tới khởi nghĩa giành chính quyền (1941 - 1945), Đảng Cộng sản Đông Dương đã có chủ trương nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Giương cao khẩu hiệu cách mạng ruộng đất", "B": "Phát động Cao trào kháng Nhật cứu nước", "C": "Đặt nhiệm vụ đấu tranh giai cấp lên hàng đầu", "D": "Đưa Đảng ra hoạt động công khai, hợp pháp"}', 'B', 'A loại vì trong giai đoạn này Đảng chủ trương tạm gác khẩu hiệu cách mạng ruộng đất.B chọn&nbsp;vì trong giai đoạn 1941 – 1945, Đảng Cộng sản Đông Dương đã phát động Cao trào kháng Nhật cứu nước làm tiền đề cho Tổng khởi nghĩa tháng Tám năm 1945.C loại&nbsp;vì trong giai đoạn này Đảng đã chủ trương đưa vấn đề giải phóng dân tộc lên hàng đầu.&nbsp;D loại vì&nbsp;giai đoạn này Đảng chưa hoạt động công khai.Chọn B', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(207, 'Tại Hội nghị lanta (2 - 1945), ba cường quốc Mĩ, Anh, Liên Xô đã thông qua một trong những nội dung nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Trả lại cho Liên Xô phía Nam đảo Zakhalin và 4 đảo thuộc quần đảo Curin", "B": "Mĩ sẽ tham gia chống Nhật ở Thái Bình Dương sau khi đánh bại phát xít Đức", "C": "Liên Xô có phạm vi ảnh hưởng và hoạt động kiểm soát ở các nước Đông Dương", "D": "Giao cho quân Pháp, Anh làm nhiệm vụ giải giáp quân đội Nhật ở Đông Dương"}', 'A', 'Tại Hội nghị lanta (2 - 1945), ba cường quốc Mĩ, Anh, Liên Xô đã thông qua một trong những nội dung trả lại cho Liên Xô phía Nam đảo Zakhalin và 4 đảo thuộc quần đảo Curin.&nbsp;Chọn A.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(208, 'Trong cuộc chiến đấu chống chiến lược “Chiến tranh đặc biệt” (1961 - 1965) của Mĩ, quân dân miền Nam Việt Nam đã giành được thắng lợi quân sự nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Núi Thành (Quảng Nam)", "B": "Vạn Tường (Quảng Ngãi)", "C": "Bác Ái (Ninh Thuận)", "D": "An Lão (Bình Định)"}', 'D', 'Trong cuộc chiến đấu chống chiến lược “Chiến tranh đặc biệt” (1961 - 1965) của Mĩ, quân dân miền Nam Việt Nam đã giành được thắng lợi quân sự An Lão (Bình Định).Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(209, 'Trong những năm 1951 - 1953, để xây dựng hậu phương kháng chiến vững mạnh toàn diện, Đảng, Chính phủ Việt Nam Dân chủ Cộng hòa đã có hoạt động nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Tiến hành cải tạo quan hệ sản xuất và cải tạo xã hội chủ nghĩa", "B": "Kêu gọi tinh thần “nhường cơm sẻ áo”, lập hũ gạo cứu đói", "C": "Tiếp tục phát động phong trào “Tuần lễ vàng”, “Quỹ độc lập”", "D": "Thành lập Mặt trận Liên hiệp quốc dân Việt Nam (Liên Việt)"}', 'D', 'Trong những năm 1951 - 1953, để xây dựng hậu phương kháng chiến vững mạnh toàn diện, Đảng, Chính phủ Việt Nam Dân chủ Cộng hòa đã thành lập Mặt trận Liên hiệp quốc dân Việt Nam (Liên Việt).Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(210, 'Đại hội Quốc dân họp ở Tân Trào (Tuyên Quang, tháng 8 - 1945) đã&nbsp;', 'SINGLE_CHOICE', '{"A": "lập Ủy Ban khởi nghĩa toàn quốc và ra “Quân lệnh số 1”", "B": "thông qua 10 chính sách của Mặt trận Việt Minh", "C": "thông qua kế hoạch lãnh đạo toàn dân Tổng khởi nghĩa", "D": "chính thức phát lệnh Tổng khởi nghĩa cả nước"}', 'C', 'Đại hội Quốc dân họp ở Tân Trào (Tuyên Quang, tháng 8 - 1945) đã thông qua kế hoạch lãnh đạo toàn dân Tổng khởi nghĩa.&nbsp;Chọn C', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(211, 'Vào giữa thế kỷ XIX, trước nguy cơ xâm lược của các nước tư bản phương Tây, triều đình nhà Nguyễn thực hiện chính sách nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Bế quan tỏa cảng", "B": "Tự do tôn giáo", "C": "Cải cách, mở cửa", "D": "Cải cách văn hóa"}', 'A', 'Vào giữa thế kỷ XIX, trước nguy cơ xâm lược của các nước tư bản phương Tây, triều đình nhà Nguyễn thực hiện chính sách Bế quan tỏa cảng.Chọn A.&nbsp;', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(212, 'Phong trào “Đồng khởi” (1939 - 1960) của nhân dân miền Nam Việt Nam đã&nbsp;', 'SINGLE_CHOICE', '{"A": "làm lung lay tận gốc chính quyền tay sai Ngô Đình Diệm", "B": "đánh dấu sự thất bại hoàn toàn chiến lược “Chiến tranh đặc biệt” của Mĩ", "C": "giáng đòn nặng nề vào chiến lược “Việt Nam hóa chiến tranh” của Mĩ", "D": "độc lập dân tộc và ruộng đất dân cày. sở cà mau"}', 'A', 'Phong trào “Đồng khởi” (1939 - 1960) của nhân dân miền Nam Việt Nam đã làm lung lay tận gốc chính quyền tay sai Ngô Đình Diệm.&nbsp;Chọn A.&nbsp;', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(213, 'Hội nghị Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (3 - 1936) xác định mục đấu tranh trước mắt của cách mạng Đông Dương là&nbsp;', 'SINGLE_CHOICE', '{"A": "đòi nới rộng quyền dân sinh, dân chủ", "B": "tự do, dân chủ, cơm áo và hòa bình", "C": "thực hiện khẩu hiệu “Người cày có ruộng”", "D": "độc lập dân tộc và ruộng đất dân cày"}', 'B', 'Hội nghị Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (3 - 1936) xác định mục đấu tranh trước mắt của cách mạng Đông Dương là đấu tranh đòi tự do, dân chủ, cơm áo và hòa bình.Chọn B.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(214, 'Trong thời gian ở Trung Quốc (1924 - 1927), Nguyễn Ái Quốc đã có những hoạt động nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Đọc Sơ thảo luận cương về vấn đề dân tộc và thuộc địa của Lênin", "B": "Sáng lập Hội Liên hiệp thuộc địa và xuất bản báo Người cùng khổ", "C": "Tham dự Hội nghị quốc tế Nông dân và Đại hội Quốc tế Cộng sản", "D": "Thành lập Cộng sản đoàn và Hội Việt Nam Cách mạng Thanh niên"}', 'D', 'A loại&nbsp;vì Nguyễn Ái Quốc đọc Sơ thảo luận cương về vấn đề dân tộc và thuộc địa của Lênin năm 1920.B loại&nbsp;vì Nguyễn Ái Quốc lập Hội Liên hiệp thuộc địa và xuất bản báo Người cùng khổ năm 1921. C loại vì Nguyễn Ái Quốc tham dự Hội nghị quốc tế Nông dân (1923) và Đại hội Quốc tế Cộng sản (1924).Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(215, 'Trong phong trào cách mạng 1930 - 1931 ở Việt Nam, chính quyền Xô viết Nghệ - Tĩnh đã có hoạt động nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Ra mắt Hội Đồng minh phản đế Đông Dương", "B": "Phát động triệt để giảm tổ và cải cách ruộng đất", "C": "Lập các tổ chức để nhân dân giúp nhau sản xuất", "D": "Thành lập Hội Văn hóa cửu quốc Việt Nam"}', 'C', 'Trong phong trào cách mạng 1930 - 1931 ở Việt Nam, chính quyền Xô viết Nghệ - Tĩnh đã có hoạt động các tổ chức để nhân dân giúp nhau sản xuất.&nbsp;Chọn C', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(216, 'Trong thời kỳ 1945 - 1973, Liên Xô đạt được thành tựu nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Là quốc gia nắm độc quyền về sức mạnh bom nguyên tử", "B": "Khởi đầu cuộc cách mạng khoa học - kĩ thuật lần thứ hai", "C": "Phóng thành công vệ tinh nhân tạo đầu tiên của nhân loại", "D": "Trở thành một trung tâm kinh tế - tài chính lớn của thế giới"}', 'C', 'Trong thời kỳ 1945 - 1973, Liên Xô đạt được thành tựu là phóng thành công vệ tinh nhân tạo đầu tiên của nhân loại.Chọn C', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(217, 'Trong những năm 1953 - 1954, để triển khai kế hoạch Nava, Pháp đã thực hiện biện pháp nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Xin Mĩ tăng thêm viện trợ quân sự, chiếm tới 73% chi phí chiến tranh", "B": "Mở chiến dịch quy mô lớn tấn công lên căn cứ địa Việt Bắc lần hai", "C": "Tiến hành cuộc chiến tranh tổng lực, chiến tranh kinh tế, chiến tranh tâm lí", "D": "Xây dựng phòng tuyến công sự bao quanh trung du và đồng bằng Bắc Bộ"}', 'A', 'A chọn&nbsp;vì để triển khai kế hoạch Nava, Pháp đã xin Mĩ tăng thêm viện trợ quân sự, chiếm tới 73% chi phí chiến tranh.B loại&nbsp;vì trong kế hoạch Nava không có nội dung về mở chiến dịch quy mô lớn tấn công lên căn cứ địa Việt Bắc lần hai.C, D loại&nbsp;vì đây là nội dung thuộc kế hoạch Đà Lát đơ Tátxinhi.Chọn A', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(218, 'Cơ hội bên ngoài nào sau đây được các nước Tây Âu tận dụng để phát triển kinh tế từ sau Chiến tranh thế giới thứ hai?&nbsp;', 'SINGLE_CHOICE', '{"A": "Giá nguyên liệu rẻ từ các nước vốn là thuộc địa", "B": "Hợp tác toàn diện, chặt chẽ với tổ chức ASEAN", "C": "Cuộc chiến tranh xâm lược Việt Nam của Mĩ", "D": "Cuộc chiến tranh Triều Tiên (1950 – 1953)"}', 'A', 'A chọn&nbsp;vì các nước Tây Âu đã tận dụng giá nguyên liệu rẻ từ các nước vốn là thuộc địa để phát triển kinh tế từ sau Chiến tranh thế giới thứ hai.B loại&nbsp;và các nước Tây Âu không hợp tác toàn diện, chặt chẽ với tổ chức ASEAN để phát triển kinh tế từ sau Chiến tranh thế giới thứ hai.&nbsp;C, D loại vì&nbsp;chỉ đúng với Nhật Bản.Chọn A.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(219, 'Nội dung nào sau đây là một trong những biểu hiện của xu thế hòa hoãn Đông - Tây (từ đầu thập kỷ 70 của thế kỷ XX)?', 'SINGLE_CHOICE', '{"A": "Hiệp định đình chiến giữa hai miền Triều Tiên đã được ký kết", "B": "Sự thành lập Tổ chức Hiệp ước Bắc Đại Tây Dương", "C": "Liên Xô và Mĩ kí thỏa thuận về việc hạn chế vũ khí chiến lược", "D": "Sự ra đời của tổ chức liên minh chính trị - quân sự Vácsava"}', 'C', 'Liên Xô và Mĩ kí thỏa thuận về việc hạn chế vũ khí chiến lược là một trong những biểu hiện của xu thế hòa hoãn Đông - Tây (từ đầu thập kỷ 70 của thế kỷ XX).Chọn C.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(220, 'Theo Hiệp định Pari (1973) về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam, Hoa Kỳ cam kết&nbsp;', 'SINGLE_CHOICE', '{"A": "chấm dứt mọi hoạt động quân sự chống miền Bắc Việt Nam", "B": "thực hiện cuộc tập kết, chuyển quân và chuyển giao khu vực", "C": "thực hiện tổng tuyển cử thống nhất hai miền Bắc - Nam Việt Nam", "D": "thực hiện ngừng bắn, lập lại hòa bình trên toàn Đông Dương"}', 'A', 'Theo Hiệp định Pari (1973) về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam, Hoa Kỳ cam kết chấm dứt&nbsp;mọi hoạt động quân sự chống miền Bắc Việt Nam.Chọn A.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(221, 'Quốc gia nào sau đây ở Đông Nam Á giành độc lập vào năm 1945?&nbsp;', 'SINGLE_CHOICE', '{"A": "Thái Lan", "B": "Malaixia", "C": "Lào", "D": "Campuchia"}', 'C', 'SGK Lịch sử 12, trang 25.&nbsp;Lào là 1 trong ba nước Đông Nam Á giành độc lập vào năm 1945.Chọn C.&nbsp;', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(222, 'Trong đường lối đổi mới đất nước của Đảng Cộng sản Việt Nam (từ tháng 12 - 1986), nội dung nào sau đây là một trong những chủ trương đổi mới về chính trị?&nbsp;', 'SINGLE_CHOICE', '{"A": "Xóa bỏ cơ chế quản lý kinh tế tập trung", "B": "Xây dựng Nhà nước pháp quyền xã hội chủ nghĩa", "C": "Phát triển kinh tế hàng hóa nhiều thành phần", "D": "Mở rộng quan hệ kinh tế đối ngoại"}', 'B', 'Xây dựng Nhà nước pháp quyền xã hội chủ nghĩa là một trong những chủ trương đổi mới về chính trị trong đường lối đổi mới đất nước của Đảng Cộng sản Việt Nam (từ tháng 12 - 1986).Chọn B.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(223, 'Khi chuyển sang thực hiện chiến lược kinh tế hướng ngoại từ những năm 60 - 70 của thế kỷ XX trở đi, nhóm năm nước sáng lập ASEAN đều', 'SINGLE_CHOICE', '{"A": "đẩy mạnh sản xuất hàng tiêu dùng nội địa", "B": "tập trung sản xuất hàng hóa để xuất khẩu", "C": "chủ trương xây dựng nền kinh tế tự chủ", "D": "mở rộng quan hệ kinh tế đối ngoại"}', 'B', 'Khi chuyển sang thực hiện chiến lược kinh tế hướng ngoại từ những năm 60 - 70 của thế kỷ XX trở đi, nhóm năm nước sáng lập ASEAN đều tập trung sản xuất hàng hóa để xuất khẩu.&nbsp;Chọn B', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(224, 'Cuộc cách mạng khoa học - kĩ thuật hiện đại (từ những năm 40 của thế kỷ XX) có nguồn gốc từ&nbsp;', 'SINGLE_CHOICE', '{"A": "sự hợp tác nghiên cứu khoa học giữa hai quốc gia Mỹ và Liên Xô", "B": "nhu cầu đào tạo nguồn nhân lực chất lượng cao cho các quốc gia", "C": "tiền đề của cuộc cách mạng khoa học - kĩ thuật lần thứ nhất", "D": "yêu cầu giải quyết tình trạng khủng hoảng kinh tế thế giới"}', 'C', 'Cuộc cách mạng khoa học - kĩ thuật hiện đại (từ những năm 40 của thế kỷ XX) có nguồn gốc từ tiền đề của cuộc cách mạng khoa học - kĩ thuật lần thứ nhất ở thế kỉ XVIII- XIX.&nbsp;Chọn C.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(225, 'Một trong những yếu tố thúc đẩy Mĩ triển khai chiến lược toàn cầu từ sau Chiến tranh thế giới thứ hai là&nbsp;', 'SINGLE_CHOICE', '{"A": "sự trỗi dậy của chủ nghĩa khủng bố và chủ nghĩa ly khai", "B": "sự cạnh tranh quyết liệt của Liên Xô và Trung Quốc", "C": "sự vươn lên mạnh mẽ của Tây Âu và Nhật Bản", "D": "tiềm lực kinh tế - tài chính và sức mạnh quân sự của Mĩ"}', 'D', 'Một trong những yếu tố thúc đẩy Mĩ triển khai chiến lược toàn cầu từ sau Chiến tranh thế giới thứ hai là tiềm lực kinh tế - tài chính và sức mạnh quân sự của Mĩ.&nbsp;Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(226, 'Đảng Cộng sản Việt Nam ra đời đầu năm 1930 là', 'SINGLE_CHOICE', '{"A": "sự kết hợp giữa chủ nghĩa Mác - Lênin và phong trào công nông", "B": "cuộc tập dượt đầu tiên của giai cấp công nhân bước lên vũ đài chính trị", "C": "kết quả của phong trào dân tộc dân chủ diễn ra sôi nổi ở hải ngoại", "D": "sự chuẩn bị đầu tiên mang tính quyết định cho mọi thắng lợi của Việt Nam"}', 'D', 'Đảng Cộng sản Việt Nam ra đời đầu năm 1930 là sự chuẩn bị đầu tiên mang tính quyết định cho mọi thắng lợi của Việt Nam.&nbsp;Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(227, 'Việc đàm phán và ký kết Hiệp định Sơ bộ giữa đại diện Chính phủ Việt Nam Dân chủ Cộng hoà với đại diện Chính phủ Pháp (6-3-1946) có tác dụng nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Tránh phải đối đầu quân sự với nhiều kẻ thù nguy hiểm củng một lúc", "B": "Tạo thời gian hoà bình để Việt Nam tổ chức bầu cử Quốc hội", "C": "Thể hiện thiện chí hoà bình của hai Chính phủ Việt Nam và Pháp", "D": "Giúp Việt Nam ngăn chặn được mọi nguy cơ xung đột với Pháp"}', 'A', 'Việc đàm phán và ký kết Hiệp định Sơ bộ giữa đại diện Chính phủ Việt Nam Dân chủ Cộng hoà với đại diện Chính phủ Pháp (6-3-1946) có tác dụng là giúp ta tránh phải đối đầu quân sự với nhiều kẻ thù nguy hiểm củng một lúc.&nbsp;Chọn A', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(228, 'Nội dung nào sau đây là yếu tố khách quan tác động đòi hỏi Đảng và Nhà nước Việt Nam tiến hành công cuộc đổi mới (từ tháng 12 - 1986)?&nbsp;', 'SINGLE_CHOICE', '{"A": "Mĩ và Việt Nam bình thường hóa quan hệ ngoại giao", "B": "Các nước ASEAN trở thành những “con rồng” kinh tế", "C": "Quan hệ quốc tế chuyển từ đối đầu sang đối thoại, hợp tác", "D": "Chiến tranh lạnh kết thúc, trật tự hai cực Ianta sụp đổ"}', 'C', 'A loại&nbsp;vì Mĩ và Việt Nam bình thường hóa quan hệ năm 1995.B loại&nbsp;vì chỉ có Xingapo là nước duy nhất ở Đông Nam Á trở thành con rồng kinh tế châu Á.C chọn&nbsp;vì Đảng tiến hành đổi mới khi quan hệ quốc tế đang chuyển từ đối đầu sang đối thoại, hợp tác.D loại&nbsp;vì Chiến tranh lạnh kết thúc năm 1991.Chọn C.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(229, 'Thắng lợi của quân dân Việt Nam trong chiến dịch Hồ Chí Minh (4 - 1975) đã&nbsp;', 'SINGLE_CHOICE', '{"A": "đây chính quyền Sài Gòn đứng trước nguy cơ sụp đổ hoàn toàn", "B": "hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trong cả nước", "C": "buộc Mĩ kí Hiệp định Pari, chấm dứt chiến tranh xâm lược", "D": "mở ra thời cơ chiến lược để giải phóng hoàn toàn miền"}', 'B', 'Thắng lợi của quân dân Việt Nam trong chiến dịch Hồ Chí Minh (4 - 1975) đã hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trong cả nước.Chọn B.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(230, 'Luận cương chính trị (10 – 1930) của Đảng Cộng sản Đông Dương có ưu điểm nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Đã giải quyết đúng đắn mối quan hệ giữa nhiệm vụ dân tộc và dân chủ", "B": "Là Cương lĩnh cách mạng giải phóng dân tộc đúng đắn, sáng tạo", "C": "Xác định được động lực cơ bản của cách mạng là công nhân, nông dân", "D": "Đánh giá đúng khả năng cách mạng của các giai cấp, tầng lớp trong xã hội"}', 'C', 'A loại&nbsp;vì Luận cương chưa giải quyết đúng đắn mối quan hệ giữa nhiệm vụ dân tộc và dân chủ.&nbsp;B, D loại&nbsp;vì đây là ưu điểm của Cương lĩnh chính trị đầu tiên.C chọn&nbsp;vì Luận cương đã xác định đúng được động lực cơ bản của cách mạng là công nhân, nông dân.Chọn C.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(231, 'Trong cuộc kháng chiến chống thực dân Pháp xâm lược (1945-1954), Chính phủ nước Việt Nam Dân chủ Cộng hòa thực hiện phương châm đánh lâu dài vì một trong những lí do nào sau đây?', 'SINGLE_CHOICE', '{"A": "Xuất phát từ truyền thống chống ngoại xâm của dân tộc ta", "B": "Có thời gian để khắc phục hạn chế của ta về tinh thần và chính trị", "C": "Địch chủ trương đánh lâu dài nên ta cũng phải kháng chiến lâu dài", "D": "Từng bước làm thay đổi so sánh lực giữa ta và Pháp trên chiến trường"}', 'D', 'A, B loại&nbsp;vì không phải là lí do Chính phủ nước Việt Nam Dân chủ Cộng hòa thực hiện phương châm đánh lâu dài.&nbsp;C loại&nbsp;vì ban đầu Pháp chọn đánh nhanh thắng nhanh.D chọn&nbsp;vì ta yếu hơn Pháp về nhiều mặt và Pháp muốn đánh nhanh thắng nhanh thì ta chọn đánh lâu dài để từng bước làm thay đổi so sánh lực giữa ta và Pháp trên chiến trường.Chọn D', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(232, 'Tổ chức Liên hợp quốc được thành lập năm 1945 nhằm thực hiện một trong những nhiệm vụ nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Phát triển các mối quan hệ hợp tác hữu nghị giữa các dân tộc", "B": "Ngăn chặn mưu đồ làm bá chủ thế giới của Mỹ và Liên Xô", "C": "Biến Liên hợp quốc thành trung tâm kinh tế - tài chính lớn", "D": "Tập hợp đoàn kết lực lượng nhằm đánh bại chủ nghĩa phát xít"}', 'A', 'Tổ chức Liên hợp quốc được thành lập năm 1945 nhằm thực hiện một trong những nhiệm vụ là phát triển các mối quan hệ hợp tác hữu nghị giữa các dân tộc.Chọn A', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(233, 'Cách mạng tháng Mười năm 1917 ở Nga và Cách mạng tháng Tám năm 1945 ở Việt Nam có điểm chung nào sau đây?', 'SINGLE_CHOICE', '{"A": "Góp phần cổ vũ phong trào cách mạng", "B": "Đối tượng đấu tranh chủ yếu là giai cấp tư sản", "C": "Làm cho chủ nghĩa tư bản không còn hoàn chỉnh", "D": "Nhiệm vụ chủ yếu là chống chủ nghĩa thực dân"}', 'A', 'A chọn&nbsp;vì Cách mạng tháng Mười năm 1917 ở Nga và Cách mạng tháng Tám năm 1945 ở Việt Nam có điểm chung là đều góp phần cổ vũ phong trào cách mạng.&nbsp;B, C loại&nbsp;vì chỉ đúng với Cách mạng tháng Mười.D loại&nbsp;vì không đúng với Cách mạng tháng Mười.Chọn A', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(234, 'Phong trào cách mạng 1930 - 1931 và phong trào dân chủ 1936 - 1939 ở Việt Nam có điểm chung nào sau đây?', 'SINGLE_CHOICE', '{"A": "Đường lối chiến lược cách mạng không thay đổi", "B": "Để lại nhiều bài học kinh nghiệm về đấu tranh hợp pháp", "C": "Sử dụng bạo lực cách mạng để giành chính quyền", "D": "Tổ chức các lực lượng yêu nước trong một mặt trận"}', 'A', 'A chọn&nbsp;vì đường lối chiến lược của cách mạng qua hai phong trào này không thay đổi đó là chống đế quốc và phong kiến.B loại&nbsp;và phong trào 1930 – 1931 ta đấu tranh bí mật, bất hợp pháp.C loại vì&nbsp;không đúng với phong trào 1936 – 1939.D loại&nbsp;và phong trào 1930 – 1931 chưa có mặt trận dân tộc thống nhất.Chọn A.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(235, 'Chiến lược “Chiến tranh đặc biệt” (1961 – 1965), chiến lược “Chiến tranh cục bộ” (1965 - và chiến lược “Việt Nam hóa chiến tranh” (1969 - 1973) của Mĩ ở Việt Nam có điểm chung nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Đều sử dụng quân đồng minh của Mĩ", "B": "Sử dụng quân đội Sài Gòn làm công cụ", "C": "Quân đội Sài Gòn là lực lượng duy nhất", "D": "Quân Mĩ luôn giữ vai trò quan trọng"}', 'B', 'A loại&nbsp;vì không đúng với chiến lược “Chiến tranh đặc biệt” (1961 – 1965).C loại vì&nbsp;không đúng với chiến lược “Chiến tranh cục bộ” (1965 - và chiến lược “Việt Nam hóa chiến tranh” (1969 - 1973).D loại vì&nbsp;không đúng với chiến lược “Chiến tranh đặc biệt” (1961 – 1965).Chọn B.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(236, 'Một trong những điểm giống nhau giữa chiến dịch Việt Bắc - thu đông năm 1947, chiến dịch Biên giới thu - đông năm 1950 và chiến dịch Điện Biên Phủ năm 1954 trong cuộc kháng chiến chống Pháp (1945 - 1954) của quân dân Việt Nam là&nbsp;', 'SINGLE_CHOICE', '{"A": "quân đội ta đã giành được thế chủ động trên chiến trường chính", "B": "tiêu diệt một bộ phận quan trọng sinh lực quân Pháp", "C": "làm xoay chuyển cục diện chiến tranh ở Đông Dương", "D": "làm thất bại kế hoạch “đánh nhanh thắng nhanh của Pháp"}', 'B', 'A loại vì sau thắng lợi của chiến dịch Biên giới ta mới giành quyền chủ động trên chiến trường chính Bắc Bộ.B chọn&nbsp;vì cả ba chiến dịch đều tiêu diệt một bộ phận quan trọng sinh lực quân Pháp. C loại vì không đúng với chiến dịch Việt BắcD loại&nbsp;vì chỉ đúng với chiến dịch Việt Bắc.Chọn B.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(237, 'Nội dung nào sau đây là điểm giống nhau giữa Định ước Henxinki (1975) và Hiệp ước Bali (1976)?&nbsp;', 'SINGLE_CHOICE', '{"A": "Mở ra xu thể “nhất thể hóa” khu vực và kết nối Á - Âu", "B": "Tăng cường sự hợp tác liên minh khu vực về kinh tế", "C": "Tăng cường sự trao đổi, hợp tác về khoa học - kĩ thuật", "D": "Giải quyết các tranh chấp bằng biện pháp hòa bình"}', 'D', 'A loại&nbsp;vì Hiệp ước Bali không mở ra xu thể “nhất thể hóa” khu vực.B loại vì&nbsp;không đúng với Định ước Henxinki (1975).C loại&nbsp;vì không đúng với Hiệp ước Bali.D chọn&nbsp;vì điểm giống nhau giữa Định ước Henxinki (1975) và Hiệp ước Bali (1976) là giải quyết các tranh chấp bằng biện pháp hòa bình.Chọn D', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(238, 'Phong trào giải phóng dân tộc ở Á, Phi, Mĩ Latinh từ sau Chiến tranh thế giới thứ hai có điểm chung nào sau đây?&nbsp;', 'SINGLE_CHOICE', '{"A": "Nhiệm vụ đấu tranh là chống chế độ độc tài thân Mĩ", "B": "Sau khi giành độc lập đều tiến lên chủ nghĩa xã hội", "C": "Hầu hết các quốc gia đã giành được độc lập", "D": "Đặt dưới sự lãnh đạo của chính đảng vô sản"}', 'C', 'A loại&nbsp;vì chỉ đúng với Mĩ Latinh.B loại vì không phải nước nào sau khi giành độc lập cũng đều tiến lên chủ nghĩa xã hội.C chọn&nbsp;vì phong trào giải phóng dân tộc ở Á, Phi, Mĩ Latinh từ sau Chiến tranh thế giới thứ hai có điểm chung là hầu hết các quốc gia đã giành được độc lập.D loại vì ở châu Phi đặt dưới sự lãnh đạo của tư sản dân tộc và Tổ chức thoáng nhất châu Phi (OAU).Chọn C', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(239, 'Trong thời gian hoạt động (1925 - 1929), Hội Việt Nam Cách mạng Thanh niên đã&nbsp;', 'SINGLE_CHOICE', '{"A": "quyết định sự thắng lợi của khuynh hướng cách mạng vô sản ở Việt Nam", "B": "lãnh đạo một số phong trào đấu tranh của giai cấp công nhân Việt Nam", "C": "hoàn thành nhiệm vụ truyền bá chủ nghĩa Mác - Lênin vào Việt Nam", "D": "chấm dứt sự khủng hoảng đường lối và giai cấp lãnh đạo ở Việt Nam"}', 'B', 'A loại&nbsp;vì thực tế lịch sử Việt Nam đã lựa chọn khuynh hướng cách mạng vô sản do khuynh hướng này đáp ứng được yêu cầu của cách mạng.&nbsp;B chọn vì&nbsp;trong thời gian hoạt động (1925 - 1929), Hội Việt Nam Cách mạng Thanh niên đã lãnh đạo một số phong trào đấu tranh của giai cấp công nhân Việt Nam. C loại vì chủ nghĩa Mác – Lê nin vẫn tiếp tục được truyền bá cho đến khi Đảng ra đời đầu năm 1930.D loại&nbsp;vì đây là ý nghĩa sự ra đời của Đảng.Chọn B', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(240, 'Nội dung nào sau đây là nét nổi bật về nghệ thuật chỉ đạo của Đảng Lao động Việt Nam trong cuộc Tổng tiến công và nổi dậy Xuân 1975?&nbsp;', 'SINGLE_CHOICE', '{"A": "Kết hợp tài tình giữa tổng công kích và tổng khởi nghĩa của quần chúng", "B": "Thực hiện chiến thuật đánh từng bước, tiêu diệt từng cứ điểm của địch", "C": "Chớp đúng thời thời cơ để tổ chức phản công chiến lược giành thắng lợi", "D": "Linh hoạt cách đánh trong từng chiến dịch, đảm bảo yếu tố bí mật, bất ngờ"}', 'D', 'A loại&nbsp;vì cuộc Tổng tiến công và nổi dậy Xuân 1975 không kết giữa tổng công kích và tổng khởi nghĩa của quần chúng mà kết hợp tiến công quân sự của lực lượng vũ trang và sự nổi dậy của quần chúng.B loại&nbsp;vì không đúng với nghệ thuật chỉ đạo của Đảng trong cuộc Tổng tiến công và nổi dậy Xuân 1975.C loại&nbsp;vì cuộc Tổng tiến công và nổi dậy Xuân 1975 là cuộc tổng tiến công do ta chủ động mở.Chọn D.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(241, 'Nội dung nào sau đây phản ánh đúng điểm tiến bộ của phong trào yêu nước và cách mạng ở Việt Nam đầu thế kỷ XX?', 'SINGLE_CHOICE', '{"A": "Các sĩ phu kêu gọi nhân dân thương yêu, đoàn kết trong làm ăn", "B": "Vận động nhân dân Việt Nam làm kinh tế theo phương thức mới", "C": "Đưa khuynh hướng cứu nước mới vào Việt Nam thành công", "D": "Các sĩ phu ủng hộ nhân dân đi theo chế độ tư bản chủ nghĩa"}', 'B', 'A loại&nbsp;vì không phản ánh đúng điểm tiến bộ của phong trào yêu nước và cách mạng ở Việt Nam đầu thế kỷ XX.B chọn&nbsp;vì điểm tiến bộ của phong trào yêu nước và cách mạng ở Việt Nam đầu thế kỷ XX là vận động nhân dân Việt Nam làm kinh tế theo phương thức mới.C loại&nbsp;vì khuynh hướng dân chủ tư sản đã bước đầu thất bại với các hoạt động của Phan Bội Châu và Phan Châu Trinh.&nbsp;D loại&nbsp;vì xét ví dụ như Phan Bội Châu hướng theo con đường thiết lập chế độ Cộng hòa.Chọn B.', 9);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(242, 'Nhận định nào sau đây là đúng về cuộc Cách mạng tháng Tám năm 1945 ở Việt Nam?', 'SINGLE_CHOICE', '{"A": "Giành chính quyền ở các vùng nông thôn rồi bao vây các thành thị", "B": "Cuộc cách mạng kết hợp tổng công kích với tổng khởi nghĩa toàn dân", "C": "Giành chính quyền ở các đô thị trước rồi tỏa về các vùng nông thôn", "D": "Sử dụng bạo lực chính trị là chủ yếu, kết hợp với lực lượng vũ trang"}', 'D', 'A, C loại&nbsp;vì Cách mạng tháng Tám kết hợp hài hòa ở nông thôn và thành thị.B loại&nbsp;vì Cách mạng tháng Tám không kết hợp tổng công kích với tổng khởi nghĩa toàn dân.D chọn&nbsp;vì Cách mạng tháng Tám là cuộc cách mạng bạo lực sử dụng lực lượng chính trị là chủ yếu kết hợp với lực lượng vũ trang.Chọn D', 9);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(10, 'Đề thi thử giữa học kỳ 2 môn Lịch Sử lớp 11 online - Mã đề 01', 'Lịch Sử', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Lịch Sử. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(243, 'Ai là người đã chỉ huy nghĩa quân đánh chìm tàu Étpêrăng của Pháp trên sông Vàm Cỏ Đông (1861)?', 'SINGLE_CHOICE', '{"A": "Trương Định", "B": "Nguyễn Trung Trực", "C": "Nguyễn Hữu Huân", "D": "Dương Bình Tâm"}', 'A', 'Nguyễn Trung Trực là người đã chỉ huy nghĩa quân đánh chìm tàu Étpêrăng của Pháp trên song Vàm Cỏ Đông (1861) và có câu nói nổi tiếng: “Bao giờ người Tây nhổ hết cỏ nước Nam thì mới hết người Nam đánh Tây”Chọn đáp án: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(244, 'Sau khi bắt được vua Hàm Nghi, thực dân Pháp đã đưa ông đi đày ở đâu?', 'SINGLE_CHOICE', '{"A": "Mêhicô", "B": "Angiêri", "C": "Tuynidi", "D": "Nam Phi"}', 'A', 'Sau khi bắt được vua Hàm Nghi, thực dân Pháp đã đưa ông đi đày ở Angiêri.Chọn đáp án: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(245, 'Cuộc khởi nghĩa vũ trang lớn và kéo dài nhất trong phong trào chống Pháp cuối thế kỉ XIX – đầu thế kỉ XX là gì?', 'SINGLE_CHOICE', '{"A": "Khởi nghĩa của đồng bào Tây Nguyên", "B": "Khởi nghĩa Hương Khê", "C": "Khởi nghĩa ở vùng Tây Bắc và hạ lưu sông Đà", "D": "Khởi nghĩa Yên Thế"}', 'A', 'Trong lịch sử cận đại Việt Nam,&nbsp;cuộc khởi nghĩa Yên Thế chống thực dân Pháp xâm lược&nbsp;là cuộc khởi nghĩa lâu dài nhất, oanh liệt nhất trong giai đoạn cuối thế kỷ XIX, đầu thế kỷ XX.Đáp án D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(246, 'Điểm khác của khởi nghĩa Yên Thế so với các cuộc khởi nghĩa trong phong trào Cần vương là gì?', 'SINGLE_CHOICE', '{"A": "Hưởng ứng chiếu Cần vương", "B": "Chống thực dân Pháp, chống triều đình nhà Nguyễn", "C": "Phản ứng trước hành động đầu hàng thực dân Pháp của triều đình", "D": "Là phong trào nông dân chống Pháp, không thuộc phạm trù phong trào Cần vương"}', 'A', '- Khởi nghĩa Yên Thế bùng nổ là do nhân dân nơi đây muốn bảo vệ cuộc sống của mình trước chính sách xâm lược thực dân Pháp, do nông dân lãnh đạo và bùng nổ năm 1884, trước khi phong trào Cần vương bùng nổ.=&gt; Phong trào Cần vương là phong trào nông dân chống Pháp, không thuộc phạm trù phong trào Cần vương.Đáp án cần chọn là: D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(247, 'Trong giai đoạn từ năm 1893 đến năm 1897, lãnh tụ tối cao của khởi nghĩa Yên Thế là ai?', 'SINGLE_CHOICE', '{"A": "Đề Thám", "B": "Đề Nắm", "C": "Phan Đình Phùng", "D": "Nguyễn Trung Trực"}', 'A', 'Sau khi Đề Nắm bị sát hại, Đề Thám (Hoàng Hoa Thám) đã lên thay thế và trở thành lãnh tụ tối cao của khởi nghĩa Yên ThếĐáp án cần chọn là:&nbsp;A', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(248, 'Hội nghị Muy-nich với sự tham gia của các quốc gia nào sau đây?', 'SINGLE_CHOICE', '{"A": "Anh, Pháp, Đức, Italia.", "B": "Liên Xô, Mỹ, Anh, Pháp.", "C": "Đức, Áo, Hung, Bỉ.", "D": "Anh, Pháp, Nhật, Italia."}', 'A', 'Ngày 29/09/1938, Hội nghị Muy-ních được triệu tập với sự tham gia của&nbsp;Anh, Pháp, Đức và I-ta-li-a.Đáp án cần chọn là:&nbsp;A', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(249, 'Đâu không phải là hành động của nhân dân Bắc Kì khi Gác-ni-ê đưa quân tấn công Bắc Kì lần thứ nhất năm 1873?', 'SINGLE_CHOICE', '{"A": "Bất hợp tác với Pháp.", "B": "Bỏ thuốc độc vào các giếng nước uống.", "C": "Đốt kho thuốc súng của Pháp.", "D": "Tìm cách thỏa hiệp với Pháp."}', 'A', 'Thông tin: SGK Lịch sử 11, trang 117 – 118.Khi Gác-ni-ê đưa quân tấn công Bắc Kì lần thứ nhất năm 1873, nhân dân Bắc Kì đã: bất hợp tác với thực dân Pháp, bỏ thuốc độc các giếng nước uống, đốt chấy các kho thuốc súng của Pháp.Chọn:&nbsp;D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(250, 'Sau khi cuộc phản công kinh thành Huế thất bại, Tôn Thất Thuyết đã làm gì?', 'SINGLE_CHOICE', '{"A": "Đưa vua Hàm Nghi và Tam cung rời khỏi Hoàng thành đến sơn phòng Âu Sơn (Hà Tĩnh)", "B": "Đưa vua Hàm Nghi và Tam cung rời khỏi Hoàng thành đến sơn phòng Tân Sở (Quảng Trị)", "C": "Bổ sung lực lượng quân sự", "D": "Tiếp tục xây dựng hệ thống sơn phòng"}', 'A', 'Sau cuộc phản công quân Pháp của phái chủ chiến thất bại, Tôn Thất Thuyết đã đưa vua Hàm Nghi và Tam cung rời khỏi hoàng thành đến sơn phòng Tân Sở (Quảng Trị). Tại đây, nhân danh vua Hàm Nghi, Tôn Thất Thuyết đã xuống chiếu Cần Vương, kêu gọi các văn thân và nhân dân đứng lên giúp vua cứu nước.Đáp án cần chọn là: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(251, 'Sau khi vua Hàm Nghi bị bắt, phong trào Cần vương _______.', 'SINGLE_CHOICE', '{"A": "vẫn tiếp tục nhưng thu hẹp địa bàn ở Nam Trung Bộ", "B": "tiếp tục hoạt động, quy tụ dần thành những trung tâm lớn", "C": "chỉ hoạt động cầm chừng", "D": "chấm dứt hoạt động"}', 'A', 'Tuy vua Hàm Nghi bị bắt nhưng phong trào Cần Vương vẫn được duy trì và dần quy tục thành những cuộc khởi nghĩa lớn, có quy mô và trình độ tổ chức cao hơn trong giai đoạn 1888 – 1896.Chọn: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(252, 'Cuộc khủng hoảng kinh tế tg 1929 – 1933 đã để lại hậu quả nghiêm trọng nhất đối với thế giới là gì?', 'SINGLE_CHOICE', '{"A": "Dư thừa hàng hóa do cung vượt quá cầu", "B": "Xuất hiện chủ nghĩa phát xít và nguy cơ chiến tranh", "C": "Nạn thất nghiệp tràn lan", "D": "Sản xuất đình đốn"}', 'A', 'Từ trong cuộc khủng hoảng kinh tế 1929-1933, các thế lực phát xít đã lên nắm quyền ở Đức, Italia, Nhật Bản, ráo riết chạy đua vũ trang chuẩn bị cho một cuộc chiến tranh thế giới mới. Đây chính là hậu quả nghiêm trọng nhất mà cuộc khủng hoảng kinh tế thế giới 1929 – 1933 tạo ra.Đáp án cần chọn là:&nbsp;B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(253, 'Nhật Hoàng tuyên bố đầu hàng đồng minh vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "15/08/1945.", "B": "25/08/1945.", "C": "05/08/1945.", "D": "30/08/1945."}', 'A', 'Ngày&nbsp;15/8/1945, Đoạn băng ghi âm tuyên bố đầu hàng Đồng Minh của Nhật hoàng Horohito được phát sóng trên Đài NHK (là Đài phát thanh duy nhất của Nhật Bản đương thời), phát vào đúng chính ngọ (12h) ngày 15/8/1945.', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(254, 'Liên Xô là cụm từ viết tắt của tổ chức nào?', 'SINGLE_CHOICE', '{"A": "Liên bang Xô viết", "B": "Liên hiệp các Xô viết", "C": "Liên bang Cộng hòa xã hội chủ nghĩa Xô viết", "D": "Liên hiệp các Xô viết xã hội chủ nghĩa"}', 'C', 'Liên Xô hay Liên bang Xô Viết, tên chính thức là&nbsp;Liên bang Cộng hòa Xã hội chủ nghĩa Xô viết, là một cựu quốc gia nằm ở phía bắc lục địa Á-Âu, tồn tại từ năm 1922 đến cuối năm 1991.Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(255, 'Bản chất của phong trào Cần vương là gì?', 'SINGLE_CHOICE', '{"A": "Là phong trào yêu nước theo khuynh hướng và ý thức hệ phong kiến", "B": "Là phong trào yêu nước theo khuynh hướng dân chủ tư sản", "C": "Là phong trào yêu nước theo khuynh hướng vô sản", "D": "Là phong trào yêu nước của các tầng lớp nông dân"}', 'A', 'Xét tính chất của phong trào Cần Vương dựa trên các tiêu chí sau:- Nguyên nhân bùng nổ: nguyên nhân sâu xa dẫn tới sự bùng nổ của phong trào Cần Vương là do mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp, tay sai phát triển gay gắt- Mục tiêu:&nbsp;hướng tới xây dựng một nhà nước phong kiến với vua hiền tôi giỏi- Lãnh đạo:&nbsp;trong giai đoạn thứ nhất, phong trào đặt dưới sự lãnh đạo của vua Hàm Nghi và Tôn Thất Thuyết. Tuy nhiên sau khi vua Hàm Nghi bị bắt, phong trào không những không bị dập tắt mà còn phát triển, quy tụ lại thành các cuộc khởi nghĩa lớn, trình độ tổ chức cao. Như vậy Cần Vương chỉ là cái cớ, ngọn cờ để tập hợp lực lượng đấu tranh- Lực lượng tham gia: các văn thân, sĩ phu phong kiến và đông đảo quần chúng nhân dân.Đáp án cần chọn là:&nbsp;A', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(256, 'Ai là người lãnh đạo cuộc khởi nghĩa Hương Khê?', 'SINGLE_CHOICE', '{"A": "Phan Đình Phùng và Hoàng Hoa Thám", "B": "Cao Điền và Tống Duy Tân", "C": "Phan Đình Phùng và Cao Thắng", "D": "Tống Duy Tân và Cao Thắng"}', 'A', 'Lãnh tụ của cuộc khởi nghĩa Hương Khê là Phan Đình Phùng và Cao ThắngĐáp án cần chọn là:&nbsp;C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(257, 'Tội phạm chiến tranh, đã lôi kéo 1700 triệu người ở trên 70 nước tham gia, gây ra cái chết cho khoảng 60 triệu người và làm tàn phế 90 triệu người khác là nước nào?', 'SINGLE_CHOICE', '{"A": "Phát xít Đức", "B": "Anh, Pháp", "C": "Mĩ", "D": "Các nước phát xít Đức, Italia và Nhật Bản"}', 'A', 'Tội phạm chiến tranh, đã lôi kéo 1700 triệu người ở trên 70 nước tham gia, gây ra cái chết cho khoảng 60 triệu người và làm tàn phế 90 triệu người khác các nước phát xít Đức, Italia và Nhật BảnĐáp án cần chọn là:&nbsp;D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(258, 'Thực dân Pháp đã chiếm gọn ba tỉnh miền Tây Nam Kì (1867) mà không tốn một viên đạn vì sao?', 'SINGLE_CHOICE', '{"A": "thực dân Pháp tấn công bất ngờ.", "B": "nhân dân không ủng hộ triều đình chống Pháp.", "C": "triều đình bạc nhược, thiếu kiên quyết chống Pháp.", "D": "quân đội triều đình trang bị vũ khí quá kém."}', 'C', 'Lợi dụng sự bạc nhược, thiếu kiên quyết của triều đình Huế, Pháp đã chiếm trọn 3 tỉnh miền Tây Nam Kì (Vĩnh Long, An Giang, Hà Tiên) mà không tốn một viên đạn.Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(259, 'Anh và Pháp phải chịu một phần trách nhiệm về sự bùng nổ cuộc Chiến tranh thế giới thứ hai (1939 - 1945) vì sao?', 'SINGLE_CHOICE', '{"A": "không tham gia khối Đồng minh chống phát xít.", "B": "ngăn cản việc thành lập liên minh chống phát xít.", "C": "thực hiện chính sách nhượng bộ phát xít.", "D": "thực hiện chính sách hòa bình, trung lập."}', 'C', 'Anh, Pháp, Mỹ&nbsp;đều muốn giữ nguyên trật tự thế giới có lợi cho mình. Anh, Pháp&nbsp;thực hiện chính sách nhượng bộ phát xít&nbsp;để đẩy chiến tranh về phía Liên Xô. Mĩ với “Đạo luật trung lập’ (1935) không can thiệp vào các sự kiện bên ngoài&nbsp;châu Mĩ. =&gt; Các nước phát xít đã lợi dụng tình hình đó để thực hiện mục tiêu gây chiến tranh xâm lược của mình. Chính vì thế, các nước Anh và Pháp phải chịu một phần trách nhiệm về sự bùng nổ cuộc Chiến tranh thế giới thứ hai (1939 – 1945)Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(260, 'Nguyên nhân chủ yếu dẫn đến hai cuộc chiến tranh thế giới trong thế kỉ XX là do đâu?', 'SINGLE_CHOICE', '{"A": "âm mưu muốn bá chủ thế giới của Đức và Nhật Bản.", "B": "các nước Anh, Pháp, Mĩ dung dưỡng, nhượng bộ với phát xít.", "C": "cuộc khủng hoảng kinh tế thế giới diễn ra trầm trọng.", "D": "mâu thuẫn giữa các nước đế quốc xung quanh về vấn đề thuộc địa."}', 'A', 'Nguyên nhân sâu xa hay chính là nguyên nhân cơ bản bùng nổ Chiến tranh thế giới thứ nhất (1914 -1918) và chiến tranh thế giới thứ hai (1939 – 1945) là do mâu thuẫn giữa các nước đế quốc về vấn đề thuộc địa:- Đế quốc “già” (Anh, Pháp) có hệ thống thuộc địa rộng lớn &gt;&lt; các nước đế quốc “trẻ” (Mĩ, Đức, Nhật Bản) đang vươn lên mạnh mẽ về kinh tế nhưng lại có quá ít thuộc địa.- Đến sau cuộc chiến tranh thế giới thứ nhất kết thúc, trật tự Vecxai – Oasinhtơn được thiết lập nhưng không giải quyết được triệt để mâu thuẫn&nbsp;này. Đây cũng tiếp tục là nguyên nhân sâu xa dẫn đến bùng nổ Chiến tranh thế giới thứ hai.Chọn đáp án: D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(261, 'Nước tư bản nào đã liên quân với Pháp để tấn công Đà Nẵng vào 1858?', 'SINGLE_CHOICE', '{"A": "Hà Lan.", "B": "Anh.", "C": "Tây Ban Nha.", "D": "Bồ Đào Nha."}', 'C', 'Thông tin: SGK Lịch sử 11, trang 108.Sau nhiều lần đưa quân đến khiêu khích, chiều 31 – 8 – 1858 liên quân Pháp – Tây Ban Nha với khoảng 30000 binh lính và sĩ quan, bố trí trên 14 chiến thuyền kéo tới dàn trận trước cửa biển Đà Nẵng.Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(262, 'Chọn đáp án đúng để sắp xếp các Hiệp ước mà triều đình nhà Nguyễn kí với thực dân Pháp theo trình tự thời gian1. Hiệp ước Hác – măng.2. Hiệp ước Nhâm Tuất.3. Hiệp ước Pa - tơ – nốt.4. Hiệp ước Giáp Tuất.', 'SINGLE_CHOICE', '{"A": "2 – 4 – 1 – 3.", "B": "3 - 2 - 4 - 1.", "C": "2 – 3 – 1 - 4.", "D": "1 - 2 - 3 - 4."}', 'A', '-&nbsp;Hiệp ước Nhâm Tuất (1862)- Hiệp ước Giáp Tuất (1874)- Hiệp ước Hác-măng (1883)- Hiệp ước Pa-tơ-nốt (1884).Chọn A', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(263, 'Câu nói của Nguyễn Trung Trực “Bao giờ người Tây nhổ hết cỏ nước Nam thì mới hết người Nam đánh Tây” thể hiện điều gì?', 'SINGLE_CHOICE', '{"A": "Quyết tâm đánh Pháp của nhân dân Việt Nam.", "B": "Tinh thần đoàn kết chống ngoại xâm của nhân dân Việt Nam.", "C": "Lòng căm thù giặc sâu sắc của nhân dân Việt Nam.", "D": "Ý chí độc lập, tự chủ của dân tộc Việt Nam."}', 'A', 'Khi bị giặc bắt đem đi hành hình, Nguyễn Trung Trực đã khảng khái nói: “Bao giờ người Tây nhổ hết cỏ nước Nam thì mới hết người Nam đánh Tây”.&nbsp;Câu nói này thể hiện quyết tâm đánh Pháp không chỉ của riêng Nguyễn Trung Trực mà nó còn đại diện cho quyết tâm của toàn thể nhân dân Việt Nam.Chọn: A', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(264, 'Thực dân Pháp đã viện cớ nào để tấn công ra Bắc Kì lần thứ nhất (1873)?', 'SINGLE_CHOICE', '{"A": "Nhà Nguyễn vẫn tiếp tục chính sách “bế quan tỏa cảng”", "B": "Nhà Nguyễn phản đối những chính sách ngang ngược của Pháp", "C": "Nhà Nguyễn đàn áp đẫm máu các cuộc khởi nghĩa của nông dân", "D": "Nhà Nguyễn nhờ giải quyết “vụ Đuypuy”"}', 'A', 'Cái cớ Pháp kéo quân ra Bắc chính là nguyên nhân trực tiếp Pháp tấn công Bâc Kì lần 1 (1973). Pháp chớp cơ hội triều Nguyễn nhờ giải quyết “vụ Đuy – puy”&nbsp;đang gây rối ở Hà Nội, thực dân Pháp ở Sài Gòn phái Đại úy Gác-ni-ê đưa quân ra Bắc.Chọn đáp án: D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(265, 'Năm 1917, sự kiện nào đã làm thay đổi hoàn toàn tình hình đất nước và số phận của hàng triệu con người ở Nga?', 'SINGLE_CHOICE', '{"A": "Chiến tranh thế giới thứ nhất", "B": "Cách mạng tháng Hai", "C": "Cách mạng tháng Mười", "D": "Luận cương tháng tư"}', 'C', 'Cách mạng Tháng Mười Nga năm 1917, đã đi vào lịch sử nhân loại như là một sự kiện vĩ đại có tiếng vang và tầm ảnh hưởng sâu rộng, làm rung chuyển, đảo lộn trật tự thế giới, ấn định chiều hướng phát triển của xã hội loài người.Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(266, 'Cao Thắng có vai trò như thế nào trong khởi nghĩa Hương Khê?', 'SINGLE_CHOICE', '{"A": "Chiêu tập binh sĩ, trang bị và huấn luyện quân sự", "B": "Xây dựng căn cứ thuộc vùng rừng núi các tỉnh Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình", "C": "Chiêu tập binh sĩ, trang bị và huấn luyện quân sự, xây dựng căn cứ, nghiên cứu chế tạo thành công súng trường theo mẫu của Pháp", "D": "Chuẩn bị lực lượng và vũ khí cho khởi nghĩa"}', 'A', 'Trong cuộc khởi nghĩa Hương Khê, Cao Thắng có vai trò chiêu tập binh sĩ, trang bị và huấn luyện quân sự, xây dựng căn cứ, nghiên cứu chế tạo thành công súng trường theo mẫu của Pháp cùng với các thợ rèn ở làng Trung Lương và Văn Chàng (Đức Thọ).Chọn đáp án: C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(267, 'Cuộc chiến đấu chống thực dân Pháp của quân dân Việt Nam ở mặt trận Đà Nẵng (1858) ________.', 'SINGLE_CHOICE', '{"A": "Làm phá sản hoàn toàn kế hoạch đánh nhanh thắng nhanh của Pháp.", "B": "Bước đầu làm thất bại kế hoạch đánh nhanh thắng nhanh của Pháp.", "C": "Buộc pháp phải lập tức thực hiện kế hoạch tấn công bắc kì.", "D": "Buộc pháp phải lập tức chuyển hướng tiến công cửa biển Thuận An."}', 'B', 'Cuộc chiến đấu chống thực dân Pháp của quân dân Việt Nam ở mặt trận Đà Nẵng (1858) đã&nbsp;bước đầu làm thất bại kế hoạch “đánh nhanh thắng nhanh” của Pháp buộc Pháp phải chuyển sang tấn công ở Gia Định.Chọn B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(268, 'Trước khi thực dân Pháp xâm lược (1858), Việt Nam là một quốc gia thế nào?', 'SINGLE_CHOICE', '{"A": "tự do trong Liên bang Đông Dương.", "B": "độc lập, có chủ quyền.", "C": "dân chủ, có chủ quyền.", "D": "độc lập trong Liên bang Đông Dương."}', 'A', 'Vào giữa thế kỉ XIX, trước khi bị thực dân Pháp xâm lược, Việt Nam là một quốc gia độc lập, có chủ quyền, đạt được những tiến bộ nhất định về kinh tế, văn hóa.Chọn đáp án: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(269, 'Hiệp ước nào đánh dấu việc triều đình nhà Nguyễn chính thức thừa nhận sáu tỉnh Nam Kì là đất thuộc Pháp?', 'SINGLE_CHOICE', '{"A": "Hiệp ước Nhâm Tuất.", "B": "Hiệp ước Hácmăng.", "C": "Hiệp ước Patơnốt.", "D": "Hiệp ước Giáp Tuất."}', 'A', 'Hiệp ước Giáp Tuất năm 1874 đã chính thức thừa nhận 6 tỉnh Nam Kì là đất thuộc Pháp, công nhận quyền đi lại, buôn bán, kiểm soát và điều tra tình hình Việt Nam của chúng…Đáp án cần chọn là: D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(270, 'Nguyên nhân nào thúc đẩy các quốc gia trên thế giới hình thành liên minh chống phát xít?', 'SINGLE_CHOICE', '{"A": "Do Anh, Mĩ đều thua nhiều trận trên chiến trường.", "B": "Do uy tín của Liên Xô đã tập hợp được các nước khác.", "C": "Do nhân dân các nước trên thế giới đoàn kết.", "D": "Do hành động xâm lược, bành trướng của phe phát xít khiến thế giới lo ngại."}', 'A', '- Đáp án A loại vì lúc này Anh chưa thất bại trên chiến trường (Anh có ưu thế về hải quân, không quân và có sự viện trợ của Mĩ nên kế hoạch đổ bộ lên nước Anh của quân Đức không thực hiện được).- Đáp án B loại vì đây chỉ là 1 trong các nguyên nhân thúc đẩy sự hợp tác giữa các nước lớn chống lại phe phát xít.- Đáp án C loại vì thực tế chiến trường cho thấy chỉ có một số nước lớn tham chiến.- Đáp án D đúng vì hành động xâm lược của phe phát xít đã làm cho các nước lo ngại. Cụ thể là Anh, Pháp sau đó có Mĩ đã bắt tay với Liên Xô để cùng chống lại các nước phát xít.Đáp án cần chọn là:&nbsp;D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(271, 'Vì sao tại Gia Định, kế hoạch “Đánh nhanh thắng nhanh” của Pháp bị thất bại?', 'SINGLE_CHOICE', '{"A": "Sự chiến đấu anh dũng của quân đội triều đình, quân xâm lược bị thiệt hại nặng nề", "B": "Vấp phải sự kháng cự quyết liệt của nhân dân ta", "C": "Các đội dân binh chiến đấu dũng cảm, ngày đêm bám sát địch, quấy rối tiêu diệt chúng", "D": "Tất cả các vấn đề trên"}', 'A', 'Pháp tiền vào Gia Đinh nhân dân ta đã chiến đấu rất quyết liệt, ngày đêm bám sát đich để quẩy rối và tiêu diệt chúng. Kế hoạch "đánh nhanh thắng nhanh" của Pháp thất bại, buộc dịch phải chuyển sang kế hoạch "chinh phục từng gôi nhỏ".Chon đáp án: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(272, 'Điểm chung và cũng là ưu điểm lớn nhất của phong trào yêu nước chống Pháp cuối thế kỉ XIX là gì?', 'SINGLE_CHOICE', '{"A": "Tập hợp đông đảo các giai cấp tầng lớp trong xã hội.", "B": "Khởi nghĩa vũ trang theo phạm trù phong kiến.", "C": "Xác định đúng đối tượng đấu tranh là thực dân Pháp.", "D": "Làm chậm quá trình xâm lược Việt Nam của Pháp."}', 'C', '- Đáp án A loại vì đây là điểm chung nhưng không phải ưu điểm lớn nhất.- Đáp án B loại vì phong trào nông dân Yên Thế không theo phạm trù phong kiến.- Đáp án C chọn vì lúc này phong trào đấu tranh đều xác định là chống Pháp.- Đáp án D loại vì với Hiệp ước Pa tơ nốt năm 1884 giữa triều đình nhà Nguyễn và thực dân Pháp thì thực dân Pháp đã cơ bản hoàn thành công cuộc xâm lược Việt Nam. Phong trào yêu nước chống Pháp cuối thế kỉ XIX đã làm chậm quá trình bình định Việt Nam của thực dân Pháp.Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(273, 'Nhận xét nào dưới đây phản ánh&nbsp;đúng&nbsp;tính chất của phong trào Cần vương (1885 – 1896) ở Việt Nam?', 'SINGLE_CHOICE', '{"A": "Phong trào đấu tranh có tính chất cải lương.", "B": "Yêu nước nhưng không mang tính cách mạng.", "C": "Phong trào đấu tranh tự phát, không có tổ chức.", "D": "Phong trào yêu nước và mang tính cách mạng."}', 'B', '- Đáp án B phản ánh đúng tính chất của phong trào Cần vương vì:+ Nhiệm vụ: chống Pháp, giải phóng dân tộc, xây dựng chế độ phong kiến với vua hiền, tôi giỏi.+ Lãnh đạo: giai đoạn 1885 - 1888 là vua Hàm Nghi, Tôn Thất Thuyết; giai đoạn 1888 - 1896 là văn thân, sĩ phu yêu nước tiến bộ.+ Khuynh hướng: phong kiến.→ Mang tính yêu nước nhưng không mang tính cách mạng.Chọn B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(274, 'Nét nổi bật của phong trào Cần vương ở giai đoạn hai (1888 – 1896) là gì?', 'SINGLE_CHOICE', '{"A": "Đặt dưới sự chỉ huy thống nhất của triều đình kháng chiến.", "B": "Đặt dưới sự chỉ huy gián tiếp của triều đình kháng chiến.", "C": "Không có sự chỉ huy của triều đình, các cuộc khởi nghĩa nổ ra lẻ tẻ.", "D": "Phong trào phát triển theo chiều sâu, quy tụ thành những trung tâm lớn."}', 'D', 'Nét nổi bật của phong trào Cần Vương ở giai đoạn hai (1888 – 1896) là: Phong trào phát triển theo chiều sâu, quy tụ thành những trung tâm lớn.Chọn D', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(275, 'Thất bại tại trận Cầu Giấy lần thứ hai (19/5/1883) đã khiến thực dân Pháp rơi vào tình trạng như thế nào?', 'SINGLE_CHOICE', '{"A": "Càng củng cố dã tâm xâm chiếm hoàn toàn Việt Nam.", "B": "Hoang mang lo sợ và tìm cách thương thuyết để rút khỏi Bắc Kỳ.", "C": "Cầu cứu sự chi viện của triều đình Mãn Thanh.", "D": "Quyết định đánh thẳng vào Huế để kết thúc chiến tranh."}', 'A', 'Sau thất bại tại trận Cầu Giấy lần thứ hai (19/5/1883), khác với lần trước, thực dân Pháp càng củng cố dã tâm xâm chiếm toàn bộ Việt NamChọn A', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(276, 'Hiệp ước nào đánh dấu việc triều đình nhà Nguyễn chính thức thừa nhận sáu tỉnh Nam Kì là đất thuộc Pháp?', 'SINGLE_CHOICE', '{"A": "Hiệp ước Hácmăng.", "B": "Hiệp ước Giáp Tuất.", "C": "Hiệp ước Patơnốt.", "D": "Hiệp ước Nhâm Tuất."}', 'B', 'Với Hiệp ước Giáp Tuất (1874), triều đình nhà Nguyễn chính thức thừa nhận sáu tỉnh Nam Kì là đất thuộc Pháp.Chọn B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(277, 'Nguyên nhân nào thúc đẩy các quốc gia trên thế giới hình thành liên minh chống phát xít?', 'SINGLE_CHOICE', '{"A": "Do uy tín của Liên Xô đã tập hợp được các nước khác.", "B": "Do hành động xâm lược, bành trướng của phe phát xít khiến thế giới lo ngại.", "C": "Do Anh, Mĩ đều thua nhiều trận trên chiến trường.", "D": "Do nhân dân các nước trên thế giới đoàn kết."}', 'B', '- Đáp án A loại vì đây chỉ là 1 trong các nguyên nhân thúc đẩy sự hợp tác giữa các nước lớn chống lại phe phát xít.- Đáp án B đúng vì hành động xâm lược của phe phát xít đã làm cho các nước lo ngại. Cụ thể là Anh, Pháp sau đó có Mĩ đã bắt tay với Liên Xô để cùng chống lại các nước phát xít.- Đáp án C loại vì lúc này Anh chưa thất bại trên chiến trường (Anh có ưu thế về hải quân, không quân và có sự viện trợ của Mĩ nên kế hoạch đổ bộ lên nước Anh của quân Đức không thực hiện được).- Đáp án D loại vì thực tế chiến trường cho thấy chỉ có một số nước lớn tham chiến.Chọn B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(278, 'Cuộc khởi nghĩa chống Pháp nào ở Lào, kéo dài suốt hơn 30 năm đầu thế kỉ XX?', 'SINGLE_CHOICE', '{"A": "Khởi nghĩa Ong Kẹo", "B": "Khởi nghĩa Commađam", "C": "Khởi nghĩa Ong Kẹo và Commađam.", "D": "Khởi nghĩa Chậu Pachay"}', 'C', 'Ở Lào, cuộc khởi nghĩa Ong Kẹo và Commađam nổ ra từ năm 1901, tiếp diễn trong hơn 30 năm đầu thế kỉ XX&nbsp;(SGK Lịch sử 11, trang 87).Chọn C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(279, 'Quốc gia nào được xem là đã thoát khỏi cuộc khủng hoảng kinh tế thế giới 1929 - 1933 bằng con đường phát xít hóa bộ máy nhà nước?', 'SINGLE_CHOICE', '{"A": "Anh.", "B": "Pháp.", "C": "Đức.", "D": "Mĩ."}', 'A', 'Giải thích:&nbsp;Quốc gia Đức đã thoát khỏi cuộc khủng hoảng kinh tế thế giới 1929 – 1933 bằng con đường phát xít hóa bộ máy nhà nước.Đáp án:&nbsp;C', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(280, 'Nguyên nhân cơ bản nào dẫn đến sự sụp đổ của Trật tự Véc-xai - Oa-sinh-tơn?', 'SINGLE_CHOICE', '{"A": "Sự hình thành liên minh phát xít, gây chiến tranh thế giới thứ hai.", "B": "Sự mâu thuẫn về quyền lợi giữa các nước đế quốc không thể dung hòa.", "C": "Sự phát triển mạnh mẽ của phong trào giải phóng dân tộc.", "D": "Sự tác động mạnh mẽ của cuộc khủng hoảng kinh tế thế giới 1929 – 1933."}', 'A', 'Hai tháng sau khi Chiên tranh thế giới thứ nhất kết thúc, các nước tư bản họp hội nghị hòa bình ở Vecxai (1919-1920) và Oasinhtơn (1921-1922) nhằm phân chia thành quả giữa các nước thắng trận và thiết lập một trật tự thế giới mới sau chiến tranh. Một trật tự thế giới mới được thiết lập thông qua các văn kiện được kí kết tại Véc xai và Oasinhtơn (hệ thống Vecxai-Oasinhtơn). Trật tự này quá nặng nề với các nước bại trận, không thỏa mãn được quyền lợi của các nước thắng trận khiến cho những mâu thuẫn giữa các nước đế quốc tiếp tục bị đào sâu. Đây là nguyên nhân cơ bản dẫn đến sự sụp đổ của trật tự Vécxai - Oasinhtơn.Đáp án cần chọn là: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(281, 'Trật tự Véc-xai - Oa-sinh-tơn được coi là đã thiết lập phản ánh điều gì trong quan hệ quốc tế?', 'SINGLE_CHOICE', '{"A": "Sự phân chia quyền lợi giữa các nước thắng trận.", "B": "Tương quan lực lượng mới giữa các nước tư bản.", "C": "Sự bất đồng, mâu thuẫn về quyền lợi.", "D": "Sự xác lập ách thống trị và nô dịch đối với các nước bại trận."}', 'A', 'Với hệ thống Véc-xai – Oa-sinh-tơn, một trật tự thế giới mới đã được thiết lập. Sự phân chia quyền lợi giữa các nước tại hội nghị đã phản ánh tương quan lực lượng mới giữa các nước tư bản (quy mô thị trường, thuộc địa, sự phát triển kinh tế sau chiến tranh).Đáp án cần chọn là: B', 10);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(282, 'Cuộc khủng hoảng kinh tế thế giới 1929 - 1933 không mang đặc điểm nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Diễn ra tình trạng hàng hóa ế thừa, cung vượt quá xa cầu.", "B": "Cuộc khủng hoảng bùng nổ ở Mĩ sau đó lan ra các nước tư bản chủ nghĩa.", "C": "Cuộc khủng hoảng kéo dài 4 năm và để lại nhiều hậu quả nghiêm trọng.", "D": "Cuộc khủng hoảng chỉ ảnh hưởng đến các nước tư bản chủ nghĩa."}', 'A', 'Cuộc khủng hoảng 1929 - 1933 là “khủng hoảng thừa”. Nguyên nhân chủ yếu là do các nước tư bản chạy theo lợi nhuận, sản xuất hàng hóa ồ ạt, không gắn với cải thiện đời sống người lao động khiến cho hàng hóa ế thừa, cung vượt quá xa cầu.Bùng nổ đầu tiên ở nước Mĩ sau đó lan ra các nước tư bản chủ nghĩa. Cuộc khủng hoảng kéo dài 4 năm và để lại nhiều hậu quả nghiêm trọng. Không chỉ đối với nền kinh tế các nước tư bản, nó còn có tác động mạnh mẽ tới nhiều quốc gia khác trên thế giới.Đáp án cần chọn là: D', 10);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(11, 'Đề thi thử học kỳ 2 môn Hoá Học lớp 11 online - Mã đề 03', 'Hóa Học', 35, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Hóa Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(283, 'Benzen không tan trong nước vì lí do nào sau đây?', 'SINGLE_CHOICE', '{"A": "Benzen là chất hữu cơ, nước là chất vô cơ nên không tan vào nhau.", "B": "Benzen có khối lượng riêng bé hơn nước.", "C": "Phân tử benzen là phân tử phân cực.", "D": "Phân tử benzen là phân tử không phân cực, nước là dung môi có cực."}', 'A', 'Benzen không tan trong nước vì “Phân tử benzen là phân tử không phân cực, nước là dung môi có cực”.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(284, 'Theo danh pháp IUPAC, hợp chất CH3CHOHCH2CH2CH(CH3)2&nbsp;có tên gọi:', 'SINGLE_CHOICE', '{"A": "5 – metylhexan – 2 – ol.", "B": "5,5 – đimetylpentan – 2 – ol.", "C": "2 – đimetylhexan – 5 – ol.", "D": "2,2 – đimetylpentan – 5 – ol."}', 'A', 'Theo danh pháp IUPAC, hợp chất CH3CHOHCH2CH2CH(CH3)2&nbsp;có tên gọi:&nbsp;5 – metylhexan – 2 – ol.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(285, 'Đốt cháy hoàn toàn một anđehit X, thu được số mol CO2&nbsp;bằng số mol H2O. Nếu cho X tác dụng với lượng dư AgNO3&nbsp;trong dung dịch NH3, sinh ra số mol Ag gấp bốn lần số mol X đã phản ứng. Công thức của X là:', 'SINGLE_CHOICE', '{"A": "HCHO.", "B": "(CHO)2.", "C": "CH3CHO.", "D": "C2H5CHO."}', 'A', '- Đốt cháy X, thu được số mol CO2&nbsp;bằng số mol H2O&nbsp;&nbsp;&nbsp;→ loại đáp án B.- 1 mol X tác dụng AgNO3/ NH3&nbsp;thu được 4 mol Ag&nbsp;&nbsp;&nbsp;→ HCHO thỏa mãn.- Chọn đáp án A.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(286, 'Cho dãy các chất sau: HCHO, HCOOH, C2H2, CH3&nbsp;– CO – CH3. Số chất trong dãy tham gia phản ứng với AgNO3/ NH3&nbsp;là:', 'SINGLE_CHOICE', '{"A": "1.", "B": "2.", "C": "3.", "D": "4."}', 'A', '&nbsp;Chất trong dãy tham gia phản ứng với AgNO3/ NH3&nbsp;là HCHO, HCOOH, C2H2.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(287, 'Số đồng phân anđehit ứng với công thức phân tử C5H10O là:', 'SINGLE_CHOICE', '{"A": "3.", "B": "5.", "C": "6.", "D": "4."}', 'A', '$27', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(288, 'Dung dịch axit axetic phản ứng được với tất cả các chất trong dãy nào sau đây?', 'SINGLE_CHOICE', '{"A": "NaOH, Cu, NaCl.", "B": "Na, NaCl, CuO.", "C": "NaOH, Na, CaCO3.", "D": "Na, CuO, HCl."}', 'A', 'Dung dịch axit axetic phản ứng được với: NaOH, Na, CaCO3.NaOH + CH3COOH → CH3COONa + H2ONa &nbsp;+ CH3COOH → CH3COONa + 1/2H2CaCO3 + CH3COOH → (CH3COO)2Ca + + CO2 + H2O', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(289, 'Axit fomic&nbsp;không&nbsp;thể tác dụng với chất nào sau đây?', 'SINGLE_CHOICE', '{"A": "dd AgNO3/ NH3.", "B": "CH3OH.", "C": "CH3CHO.", "D": "Cu(OH)2."}', 'A', 'Axit fomic không thể tác dụng với CH3CHO.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(290, 'Có bao nhiêu đồng phân ankin có công thức phân tử C5H8 có thể tham gia phản ứng với dung dịch bạc nitrat trong amoniac?', 'SINGLE_CHOICE', '{"A": "2.", "B": "3.", "C": "4.", "D": "5."}', 'A', 'Chỉ có 2 ankin có liên kết ba ở đầu mạch mới tác dụng đó là pent – 1 – in và 3 – metylbut – 1 – in.CH\(\equiv \)C-CH2-CH2-CH3 + AgNO3 + NH3 → Ag-C\(\equiv \)C-CH2-CH2-CH3 + NH4NO3CH\(\equiv \)C-CH(CH3)-CH3+ AgNO3 + NH3 → Ag-C\(\equiv \)C-CH(CH3)-CH3 + NH4NO3', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(291, 'Hỗn hợp gồm C2H2, C2H4, C2H6&nbsp;để tinh chế C2H6&nbsp;người ta cho hỗn hợp lội chậm qua:', 'SINGLE_CHOICE', '{"A": "dd NaOH.", "B": "dd KMnO4.", "C": "dd AgNO3/ NH3.", "D": "H2O."}', 'A', 'Cả C2H2&nbsp;và C2H4&nbsp;đều phản ứng với dung dịch KMnO4&nbsp;nên bị giữa lại trong dung dịch do chúng có liên kết pi trong phân tử, còn C2H6&nbsp;thì không phản ứng.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(292, 'Hiđrocacbon sau:CH3-CH2-CH(CH3)-CH=CH-CH2-CH((CH3))2có tên gọi là:', 'SINGLE_CHOICE', '{"A": "4, 7 – đimetyloct – 4 – en.", "B": "3, 7 – đimetyloct – 4 – en.", "C": "2, 8 – đimetyloct – 4 – en.", "D": "2, 7 – đimetyloct – 4 – en."}', 'A', 'CH3-CH2-CH(CH3)-CH=CH-CH2-CH((CH3))2: 2, 7 – đimetyloct – 4 – en.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(293, 'Hiện tượng xảy ra khi cho brom lỏng vào ống nghiệm chứa benzen, lắc nhẹ hỗn hợp?', 'SINGLE_CHOICE', '{"A": "Brom lỏng bị mất màu.", "B": "Có khí thoát ra.", "C": "Xuất hiện kết tủa.", "D": "Brom lỏng không bị mất màu."}', 'A', 'Hỗn hợp tách lớp và brom lỏng không bị mất màu do benzen chỉ tác dụng với brom khan có xúc tác bột sắt', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(294, 'Trong điều kiện thích hợp glucozơ lên men tạo thành khí CO2&nbsp;và chất nào dưới đây?', 'SINGLE_CHOICE', '{"A": "CH3COOH.", "B": "CH3CHO.", "C": "HCOOH.", "D": "C2H5OH."}', 'A', 'Trong điều kiện thích hợp glucozơ lên men tạo thành khí CO2&nbsp;và C2H5OH.C6H12O6&nbsp;→ 2C2H5OH + 2CO2&nbsp;', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(295, 'Oxi hoá không hoàn toàn ancol isopropylic bằng CuO nung nóng, thu được chất hữu cơ X. Tên gọi của X là:', 'SINGLE_CHOICE', '{"A": "metyl phenyl xeton.", "B": "metyl vinyl xeton.", "C": "đimetyl xeton.", "D": "propanal."}', 'A', 'Ancol isopropylic: (CH3)2CHOH là ancol bậc 2 → X là CH3&nbsp;– CO – CH3&nbsp;(đimetyl xeton).', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(296, 'Oxi hoá không CH3CH2OH bằng CuO đun nóng, thu được anđehit có công thức là:', 'SINGLE_CHOICE', '{"A": "CH3CH2CHO.", "B": "CH3CHO.", "C": "CH2 = CHCHO.", "D": "HCHO."}', 'A', 'Oxi hoá CH3CH2OH bằng CuO đun nóng, thu được anđehit có công thức là CH3CHO do ancol CH3CH2OH bậc 1', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(297, 'Cho m (g) anđehit axetic vào dung dịch AgNO3/ NH3&nbsp;dư thì thu được 6,48 gam Ag. Với H = 75% thì m có giá trị là:', 'SINGLE_CHOICE', '{"A": "1,32g.", "B": "1,98g.", "C": "1,76g.", "D": "0,99g."}', 'A', '&nbsp;nAg&nbsp;= 2nanđehit&nbsp;pư → nanđehit&nbsp;pư = 0,03 mol.m = 0,03.44/75% = 1,76 g', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(298, 'Cho dãy các chất sau: HCHO, HCOOH, C2H2, CH3&nbsp;– CO – CH3. Số chất trong dãy tham gia phản ứng tráng bạc là:', 'SINGLE_CHOICE', '{"A": "1.", "B": "2.", "C": "3.", "D": "4."}', 'A', 'Chất trong dãy tham gia phản ứng tráng bạc là HCHO, HCOOH.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(299, 'Axit axetic có công thức là?', 'SINGLE_CHOICE', '{"A": "CH3CHO.", "B": "CH3COOH.", "C": "HCOOH.", "D": "HCHO."}', 'A', 'Axit axetic là CH3COOH', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(300, 'Đốt cháy hoàn toàn a gam hỗn hợp gồm 4 hiđrocacbon thu được 33g CO2&nbsp;và 13,5g H2O. Giá trị của a là:', 'SINGLE_CHOICE', '{"A": "10,5.", "B": "11.", "C": "11,5.", "D": "12."}', 'A', 'Số mol CO2&nbsp;= số mol H2O = 0,75 (mol)&nbsp;&nbsp;&nbsp;a = mC&nbsp;+ mH&nbsp;= 0,75.12 + 0,75.2.1 = 10,5 (gam).', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(301, 'Hiện tượng xảy ra khi đun nóng toluen với dung dịch thuốc tím&nbsp;KMnO4 là:', 'SINGLE_CHOICE', '{"A": "dung dịch KMnO4 bị nhạt màu.", "B": "có kết tủa trắng.", "C": "có sủi bọt khí.", "D": "không có hiện tượng gì."}', 'A', 'Hiện tượng xảy ra khi đun nóng toluen với dung dịch thuốc tím là dung dịch KMnO4&nbsp;bị nhạt màu.2KMnO4&nbsp;+&nbsp;C6H5CH3&nbsp;\(\xrightarrow{{{t}^{o}}}\)&nbsp;H2O&nbsp;+&nbsp;KOH&nbsp;+&nbsp;2MnO2&nbsp;+&nbsp;C6H5COOK', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(302, 'Dãy gồm các chất đều phản ứng với phenol là:', 'SINGLE_CHOICE', '{"A": "dung dịch NaCl, dung dịch NaOH, kim loại Na.", "B": "nước brom, anđehit axetic, dung dịch NaOH.", "C": "nước brom, anhiđrit axetic, dung dịch NaOH.", "D": "nước brom, axit axetic, dung dịch NaOH."}', 'A', 'Dãy gồm các chất đều phản ứng với phenol là nước brom, anhiđrit axetic, dung dịch NaOH.C6H5OH + NaOH → C6H5ONa + H2OC6H5OH + 3Br2→ C6H2Br3OH + 3HBrC6H5OH + (CH3CO)2O → CH3COOH + CH3COOC6H5', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(303, 'Đốt cháy hoàn toàn anđehit X, thu được thể tích khí CO2&nbsp;bằng thể tích hơi nước (trong cùng điều kiện nhiệt độ, áp suất). Khi cho 0,01 mol X tác dụng với một lượng dư dung dịch AgNO3&nbsp;trong NH3&nbsp;thì thu được 0,04 mol Ag. X là:', 'SINGLE_CHOICE', '{"A": "anđehit no, mạch hở, hai chức.", "B": "anđehit không no, mạch hở, hai chức.", "C": "anđehit axetic.", "D": "anđehit fomic."}', 'A', '$28', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(304, 'Đốt cháy hoàn toàn 1 mol hợp chất hữu cơ X, thu được 4 mol CO2. Chất X tác dụng được với Na, tham gia phản ứng tráng bạc và phản ứng cộng Br2&nbsp;theo tỉ lệ mol 1 : 1. Công thức cấu tạo của X là', 'SINGLE_CHOICE', '{"A": "HOOC – CH = CH – COOH.", "B": "HO - CH2 - CH2 – CH2 – CHO.", "C": "HO - CH2 – CH = CH – CHO.", "D": "HO - CH2 - CH2 – CH = CH – CHO."}', 'A', '- Số C trong X = nCO2&nbsp;: nX&nbsp;= 4&nbsp;&nbsp;&nbsp;→ Loại đáp án D.- X tham gia phản ứng tráng Ag → X có nhóm CHO&nbsp;&nbsp;&nbsp;→ Loại đáp án A.- X phản ứng với Br2&nbsp;theo tỉ lệ 1 : 1&nbsp;&nbsp;&nbsp;→ Loại đáp án C.- Đáp án đúng là B.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(305, 'Cho 0,36g metanal vào dung dịch AgNO3/ NH3&nbsp;dư đến khi phản ứng hoàn toàn thì thu được m gam Ag. Giá trị của m là:', 'SINGLE_CHOICE', '{"A": "1,296g.", "B": "2,592g.", "C": "5,184g.", "D": "2,568g."}', 'A', 'metanal: HCHO.- Ta có:&nbsp;&nbsp;&nbsp;nAg&nbsp;= 4.nHCHO&nbsp;= 0,012.4 = 0,048 mol&nbsp;&nbsp;&nbsp;→ m = 0,048.108 = 5,184g.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(306, 'Chất nào sau đây là axit acrylic?', 'SINGLE_CHOICE', '{"A": "CH3COOH.", "B": "HCOOH.", "C": "CH2 = CH – COOH.", "D": "HCHO."}', 'A', 'Axit acrylic: CH2&nbsp;= CH – COOH.', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(307, 'Cho các chất: but – 1 – en, but – 1 – in, buta – 1, 3 – đien, vinylaxetilen, isobutilen, anlen. Có bao nhiêu chất trong số các chất trên khi phản ứng hoàn toàn với khí dư (xúc tác Ni, đun nóng) tạo ra butan?', 'SINGLE_CHOICE', '{"A": "6.", "B": "5.", "C": "4.", "D": "3."}', 'A', '$29', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(308, 'Công thức tổng quát của hiđrocacbon có dạng CnH2n + 2 – 2a. Khi giá trị a = 2 ứng với:', 'SINGLE_CHOICE', '{"A": "xiclopentan.", "B": "2 – metylbuta – 1, 3 – đien.", "C": "vinylaxetylen.", "D": "xiclohexan."}', 'A', 'Khi a = 2 thì công thức tổng quát là:&nbsp;CnH2n - 2&nbsp;ứng với 2 – metylbuta – 1, 3 – đien:CH2=C(CH3)-CH=CH2', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(309, 'Hỗn hợp G gồm 2 ancol X, Y (MX&nbsp;&lt; MY). Tiến hành thí nghiệm về G thu được kết quả như sau:&nbsp;&nbsp;&nbsp;- Lấy 6,64 gam G cho vào H2SO4&nbsp;đặc đun nóng thu được 2 anken liên tiếp.&nbsp;&nbsp;&nbsp;- Nhỏ 5 ml H2SO4&nbsp;đặc vào m gam G và đun nóng ở 140°c sau một thời gian thu được 13,9 gam hỗn hợp Z gồm 3 ete. Đốt cháy hoàn toàn Z thu được 17,92 lít CO2&nbsp;(ở đktc).Xác định CTPT của X, Y.', 'SINGLE_CHOICE', '{"A": "X: C2H5OH; Y: C3H7OH", "B": "X: C3H7OH; Y: C4H9OH", "C": "X: C2H5OH; Y: C4H9OH", "D": "X: CH3OH; Y: C2H5OH"}', 'A', '- Vì G cho vào H2SO4 đặc đun nóng thu được 2 anken liên tiếp nên G gồm 2 ancol no, đơn chức, mạch hở và liên tiếp.- Gọi CTC của G là:&nbsp;\({{C}_{\overline{n}}}{{H}_{2\overline{n}+1}}OH\)- Phản ứng tạo ete:&nbsp;&nbsp;&nbsp;\(2{{C}_{\overline{n}}}{{H}_{2\overline{n}+1}}OH\xrightarrow{{{140}^{0}}C,xt}{{({{C}_{\overline{n}}}{{H}_{2\overline{n}+1}})}_{2}}O+{{H}_{2}}O\)- Đốt cháy ete:&nbsp;&nbsp;&nbsp;\({{({{C}_{\overline{n}}}{{H}_{2\overline{n}+1}})}_{2}}O+{{O}_{2}}\xrightarrow{{{t}^{0}}}2\overline{n}C{{O}_{2}}+(2\overline{n}+1){{H}_{2}}O\)- Tìm được&nbsp;\(\overline{n}=2,667\)- Vậy 2 ancol là: X: C2H5OH; Y: C3H7OH', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(310, 'Trung hòa 3,36 gam một axit hữu cơ Y đơn chức cần dùng 100 gam dung dịch NaOH 2,24%. Công thức phân tử của Y là', 'SINGLE_CHOICE', '{"A": "C2H3COOH", "B": "C2H5COOH", "C": "HCOOH", "D": "CH3COOH"}', 'A', '- Tính số mol NaOH = 0,056 mol- Gọi CTTQ axit RCOOH (R là H hoặc gốc HC)- Viết PT:&nbsp;&nbsp;&nbsp;RCOOH + NaOH → RCOONa + H2O- Theo PTHH xác định số mol axit 0,056 mol&nbsp;&nbsp;&nbsp;→ Maxit&nbsp;= 60 ⇒ R = 15 ( R là - CH3)- CTPT: C2H4O2- CTCT: CH3COOH', 11);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(311, 'Hiđrat hóa 2 – metylbut – 2 – en (điều kiện nhiệt độ, xúc tác thích hợp) thu được sản phẩm chính là:', 'SINGLE_CHOICE', '{"A": "3 – metylbutan – 2 – ol.", "B": "3 – metylbutan – 1 – ol.", "C": "2 – metylbutan – 2 – ol.", "D": "2 – metylbutan – 3 – ol."}', 'A', 'CH3-C(CH3)=CH-CH3 + H2O → CH3-C(CH3)OH-CH2-CH3 (spc)CH3-C(CH3)OH-CH2-CH3&nbsp;: 2 – metylbutan – 2 – ol.', 11);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(12, 'Đề thi thử giữa học kỳ 1 môn Hoá Học lớp 12 online - Mã đề 06', 'Hóa Học', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Hóa Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(312, 'Công thức phân tử không thể este.', 'SINGLE_CHOICE', '{"A": "C4H8O2.", "B": "C4H10O2.", "C": "C2H4O2.", "D": "C4H6O2."}', 'A', 'Este có dạng: CnH2n+2-2kO2&nbsp;(k ≥ 1)→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(313, 'Công thức đã viết đúng Este của glixerol với axit cacboxylic (RCOOH)&nbsp;(1) (RCOO)3C3H5&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(2) (RCOO)2C3H5(OH)(3) RCOOC3H5(OH)2&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(4) (ROOC)2C3H5(OH)(5) C3H5(COOR)3.', 'SINGLE_CHOICE', '{"A": "(1), (4).", "B": "(5).", "C": "(1), (5), (4).", "D": "(1), (2), (3)."}', 'A', 'Este của glixerol với axit cacboxylic (RCOOH) có dạng (RCOO)nC3H5(OH)3-n→ Vậy các este đó có thể là RCOOC3H5(OH)2; (RCOO)2C3H5(OH); (RCOO)3C3H5→ Các công thức viết đúng là (1), (2), (3)→ Đáp án&nbsp;D', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(314, 'Cho C4H6O2&nbsp;có số este mạch hở là mấy?', 'SINGLE_CHOICE', '{"A": "4", "B": "3", "C": "5", "D": "6"}', 'A', 'C4H6O2&nbsp;có k = 2 → este không no, có chứa liên kết đôi C = C, đơn chức, mạch hở→ Các đồng phân este mạch hở của C4H6O2&nbsp;làHCOOCH=CH-CH3HCOOCH2CH=CH2HCOOC(CH3)=CH2CH3COOCH=CH2CH2=CHCOOCH3→ Có 5 đồng phân este→ Đáp án&nbsp;C', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(315, 'Bao nhiêu đồng phân este của công thức C3H6O2&nbsp;bên dưới?', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "3", "D": "4"}', 'A', 'C3H6O2&nbsp;có k = 1 → este no, đơn chức, mạch hở→ Các đồng phân este có công thức phân tử C3H6O2&nbsp;là1. HCOOCH2CH3&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. CH3COOCH3→ Có 2 đồng phân este→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(316, 'Xác định tổng số liên kết π trong este no, đơn chức, mạch hở là bao nhiêu?', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "3", "D": "4"}', 'A', 'Este no, đơn chức, mạch hở (CnH2nO2) có k = 1→ có 1 liên kết π (trong nhóm – COO –)→ Đáp án&nbsp;A', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(317, 'Este no, đơn chức, mạch hở có công thức tổng quát là gì bên dưới?', 'SINGLE_CHOICE', '{"A": "CnH2nO (n ≥ 1).", "B": "CnH2nO2 (n ≥ 1).", "C": "CnH2nO2 (n ≥ 2).", "D": "CnH2nO3 (n ≥ 2)."}', 'A', 'Công thức tổng quát của este no, đơn chức, mạch hở là CnH2nO2&nbsp;(n ≥ 2)→ Đáp án&nbsp;C', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(318, 'Đâu không là este trong tổng 4 chất bên dưới?', 'SINGLE_CHOICE', '{"A": "HCOOC2H5.", "B": "C2H5CHO.", "C": "CH3COOCH = CH2.", "D": "CH2(CH2-COO-C2H5)-COO-CH3"}', 'A', 'HCOOC2H5&nbsp;và CH3COOCH = CH2&nbsp;là este đơn chức → Loại đáp án A, CCH2(CH2-COO-C2H5)-COO-CH3&nbsp;là este 2 chức → Loại đáp án DC2H5CHO là anđêhit → C2H5CHO không phải là este→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(319, 'Phương pháp làm sạch dầu ăn dính quần áo ?', 'SINGLE_CHOICE', '{"A": "Nhỏ vài giọt cồn vào vết dầu ăn", "B": "Giặt bằng nước", "C": "Giặt bằng xăng", "D": "Giặt bằng xà phòng"}', 'A', 'Xà phòng thường dùng là hỗn hợp muối natri hoặc kali của axit béo, có thêm một số chất phụ gia. Phân tử muối natri của axit béo gồm 1 đầu ưa nước là nhóm COO-Na+ nối với 1 đuôi kị nước, ưa dầu mỡ là nhóm –CxHy&nbsp;(thường x ≥ 15). Đầu ưa dầu mỡ thâm nhập vào vết bẩn, còn nhóm COO-Na+ ưa nước có xu hướng kéo ra các phía phân tử nước → làm giảm sức căng bề mặt các chất bẩn bám trên vải, da → vết bẩn phân tán nhiều phần nhỏ rồi phân tán vào nước và bị rửa trôi (Xem hình 1.8: Sơ đồ quá trình làm sạch vết bẩn của xà phòng – SGK lớp 12 cơ bản – trang 15).→ Đáp án&nbsp;D', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(320, 'Chất phân biệt tinh bột, glixerin, lòng trắng trứng riêng biệt dưới đây?', 'SINGLE_CHOICE', '{"A": "HNO3", "B": "Cu(OH)2", "C": "I2", "D": "Giấy quì"}', 'A', 'Trích mẫu thử, đánh số thứ tự.- Ống nghiệm tác dụng với Cu(OH)2&nbsp;tạo phức màu xanh lam → glixerin.- Ống nghiệm tác dụng với Cu(OH)2&nbsp;tạo phức màu tím → lòng trắng trứng (protein).- Ống nghiệm tác dụng với Cu(OH)2&nbsp;không có hiện tượng → tính bột.→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(321, 'Số phát biểu đúng của protein trong 4 ý?(1) Protein phản ứng màu biure Cu(OH)2&nbsp;ở nhiệt độ thường cho màu tím đặc trưng.(2) Protein dạng sợi tan trong nước tạo dung dịch keo.(3) Protein tác dụng với HNO3&nbsp;đặc, cho kết tủa vàng.(4) Protein đều là chất lỏng ở điều kiện thường.', 'SINGLE_CHOICE', '{"A": "2", "B": "1", "C": "3", "D": "4"}', 'A', 'Các phát biểu đúng là (1), (3)(2) sai phải là protein hình cầu.(4) sai phải là chất rắn ở điều kiện thường.→ Đáp án&nbsp;A', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(322, 'Hãy tìm các chất X, Y, Z, T biết chúng thõa mãn dưới đây?Mẫu thửThí nghiệmHiện tượngXTác dụng với Cu(OH)2Hợp chất màu tímYQuì tím ẩmQuì đổi xanhZTác dụng với dung dịch Br2Dung dịch mất màu và có kết tủa trắngTTác dụng với dung dịch Br2Dung dịch mất màu', 'SINGLE_CHOICE', '{"A": "Acrilonitrin, Anilin, Gly-Ala-Ala, Metylamin.", "B": "Gly-Ala-Ala, Metylamin, Acrilonitrin, Anilin.", "C": "Gly-Ala-Ala, Metylamin, Acrilonitrin, Anilin.", "D": "Metylamin, Anilin, Gly-Ala-Ala, Acrilonitrin."}', 'A', 'X + Cu(OH)2&nbsp;→ màu tím → X phải là tripeptit trở lên → loại A và D.Z + Br2&nbsp;→ Kết tủa trắng → Anilin chứ không thể là acrilonitrin → loại C.→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(323, 'Mấy tripeptit chứa 3 gốc aminoaxit khác nhau bên dưới?', 'SINGLE_CHOICE', '{"A": "6", "B": "4", "C": "2", "D": "3"}', 'A', 'Có 3 loại gốc aminoaxit khác nhau thì số đồng phân peptit sẽ là 3! = 6→ Đáp án đúng là đáp án A', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(324, 'Thuỷ phân 1,0 mol H2N-CH(CH3)-CO-NH-CH2-CO-NH-CH2-CH2-CO-NH-CH(C6H5)-CO-NH-CH(CH3)-COOH được mấy mol α-amino axit ?', 'SINGLE_CHOICE', '{"A": "3", "B": "5", "C": "2", "D": "4"}', 'A', 'Thủy phân hoàn toàn sẽ thu được:2 mol Alanin, 1 mol Glyxin, 1 mol Phenylalanin và 1 amino axit không phải là α-amino axit→ Đáp án&nbsp;D', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(325, 'Thuỷ phân 51,3 gam mantozơ trong môi trường axit với hiệu suất phản ứng đạt 80% thu được hỗn hợp X. Trung hoà X bằng NaOH thu được dung dịch Y. Cho Y tác dụng hết với lượng dư dung dịch AgNO3&nbsp;trong NH3&nbsp;đun nóng, sinh ra m gam Ag. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "51,84", "B": "32,40.", "C": "58,32.", "D": "58,82"}', 'A', 'Đáp án CKhi thủy phân mantozo thì Mantozo → 2 glucozoSau phản ứng có mantozo và glucozo do phản ứng có hiệu suất đều tham gia phản ứng vớiAgNO3&nbsp;tạo Ag với : mantozo → 2Ag và glucozo → 2 AgSuy ra nAg = 0,03.2 + 0,24.2 = 0,54 mol → m = 58,32g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(326, 'Cho m gam dung dịch glucozơ 20% tráng bạc, phản ứng hoàn toàn sinh ra 32,4 gam bạc. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "108 gam.", "B": "135 gam.", "C": "54 gam.", "D": "270 gam."}', 'A', 'Đáp án BGlucozo&nbsp;→ 2Ag0,15 → 0,3 mol→ mdd Glucozo = 135g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(327, 'Đun nóng dung dịch chứa 27g glucozơ với dung dịch AgNO3/NH3&nbsp;thì khối lượng Ag thu được tối đa là', 'SINGLE_CHOICE', '{"A": "21,6g.", "B": "10,8g.", "C": "32,4g.", "D": "16,2g."}', 'A', 'Đáp án CGlucozo&nbsp;→ 2Ag0,15 → 0,3 mol→ m = 32,4g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(328, 'Đun nóng dung dịch chứa m gam glucozo với lượng dư AgNO3/NH3&nbsp;đến khi phản ứng hoàn toàn được 10,8 gam Ag. Giá trị của m là?', 'SINGLE_CHOICE', '{"A": "16,2 gam", "B": "18 gam", "C": "9 gam", "D": "10,8 gam"}', 'A', 'Đáp án CnAg = 0,1 mol =&gt; n glu = 0,05 mol=&gt; m = 0,05.180 = 9g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(329, 'Điều chế ancol etylic từ 1 tấn tinh bột chứa 5% tạp chất trơ, hiệu suất toàn bộ quá trình đạt 85%. Khối lượng ancol thu được là?', 'SINGLE_CHOICE', '{"A": "458,58 kg", "B": "485,85 kg", "C": "398,8 kg", "D": "389,79 kg"}', 'A', 'Đáp án AmTinh bột = 1000.95% = 950 kg(C6H10O5)n&nbsp;→ C6H12O6&nbsp;→ 2C2H5OH950/162 → 950.2/162→ mC2H5OH = 85%.46.950.2/162 = 458,58 kg', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(330, 'Miếng chuối xanh tác dụng với dung dịch iot cho màu xanh do chuối xanh có chứa', 'SINGLE_CHOICE', '{"A": "tinh bột", "B": "xenlulozo", "C": "glucozo", "D": "saccarozo"}', 'A', 'Miếng chuối xanh tác dụng với dung dịch iot cho màu xanh do chuối xanh có chứa tinh bột', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(331, 'Cho các tính chất hoặc thuộc tính sau:(1) là chất rắn kết tinh, không màu;(2) tan tốt trong nước và tạo dung dịch có vị ngọt;(3) phản ứng với Cu(OH)2&nbsp;trong NaOH ở nhiệt độ thường;(4) tồn tại ở dạng mạch vòng và mạch hở;(5) có phản ứng tráng gương;(6) thủy phân trong môi trường axit thu được glucozơ và fructozơ.Những tính chất đúng với saccarozơ là:', 'SINGLE_CHOICE', '{"A": "(1), (2), (3), (6)", "B": "(1), (2), (4), (5)", "C": "(2), (4), (5), (6)", "D": "(2), (3), (5), (6)"}', 'A', 'Đáp án ASaccarozơ vẫn phản ứng với Cu(OH)2&nbsp;trong NaOH ở nhiệt độ thường (chỉ thể hiện phản ứng với Cu(OH)2&nbsp;tính chất của ancol còn NaOH ko hề tham gia phản ứng ở đây)', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(332, 'Đốt cháy hoàn toàn m gam hỗn hợp gồm xenlulozơ, tinh bột, glucozơ và sacarozơ cần 2,52 lít O2&nbsp;(đktc) thu được 1,8 gam nước. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "6,20", "B": "5,25", "C": "3,60", "D": "3,15"}', 'A', '4 chất Xenlulozơ , tinh bột, fructozơ, glucozơ, đều thuộc cacbohiđrat → CTTQ: Cn(H2O)mBản chất đốt cháy các chất này là quá trình đốt cháy Cacbon: C + O2&nbsp;→ CO2Từ PTHH: → nC = nO2&nbsp;= 2,52 : 22,4 = 0,1125 (mol)BTKL: m = mC + mH2O = 0,1125. 12 + 1,8 = 3,15 (g)', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(333, 'Cho m gam glucozo lên men tạo thành ancol etylic với hiệu suất 75%. Toàn bộ khí CO2&nbsp;sinh ra được hấp thụ vào dung dịch Ca(OH)2&nbsp;dư thu được 80 g kết tủa. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "144", "B": "72", "C": "54", "D": "96"}', 'A', 'Đáp án DnCaCO3&nbsp;=0,8 mol → nCO2&nbsp;=0,8 mol → theo lý thuyết nglucose= 0,4 mol→ thực tế nglucozo= 0,4 :0,75 =0,53 mol→ m = 96g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(334, 'Đốt cháy hoàn toàn một lượng hỗn hợp X chứa glucozơ và fructozơ, saccarozơ, mantozơ cân dùng vừa đủ 37,632 lít khí O2&nbsp;(đktc) thu được CO2&nbsp;và H2O. Cho toàn bộ sản phẩm cháy qua dung dịch Ba(OH)2&nbsp;dư thấy có m gam kết tủa xuất hiện. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "260,04.", "B": "287,62.", "C": "330,96.", "D": "220,64."}', 'A', 'Đáp án CC6H12O6&nbsp;và C12H22O11&nbsp;đều có CTTQ CnH2nOnCnH2nOn&nbsp;+ nO2&nbsp;→ nCO2&nbsp;+ nH2OnCO2&nbsp;= nO2&nbsp;= 1,68 (mol)→ m BaCO3&nbsp;= 1,68.197 =330, 96 (g)', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(335, 'Lên men hoàn toàn 135g Glucozo thành ancol etylic và V lit CO2&nbsp;(dktc). Giá trị của V là:', 'SINGLE_CHOICE', '{"A": "8,4", "B": "33,6", "C": "16,8", "D": "50,4"}', 'A', 'Đáp án BC6H12O6&nbsp;→&nbsp; 2CO2&nbsp;+ 2C2H5OH0,75 → 1,5 mol→ VCO2&nbsp;= 33,6 lit', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(336, 'Thủy phân hoàn toàn 34,2 gam saccarozơ trong 200 ml dung dịch HCl 0,1M thu được dung dịch X. Trung hòa dung dịch X bằng một lượng NaOH vừa đủ thu được dung dịch Y; sau đó cho toàn bộ Y tác dụng với lượng dư dung dịch AgNO3&nbsp;trong NH3, thu được m gam kết tủa. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "43,20.", "B": "21,60.", "C": "46,07.", "D": "24,47."}', 'A', 'Đáp án CSaccarozo → Glucozo + Fructozo&nbsp; &nbsp; &nbsp; &nbsp;0,1 →&nbsp; &nbsp; &nbsp; &nbsp; 0,1 →&nbsp; &nbsp; &nbsp; &nbsp; 0,1 molY + AgNO3:Glucozo → 2AgFructozo → 2AgNaCl → AgClKết tủa gồm: 0,4 mol Ag; 0,02 mol AgCl→ m = 46,07g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(337, 'Cho dung dịch chứa m gam hỗn hợp glucozo và fructozo vào dung dịch AgNO3/NH3&nbsp;dư thu được 38,88g Ag. Giá trị của m là :', 'SINGLE_CHOICE', '{"A": "48,6", "B": "32,4", "C": "64,8", "D": "16,2"}', 'A', 'Đáp án BGlucozo → 2AgFructozo → 2Ag→ nGlucozo + nFructozo = 0,18 mol→ m = 32,4g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(338, 'Xenlulozơ trinitrat là chất dễ cháy và nổ mạnh được điều chế từ xenlulozơ và HNO3. Muốn điều chế 29,7 kg Xenlulozơ trinitrat (hiệu suất 90%) thì thể tích HNO3 96%( d=1,52 g/ml) cần dùng là', 'SINGLE_CHOICE', '{"A": "1,439 lít.", "B": "14,39 lít.", "C": "24,39 lít.", "D": "15 lít."}', 'A', 'Đáp án BnC6H7O2(NO3)3&nbsp;= 0,1 k.mol → nHNO3&nbsp;= 0,3 k.mol→ n lý thuyết = 0,3 : 90 . 100 = k.mol → m HNO3&nbsp;= 21 g→ m dd HNO3&nbsp;= 21: 96.100 = 21,875 k.g→ V dd HNO3&nbsp;= 21,875 : 1,52 = 14,39 k.ml = 14,39 lít', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(339, 'Đun nóng dung dịch chứa m gam glucozơ với lượng dư dung dịch AgNO3&nbsp;trong NH3. Sau khi phản ứng xảy ra hoàn toàn, thu được 10,8 gam Ag. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "4,5.", "B": "9,0.", "C": "18,0.", "D": "8,1."}', 'A', 'Đáp án BC6H12O6&nbsp;+ AgNO3&nbsp;+ NH3&nbsp;→ 2 Agn Ag = 0,1 mol → n glucozo = 0,05 mol→ m Glucozo = 9 g', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(340, 'Đốt cháy hoàn toàn V lít hơi một amin X bằng một lượng oxi vừa đủ tạo ra 8V lít hỗn hợp gồm khí cacbonic, khí nitơ và hơi nước (các thể tích khí và hơi đều đo ở cùng điều kiện). Amin X có cùng bậc với ancol metylic. Chất X là', 'SINGLE_CHOICE', '{"A": "CH2=CH-NH-CH3.", "B": "CH3-CH2-NH-CH3.", "C": "CH3-CH2-CH2-NH2.", "D": "CH2=CH-CH2-NH2"}', 'A', 'Đáp án CAmin X bậc 1 nên X là CxHyNH2&nbsp;Khi X tác dụng với O2&nbsp;thì tạo ra CO2, N2&nbsp;và H2O có thể tích là8V = x.V + V:2 + (y+2).V : 2 nên 13 = 2x + yChọn x = 3 và y =7', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(341, 'Trong bình kín chứa 40 ml khí oxi và 35 ml hỗn hợp khí gồm hiđro và một amin đơn chức X. Bật tia lửa điện để phản ứng cháy xảy ra hoàn toàn, rồi đưa bình về điều kiện ban đầu, thu được hỗn hợp khí có thể tích là 20 ml gồm 50%CO2, 25%N2, 25%O2. Coi hơi nước đã bị ngưng tụ. Chất X là', 'SINGLE_CHOICE', '{"A": "anilin", "B": "propylamin", "C": "etylamin", "D": "metylamin"}', 'A', 'Đáp án DBan đầu đặt thể tích H2 là x thì thể tích amin là 35-x mlSau phản ứng có 10 mol CO2&nbsp;và 5 ml N2, 5 ml O2&nbsp;40 ml O2&nbsp;+ (X, H2) → H2O, CO2: 10 ml, N2: 5 ml và còn dư 5 ml O2Từ sơ đồ thấy có 35ml O2&nbsp;tham gia vào phản ứngVì amin này đơn chức nên Vamin = 2VN2&nbsp;= 10ml nên số C trong X là 10 :10 =1', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(342, 'Cho 11,8 gam amin đơn chức X tác dụng vừa đủ với dung dịch HCl, sau khi phản ứng xảy ra hoàn toàn thu được dung dịch Y. Làm bay hơi dung dịch Y được 19,1 gam muối khan. Số công thức cấu tạo ứng với công thức phân tử của X là', 'SINGLE_CHOICE', '{"A": "3", "B": "4", "C": "5", "D": "2"}', 'A', 'Đáp án BTQ : R-N + HCl → RNH3ClBảo toàn khối lượng: nHCl = nX = 59g→ X là C3H9NCác công thức cấu tạo thỏa mãn là :C – C – C – NH2C – C(NH2) – CC – C – NH – C(CH3)3N', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(343, 'Cho 40 gam hỗn hợp gồm hai amin no, đơn chức, mạch hở tác dụng vừa đủ với V ml dung dịch HCl 1M, thu được dung dịch chứa 63,36 gam hỗn hợp muối. Giá trị của V là', 'SINGLE_CHOICE', '{"A": "320.", "B": "400.", "C": "560.", "D": "640."}', 'A', 'Đáp án DTQ : R – NH2&nbsp;+ HCl → R – NH3ClBảo toàn khối lượng : mamin + mHCl = mMuối→ nHCl = 0,64 mol→ V = 640 ml', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(344, 'Amino axit X nào trong 4 chất dưới đây biết trong phân tử có một nhóm –NH2&nbsp;và một nhóm –COOH. Cho 26,7 gam X phản ứng với lượng dư dung dịch HCl, thu được dd chứa 37,65 gam muối.&nbsp;', 'SINGLE_CHOICE', '{"A": "H2N–[CH3]3–COOH.", "B": "H2N–[CH2]2–COOH.", "C": "H2N–[CH2]4–COOH.", "D": "H2N–CH2–COOH."}', 'A', 'Đặt CT của X là H2NRCOOH26,7(g) X + ?HCl → 37,65(g) Muối.Bảo toàn khối lượng: mHCl&nbsp;= 10,95(g) ⇒ nX&nbsp;= nHCl&nbsp;= 0,3 mol.→ MX&nbsp;= 26,7 : 0,3 = 89 ⇒ R = 28 (C2H4)→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(345, 'X gồm ba amino axit, trong đó tỉ lệ mN : mO = 7:16. Để tác dụng với 10,36 gam X cần đủ 120 ml HCl 1M. Mặt khác cho 10,36 gam hỗn hợp X vào 150 ml dung dịch NaOH 1M rồi cô cạn thu được mấy gam rắn.&nbsp;', 'SINGLE_CHOICE', '{"A": "13,36", "B": "14,20", "C": "13,00", "D": "12,46"}', 'A', 'Ta có: nN:nO&nbsp;= 1:2 nên nNH2&nbsp;: nCOOH&nbsp;= 1:1.Suy ra khi tác dụng với 0,15 mol NaOH thì dư ra 0,03mol NaOH.Áp dụng sự tăng giảm khối lượng, ta có:mrắn&nbsp;= mmuối&nbsp;+ mNaOH dư&nbsp;= (mX&nbsp;+ 22.nNaOH pư) + 0,03.40 = 10,36 + 22.0,12 + 0,03.40 = 14,2 gam.→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(346, 'Một α-amino axit nào dưới đây (trong phân tử chỉ chứa 1 nhóm amino và 1 nhóm cacboxyl) biết cho 13,35 gam X tác dụng với HCl dư thu được 18,825 gam muối.&nbsp;', 'SINGLE_CHOICE', '{"A": "valin", "B": "axit glutamic", "C": "alanin", "D": "glyxin"}', 'A', 'Áp dụng sự tăng, giảm khối lượng, ta có&nbsp;nX = (18,825 - 13,35) : 36,5 = 0,15 molSuy ra MX&nbsp;= 89 (alanin)→ Đáp án&nbsp;C', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(347, 'Cho 0,04 mol X là (H2N)2C3H5COOH tác dụng với 400ml dung dịch hỗn hợp H2SO4 0,1M và HCl 0,3M thu được dung dịch Y. Cho Y phản ứng vừa đủ với V ml dung dịch gồm NaOH 0,2M và KOH 0,4M, thu được dung dịch chứa bao nhiêu gam muối.&nbsp;', 'SINGLE_CHOICE', '{"A": "7,12", "B": "20,86", "C": "23,38", "D": "16,18"}', 'A', 'Ta có: ∑nOH-&nbsp;= nX&nbsp;+ nH+&nbsp;= 0,04 + 0,04.2 + 0,12 = 0,24 = 3x ⇒ x = 0,08 molTa có H2O được sinh ra từ: OH-&nbsp;+ H+&nbsp;→ H2O và cho X tác dụng với bazơ.⇒ nH2O&nbsp;= nH+&nbsp;= 0,04.2 + 0,12 + 0,04 = 0,24 molBảo toàn khối lượng:mmuối&nbsp;= 0,04.118 + 0,04.98 + 0,12.36,5 + 0,08.40 + 0,16.56 – 0,24.18 = 20,86 gam→ Đáp án&nbsp;B', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(348, 'Xác định tên axit thu được sau phản ứng biết&nbsp;xà phòng hóa trieste X bằng NaOH thu được 9,2g glixerol và 83,4g muối của một axit no.&nbsp;', 'SINGLE_CHOICE', '{"A": "Stearic", "B": "Oleic", "C": "Panmitic", "D": "Linoleic"}', 'C', 'nglixerol&nbsp;= 0,1mol(RCOO)3C3H5&nbsp;+ 3NaOH&nbsp;→ 3RCOONa + C3H5(OH)3&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;0,3&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;0,1mmuối&nbsp;= 83,4 : 3&nbsp;= 27,8g⇒ Mmuối&nbsp;= 27,8: 0,1 = 278 ⇒ Maxit&nbsp;= 278 -22 = 256 (panmitic)⇒ Chọn C.', 12);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(349, 'Tìm X và a biết đun sôi ag một triglixrit X với KOH thu được 0,92g glixerol và mg hỗn hợp Y gồm muối của a xit oleic với 3,18g muối của axit linoleic.&nbsp;', 'SINGLE_CHOICE', '{"A": "(C17H33COO)2C3H5OOCC17H31; 8,41g", "B": "(C17H31COO)2 C3H5OOCC17H33; 8,41g", "C": "(C17H31COO)2 C3H5OOCC17H33; 4,81g", "D": "(C17H33COO)2C3H5OOCC17H31; 4,81g"}', 'A', 'nglixerol&nbsp;= 0,01molNếu triglixrit là (C17H31COO)2&nbsp;C3H5OOCC17H33(C17H31COO)2C3H5OOCC17H33&nbsp;+ 3KOH → 2C17H31COOK + C17H33COOK + C3H5(OH)3Khối lượng muối linoleat: 0,02. 318 = 6,36g &gt; 3,18 : loạiVậy công thức của X là:(C17H33COO)2C3H5OOCC17H31&nbsp;+ 3 KOH → 2C17H33COOK + C17H31COOK + C3H5(OH)3Và a = 0,01.841 = 8,41g.', 12);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(13, 'Thi thử trắc nghiệm ôn tập Chủ nghĩa xã hội khoa học online - Đề #8', 'Hóa Học', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Hóa Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(350, 'Câu “Những tư tưởng thống trị của một thời đại bao giờ cũng chỉ là tư tưởng của giai cấp thống&nbsp;trị”của ai?', 'SINGLE_CHOICE', '{"A": "C.Mác", "B": "Ph.Ăng ghen", "C": "C.Mác & Ph.Ăng ghen", "D": "V.I Lênin."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(351, 'Điền từ vào ô trống: “Lực lượng sản xuất hàng đầu của nhân loại là…, là người lao động”&nbsp;(V.I.Lênin).', 'SINGLE_CHOICE', '{"A": "Khoa học kỹ thuật", "B": "Nền đại công nghiệp", "C": "Công nhân", "D": "Trí thức"}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(352, '“Muốn xây dựng CNXH, trước hết cần có những con người XHCN” được Bác nói ở đâu?', 'SINGLE_CHOICE', '{"A": "Đại hội Đại biểu toàn quốc lần thứ 2 của Đảng 1951.", "B": "Đại hội Đại biểu toàn quốc lần thứ 3 của Đảng 1960.", "C": "Hội nghị bồi dưỡng lãnh đạo các cấp toàn miền Bắc tháng 3.1961.", "D": "Bác nói chuyện tại Đại hội công đoàn toàn quốc lần thứ II ngày 9.3.1961."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(353, 'Tìm phuơng án đúng cho câu “Hiền tài là nguyên khí của quốc gia, nguyên khí thịnh thì thế nước mạnh,&nbsp;nguyên khí suy thì thế nước hèn và càng xuống thấp”.&nbsp;', 'SINGLE_CHOICE', '{"A": "Nguyễn Trãi", "B": "Nguyễn Huệ", "C": "Lời ghi trên bia ở Văn miếu Quốc Tử Giám", "D": "Hồ Chí Minh"}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(354, 'Bộ “ Tư bản” – tác phẩm chủ yếu và cơ bản ấy trình bày chủ nghĩa xã hội khoa học… xác định trên của Lê nin với ý nghĩa:', 'SINGLE_CHOICE', '{"A": "CNXHKH là một trong ba bộ phận của chủ nghĩa Mác.", "B": "CNXHKH là chủ nghĩa Mác.", "C": "CNXHKH là một trong những đỉnh cao nhất của khoa học xã hội", "D": "CNXHKH là hệ tư tưởng chính trị của giai cấp công nhân."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(355, 'Nguyên lý cơ bản nghiên cứu CNXHKH là:', 'SINGLE_CHOICE', '{"A": "Mối liên hệ phổ biến và sự phát triển của lịch sử xã hội.", "B": "Mối liên hệ LLSX và QHSX.", "C": "Mâu thuẫn LLSX và QHSX.", "D": "Hình thai kinh tế - xã hội."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(356, '“Sự khái quát lý luận về những điều kiện giải phóng của giai cấp vô sản”, thuộc về:', 'SINGLE_CHOICE', '{"A": "Khái niệm Chủ nghĩa xã hội khoa học.", "B": "Vị trí của Chủ nghĩa xã hội khoa học.", "C": "Phương pháp nghiên cứu Chủ nghĩa xã hội khoa học.", "D": "Đối tượng nghiên cứu của Chủ nghĩa xã hội khoa học."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(357, '“Vận dụng sáng tạo lý luận của chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh để nghiên cứu phát triển chủ nghĩa xã hội khoa học”, thuộc phương pháp nghiên cứu:', 'SINGLE_CHOICE', '{"A": "Kết hợp lịch sử – lôgíc.", "B": "Khảo sát và phân tích.", "C": "Tổng kết lý luận từ thực tiễn.", "D": "Liên ngành."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(358, 'Nghiên cứu, học tập Chủ nghĩa xã hội khoa học không chỉ để nhận thức và giải thích thế giới, mà điều quan trọng là góp phần cải tạo thế giới. Nội dung nói về:', 'SINGLE_CHOICE', '{"A": "Ý nghĩa của việc nghiên cứu Chủ nghĩa xã hội khoa học.", "B": "Chức năng của Chủ nghĩa xã hội khoa học.", "C": "Vị trí của Chủ nghĩa xã hội khoa học.", "D": "Phương pháp nghiên cứu của Chủ nghĩa xã hội khoa học."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(359, 'Chủ nghĩa xã hội khoa học thuộc sự phân loại tư tưởng xã hội chủ nghĩa theo:', 'SINGLE_CHOICE', '{"A": "Lịch đại.", "B": "Trình độ phát triển.", "C": "Sự kết hợp giữa lịch đại và trình độ phát triển.", "D": "Quan điềm của chủ nghĩa Mác – Lênin."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(360, 'Những ước mơ, khát vọng của người lao động bị áp bức, bóc lột về một xã hội mới tốt đẹp. Thuộc tư tưởng XHCN thời:', 'SINGLE_CHOICE', '{"A": "Nguyên thủy.", "B": "Cổ đại.", "C": "Cận đại tư bản.", "D": "Hiện đại."}', 'A', '', 13);
