(375, 'Phương thức lao động và phương thức sản xuất khác nhau ở chỗ:', 'SINGLE_CHOICE', '{"A": "Lao động cụ thể.", "B": "Lao động trừu tượng.", "C": "Kết quả của quá trình lao động sản xuất.", "D": "Lao động chân tay"}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(376, 'Tập đoàn xã hội, nghĩa là “một tổ chức lao động xã hội nhất định” do quá trình nào tạo ra:', 'SINGLE_CHOICE', '{"A": "Sự phân công lao động trong công trường thủ công.", "B": "Hợp tác giản đơn.", "C": "Nền công nghiệp hiện đại.", "D": "Sự phân chia lao động thành các lĩnh vực."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(377, 'Giai cấp vô sản phát triển trong xã hội tư bản do:', 'SINGLE_CHOICE', '{"A": "Quá trình tích lũy nguyên thủy.", "B": "Bị bóc lột giá trị thặng dư.", "C": "Sự phát triển của đại công nghiệp.", "D": "Sự thống trị của nhà tư bản."}', 'A', '', 13);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(378, 'Công nhân công xưởng bao gồm:', 'SINGLE_CHOICE', '{"A": "Giám đốc công xưởng, những kỹ sư.", "B": "Thợ máy, thợ chính, thợ phụ.", "C": "Người đi chào hàng, kẻ môi giới bán hàng…", "D": "Tất cả mọi người nói trên."}', 'A', '', 13);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(14, 'Đề thi thử giữa học kỳ 1 môn Hoá Học lớp 11 online - Mã đề 04', 'Hóa Học', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Hóa Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(379, 'Dung dịch HNO3&nbsp;đặc để lâu thường có màu vàng do', 'SINGLE_CHOICE', '{"A": "HNO3 tan nhiều trong nước.", "B": "HNO3 bị khử bởi các chất của môi trường", "C": "dung dịch HNO3 có tính oxi hóa mạnh.", "D": "dung dịch HNO3 có hoà tan một lượng nhỏ NO2."}', 'A', 'Axit nitric kém bền. Ngay điều kiện thường, khi có ánh sáng dung dịch HNO3&nbsp;bị phân hủy một phần giải phóng NO2. Khí này tan trong dung dịch axit, làm cho dung dịch có màu vàng.Đáp án D', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(380, 'Trong phân tử H3PO4&nbsp;photpho có số oxi hóa là', 'SINGLE_CHOICE', '{"A": "+5.", "B": "+3.", "C": "-5.", "D": "-3."}', 'A', 'Gọi số oxi hóa của P là x có: 3.(+1) + x + 4.(-2) = 0 → x = + 5.Đáp án A', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(381, 'Thuốc thử để phân biệt hai dung dịch Na3PO4&nbsp;và NaNO3&nbsp;là', 'SINGLE_CHOICE', '{"A": "AgNO3.", "B": "NaOH.", "C": "KOH.", "D": "HCl."}', 'A', 'AgNO3&nbsp;+ NaNO3&nbsp;→ không phản ứngNa3PO4&nbsp;+ 3AgNO3&nbsp;→ 3NaNO3&nbsp;+ Ag3PO4 (↓ vàng)Đáp án A', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(382, 'Ở nhiệt độ thường, nitơ khá trơ về mặt hóa học do', 'SINGLE_CHOICE', '{"A": "nitơ có bán kính nguyên tử nhỏ.", "B": "nitơ có độ âm điện lớn nhất trongnhóm.", "C": "phân tử nitơ có liên kết ba rất bền.", "D": "phân tử nitơ không phân cực."}', 'A', 'Ở nhiệt độ thường, nitơ khá trơ về mặt hóa học do trong phân tử có liên kết ba rất bền.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(383, 'Ở 3000°C (hoặc có tia lửa điện) N2&nbsp;hoá hợp với O2&nbsp;theo phương trình phản ứng nào sau đây', 'SINGLE_CHOICE', '{"A": "N2 + O2 ⇌ 2NO.", "B": "N2 + 2O2 ⇌ 2NO2.", "C": "4N2 + O2 ⇌ 2N2O.", "D": "4N2 + 3O2 ⇌ 2N2O."}', 'A', 'Đáp án A', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(384, 'Magie photphua có công thức là', 'SINGLE_CHOICE', '{"A": "Mg2P2O7.", "B": "Mg3P2.", "C": "Mg2P3.", "D": "Mg3(PO4)3."}', 'A', 'Magie photphua: Mg3P2.Đáp án B', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(385, 'Từ 34 tấn NH3&nbsp;sản xuất được 160 tấn dung dịch HNO3&nbsp;63%. Hiệu suất', 'SINGLE_CHOICE', '{"A": "80%", "B": "50%", "C": "60%", "D": "85%."}', 'A', '$27', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(386, 'Xác định chất (A) và (B) trong chuỗi sau&nbsp;', 'SINGLE_CHOICE', '{"A": "(A) là NO, (B) là N2O5.", "B": "(A) là N2, (B) là N2O5.", "C": "(A) là NO, (B) là NO2.", "D": "(A) là N2, (B) là NO2."}', 'A', '(A) là NO, (B) là NO2.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(387, 'Trong thí nghiệm đồng tác dụng với dung dịch HNO3&nbsp;đặc để tránh khí độc NO2&nbsp;bay ra người ta thường nút ống nghiệm bằng bông có tẩm dung dịch nào sau đây?', 'SINGLE_CHOICE', '{"A": "dd NaCl .", "B": "dd NaOH.", "C": "dd HCl.", "D": "dd NaNO3."}', 'A', '2NO2&nbsp;+ 2NaOH → NaNO3&nbsp;+ NaNO2&nbsp;+ H2O.Đáp án B', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(388, 'Các số oxi hoá có thể có của photpho là', 'SINGLE_CHOICE', '{"A": "–3, +3, +5.", "B": "–3, +3, +5, 0.", "C": "+3, +5, 0.", "D": "–3, 0, +1, +3, +5."}', 'A', 'Các số oxi hóa có thể có của photpho là -3, 0, +3, +5.Đáp án B', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(389, 'Cho các phản ứng: N2&nbsp;+ O2&nbsp;⇌ 2NO và N2&nbsp;+ 3H2&nbsp;⇌ 2NH3. Trong hai phản ứng trên thì nitơ', 'SINGLE_CHOICE', '{"A": "chỉ thể hiện tính oxi hóa.", "B": "chỉ thể hiện tính khử.", "C": "thể hiện cả tính khử và tính oxi hóa.", "D": "không thể hiện tính khử và tính oxi hóa."}', 'A', 'N2&nbsp;+ O2&nbsp;⇌ 2NOSố oxi hóa của N tăng từ 0 lên +2, vậy N2&nbsp;thể hiện tính khử.N2&nbsp;+ 3H2&nbsp;⇌ 2NH3Số oxi hóa của N giảm từ 0 xuống -3, vậy N2&nbsp;thể hiện tính oxi hóa.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(390, 'Khi cho kim loại Cu phản ứng với HNO3&nbsp;tạo thành khí độc hại. Biện pháp nào xử lý tốt nhất để chống ô nhiễm môi trường?', 'SINGLE_CHOICE', '{"A": "Nút ống nghiệm bằng bông tẩm nước.", "B": "Nút ống nghiệm bằng bông tẩm cồn.", "C": "Nút ống nghiệm bằng bông tẩm giấm.", "D": "Nút ống nghiệm bằng bông tẩm nước vôi."}', 'A', '4NO2&nbsp;+ 2Ca(OH)2&nbsp;→ Ca(NO2)2&nbsp;+ Ca(NO3)2&nbsp;+ 2H2OĐáp án D', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(391, 'Có thể dùng bình đựng HNO3&nbsp;đặc, nguội bằng kim loại nào?', 'SINGLE_CHOICE', '{"A": "Đồng, bạc.", "B": "Đồng, chì.", "C": "Sắt, nhôm.", "D": "Đồng, kẽm."}', 'A', 'Sắt, nhôm bị thụ động hóa trong HNO3&nbsp;đặc, nguội nên có thể dùng bình bằng những kim loại này để chứa HNO3&nbsp;đặc, nguội.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(392, 'Cho các dung dịch: (NH4)2SO4; NH4Cl; Al(NO3)3; Fe(NO3)3; Cu(NO3)2&nbsp;.Để phân biệt các dung dịch trên chỉ dùng 1 hóa chất nào sau?', 'SINGLE_CHOICE', '{"A": "Dung dịch NH3.", "B": "Dung dịch Ba(OH)2.", "C": "Dung dịch KOH.", "D": "Dung dịch NaCl."}', 'A', '$28', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(393, 'Chọn cấu hình electron lớp ngoài cùng của nguyên tố nhóm VA?', 'SINGLE_CHOICE', '{"A": "ns2np5.", "B": "ns2np3.", "C": "ns2np2.", "D": "ns2np4."}', 'A', 'Nhóm VA có 5 electron lớp ngoài cùng. Cấu hình electron lớp ngoài cùng có dạng: ns2np3.Đáp án B', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(394, 'Trong phản ứng nào sau đây, nitơ thể hiện tính khử?', 'SINGLE_CHOICE', '{"A": "N2 + 3H2 ⇌ 2NH3", "B": "N2 + 6Li → 2Li3N", "C": "N2 + O2 ⇌ 2NO", "D": "N2 + 3Mg → Mg3N2"}', 'A', 'N2&nbsp;+ O2&nbsp;⇌ 2NOSố oxi hóa của N tăng từ 0 lên +2. Vậy N2&nbsp;thể hiện tính khử.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(395, 'Cho sơ đồ sauTrong sơ đồ A ,B lần lượt là các chất', 'SINGLE_CHOICE', '{"A": "HCl , HNO3", "B": "CaCl2 , HNO3", "C": "BaCl2 , AgNO3", "D": "HCl , NaNO3."}', 'A', '(NH4)2SO4&nbsp;+ BaCl2&nbsp;→ BaSO4&nbsp;↓ + 2NH4ClNH4Cl + AgNO3&nbsp;→ AgCl ↓ + NH4NO3.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(396, 'Hiện tượng xảy ra khi cho giấy quỳ khô vào bình đựng khí amoniac là', 'SINGLE_CHOICE', '{"A": "Giấy quỳ chuyển sang màu đỏ.", "B": "Giấy quỳ chuyển sang màu xanh.", "C": "Giấy quỳ mất màu.", "D": "Giấy quỳ không chuyển màu."}', 'A', 'Khí NH3&nbsp;không làm đổi màu giấy quỳ khô.Đáp án D', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(397, 'Nồng độ ion NO3-&nbsp;trong nước uống tối đa cho phép là 9 ppm. Nếu thừa ion NO3-&nbsp;sẽ gây một loại bệnh thiếu máu hoặc tạo thành nitrosamin, một hợp chất gây ung thư đường tiêu hóa. Để nhận biết ion NO3-, người ta dùng', 'SINGLE_CHOICE', '{"A": "CuSO4 và NaOH.", "B": "Cu và NaOH.", "C": "Cu và H2SO4.", "D": "CuSO4 và H2SO4."}', 'A', 'Để nhận ra NO3-&nbsp;dùng Cu và H2SO4. Hiện tượng: Cu tan dần, dung dịch sau phản ứng có màu xanh, thoát ra khí không màu hóa nâu trong không khí.3Cu + 8H+&nbsp;+ 2NO3-&nbsp;→ 3Cu2+&nbsp;+ 2NO + 4H2OĐáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(398, 'Dãy gồm tất cả các chất khi tác dụng với HNO3&nbsp;thì HNO3&nbsp;chỉ thể hiện tính axit là', 'SINGLE_CHOICE', '{"A": "CaCO3, Cu(OH)2, Fe(OH)2, FeO.", "B": "CuO, NaOH, FeCO3, Fe2O3.", "C": "Fe(OH)3, Na2CO3, Fe2O3, NH3.", "D": "KOH, FeS, K2CO3, Cu(OH)2."}', 'A', 'Fe(OH)3&nbsp;+ 3HNO3&nbsp;→ Fe(NO3)3&nbsp;+ 3H2ONa2CO3&nbsp;+ 2HNO3&nbsp;→ 2NaNO3&nbsp;+ CO2&nbsp;+ H2OFe2O3&nbsp;+ 6HNO3&nbsp;→ 2Fe(NO3)3&nbsp;+ 3H2ONH3&nbsp;+ HNO3&nbsp;→ NH4NO3.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(399, 'Thuốc thử dùng để phân biệt ba dung dịch muối NaNO3, Na3PO4, NaCl là', 'SINGLE_CHOICE', '{"A": "AgNO3.", "B": "BaCl2.", "C": "NaOH.", "D": "H2SO4."}', 'A', 'Sử dụng AgNO3&nbsp;làm thuốc thử.+ Không có hiện tượng → NaNO3.+ Có kết tủa trắng → NaCl NaCl + AgNO3&nbsp;→ AgCl&nbsp;(↓ trắng)&nbsp;+ NaNO3+ Có kết tủa vàng → Na3PO4. Na3PO4&nbsp;+ 3AgNO3&nbsp;→ 3NaNO3&nbsp;+ Ag3PO4 (↓ vàng)Đáp án A', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(400, 'Hòa tan 32 g hỗn hợp Cu và CuO trong dung dịch HNO3&nbsp;1M (dư), thoát ra 6,72 lít khí NO (đktc). Khối lượng CuO trong hỗn hợp ban đầu là', 'SINGLE_CHOICE', '{"A": "1,2g.", "B": "1,88g.", "C": "2,52g.", "D": "3,2g."}', 'A', 'Bảo toàn electron có:2.nCu&nbsp;= 3.nNO&nbsp;→ nCu&nbsp;= 0,45 molmCuO&nbsp;= 32 – 0,45.64 = 3,2 gamĐáp án D', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(401, 'Chọn phát biểu đúng?', 'SINGLE_CHOICE', '{"A": "Photpho trắng tan trong nước không độc.", "B": "Photpho trắng được bảo quản bằng cách ngâm trong nước.", "C": "Photpho trắng hoạt động hoá học kém hơn photpho đỏ.", "D": "Photpho đỏ phát quang màu lục nhạt trong bóng tối."}', 'A', 'A sai vì photpho trắng độc.C sai vì photpho trắng hoạt động&nbsp;mạnh&nbsp;hơn photpho đỏ.D sai vì Photpho&nbsp;trắng&nbsp;phát quang màu lục nhạt trong bóng tối.Đáp án B', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(402, 'Cho m(g) Al tan hoàn toàn trong dung dịch HNO3&nbsp;thấy tạo ra 11,2 lít (đktc) hỗn hợp 3 khí NO, N2O, N2&nbsp;với tỷ lệ mol tương ứng là 1: 2 : 2. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "16.47g.", "B": "23g.", "C": "35.1g.", "D": "12.73g."}', 'A', 'Gọi số mol của NO là a mol → số mol của N2O là 2a mol; số mol N2&nbsp;là 2a mol.nkhí&nbsp;= 0,5 mol → a + 2a + 2a = 0,5 mol → a = 0,1 mol.Bảo toàn electron có:3.nAl&nbsp;= 3.nNO&nbsp;+ 8.nN2O&nbsp;+ 10.nN2&nbsp;→ nAl&nbsp;= 1,3 (mol)Vậy m = 1,3.27 = 35,1 gam.Đáp án C', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(403, 'Hòa tan hết m(g) Al trong dung dịch HNO3, thu được hỗn hợp khí (đktc) gồm NO và NO2&nbsp;có thể tích là 8,96 lít và có tỷ khối đối với hiđro là 16,75. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "9,252.", "B": "2,7g.", "C": "8,1g.", "D": "9,225g."}', 'A', 'Gọi số mol của NO và NO2&nbsp;lần lượt là x và y (mol)Theo bài ra ta có: x + y = 0,4 (mol) (1)mkhí&nbsp;= 0,4.16,75.2 = 13,4 gam → 30x + 46y = 13,4 (gam) (2)Từ (1) và (2) có: x = 0,3125 mol và y = 0,0875 mol.Bảo toàn electron có:3.nAl&nbsp;= 3.nNO&nbsp;+ nNO2&nbsp;→ nAl&nbsp;= 41/120&nbsp;(mol)mAl&nbsp;= 27. nAl&nbsp;= 9,225 gam.Đáp án D', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(404, 'Nitơ đóng vai trò là chất oxi hóa trong phản ứng với', 'SINGLE_CHOICE', '{"A": "oxi và các chất oxi hóa khác.", "B": "hiđro và oxi.", "C": "kim loại và oxi.", "D": "kim loại và hiđro."}', 'A', 'N2&nbsp;đóng vai trò là chất oxi hóa khi tác dụng với kim loại và hiđro.Đáp án D', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(405, 'Cho 9,6 gam Cu tác dụng hết với dd HNO3&nbsp;loãng. Thể tích khí NO là sản phẩm khử duy nhất ở đktc thu được là', 'SINGLE_CHOICE', '{"A": "3,36 lít.", "B": "2,24 lít.", "C": "4,48 lít.", "D": "6,72 lít."}', 'A', 'Bảo toàn electron: 2.nCu&nbsp;= 3.nNO&nbsp;→ nNO&nbsp;= 0,1 mol→ Vkhí&nbsp;= 0,1.22,4 = 2,24 lít.Đáp án B', 14);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(406, 'Hòa tan hoàn toàn 15,9g hỗn hợp 3 kim loại Al, Mg, Cu bằng dd HNO3&nbsp;thu được 6,72 lit khí NO (là sản phẩm khử duy nhất ở đktc) và dd X. Đem cô cạn dd X thì thu được khối lượng muối khan là', 'SINGLE_CHOICE', '{"A": "77,1g.", "B": "71,7g.", "C": "17,7g.", "D": "53,1g."}', 'A', 'nNO3-&nbsp;(muối)&nbsp;= ne nhường&nbsp;= ne nhận&nbsp;= 3.nNO&nbsp;= 0,9 molmmuối&nbsp;= mKL&nbsp;+ mNO3&nbsp;= 15,9 + 0,9.62 = 71,7 gam.Đáp án B', 14);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(15, 'Thi thử trắc nghiệm online môn Hoá Học - Đề thi tốt nghiệp THPT quốc gia 2022 - Mã đề 201', 'Toán', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Toán. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(407, 'Chất nào sau đây tan hết trong dung dịch NaOH loãng, dư?', 'SINGLE_CHOICE', '{"A": "Al2O3.", "B": "MgO.", "C": "FeO.", "D": "Fe2O3."}', 'A', '', 15);
