(433, 'Phát biểu nào sau đây sai?', 'SINGLE_CHOICE', '{"A": "Trùng ngưng buta-1,3-đien thu được polime dùng để sản xuất chất dẻo.", "B": "Trùng hợp etilen thu được polime dùng để sản xuất chất dẻo.", "C": "Trùng ngưng axit ε-aminocaproic thu được policaproamit.", "D": "Trùng hợp vinyl xianua thu được polime dùng để sản xuất tơ nitron $($tơ olon$)$."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(434, 'Cho bột kim loại Cu dư vào dung dịch gồm $Fe(NO_3)_3$ và $AgNO_3$, sau khi các phản ứng xảy ra hoàn toàn thu được dung dịch chứa các muối nào sau đây?', 'SINGLE_CHOICE', '{"A": "$AgNO_3, Fe(NO_3)_3$", "B": "$Cu(NO_3)_2, Fe(NO_3)_2$", "C": "$Cu(NO_3)_2, AgNO_3$", "D": "$Cu(NO_3)_2, Fe(NO_3)_3$"}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(435, 'Cho 0,78 gam hỗn hợp gồm Mg và Al tan hoàn toàn trong dung dịch HCl thu được 0,896 lít khí H2 và dung dịch chứa m gam muối. Giá trị của m là', 'SINGLE_CHOICE', '{"A": "3,62.", "B": "2,24.", "C": "3,27.", "D": "2,20."}', 'A', '', 15);
