(436, 'Phát biểu nào sau đây sai?', 'SINGLE_CHOICE', '{"A": "Etyl axetat có công thức phân tử là C4H8O2.", "B": "Phân tử metyl metacrylat có một liên kết π trong phân tử.", "C": "Metyl acrylat có khả năng tham gia phản ứng cộng Br2 trong dung dịch.", "D": "Etyl fomat có khả năng tham gia phản ứng tráng bạc."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(437, 'Hỗn hợp E gồm Fe, Fe3O4, Fe2O3 và Fe(NO3)2. Nung 23,84 gam E trong môi trường trơ thu được chất rắn X $($chỉ gồm Fe và các oxit$)$ và 0,12 mol khí NO2. Hòa tan hết X trong dung dịch HCl nồng độ 3,65% thu được 672 ml khí H2 và dung dịch Y chỉ chứa muối. Cho tiếp dung dịch AgNO3 dư vào Y thu được 102,3 gam kết tủa gồm Ag và AgCl. Biết các phản ứng xảy ra hoàn toàn. Nồng độ phần trăm của muối FeCl2 trong Y gần nhất với giá trị nào sau đây?', 'SINGLE_CHOICE', '{"A": "3,08%.", "B": "3,58%.", "C": "3,12%.", "D": "2,84%."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(438, 'Cho các phát biểu sau:$(a)$ Giấm ăn có thể khử được mùi tanh của cá do các amin gây ra.$(b)$ Glucozơ bị oxi hóa bởi dung dịch $AgNO_3$ trong $NH_3$ đun nóng.$(c)$ Đun nóng tristearin với dung dịch NaOH sẽ xảy ra phản ứng thủy phân.$(d)$ Nhỏ vài giọt nước brom vào dung dịch phenol $(C_6H_5OH)$ xuất hiện kết tủa trắng.$(đ)$ Đồng trùng hợp buta-1,3-đien với acrilonitrin $($xúc tác Na$)$ thu được cao su buna-N.Số phát biểu đúng là', 'SINGLE_CHOICE', '{"A": "3.", "B": "5.", "C": "2.", "D": "4."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(439, 'Cho sơ đồ các phản ứng sau:$(1) Al_2O_3 + H_2SO_4 → X + H_2O$$(2) Ba(OH)_2 + X → Y + Z$$(3) Ba(OH)_2 (dư) + X → Y + T + H_2O$Các chất X, Z thỏa mãn sơ đồ trên lần lượt là:', 'SINGLE_CHOICE', '{"A": "$Al_2(SO_4)_3, Al(OH)_3$", "B": "$Al_2(SO_4)_3, BaSO_4$", "C": "$Al_2(SO_4)_3, Ba(AlO_2)_2$", "D": "$Al(OH)_3, BaSO_4$"}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(440, 'Điện phân dung dịch chứa x mol CuSO4, y mol H2SO4 và z mol NaCl $($với điện cực trơ, có màng ngăn xốp, hiệu suất điện phân là 100%$)$. Lượng khí sinh ra từ quá trình điện phân và khối lượng Al2O3 bị hòa tan tối đa trong dung dịch sau điện phân ứng với mỗi thí nghiệm được cho ở bảng dưới đây:Biết: Tại catot ion Cu2+ điện phân hết thành Cu trước khi H+ điện phân tạo thành khí H2; cường độ dòng điện bằng nhau và không đổi trong các thí nghiệm trên. Tổng giá trị $(x + y + z)$ bằng', 'SINGLE_CHOICE', '{"A": "1,8.", "B": "1,6.", "C": "2,0.", "D": "2,2."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(441, 'Cho $E (C3H6O3)$ và $F (C4H6O4)$ là hai chất hữu cơ mạch hở đều tạo từ axit cacboxylic và ancol. Từ E và F thực hiện sơ đồ các phản ứng sau: $(1) E + NaOH → X + Y (2) F + NaOH → X + Y (3) X + HCl → Z + NaCl$ Biết X, Y, Z là các chất hữu cơ, trong đó phân tử Y không có nhóm –CH3. Cho các phát biểu sau: $(a)$ Chất E là hợp chất hữu cơ đơn chức. $(b)$ Chất Y là đổng đẳng của ancol etylic. $(c)$ Chất E và F đều có khả năng tham gia phản ứng tráng bạc. $(d)$ Nhiệt độ sôi của chất Z cao hơn nhiệt độ sôi của axit axetic. $(e)$ 1 mol chất F tác dụng được tối đa với 2 mol NaOH trong dung dịch.Số phát biểu đúng là:', 'SINGLE_CHOICE', '{"A": "5.", "B": "2.", "C": "3.", "D": "4."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(442, 'Cho các phát biểu sau: $(a)$ Kim loại Fe tan hoàn toàn trong dung dịch HNO3 đặc, nguội. $(b)$ Các kim loại kiềm và kiềm thổ đều tác dụng với nước ở điều kiện thường. $(c)$ Nhúng thanh kim loại Zn vào dung dịch $Cu(NO_3)_2$ có xảy ra ăn mòn điện hóa học. $(d)$ Cho dung dịch Na2SO4 loãng vào dung dịch BaCl2 thu được kết tủa gồm hai chất. $(e)$ Cho a mol P2O5 vào dung dịch chứa 3a mol NaOH thu được dung dịch chứa hỗn hợp muối. Số phát biểu đúng là', 'SINGLE_CHOICE', '{"A": "3.", "B": "2.", "C": "5.", "D": "4."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(443, 'Cho X là axit cacboxylic đơn chức, mạch hở; Y là ancol no, đa chức, mạch hở. Đun hỗn hợp gồm 2,5 mol X, 1 mol Y với xúc tác H2SO4 đặc $($giả sử chỉ xảy ra phản ứng este hóa giữa X và Y$)$ thu được 2 mol hỗn hợp E gồm X, Y và các sản phẩm hữu cơ $($trong đó có chất Z chỉ chứa nhóm chức este$)$. Tiến hành các thí nghiệm sau: Thí nghiệm 1: Cho 0,4 mol E tác dụng với Na dư, sau phản ứng hoàn toàn thu được 0,25 mol khí H2. Thí nghiệm 2: Cho 0,4 mol E vào dung dịch brom dư thì có tối đa 1,0 mol Br2 tham gia phản ứng cộng. Thí nghiệm 3: Đốt cháy hoàn toàn 0,4 mol E cần vừa đủ 1,95 mol khí O2 thu được CO2 và H2O. Biết có 12% axit X ban đầu đã chuyển thành Z. Phần trăm khối lượng của Z trong E là', 'SINGLE_CHOICE', '{"A": "12,09%.", "B": "8,17%.", "C": "10,33%.", "D": "6,92%."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(444, 'Khi phân tích một loại chất béo $($kí hiệu là X$)$ chứa đồng thời các triglixerit và axit béo tự do $($không có tạp chất khác$)$ thấy oxi chiếm 10,88% theo khối lượng. Xà phòng hóa hoàn toàn m gam X bằng dung dịch NaOH dư đun nóng, sau phản ứng thu được dung dịch chứa 51,65 gam hỗn hợp các muối C17H35COONa, C17H33COONa, C17H31COONa và 5,06 gam glixerol. Mặt khác, m gam X phản ứng tối đa với y mol Br2 trong dung dịch. Giá trị của y là', 'SINGLE_CHOICE', '{"A": "0,165.", "B": "0,185.", "C": "0,180.", "D": "0,145."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(445, '79: Hỗn hợp E gồm các hiđrocacbon mạch hở có cùng số nguyên tử hiđro. Tỉ khối của E so với H2 là 13. Đốt cháy hoàn toàn a mol E cần vừa đủ 0,85 mol O2 thu được CO2 và H2O. Mặt khác, a mol E tác dụng tối đa với x mol Br2 trong dung dịch. Giá trị của x là', 'SINGLE_CHOICE', '{"A": "0,325.", "B": "0,250.", "C": "0,350.", "D": "0,175."}', 'A', '', 15);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(446, 'Dẫn 0,35 mol hỗn hợp gồm khí $CO_2$ và hơi nước qua cacbon nung đỏ thu được 0,62 mol hỗn hợp X gồm $CO, H_2$ và $CO_2$. Cho toàn bộ X vào dung dịch chứa 0,1 mol NaOH và a mol $Ba(OH)_2$, sau phản ứng hoàn toàn thu được kết tủa và dung dịch Y. Nhỏ từ từ từng giọt cho đến hết Y vào 100 ml dung dịch HCl 0,5M thu được 0,01 mol khí CO2. Giá trị của a là', 'SINGLE_CHOICE', '{"A": "0,05.", "B": "0,08.", "C": "0,06.", "D": "0,10."}', 'A', '', 15);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(16, 'Đề thi thử học kỳ 1 môn Sinh Học lớp 10 online - Mã đề 18', 'Sinh Học', 35, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Sinh Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(447, 'Prôtêin tham gia trong thành phần của enzim có thể có cấu trúc thứ', 'SINGLE_CHOICE', '{"A": "1,2", "B": "2,4", "C": "2,3", "D": "3,4"}', 'A', 'Prôtêin tham gia trong thành phần của enzim có thể có cấu trúc thứ&nbsp;3 và 4.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(448, 'Năng lượng tích lũy trong các liên kết hóa học của các chất hữu cơ trong tế bào được gọi là', 'SINGLE_CHOICE', '{"A": "điện năng", "B": "hóa năng", "C": "nhiệt năng", "D": "động năng"}', 'A', 'Năng lượng tích lũy trong các liên kết hóa học của các chất hữu cơ trong tế bào được gọi là&nbsp;hóa năng.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(449, 'Ở ruồi giấm, có bộ NST 2n = 8 vào kì giữa của nguyên phân trong một tế bào có', 'SINGLE_CHOICE', '{"A": "8 NST đơn", "B": "8 NST kép", "C": "16 NST đơn", "D": "16 NST kép"}', 'A', 'Ở ruồi giấm, vào kì giữa của nguyên phân trong một tế bào có 8 NST kép.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(450, 'Xét các hoạt động diễn ra trong tế bào:(1) Tổng hợp các chất cần thiết diễn ra trong tế bào(2) Vận chuyển chủ động các chất qua màng sinh chất(3) Glucôzơ khuếch tán qua màng tế bào(4) Nước thẩm thấu vào trong tế bào khi tế bào ngập trong dung dịch nhược trươngNăng lượng ATP được sử dụng vào các hoạt động nào?', 'SINGLE_CHOICE', '{"A": "2,4", "B": "1,3", "C": "2,3", "D": "1,2"}', 'A', 'Năng lượng ATP được sử dụng vào các hoạt động: 1, 2.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(451, 'Cho các chất sau(1) Saccarozơ – saccaraza(2) Prôtêin – prôtêaza(3) Tinh bột – Amilaza(4) Urê - UreazaCó bao nhiêu cặp cơ chất - enzim phù hợp theo quy luật ổ khóa — chìa khóa?', 'SINGLE_CHOICE', '{"A": "3", "B": "2", "C": "4", "D": "1"}', 'A', 'Cả 4 cặp cơ chất – enzim đều phù hợp theo quy luật ổ khóa — chìa khóa', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(452, 'Giai đoạn đầu tiên trong cơ chế tác động của enzim là', 'SINGLE_CHOICE', '{"A": "giải phóng enzim khỏi cơ chất", "B": "tạo sản phẩm cuối cùng", "C": "tạo các sản phẩm trung gian", "D": "tạo nên phức hợp enzim – cơ chất"}', 'A', 'Giai đoạn đầu tiên trong cơ chế tác động của enzim là tạo nên phức hợp enzim – cơ chất.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(453, 'Ở người (2n = 46), số NST trong một tế bào tại kì sau của nguyên phân là', 'SINGLE_CHOICE', '{"A": "92 NST đơn", "B": "23 NST kép", "C": "23 NST đơn", "D": "46 NST đơn"}', 'A', 'Số NST trong một tế bào người tại kì sau của nguyên phân là 92 NST đơn.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(454, 'Năng lượng chủ yếu được tạo ra từ quá trình hô hấp tế bào là', 'SINGLE_CHOICE', '{"A": "NADH", "B": "ATP", "C": "ADP", "D": "FADH2"}', 'A', 'Năng lượng chủ yếu được tạo ra từ quá trình hô hấp tế bào là ATP.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(455, 'Năng lượng trong tế bào tồn tại ở nhiều dạng khác nhau trong đó ...(1)... có thể coi như năng lượng vô ích, còn ...(2)... là dạng năng lượng chủ yếu của tế bào. Trong dấu ... (1), (2) lần lượt là', 'SINGLE_CHOICE', '{"A": "nhiệt năng, cơ năng", "B": "điện năng, quang năng", "C": "nhiệt năng, hóa năng", "D": "động năng, thế năng"}', 'A', 'Năng lượng trong tế bào tồn tại ở nhiều dạng khác nhau trong đó nhiệt năng có thể coi như năng lượng vô ích, còn hóa năng là dạng năng lượng chủ yếu của tế bào.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(456, 'Hợp chất hữu cơ nằm trong nhân tế bào, chứa đựng mọi thông tin di truyền quy định mọi đặc điểm của cơ thể sinh vật. Hợp chất này có tên là gì?', 'SINGLE_CHOICE', '{"A": "Lipit", "B": "Prôtêin", "C": "Axit nuclêic (ADN)", "D": "Cacbohiđrat"}', 'A', 'Hợp chất hữu cơ nằm trong nhân tế bào, chứa đựng mọi thông tin di truyền quy định mọi đặc điểm của cơ thể sinh vật là Axit nuclêic (ADN).', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(457, 'Tại sao khi hít phải những kim loại nặng thì có nguy cơ bị bệnh viêm phổi?', 'SINGLE_CHOICE', '{"A": "Kim loại nặng gây viêm mạch máu đường hô hấp", "B": "Hệ miễn dịch cơ thể bị suy yếu, cơ thể mất đề kháng gây viêm phổi.", "C": "Màng lizoxôm hư hại, enzim trong lizoxôm giải phóng tiêu hủy tế bào niêm mạc phổi", "D": "Sự hấp thụ O2 và thải CO2 của các tế bào niêm mạc phổi diễn ra chậm làm phổi bị viêm."}', 'A', 'Khi hít phải những kim loại nặng thì có nguy cơ bị bệnh viêm phổi vì hệ miễn dịch cơ thể bị suy yếu, cơ thể mất đề kháng gây viêm phổi.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(458, 'Tế bào thường sử dụng năng lượng trong hợp chất hữu cơ nào?', 'SINGLE_CHOICE', '{"A": "ATP", "B": "Glucozơ", "C": "Prôtêin", "D": "Tinh bột"}', 'A', 'Tế bào thường sử dụng năng lượng ATP', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(459, 'Nồng độ glucôzơ trong máu là 1,2g/lít và trong nước tiểu là 0,9g/lít. Theo em tế bào sẽ vận chuyển glucôzơ bằng cách nào? Vì sao?', 'SINGLE_CHOICE', '{"A": "Nhập bào, vì glucôzơ có kích thước lớn", "B": "Thụ động, vì glucôzơ trong máu cao hơn trong nước tiểu", "C": "Chủ động, vì glucôzơ là chất dinh dưỡng nuôi cơ thể", "D": "Nhập bào, vì glucôzơ có kích thước rất lớn"}', 'A', 'Tế bào sẽ vận chuyển glucôzơ chủ động, vì glucôzơ là chất dinh dưỡng nuôi cơ thể, tế bào máu sẽ lấy lại glucôzơ, nên nó phải vận chuyển ngược chiều građien nồng độ.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(460, 'Trong các cấp tổ chức của thế giới sống, cấp tổ chức sống cơ bản nhất là cấp nào', 'SINGLE_CHOICE', '{"A": "Phân tử", "B": "Bào quan", "C": "Tế bào", "D": "Cơ thể"}', 'A', 'Cấp tổ chức sống cơ bản nhất là tế bào.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(461, 'Cho các nhóm sinh vật sau:(1) Nấm nhầy.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (2) Rêu.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (3) Động vật nguyên sinh.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(4) Thực vật nguyên sinh.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (5) Nấm sợi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (6) Động vật không xương sống.&nbsp;Giới Nguyên sinh gồm:', 'SINGLE_CHOICE', '{"A": "(1), (3), (4).", "B": "(3), (4).", "C": "(2), (4), (5).", "D": "(1), (2), (3), (5)."}', 'A', 'Giới Nguyên sinh gồm:&nbsp;(1) Nấm nhầy.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) Động vật nguyên sinh.&nbsp; &nbsp; &nbsp;&nbsp;(4) Thực vật nguyên sinh.&nbsp;', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(462, 'Hình thức dinh dưỡng&nbsp;không&nbsp;có ở giới Nấm là', 'SINGLE_CHOICE', '{"A": "tự dưỡng.", "B": "dị dưỡng.", "C": "cộng sinh.", "D": "kí sinh."}', 'A', 'Hình thức dinh dưỡng&nbsp;không&nbsp;có ở giới Nấm là&nbsp;tự dưỡng. Tự dưỡng có ở thực vật và một số vi sinh vật.&nbsp;', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(463, 'Cho các đặc điểm sau:(1) Có hệ thần kinh.&nbsp;(2) Đa bào phức tạp.(3) Sống tự dưỡng.(4) Cơ thể phân hóa thành các mô và cơ quan.(5) Có hình thức sinh sản hữu tính.&nbsp; &nbsp;(6) Có khả năng di chuyển chủ động.Các đặc điểm có ở cả giới Thực vật và giới Động vật là:', 'SINGLE_CHOICE', '{"A": "(2), (5), (6)", "B": "(1), (3), (4), (6).", "C": "(2), (4), (5).", "D": "(1), (2), (3), (4), (5)."}', 'A', 'Các đặc điểm có ở cả giới Thực vật và giới Động vật là:(2) Đa bào phức tạp.(4) Cơ thể phân hóa thành các mô và cơ quan.(5) Có hình thức sinh sản hữu tính.&nbsp; &nbsp;', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(464, 'Cho các vị trí sau:(1) Màng sinh chất.&nbsp; &nbsp;(2) Ribosome.&nbsp;(3) Lục lạp.&nbsp; &nbsp; &nbsp;(4) Nhân.&nbsp;(5) Tế bào chất.&nbsp; &nbsp;(6) ti thể.Ở sinh vật nhân thực, ARN và ADN đều phân bố ở:&nbsp;', 'SINGLE_CHOICE', '{"A": "(1), (2), (5), (6)", "B": "(4).", "C": "(3), (4), (6).", "D": "(2), (3), (4), (5), (6)."}', 'A', 'Ở sinh vật nhân thực, ARN và ADN đều phân bố ở:&nbsp;(3) Lục lạp.&nbsp; &nbsp; &nbsp;(4) Nhân.&nbsp;(6) ti thể.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(465, 'Đặc điểm&nbsp;không&nbsp;có ở tế bào nhân sơ là', 'SINGLE_CHOICE', '{"A": "thành tế bào cấu tạo chủ yếu là chitin (kitin).", "B": "kích thước nhỏ nên sinh trưởng, sinh sản nhanh.", "C": "chưa có hệ thống nội màng, chưa có màng nhân.", "D": "bào quan không có màng bao bọc."}', 'A', 'Đặc điểm&nbsp;không&nbsp;có ở tế bào nhân sơ là: thành tế bào cấu tạo chủ yếu là chitin (kitin) (đây là đặc điểm giới nấm).', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(466, 'Ở tế bào nhân thực, thành phần của chất nhiễm sắc trong nhân gồm', 'SINGLE_CHOICE', '{"A": "ADN liên kết với protein loại histon và rARN.", "B": "chỉ có ADN.", "C": "ADN liên kết với protein loại histon.", "D": "ADN liên kết với rARN."}', 'A', 'Ở tế bào nhân thực, thành phần của chất nhiễm sắc trong nhân gồm&nbsp;ADN liên kết với protein loại histon.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(467, 'Cho các thành phần sau:(1) Màng trong gấp nếp.&nbsp; &nbsp; &nbsp;(2) Ribosome lớn (80S).(3) ADN kép, vòng, không liên kết với histon.&nbsp;(4) Enzyme tổng hợp ATP.(5) Màng ngoài trơn.&nbsp; &nbsp;(6) Phiến thylakoid.Cấu trúc có ở cả ti thể và lục lạp là:', 'SINGLE_CHOICE', '{"A": "(2), (3), (6).", "B": "(1), (2), (4).", "C": "(3), (4), (5).", "D": "(4), (5), (6)."}', 'A', 'Cấu trúc có ở cả ti thể và lục lạp là: (3),(4),(5)Màng trong gấp nếp chỉ có ở ti thểRibosome lớn (80S) không có ở cả ti thể và lục lạpPhiến thylakoid chỉ có ở lục lạp.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(468, 'Khi cho tế bào hồng cầu (còn sống) vào nước cất, sau 1 thời gian quan sát tế bào có hiện tượng', 'SINGLE_CHOICE', '{"A": "trương lên rồi vỡ ra.", "B": "co lại rồi vỡ ra.", "C": "trương lên rồi co lại.", "D": "co nguyên sinh."}', 'A', 'Khi cho tế bào vào hồng cầu vào nước, thì do nồng độ chất tan trong môi trường nước cất nhỏ hơn so với môi trường trong hồng cầu (môi trường nhược trương) nên nước sẽ vận chuyển từ nơi có nồng độ chất tan thấp đến nơi có nồng độ chất tan cao. Vì vậy, hồng cầu sẽ bị trương ra (phồng to), rồi vỡ ra.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(469, 'Cho các chất sau:(1) Glucose.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Galactose.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (3) Tinh bột.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (4) Mantose&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (5) CO2.&nbsp;Trình tự đúng của quá trình dị hóa (phân giải) carbohydrate là', 'SINGLE_CHOICE', '{"A": "(3) → (4) → (1) → (5).", "B": "(3) → (2) → (4) → (5).", "C": "(5) → (1) → (4) → (3).", "D": "(5) → (4) → (2) → (3)."}', 'A', 'Trình tự đúng của quá trình dị hóa (phân giải) carbohydrate là(3) Tinh bột.&nbsp; &nbsp; &nbsp;=&gt;&nbsp; &nbsp; &nbsp;(4) Mantose&nbsp; &nbsp;=&gt;&nbsp; &nbsp;(1) Glucose.&nbsp;=&gt; (5) CO2.&nbsp;', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(470, 'Trong trồng trọt, phương pháp&nbsp;không&nbsp;phù hợp để cây trồng quang hợp tốt, cho năng suất cao là', 'SINGLE_CHOICE', '{"A": "chiếu sáng liên tục, với cường độ mạnh.", "B": "phân bố cây trồng với mật độ phù hợp.", "C": "tưới nước, bón phân hợp lý.", "D": "xen canh cây ưa sáng và cây ưa bóng."}', 'A', 'Trong trồng trọt, phương pháp&nbsp;không&nbsp;phù hợp để cây trồng quang hợp tốt, cho năng suất cao là&nbsp;chiếu sáng liên tục, với cường độ mạnh.&nbsp;', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(471, 'Thành phần cấu tạo cơ bản của enzim là', 'SINGLE_CHOICE', '{"A": "lipit.", "B": "axit nucleic.", "C": "cacbohiđrat.", "D": "protein."}', 'A', 'Thành phần cấu tạo cơ bản của enzim là&nbsp;protein.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(472, 'ADN là một đại phân tử cấu tạo theo nguyên tắc đa phân, đơn phân là 4 loại', 'SINGLE_CHOICE', '{"A": "ribonucleotit (A,T,G,X).", "B": "nucleotit (A,T,G,X ).", "C": "ribonucleotit (A,U,G,X).", "D": "nucleotit (A, U, G, X)."}', 'A', 'ADN là một đại phân tử cấu tạo theo nguyên tắc đa phân, đơn phân là 4 loại&nbsp;nucleotit (A,T,G,X ).', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(473, 'ATP là một phân tử quan trọng trong trao đổi chất vì', 'SINGLE_CHOICE', '{"A": "nó có các liên kết phốtphát cao năng dễ bị phá vỡ để giải phóng năng lượng.", "B": "các liên kết phốtphát cao năng dễ hình thành nhưng không dễ phá huỷ.", "C": "nó dễ dàng thu được từ môi trường ngoài cơ thể.", "D": "nó vô cùng bền vững và mang nhiều năng lượng."}', 'A', 'ATP là một phân tử quan trọng trong trao đổi chất vì&nbsp;nó có các liên kết phốtphát cao năng dễ bị phá vỡ để giải phóng năng lượng.', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(474, 'Thành phần hoá học của thành tế bào vi khuẩn là', 'SINGLE_CHOICE', '{"A": "Photpholipit", "B": "Peptydoglican", "C": "Kitin", "D": "Xenlulôzơ"}', 'A', 'Thành phần hoá học của thành tế bào vi khuẩn là&nbsp;Peptydoglican', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(475, 'Glicoprotein là dấu chuẩn trên màng sinh chất. Nó được tổng hợp và hoàn thiện tại cấu trúc nào?', 'SINGLE_CHOICE', '{"A": "Màng sinh chất và riboxom", "B": "Lưới nội chất trơn và lưới nội chất hạt", "C": "Lưới nội chất hạt và bộ máy gôngi", "D": "Lưới nội chất trơn và bộ máy gôngi"}', 'A', 'Glicoprotein gồm 2 thành phần là polisaccarit và protein, polisaccarit được tổng hợp ở bộ máy Golgi&nbsp;; protein được tổng hợp ở lưới nội chất hạt', 16);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(476, 'Liên kết P ~ P ở trong phân tử ATP rất dễ bị phá vỡ để giải phóng năng lượng. Nguyên nhân là do?', 'SINGLE_CHOICE', '{"A": "Phân tử ATP là chất giàu năng lượng", "B": "Đây là liên kết mạnh", "C": "Các nhóm photphat đều tích điện âm nên đẩy nhau", "D": "Phân tử ATP có chứa 3 nhóm photphat"}', 'A', 'Liên kết P ~ P ở trong phân tử ATP rất dễ bị phá vỡ để giải phóng năng lượng là do các nhóm photphat đều tích điện âm nên có xu hướng đẩy nhau.', 16);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(17, 'Đề thi thử học kỳ 2 môn Sinh Học lớp 12 online - Mã đề 14', 'Sinh Học', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Sinh Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(477, 'Khi nói về các mối quan hệ giữa các sinh vật trong quần xã sinh vật, xét phát biểu sau:(1) Giun, sán sống trong ruột lợn là biểu hiện cùa mối quan hệ kí sinh - vật chủ(2) Vi khuẩn cố định đạm sống trong nốt sần cùa cây họ đậu là biểu hiện của mối quan hệ hội sinh(3) Quan hệ giữa loài ong hút mật hoa và loài hoa có thể là mối quan hệ cộng sinh(4) Động vật nguyên sinh sống trong ruột mối là biểu hiện mối quan hệ cộng sinh(5) Quan hệ giữa cây tỏi và sinh vật xung quanh là quan hệ ức chế - cảm nhiễmSố phát biểu không đúng là:', 'SINGLE_CHOICE', '{"A": "3", "B": "1", "C": "4", "D": "2"}', 'B', '1 đúng2 sai, đây là quan hệ cộng sinh3 đúng. Trong trường hợp hoa chỉ có thể thụ phấn được nhờ loài ong đó thì là quan hệ cộng sinh. Nếu ngoài ong ra, hoa có thể được thụ phấn nhờ các sinh vật khác nữa thì đó là quan hệ hợp tác.4 đúng5 đúngChọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(478, 'Theo thuyết tiến hóa hiện đại, có bao nhiêu phát biểu sau đây đúng?(I) Chọn lọc tự nhiên làm thay đổi đột ngột tẩn sổ alen và thành phần kiểu gen cùa quần thể.(II) Quá trình tiến hóa nhỏ diễn ra trên quy mô quần thể và diễn biến không ngừng dưới tác động của các nhân tố tiến hóa.(III) Các yếu tố ngẫu nhiên làm nghèo vốn gen quần thể, giảm sự đa dạng di truyền nên luôn dẫn tới tiêu diệt quần thể.(IV) Khi không có tác động của các nhân tố tiến hóa thì tần số alen và thành phần kiểu gen của quần thể sẽ không thay đổi.', 'SINGLE_CHOICE', '{"A": "4", "B": "1", "C": "3", "D": "2"}', 'D', 'I saiII đúngIII saiIV đúngChọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(479, 'Sự phân hoá tảo diễn ra ở kỉ nào?', 'SINGLE_CHOICE', '{"A": "Đêvôn", "B": "Cambri", "C": "Than đá", "D": "Xilua"}', 'B', 'Sự phân hoá tảo diễn ra ở kỉ CambriChọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(480, 'Khi nói về các yếu tố ngẫu nhiên, phát biểu nào sau đây&nbsp;sai?', 'SINGLE_CHOICE', '{"A": "Kết quả tác động của các yểu tố ngẫu nhiên thường dẫn tới làm nghèo vốn gen của quần thể, giảm sự đa dạng di truyền và có thể dẫn tới làm suy thoái quần thể.", "B": "Một quần thể đang có kích thước lớn nhưng do các yếu tố thiên tai hoặc bất kì các yếu tố nào khác làm giảm kích thước của quần thể một cách đáng kể thì những cá thể sống sót có thể có vốn gen khác biệt hẳn với vốn gen của quần thể ban đầu.", "C": "Khi không xảy ra đột biển, không có CLTN, không có di - nhập gen, nểu thành phẩn kiêu gen và tần số alen của quần thể có biến đổi thì đó là do tác động của các yếu tổ ngẫu nhiên.", "D": "Với quần thể có kích thước càng lớn thì các yếu tố ngẫu nhiên càng dễ làm thay đổi tần số alen của quần thể và ngược lại."}', 'D', 'D sai, các yếu tố ngẫu nhiên dễ làm thay đổi tần số alen của quần thể có kích thước nhỏChọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(481, 'Các đặc trưng cơ bản của quần xã là gì?', 'SINGLE_CHOICE', '{"A": "thành phần loài, tỉ lệ nhóm tuổi, mật độ.", "B": "thành phần loài, sự phân bố các cá thể trong quần xã.", "C": "thành phần loài, sức sinh sản và sự tử vong.", "D": "độ phong phú, sự phân bố các cá thể trong quần xã."}', 'B', 'Các đặc trưng cơ bản của quần xã là: thành phần loài, sự phân bố các cá thể trong quần xãChọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(482, 'Nếu kích thước quần thể giảm xuống dưới mức tối thiểu thì có kết quả thế nào?', 'SINGLE_CHOICE', '{"A": "số lượng cá thể trong quần thể ít, cơ hội gặp nhau của các cá thể đực và cái tăng lên dần tới làm tăng tỉ lệ sinh sản, làm số lượng cá thể của quần thể tăng lên nhanh chóng.", "B": "sự cạnh tranh về nơi ở của cá thể giảm nên số lượng cá thể của quần thể tăng lên nhanh chóng.", "C": "mật độ cá thể của quần thể tăng lên nhanh chóng, làm cho sự cạnh tranh cùng loài diễn ra khốc liệt hơn.", "D": "sự hỗ trợ của cá thể trong quần thể và khả năng chống chọi với những thay đổi của môi trường của quần thể giảm."}', 'D', 'Nếu kích thước quần thể giảm xuống dưới mức tối thiểu thì sự hỗ trợ của cá thể trong quần thể và khả năng chống chọi với những thay đổi của môi trường của quần thể giảm.Chọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(483, '$14', 'SINGLE_CHOICE', '{"A": "3", "B": "1", "C": "4", "D": "2"}', 'C', 'Quần thể P có tần số alen a = 0,2, A = 0,8Đến thế hệ F1, quần thể cân bằng di truyền → I đúngỞ F2, tần số alen a = 0,5, A = 0,5. Tần số alen a tăng, A giảm, quần thể có thể chịu tác động của yếu tố ngẫu nhiên chống lại alen A → II đúngNếu các cá thể aa ở F3 không có khả năng sinh sản thì thành phần kiểu gen của F3 là: 1/4AA: 2/4Aa → Tần số alen là: A = 2/3, a = 1/3 → Thành phần kiểu gen của F4 là: 4/9AA: 4/9Aa : 1/9aa → III đúngNếu các cá thể aa ở F4 không có khả năng sinh sản thì thành phần kiểu gen của F4 là: 4/9AA: 4/9Aa → Tần số alen là: A = 3/4, a = 1/4 → Tần số kiểu gen aa của F4 là: 1/16 aa → IV đúngChọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(484, 'Trong cấu trúc hệ sinh thái, giun đất thuộc nhóm sinh vật nào sau đây?', 'SINGLE_CHOICE', '{"A": "sinh vật tiêu thụ.", "B": "động vật có xương sống.", "C": "sinh vật sản xuất.", "D": "sinh vật phân giải."}', 'D', 'Trong cấu trúc hệ sinh thái, giun đất thuộc nhóm: sinh vật phân giảiChọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(485, 'Trong các mối quan hệ sinh học giữa các loài sau đây, quan hệ nào là kiểu quan hệ cạnh tranh?', 'SINGLE_CHOICE', '{"A": "Mối và trùng roi sống trong ruột mối.", "B": "Lợn và giun đũa sống trong ruột lợn.", "C": "Lúa và cỏ dại trong cùng một ruộng lúa.", "D": "Chim ăn sâu và sâu ăn lá."}', 'C', 'Quan hệ cạnh tranh là: Lúa và cỏ dại trong cùng một ruộng lúaA là cộng sinhB là kí sinhD là vật ăn thịt – con mồi.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(486, 'Quá trình hình thành loài lúa mì (T. aestivum) được các nhà khoa học mô tả như sau: Loài lúa mì (T. monococcum) lai với loài cỏ dại (T. speltoides) đã tạo ra con lai. Con lai này được gấp đôi bộ nhiễm sắc thể tạo thành loài lúa mì hoang dại (A. squarrosa). Loài lúa mì hoang dại (A. squarrosa) lai với loài cỏ dại (T. tauschii) đã tạo ra con lai. Con lai này lại được gấp đôi bộ nhiễm sắc thể tạo thành loài lúa mì (T. aestivum). Loài lúa mì (T. aestivum) có bộ nhiễm sắc thể gồm:', 'SINGLE_CHOICE', '{"A": "ba bộ nhiễm sắc thể đơn bội của ba loài khác nhau.", "B": "bốn bộ nhiễm sắc thể lưỡng bội của bốn loài khác nhau.", "C": "bốn bộ nhiễm sắc thể đơn bội của bốn loài khác nhau.", "D": "ba bộ nhiễm sắc thể lưỡng bội của ba loài khác nhau."}', 'D', 'Loài lúa mì (T. aestivum) có bộ nhiễm sắc thể gồm ba bộ nhiễm sắc thể lưỡng bội của ba loài khác nhau do loài này được hình thành theo con đường lai xa và đa bội hóa 2 lần.Chọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(487, 'Các nhân tố nào sau đây vừa làm thay đổi tần số alen vừa có thể làm phong phú vốn gen của quần thể?', 'SINGLE_CHOICE', '{"A": "Chọn lọc tự nhiên và giao phối không ngẫu nhiên.", "B": "Giao phối ngẫu nhiên và các cơ chế cách li.", "C": "Đột biến và di - nhập gen.", "D": "Chọn lọc tự nhiên và các yếu tố ngẫu nhiên."}', 'C', 'Đột biến và di - nhập gen vừa làm thay đổi tần số alen vừa có thể làm phong phú vốn gen của quần thể.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(488, 'Trình tự các giai đoạn trong quá trình phát sinh sự sống là gì?', 'SINGLE_CHOICE', '{"A": "Tiến hoá tiền sinh học - tiến hoá hoá học - tiến hoá sinh học.", "B": "Tiến hoá hoá học - tiến hoá tiền sinh học - tiến hoá sinh học.", "C": "Tiến hoá hoá học - tiến hoá tiền sinh học", "D": "Tiến hoá hoá học - tiến hoá sinh học- tiến hoá tiền sinh học"}', 'B', 'Trình tự các giai đoạn trong quá trình phát sinh sự sống: Tiến hoá hoá học - tiến hoá tiền sinh học - tiến hoá sinh họcChọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(489, 'Một "không gian sinh thái" mà ở đó tất cả các nhân tố sinh thái của môi trường nằm trong giới hạn sinh thái cho phép loài đó tồn tại và phát triển gọi là:', 'SINGLE_CHOICE', '{"A": "Giới hạn sinh thái", "B": "Nơi ở", "C": "Sinh cảnh", "D": "Ổ sinh thái"}', 'D', 'Ổ sinh thái là một "không gian sinh thái" mà ở đó tất cả các nhân tố sinh thái của môi trường nằm trong giới hạn sinh thái cho phép loài đó tồn tại và phát triển.Chọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(490, 'Khoảng giá trị xác định của một nhân tố sinh thái mà trong khoáng đó sinh vật có thể tồn tại và phát triển ổn định theo thời gian được gọi là:', 'SINGLE_CHOICE', '{"A": "Sinh cảnh", "B": "Ổ sinh thái", "C": "Môi trường", "D": "Giới hạn sinh thái"}', 'D', 'Khoảng giá trị xác định của một nhân tố sinh thái mà trong khoáng đó sinh vật có thể tồn tại và phát triển ổn định theo thời gian được gọi là: Giới hạn sinh tháiChọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(491, 'Trong các nhân tố tiến hoá, nhân tố làm thay đổi tần số alen của quẩn thể chậm nhất là gì?', 'SINGLE_CHOICE', '{"A": "Di - nhập gen.", "B": "Giao phối.", "C": "Chọn lọc tự nhiên.", "D": "Đột biến."}', 'D', 'Đột biến làm thay đổi tần số alen của quẩn thể chậm nhất.Chọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(492, 'Ở một loài thực vật giao phấn, các hạt phấn của quần thể 1 theo gió bay sang quẩn thể 2 và thụ phấn cho các cây của quần thể 2. Đây là một ví dụ về:', 'SINGLE_CHOICE', '{"A": "biến động di truyền.", "B": "thoái hóa giống.", "C": "di - nhập gen.", "D": "giao phối không ngẫu nhiên."}', 'C', 'Đây là ví dụ về di - nhập gen.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(493, 'Theo thuyết tiến hóa hiện đại, phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Các yếu tố ngẫu nhiên làm nghèo vốn gen quần thể, giảm sự đa dạng di truyền nên không có vai trò đối với tiến hóa.", "B": "Khi không có tác động của đột biến, chọn lọc tự nhiên và di - nhập gen thì tần số alen và thành phần kiểu gen của quần thể sẽ không thay đồi.", "C": "Quá trình tiến hóa nhỏ diễn ra trên quy mô quần thể và diễn biến không ngừng dưới tác động của các nhân tố tiến hóa.", "D": "Chọn lọc tự nhiên luôn làm thay đổi đột ngột tẩn số alen và thành phần kiểu gen của quần thể."}', 'C', 'Ý đúng là CChọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(494, 'Đặc trưng nào sau đây không phải là đặc trưng của quần thể?', 'SINGLE_CHOICE', '{"A": "Tỉ lệ các nhóm tuổi.", "B": "Nhóm loài.", "C": "Tỉ lệ giới tính.", "D": "Mật độ cá thể."}', 'B', 'Nhóm loài không phải là đặc trưng của quần thể.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(495, 'Loài ưu thế là loài có vai trò quan trọng trong quần xã do đâu?', 'SINGLE_CHOICE', '{"A": "có khả năng tiêu diệt các loài khác.", "B": "sức sống mạnh, sinh khối lớn, hoạt động mạnh.", "C": "số lượng cá thể nhiều.", "D": "số lượng cá thể nhiều, sinh khối lớn, hoạt động mạnh."}', 'D', 'Loài ưu thế là loài có vai trò quan trọng trong quần xã do số lượng cá thể nhiều, sinh khối lớn, hoạt động mạnhChọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(496, 'Khi quan sát biến dị ở sinh vật, Đacuyn là người đầu tiên đưa ra khái niệm nào sau đây?', 'SINGLE_CHOICE', '{"A": "Đột biến trung tính.", "B": "Thường biến.", "C": "Biến dị cá thể.", "D": "Biến dị tổ hợp."}', 'C', 'Đacuyn là người đầu tiên đưa ra khái niệm: Biến dị cá thể.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(497, 'Quan hệ giữa chim mỏ đỏ và linh dương thuộc quan hệ gì?', 'SINGLE_CHOICE', '{"A": "hợp tác.", "B": "cạnh tranh.", "C": "cộng sinh.", "D": "hội sinh."}', 'A', 'Quan hệ giữa chim mỏ đỏ và linh dương thuộc quan hệ hợp tác.Chọn A', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(498, 'Nhân tố tiến hoá chỉ làm thay đổi thành phẩn kiểu gen mà không làm thay đổi tần số alen của quần thể là gì?', 'SINGLE_CHOICE', '{"A": "di - nhập gen.", "B": "giao phối không ngẫu nhiên.", "C": "các yếu tố ngẫu nhiên.", "D": "đột biến, CLTN."}', 'B', 'Giao phối không ngẫu nhiên chỉ làm thay đổi thành phẩn kiểu gen mà không làm thay đổi tần số alen của quần thể.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(499, 'Đối với quá trình tiến hóa, chọn lọc tự nhiên và các yếu tố ngẫu nhiên đều có vai trò gì?', 'SINGLE_CHOICE', '{"A": "làm thay đổi tần số alen và thành phần kiểu gen của quần thể.", "B": "tạo ra các kiểu gen quy định các kiểu hình thích nghi.", "C": "làm phong phú vốn gen của quần thể.", "D": "định hướng quá trình tiến hóa."}', 'A', 'Chọn lọc tự nhiên và các yếu tố ngẫu nhiên đều có vai trò làm thay đổi tần số alen và thành phần kiểu gen của quần thể.Chọn A', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(500, 'Một alen nào đó dù có lợi cũng có thể bị loại bỏ hoàn toàn khỏi quần thể là do tác động của nhân tố nào sau đây?', 'SINGLE_CHOICE', '{"A": "Giao phối không ngẫu nhiên.", "B": "Giao phối ngẫu nhiên.", "C": "Chọn lọc tự nhiên.", "D": "Các yếu tố ngẫu nhiên."}', 'D', 'Một alen nào đó dù có lợi cũng có thể bị loại bỏ hoàn toàn khỏi quần thể là do tác động của Các yếu tố ngẫu nhiên.Chọn D', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(501, 'Khi nói về độ đa dạng của quần xã, phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Một quần xã có độ đa dạng cao khi số loài nhiều và số lượng cá thể của mỗi loài nhiều.", "B": "Quần xã có độ đa dạng càng cao thì cấu trúc của quần xã càng dễ bị biến động.", "C": "Độ đa dạng của quần xã càng cao thì lưới thức ăn của quần xã càng phức tạp.", "D": "Độ đa dạng của quẩn xã thường được duy trì ổn định, không phụ thuộc điều kiện sổng của môi trường."}', 'C', 'Ý đúng là CChọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(502, 'Ở biển, sự phân bố của các nhóm tảo (tảo nâu, tảo đỏ, tảo lục) từ mặt nước xuống lớp nước sâu theo trình tự nào sau đây?', 'SINGLE_CHOICE', '{"A": "tảo lục, tảo nâu, tảo đỏ", "B": "tảo đỏ, tảo nâu, tảo lục", "C": "tảo lục, tảo đỏ, tảo nâu", "D": "tảo nâu, tảo lục, tảo đỏ."}', 'A', 'Sự phân bố của các nhóm tảo từ mặt nước xuống lớp nước sâu theo trình tự: tảo lục, tảo nâu, tảo đỏ.Chọn A', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(503, 'Theo quan điểm hiện đại, chọn lọc tự nhiên tác động trực tiếp lên yếu tố nào?', 'SINGLE_CHOICE', '{"A": "kiểu gen.", "B": "alen.", "C": "kiểu hình.", "D": "nhiễm sắc thể."}', 'C', 'Theo quan điểm hiện đại, chọn lọc tự nhiên tác động trực tiếp lên kiểu hình.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(504, 'Quần thể là một tập hợp cá thể như thế nào?', 'SINGLE_CHOICE', '{"A": "cùng loài, cùng sống trong 1 khoảng không gian xác định, vào một thời điểm xác định.", "B": "khác loài, sống trong 1 khoảng không gian xác định vào một thời điểm xác định.", "C": "cùng loài, cùng sống trong 1 khoảng không gian xác định, vào một thời điểm xác định, có khả năng sinh sản tạo thế hệ mới.", "D": "cùng loài, sống trong 1 khoảng không gian xác định, có khả năng sinh sản tạo thế hệ mới."}', 'C', 'Quần thể là một tập hợp cá thể cùng loài, cùng sống trong 1 khoảng không gian xác định, vào một thời điểm xác định, có khả năng sinh sản tạo thế hệ mới.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(505, 'Khoảng thuận lợi là khoảng các nhân tố sinh thái như thế nào?', 'SINGLE_CHOICE', '{"A": "mức phù hợp nhất để sinh vật thực hiện chức năng sống tốt nhất.", "B": "ở đó sinh vật sinh trưởng, phát triển tốt nhất.", "C": "giúp sinh vật chống chịu tốt nhất với môi trường.", "D": "ở đó sinh vật sinh sản tốt nhất."}', 'A', 'Khoảng thuận lợi là khoảng các nhân tố sinh thái ở mức phù hợp nhất để sinh vật thực hiện chức năng sống tốt nhấtChọn A', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(506, 'Cách li địa lí có vai trò quan trọng trong quá trình tiến hóa vì sao?', 'SINGLE_CHOICE', '{"A": "điều kiện địa lí khác nhau sản sinh ra các đột biến khác nhau dẫn đến hình thành loài mới.", "B": "cách li địa lí giúp duy trì sự khác biệt về tần số alen và thành phần kiểu gen giữa các quần thể gây nên bởi các nhân tố tiến hóa.", "C": "cách li địa lí là nguyên nhân trực tiếp làm xuất hiện sự cách li sinh sàn.", "D": "điều kiện địa lí khác nhau là nguyên nhân trực tiếp gây ra biến đổi trên cơ thể sinh vật."}', 'B', 'Cách li địa lí có vai trò quan trọng trong quá trình tiến hóa vì: cách li địa lí giúp duy trì sự khác biệt về tần số alen và thành phần kiểu gen giữa các quần thể gây nên bởi các nhân tố tiến hóa.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(507, 'Quan hệ giữa động vật ăn cỏ với vi khuẩn phân rã xelulôzơ thuộc quan hệ nào dưới đây?', 'SINGLE_CHOICE', '{"A": "hợp tác.", "B": "cộng sinh.", "C": "hội sinh.", "D": "cạnh tranh."}', 'B', 'Quan hệ giữa động vật ăn cỏ với vi khuẩn phân rã xelulôzơ thuộc quan hệ cộng sinh.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(508, 'Chim sâu và chim sẻ thường sinh sống ở tán lá cây, vậy kết luận nào đúng?', 'SINGLE_CHOICE', '{"A": "Chúng có cùng ổ sinh thái, khác nơi ở.", "B": "Chúng cùng giới hạn sinh thái.", "C": "Chúng có cùng nơi ở, khác ổ sinh thái.", "D": "Chúng có cùng nơi ở và ổ sinh thái."}', 'C', 'Chim sâu và chim sẻ thường sinh sống ở tán lá cây, vậy: Chúng có cùng nơi ở, khác ổ sinh thái.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(509, 'Tập hợp sinh vật nào sau đây không phải là quần thể?', 'SINGLE_CHOICE', '{"A": "Tập hợp cây cọ ở trên quả đồi Phú Thọ.", "B": "Tập hợp cây cỏ trên một đồng cỏ.", "C": "Tập hợp cây thông trong một rừng thông ở Đà Lạt.", "D": "Tập hợp cá chép sinh sống ở Hồ Tây."}', 'B', 'Tập hợp cây cỏ trên một đồng cỏ không phải là quần thể.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(510, 'Nguồn nguyên liệu sơ cấp của quá trình tiến hoá là gì?', 'SINGLE_CHOICE', '{"A": "Quá trình giao phối.", "B": "Đột biến.", "C": "Biến dị tổ hợp.", "D": "Di nhập gen."}', 'B', 'Nguồn nguyên liệu sơ cấp của quá trình tiến hoá là đột biến.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(511, 'Khi nói về kích thước của quần thể sinh vật, phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Nếu kích thước quẩn thể xuống dưới mức tối thiểu, quần thể dễ rơi vào trạng thái suy giảm dẫn tới diệt vong.", "B": "Các quần thể cùng loài luôn có kích thước quần thể giống nhau,", "C": "Kích thước quần thể thường ổn định và đặc trưng cho từng loài.", "D": "Nếu kích thước quẩn thể vượt quá mức tối đa thì cạnh tranh giữa các cá thể trong quần thể tăng cao dẫn tới có thể sẽ làm tiêu diệt quần thể."}', 'A', 'Phát biểu đúng là AChọn A', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(512, 'Hiện nay, tất cả các cơ thể sinh vật từ đơn bào đến đa bào đều được cấu tạo từ tế bào. Đây là một trong những bằng chứng chứng tỏ điều gì?', 'SINGLE_CHOICE', '{"A": "nguồn gốc thống nhất của các loài.", "B": "quá trình tiến hóa đồng quy của sinh giới.", "C": "vai trò của các yếu tố ngẫu nhiên với quá trình tiến hóa", "D": "sự tiến hóa không ngừng của sinh giới."}', 'A', 'Đây là một trong những bằng chứng chứng tỏ nguồn gốc thống nhất của các loài.Chọn A', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(513, 'Ở một loài cá nhỏ, gen A quy định cơ thể có màu nâu nhạt nằm trên NST thường trội hoàn toàn so với alen a quy định màu đốm trắng. Một quần thể của loài này sống trong hồ nước có nền cát màu nâu có thành phần kiểu gen là 0,81 AA + 0,18 Aa + 0,01 aa. Một công ty xây dựng rải một lớp sỏi xuống hồ, làm mặt hồ trở nên có nền đốm trắng. Từ khi đáy hồ được rải sỏi, xu hướng biến đổi tần số alen A của quần thể ở các thể hệ cá con tiếp theo được mô tả rút gọn bằng sơ đồ sau đây:', 'SINGLE_CHOICE', '{"A": "0,1A — 0,2A—0,3A—0,4A — 0,5A—0,6A — 0,7A —0,8A —0,9A.", "B": "0,8A — 0,9A—0,7A—0,6A — 0,5A—0,4A — 0,3A —0,2A —0,1A.", "C": "0,9A— 0,8A—0,7A— 0,6A — 0,5 A—0,4A —0,3A —0,2A —0,1A.", "D": "0,9A— 0,8A—0,7A— 0,6A — 0,5A—0,6A —0,7A —0,8A —0,9A."}', 'C', 'Khi sỏi được rải xuống hồ, mặt hồ đã bị biến đổi trở nên có đốm trắng, chọn lọc tự nhiên đã thay đổi thành giữ lại cá thể đốm, loại bỏ cá thể nâu, Qua các thế hệ, cá thể nâu sẽ giảm dần số lượng, tần số alen A cũng giảm dần.Chọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(514, 'Nội dung nào sau đây đúng khi nói về các nhân tố tiến hóa?', 'SINGLE_CHOICE', '{"A": "Các nhân tố tiến hóa không làm thay đổi tần số alen và thành phần kiểu gen", "B": "Các nhân tố tiến hóa đều làm thay đổi thành phần kiểu gen và tần số alen", "C": "Các nhân tố tiến hỏa đều làm thay đổi thành phần kiểu gen", "D": "Các nhân tố tiến hóa đều làm thay đổi tần sổ alen"}', 'C', 'Ý đúng là CChọn C', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(515, 'Theo quan niệm hiện đại, chọn lọc tự nhiên là gì?', 'SINGLE_CHOICE', '{"A": "không tác động lên từng cá thể mà chỉ tác động lên toàn bộ quần thể.", "B": "vừa làm thay đổi tẩn số alen vừa làm thay đối thành phần kiểu gen của quần thể.", "C": "chống lại alen lặn sẽ nhanh chóng loại bỏ hoàn toàn các alen lặn ra khỏi quần thể", "D": "trực tiếp tạo ra các tổ hợp gen thích nghi trong quần thể."}', 'B', 'Theo quan niệm hiện đại, chọn lọc tự nhiên vừa làm thay đổi tẩn số alen vừa làm thay đối thành phần kiểu gen của quần thể.Chọn B', 17);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(516, 'Các cây tràm ờ rừng U minh là loài gì trong hệ sinh thái?', 'SINGLE_CHOICE', '{"A": "ưu thế.", "B": "đặc biệt.", "C": "đặc trưng.", "D": "có số lượng nhiều."}', 'C', 'Các cây tràm ờ rừng U minh là loài đặc trưng.Chọn C', 17);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(18, 'Đề thi thử THPT QG năm 2022 môn Sinh Học online - Đề thi của Trường THPT Trần Quốc Tuấn', 'Sinh Học', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Sinh Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(517, 'Nhóm nào dưới đây gồm toàn những nguyên tố vi lượng được xem là nguyên tố khoáng thiết yếu cần thiết đối với sinh trưởng của mọi loại thực vật?', 'SINGLE_CHOICE', '{"A": "B, K, Ca, Mg", "B": "Fe, Mn, Cl, Cu", "C": "H, O, N, Zn", "D": "Fe, Mn, C, Ni"}', 'A', 'Chọn đáp án BGiải thích:- A loại vì có chứa nguyên tố đa lượng như Mg, Ca, K.- B đúng- C, D loại vì có chứa nguyên tố đa lượng như C, H, O, N', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(518, 'Khi bạn nín thở, khí nào trong các khí sau đây của máu thay đổi đầu tiên dẫn đến buộc bạn phải hít thở?', 'SINGLE_CHOICE', '{"A": "Tăng O2", "B": "Giảm O2", "C": "Tăng CO2", "D": "Giảm CO2 và tăng O2."}', 'A', 'Chọn đáp án CGiải thích:Khi bạn nín thở, lượng CO2 trong máu không được thở ra ngoài nên CO2 tăng lên gây độc cho cơ thể.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(519, 'Côđon nào sau không mã hóa axit amin?', 'SINGLE_CHOICE', '{"A": "5’-AUG-3’", "B": "5’-UAA-3’", "C": "5’ –AUU- 3’", "D": "5’ –UUU- 3’"}', 'A', 'Chọn đáp án BGiải thích:Côđon không mã hóa axit amin là côđon kết thúc : 5’-UAA-3’', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(520, 'Phương pháp nào sau đây có thể tạo ra được nhiều con vật có kiểu gen giống nhau từ một phôi ban đầu?', 'SINGLE_CHOICE', '{"A": "Lai tế bào sinh dưỡng", "B": "Gây đột biến nhân tạo", "C": "Nhân bản vô tính", "D": "Cấy truyền phôi"}', 'A', 'Chọn đáp án DGiải thích:- A Loại vì: “Lai tế bào sinh dưỡng” áp dụng đối với thực vật- B Loại vì: “Gây đột biến nhân tạo” thường không áp dụng đối với động vật- C Loại vì: “Nhân bản vô tính” không tạo ra được nhiều con vật có kiểu gen giống nhau từ một phôi ban đầu- D Chọn vì: “Cấy nguyên phôi” là tách phôi thành hai hay nhiều phần, mỗi phần sau đó sẽ phát triển thành 1 phôi riêng biệt.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(521, 'Trong cùng một gen, dạng đột biến nào sau gây hậu quả nghiêm trọng hơn các trường hợp còn lại?', 'SINGLE_CHOICE', '{"A": "Thêm 1 cặp nuclêôtit ở vị trí số 6.", "B": "Mất 3 cặp nuclêôtit liên tiếp ở vị trí 15,16, 17.", "C": "Thay thế 1 cặp nuclêôtit vị trí số 3", "D": "Thay thế 2 cặp nuclêôtit ở vị trí số 15 và số 30."}', 'A', 'Chọn đáp án AGiải thích:- A đúng vì trong các trường hợp trên thì “Thêm 1 cặp nuclêôtit ở vị trí số 6” gây hậu quả nghiêm trọng hơn các trường hợp còn lại vì làm thay đổi axit amin từ axit amin thứ 2.- B sai vì mất 3 cặp nuclêôtit liên tiếp ở vị trí 15, 16, 17 làm mất một axit amin- C, D là dạng đột biến thay thế có sự ảnh hưởng ít nghiêm trọng hơn.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(522, 'Ở một tế bào sinh dục đực, sự không phân li của toàn bộ bộ NST trong lần giảm phân 1 của phân bào giảm nhiễm còn giảm phân 2 diễn ra bình thường sẽ tạo ra loại giao tử nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Giao tử n", "B": "Giao tử 2n", "C": "Giao tử 4n", "D": "Giao tử 3n"}', 'A', 'Chọn đáp án BGiải thích:Ở một tế bào sinh dục đực, sự không phân li của toàn bộ bộ NST trong lần giảm phân 1 sẽ tạo ra 1 tế bào mang 2n NST kép và 1 tế bào không mang NST nào. Các tế bào này đi vào giảm phân 2 bình thường sẽ tạo ra 2 giao tử mang 2n NST đơn và 2 giao tử không mang NST nào. Vậy đáp án của câu hỏi này là: giao tử 2n.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(523, 'Đến mùa sinh sản, các cá thể đực tranh giành con cái là mối quan hệ nào?', 'SINGLE_CHOICE', '{"A": "Cạnh tranh cùng loài", "B": "Cạnh tranh khác loài", "C": "Ức chế - cảm nhiễm", "D": "Hỗ trợ cùng loài"}', 'A', 'Chọn đáp án AGiải thích:Đến mùa sinh sản, các cá thể đực tranh giành con cái là mối quan hệ cạnh tranh cùng loài.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(524, 'Theo lí thuyết, phép lai nào sau đây cho đời con có kiểu gen phân li theo tỉ lệ 1 : 2 : 1?', 'SINGLE_CHOICE', '{"A": "AaBb x aabb", "B": "Aabb x Aabb", "C": "AaBB x aabb", "D": "AaBB x aabb."}', 'A', 'Chọn đáp án BGiải thích:Kiểu gen ở đời con phân li theo tỉ lệ 1: 2 : 1 khi đời bố mẹ có chứa một cặp gen dị hợp lai với nhau, cặp còn lại đồng hợp tử. Vậy phép lai cho tỉ lệ 1 : 2 : 1 là Aabb&nbsp; x&nbsp; Aabb&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(525, 'Khi nói về lưới thức ăn, phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Trong một lưới thức ăn, mỗi bậc dinh dưỡng thường chỉ có 1 loài sinh vật.", "B": "Trong một lưới thức ăn, động vật ăn thịt thường là bậc dinh dưỡng cấp 1.", "C": "Hệ sinh thái nhân tạo thường có lưới thức ăn phức tạp hơn hệ sinh thái tự nhiên.", "D": "Mỗi loài sinh vật có thể thuộc nhiều bậc dinh dưỡng khác nhau."}', 'A', 'Chọn đáp án DGiải thích:- A sai vì trong một lưới thức ăn, mỗi bậc dinh dưỡng có thể có nhiều loài sinh vật (mặt xích chung).- B sai vì bậc dinh dưỡng cấp 1 là sinh vật sản xuất.- C sai vì hệ sinh thái nhân tạo thường có lưới thức ăn đơn giản hơn so với hệ sinh thái tự nhiên.- D đúng.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(526, 'Chọn phép lai cho ra số kiểu hình nhiều nhất, biết mỗi gen quy định một tính trạng, trội là trội hoàn toàn.', 'SINGLE_CHOICE', '{"A": "XAXa Bb x XAY Bb", "B": "AaBb x AaBb", "C": "AB/ab x AB/ab", "D": "XAXa Bb x XaY bb"}', 'A', 'Chọn đáp án AGiải thích:NST thường cho số loại giao tử ít hơn NST giới tính; kiểu gen đồng hợp cho số giao tử ít hơn kiểu gen dị hợp. Số lượng giao tử càng nhiều thì số biến dị tổ hợp càng lớn và tỉ lệ thuận với nó là kiểu hình càng phong phú. Dựa vào phân tích ttên ta có thể nhận ra trong các phép lai đang xét, phép lai:&nbsp;\({X^A}{X^a}Bb\,x\,{X^a}YBb\) &nbsp;cho số kiểu hình nhiều nhất vì hội tụ cả hai yếu tố, số cặp gen dị hợp nhiều nhất và có một cặp gen nằm trên NST giới tính. Vậy đáp án của câu hỏi này là:&nbsp;&nbsp;\({X^A}{X^a}Bb\,x\,{X^a}YBb\)', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(527, 'Trong các nhân tố tiến hóa sau, nhân tố nào không làm thay đổi tần số alen của quần thể?', 'SINGLE_CHOICE', '{"A": "Đột biến.", "B": "Giao phối không ngẫu nhiên.", "C": "Các yếu tố ngẫu nhiên", "D": "Chọn lọc tự nhiên."}', 'A', 'Trong các nhân tố tiến hóa sau, nhân tố không làm thay đổi tần số alen của quần thể:&nbsp;Giao phối không ngẫu nhiên.Đáp án B', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(528, 'Để nhân giống hoa lan có được những đặc tính giống nhau từ một giống lan quý, các nhà nhân giống cây cảnh đã áp dụng tạo giống bằng phương pháp nào?', 'SINGLE_CHOICE', '{"A": "Công nghệ gen", "B": "Gây đột biến", "C": "Lai hữu tính.", "D": "Công nghệ tế bào."}', 'A', '&nbsp;Chọn đáp án DGiải thích:Để nhân giống hoa lan có được những đặc tính giống nhau từ một giống lan quý, các nhà nhân giống cây cảnh đã áp dụng tạo giống bằng phương pháp: Công nghệ tế bào (nhanh, bảo tồn nguyên vẹn&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(529, 'Theo quan niệm hiện đại, thực chất của quá trình chọn lọc là', 'SINGLE_CHOICE', '{"A": "sự phân hóa khả năng tồn tại của các cá thể trước các điều kiện khắc nghiệt của môi trường.", "B": "sự phân hóa khả năng tìm kiếm bạn tình trong quần thể.", "C": "sự phân hóa các cá thể có sức khỏe và khả năng cạnh tranh khi kiếm mồi.", "D": "sự phân hóa khả năng sống sót và sinh sản của các kiểu gen khác nhau trong quần thể."}', 'A', 'Chọn đáp án DGiải thích:Theo quan niệm hiện đại, thực chất của quá trình chọn lọc là sự phân hóa khả năng sống sót và sinh sản của các kiểu gen khác nhau trong quần thể.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(530, 'Khi nói về nhân tố sinh thái hữu sinh, phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Mức độ tác động của nhân tố hữu sinh lên cá thể sinh vật không phụ thuộc vào mật độ của quần thể.", "B": "Khi mật độ cá thể của các quần thể càng cao thì mức độ tác động của nhân tố hữu sinh càng mạnh", "C": "Khi quần thể chịu tác động của nhân tố hữu sinh thì sẽ không chịu tác động của nhân tố sinh thái vô sinh.", "D": "Những nhân tố vật lý, hóa học có ảnh hưởng đến sinh vật thì cũng được xếp vào nhân tố hữu sinh."}', 'A', 'Chọn đáp án BGiải thích:- A sai vì mức tác động của nhân tố hữu sinh lên cá thể sinh vật là phụ thuộc vào mật độ của quần thể, nhân tố vô sinh không phụ thuộc vào mật độ của quần thể.- B đúng- C sai vì nhân tố hữu sinh và nhân tố vô sinh tác động đồng thời vào quần thể.- D sai vì vật lý, hoá học là những nhân tố vô sinh.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(531, 'Sự kiện nào sau đây thuộc về đại cổ sinh?', 'SINGLE_CHOICE', '{"A": "Xuất hiện thực vật có hoa, phân hóa côn trùng", "B": "Thực vật có hạt xuất hiện, phát sinh bò sát.", "C": "Phát sinh tảo và động vật không xương sống thấp ở biển", "D": "Phát sinh thú và chim, phân hóa bò sát cổ."}', 'A', 'Thực vật có hạt xuất hiện, phát sinh bò sát là sự kiện thuộc về đại cổ sinh.Đáp án B', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(532, 'Một đoạn gen có trình tự 5’-AGAGTX AAA GTX TXA XTX-3’. Sau khi xử lí với tác nhân gây đột biến, người ta đã thu được trình tự của đoạn gen đột biến là 5 ’-AGA GTX AAA AGT XTX AXT-3 ’. Phát biểu nào sau đây đúng khi nói về dạng đột biến trên?', 'SINGLE_CHOICE', '{"A": "Một cặp nuclêôtit G-X đã được thay thế bằng cặp nuclêôtit A-T.", "B": "Không xảy ra đột biến vì số bộ ba vẫn bằng nhau.", "C": "Một cặp nuclêôtit A-T được thêm vào đoạn gen.", "D": "Một cặp nuclêôtit G-X bị làm mất khỏi đoạn gen."}', 'A', 'Chọn đáp án CGiải thích:Gen bình thường: 5’-AGA GTX AAA GTX TXA XTX-3’&nbsp;Gen đột biến:&nbsp; &nbsp; &nbsp; &nbsp;5’-AGA GTX AAA AGT XTX AXT-3’Đây là dạng đột biến một cặp nuclêôtit A-T được thêm vào đoạn gen.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(533, 'Khi nói về kích thước của quần thể sinh vật, phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Kích thước của quần thể là khoảng không gian mà các cá thể của quần thể sinh sống.", "B": "Kích thước quần thể có ảnh hưởng đến mức sinh sản và mức tử vong của quần thể.", "C": "Nếu kích thước quần thể đạt mức tối đa thì các cá thể trong quần thể thường tăng cường hỗ trợ nhau.", "D": "Kích thước của quần thể luôn ổn định, không phụ thuộc vào điều kiện môi trường."}', 'A', 'Chọn đáp án BGiải thích:- A sai vì kích thước của quần thể hay số lượng cá thể trong quần thể là: tổng số cá thể, hay sản lượng, năng lượng của cá thể trong quần thể đó.- B đúng, kích thước của quần thể ảnh hưởng đến mức sinh sản và mức tử vong của quần thể.- C sai vì nếu kích thước của quần thể đạt tới mức tối đa thì các cá thể trong quần thể thường dẫn đến cạnh tranh nhau.- D sai vì kích thước của quần thể luôn thay đổi và phụ thuộc vào điều kiện môi trường.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(534, 'Đâu&nbsp;không phải&nbsp;lí do làm cho cây trên cạn bị ngập úng lâu ngày thì sẽ chết?', 'SINGLE_CHOICE', '{"A": "Rễ cây bị thiếu oxi nên cây hô hấp không bình thường.", "B": "Lông hút bị chết.", "C": "Cân bằng nước trong cây bị phá hủy.", "D": "Cây bị thừa nước, tất cả các tế bào đều bị úng nước nên hoạt động kém."}', 'A', 'Cây bị thừa nước, tất cả các tế bào đều bị úng nước nên hoạt động kém.&nbsp;không phải&nbsp;lí do làm cho cây trên cạn bị ngập úng lâu ngày thì sẽ chết.Đáp án D', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(535, 'Một loài thực vật, alen A qui định thân cao trội hoàn toàn so với alen a qui định thân thấp. Biết rằng không xảy ra đột biến. Theo lí thuyết, phép lai nào sau đây cho đời con chỉ xuất hiện cây thân cao?', 'SINGLE_CHOICE', '{"A": "Aa x Aa", "B": "Aa x aa", "C": "aa x aa", "D": "Aa x AA"}', 'A', 'Chọn đáp án DGiải thích:A. Aa x Aa → 3cao: 1 thấpB. Aa x aa → 1 cao: 1 thấpC. aa x aa → 100% thấpD. Aa x AA → 100% cao', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(536, 'Sự kết hợp giữa giao tử (n + 1) và giao tử (n + 1) có thể làm phát sinh thể dị bội nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Thể bốn nhiễm", "B": "Thể bốn nhiễm kép", "C": "Thể một nhiễm kép", "D": "Thể ba nhiễm."}', 'A', 'Sự kết hợp giữa giao tử (n + 1) và giao tử (n + 1) có thể làm phát sinh thể dị bội:&nbsp;Thể bốn nhiễmĐáp án A', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(537, 'Ở một loài thực vật, cho giao phấn giữa cây hoa đỏ thuần chủng với cây hoa trắng được F1 toàn hoa đỏ, cho F1 tự thụ phấn thì kiểu hình ở F2 là 3 hoa đỏ : 1 hoa trắng. Phương pháp nào sau đây không dùng để xác định kiểu gen của cây hoa đỏ ở F2?', 'SINGLE_CHOICE', '{"A": "Lai cây hoa đỏ ở F2 với cây hoa đỏ ở P", "B": "Cho cây hoa đỏ ở F2 tự thụ phấn.", "C": "Lai cây hoa đỏ ở F2 với cây F1.", "D": "Lai cây hoa đỏ ở F2 với cây hoa trắng ở P"}', 'A', 'Chọn đáp án AGiải thích:P: AA x aaF1: AaF1 x F1: Aa x AaF2: 1 AA: 2 Aa: 1aa (3 đỏ: 1 trắng)Để xác định KG hoa đỏ ở F2, có thể dùng:&nbsp;B. Cho cây hoa đỏ ở F2 tự thụ phấn. → đúng, nếu đời con đồng tính → AA; nếu đời con phân tính → AaC. Lai cây hoa đỏ ở F2 với cây F1. → đúng,&nbsp;AA x Aa → 100% đỏAa x Aa → 3 đỏ: 1 trắngD. Lai cây hoa đỏ ở F2 với cây hoa trắng ở P. → đúngAA x aa → 100% đỏAa x aa → 1 đỏ: 1 trắng&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(538, '$27', 'SINGLE_CHOICE', '{"A": "Quần thể A", "B": "Quần thể B", "C": "Quần thể C", "D": "Quần thể D"}', 'A', 'Chọn đáp án DGiải thích:Kích thước các quần thể:A = 25x10 = 250B = 240x15 = 360C = 193x20 = 3860D = 195x25 = 4875→ Quần thể D có kích thước lớn nhất.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(539, 'Phát biểu nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Vận tốc máu là áp lực của máu tác động lên thành mạch.", "B": "Hệ tuần hoàn của động vật gồm hai thành phần là tim và hệ mạch.", "C": "Huyết áp tâm trương được đo ứng với lúc tim giãn và có giá trị lớn nhất.", "D": "Dịch tuần hoàn gồm máu hoặc hỗn hợp máu và dịch mô."}', 'A', 'Chọn đáp án DGiải thích:A. Vận tốc máu là áp lực của máu tác động lên thành mạch. → sai, huyết áp là áp lực của máu tác động lên thành mạch.B. Hệ tuần hoàn của động vật gồm hai thành phần là tim và hệ mạch. → sai, hệ tuần hoàn gồm tim, hệ mạch và dịch tuần hoàn.C. Huyết áp tâm trương được đo ứng với lúc tim giãn và có giá trị lớn nhất. →&nbsp;sai, huyết áp tâm trương được đo ứng với lúc tim giãn và có giá trị nhỏ nhất.D. Dịch tuần hoàn gồm máu hoặc hỗn hợp máu và dịch mô. → đúng', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(540, 'Dùng cônsixin xử lý hợp tử có kiểu gen BbDd, sau đó cho phát triển thành cây hoàn chỉnh thì có thể tạo ra thể tứ bội có kiểu gen?', 'SINGLE_CHOICE', '{"A": "BBbbDDdd", "B": "BBbbDDDd", "C": "BBbbDddd", "D": "BBBbDdd"}', 'A', 'Chọn đáp án AGiải thích:Dùng cônsixin xử lý hợp tử có kiểu gen BbDd, sau đó cho phát triển thành cây hoàn chỉnh thì có thể tạo ra thể tứ bội có kiểu gen: BBbbDDdd.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(541, 'Cho cây dị hợp tử về 2 cặp gen (P) tự thụ phấn, thu được F1. Cho biết mỗi gen qui định một tính trạng, các alen trội là trội hoàn toàn và không xảy ra đột biến. Theo lí thuyết, tỉ lệ kiểu hình ở F1 có thể là:', 'SINGLE_CHOICE', '{"A": "3 : 3 : 1 : 1", "B": "1 : 2 : 1", "C": "19 : 19: 1 : 1", "D": "1 : 1 : 1 : 1"}', 'A', 'Chọn đáp án BGiải thích:Ở một loài thực vật, xét hai cặp alen qui định hai cặp tính trạng trội lặn hoàn toàn. Khi cho cơ thể dị hợp về hai cặp alen đang xét tự thụ phấn, gọi&nbsp; x là tỉ lệ kiểu hình lặn - lặn ở đời con, theo lý thuyết, tỉ lệ phân li kiểu hình ở F1&nbsp; sẽ là: 50% + x (trội - trội) : 25% - x (trội - lặn) : 25% - x (lặn - trội) :&nbsp; x (lặn - lặn)&nbsp;→ chỉ có tỉ lệ 1 : 2 : 1 là phù hợp (dị hợp tử chéo lai với nhau liên kết gen hoàn toàn&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(542, 'Hiện tượng nào sau đây minh họa cho cơ chế cách li trước hợp tử?', 'SINGLE_CHOICE', '{"A": "Lừa giao phối với ngựa sinh ra con la không có khả năng sinh sản.", "B": "Cừu giao phối với dê, hợp tử bị chết ngay sau khi hình thành.", "C": "Một số loài chim sống trong cùng một khu vực vẫn giao phối với nhau, tuy nhiên phần lớn con lai phát triển không hoàn chỉnh và bị bất thụ.", "D": "Chim sẻ và chim gõ kiến không giao phối với nhau do tập tính ve vãn bạn tình khác nhau."}', 'A', 'Chọn đáp án DGiải thích:Cách li trước hợp tử:D. Chim sẻ và chim gõ kiến không giao phối với nhau do tập tính ve vãn bạn tình khác nhau', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(543, 'Để khắc phục những biến đổi bất lợi của môi trường có thể gây ra diễn thế sinh thái con người cần áp dụng nhiều biện pháp khác nhau. Trong các biện pháp dưới đây, biện pháp nào&nbsp;không có&nbsp;tác dụng ngăn chặn diễn thế sinh thái?', 'SINGLE_CHOICE', '{"A": "Duy trì sự đa dạng loài trong quần xã.", "B": "Cải tạo đất, làm thủy lợi để điều tiết nước.", "C": "Sử dụng sinh vật ngoại lai kìm hãm sự phát triển mạnh của loài ưu thế.", "D": "Chăm sóc cây trồng, phòng trừ sâu bệnh hại."}', 'A', 'Chọn đáp án CGiải thích:Để khắc phục những biến đổi bất lợi của môi trường có thể gây ra diễn thế sinh thái con người cần áp dụng nhiều biện pháp biện pháp khác nhau. Biện pháp không có tác dụng ngăn chặn diễn thế sinh thái:&nbsp;C. Sử dụng sinh vật ngoại lai kìm hãm sự phát triển mạnh của loài ưu thếDo sinh vật ngoại lai sẽ tăng trưởng vượt mức  ức chế hoặc lây bệnh cho loài địa phương.&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(544, 'Khi nói về quá trình phiên mã, nhận định nào dưới đây là&nbsp;không&nbsp;chính xác?', 'SINGLE_CHOICE', '{"A": "Xảy ra theo nguyên tắc bổ sung (A - U; T - A; G - X; X - G).", "B": "Xảy ra ở cả virut (có ADN dạng sợi kép), vi khuẩn và sinh vật nhân thực.", "C": "Cả hai mạch của gen đều làm mạch khuôn trong quá trình phiên mã (tổng hợp ARN).", "D": "Trải qua 3 giai đoạn: khởi đầu, kéo dài và kết thúc."}', 'A', 'Chọn đáp án CGiải thích:Xem xét các phương án đưa ra, ta nhận thấy:- Trong phiên mã, chỉ có một mạch được chọn để làm khuôn tổng hợp ARN → C không chính xác- A, C, D là nhận định đúng.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(545, 'Một quần thể sinh vật đang chịu tác động của chọn lọc tự nhiên, có cấu trúc di truyền ở các thế hệ như sau:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; P: 0,09 AA + 0,21 Aa + 0,70 aa = 1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; F1: 0,16 AA + 0,38 Aa + 0,46 aa = 1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; F2: 0,20 AA + 0,44 Aa + 0,36 aa = 1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; F3: 0,25 AA + 0,50 Aa + 0,25 aa = 1.Biết A trội hoàn toàn so với a. Chọn lọc tự nhiên đã tác động lên quần thể trên theo hướng', 'SINGLE_CHOICE', '{"A": "Loại bỏ kiểu gen đồng hợp trội và kiểu gen đồng hợp lặn.", "B": "Loại bỏ kiểu gen đồng hợp trội và kiểu gen dị hợp.", "C": "Loại bỏ kiểu gen dị hợp và giữ lại các kiểu gen đồng hợp.", "D": "Các cá thể mang kiểu hình lặn đang bị chọn lọc tự nhiên loại bỏ dần."}', 'A', 'Chọn đáp án DGiải thích:P: 0,09 AA + 0,21 Aa + 0,70 aa = 1.F1: 0,16 AA + 0,38 Aa + 0,46 aa = 1.F2: 0,20 AA + 0,44 Aa + 0,36 aa = 1.F3: 0,25 AA + 0,50 Aa + 0,25 aa = 1.Biết A trội hoàn toàn so với a. Chọn lọc tự nhiên đã tác động lên quần thể trên theo hướng các cá thể mang kiểu hình lặn đang bị chọn lọc tự nhiên loại bỏ dần (vì aa giảm dần)&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(546, 'Cho lưới thức ăn sau, có bao nhiêu nhận định dưới đây đúng?&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; I. Lưới thức ăn bao gồm 6 chuỗi thức ăn.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; II. Không tính đến sinh vật phân giải, có 5 mắt xích chung giữa các chuỗi thức ăn.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; III. Khi gà biến mất khỏi lưới thức ăn thì số lượng thỏ sẽ giảm mạnh.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; IV. Có ba loài sinh vật thuộc nhóm sinh vật tiêu thụ bậc 2.', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "3", "D": "4"}', 'A', 'Chọn đáp án DGiải thích:Dựa vào lưới thức ăn, ta lần lượt xét các nhận định mà đề bài đưa ra:- Lưới thức ăn bao gồm 6 chuỗi thức ăn là: “Cỏ → Dê → Hổ → Vi sinh vât” ; “ Cỏ → Thỏ → Hổ → Vi sinh vật” ; “Cỏ → Thỏ → Cáo → Vi sinh vật” ; “Cỏ → Thỏ → Mèo rừng → Vi sinh vật” ; “Cỏ → Gà → Cáo →Vi sinh vật” ; “Cỏ → Gà → Mèo rừng → Vi sinh vật” → I đúng- Không tính đến sinh vật phân giải, có 5 mất xích chung giữa các chuỗi thức ăn là: Hổ; Thỏ; Cáo; Gà; Mèo rừng → II đúng- Khi gà biến mất khỏi lưới thức ăn thì cáo và mèo rừng chỉ còn nguồn thức ăn duy nhất là thỏ → số lượng thỏ sẽ giảm mạnh → III đúng- Có ba loài sinh vật thuộc nhóm sinh vật tiêu thụ bậc 2 là : Hổ; Cáo; Mèo rừng → IV đúngVậy số nhận định đúng là 4.', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(547, 'Phân tử ADN ở vùng nhân của E.coli có tổng số liên kết hiđro là 3450 liên kết. Trên mạch 1 có số lượng nuclêôtit loại G bằng loại X và số X gấp 3 lần nuclêôtit loại A trên mạch đó. Số lượng nuclêôtit loại A trên mạch 2 gấp 5 lần số lượng A trên mạch 1. Xác định phương án trả lời sai:', 'SINGLE_CHOICE', '{"A": "Khi phân tử ADN nhân đôi 2 lần đã lấy từ môi trường 2070 nuclêôtit loại A và 2070 nu loại X.", "B": "Số lượng liên kết hóa trị giữa các nuclêôtit trong phân tử ADN trên là 2758.", "C": "Phân tử ADN có A = T = G = X = 690.", "D": "Mạch 2 có số lượng các loại nu A = 575; T = 115; G = 345; X = 345."}', 'A', 'Chọn đáp án BGiải thích:Ta có G1 = X1 = 3A1 → G=X= 6A1; A2 = 5A1 →A = T = 6A1 → A=T=G=XH= 2A + 3G = 3450 → 12A1 + 18A1 = 3450 =115 → N = 24A1 = 2760 nucleotit , A=T=G=X = 690 → C đúngTa có A2 = 5A1 = 575 ; T2 = A1 = 115; G2 =X2 = G1 = X1 = 3A1 = 345 → D đúngSố liên kết hóa trị là N (vì là ADN vòng) → B saiKhi gen nhân đôi 2 lần số nucleotit loại Xmt = Amt = A (22 – 1) = 2070 → A đúng', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(548, 'Ở một loài thú, xét 4 gen : gen I và gen II đều có 3 alen và nằm trên 2 cặp NST tương đồng khác nhau, gen III và gen IV đều có 4 alen và nằm trên vùng tương đồng của NST X. Theo lý thuyết, số kiểu gen tối đa có thể có về 4 gen đang xét trong nội bộ loài là bao nhiêu?', 'SINGLE_CHOICE', '{"A": "14112", "B": "9792", "C": "12486", "D": "10112."}', 'A', 'Chọn đáp án AGiải thích:- Gen I và gen II đều có 3 alen và nằm trên 2 cặp NST tương đồng khác nhau  số KG = 6x6 = 36- Gen III và gen IV đều có 4 alen và nằm trên vùng tương đồng của NST X:+ XX = 10x10+6x6 = 136+ XY = 136 + 10x6x2 = 256→&nbsp;Tổng số = (136+256)x36 = 14112&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(549, 'Quá trình hình thành loài mới có thể theo những cơ chế cách ly khác nhau. Trong số đó vai trò của cách ly địa lý trong một số trường hợp là rất quan trọng, khẳng định nào sau đây là đúng khi nói về vai trò của cách ly địa lý?', 'SINGLE_CHOICE', '{"A": "Điều kiện địa lý khác biệt là nguyên nhân quan trọng nhất gây ra những biến đổi trên cơ thể sinh vật.", "B": "Cách ly địa lý là nguyên nhân trực tiếp dẫn đến hiện tượng cách ly sinh sản do sự ngăn cản quá trình gặp gỡ giữa các cá thể.", "C": "Cách ly địa lý tạo điều kiện duy trì sự khác biệt về tần số alen và thành phần kiểu gen giữa các quần thể gây ra bởi các nhân tố tiến hóa tác động vào quần thể.", "D": "Ngay cả trong những điều kiện địa lý như nhau, giữa các cá thể trong cùng một quần thể cũng có thể thích nghi với điều kiện sinh thái khác nhau, từ đó dẫn đến quá trình hình thành loài mới."}', 'A', 'Chọn đáp án CGiải thích:Quá trình hình thành loài mới có thể theo những cơ chế cách ly khác nhau. Trong số đó vai trò của cách ly địa lý trong một số trường hợp là rất quan trọng, cách ly địa lý tạo điều kiện duy trì sự khác biệt về tần số alen và thành phần kiểu gen giữa các quần thể gây ra bởi các nhân tố tiến hóa tác động vào quần thể.&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(550, 'Ở chim, chiều dài lông và dạng lông do hai cặp alen (A, a, B, b) trội lặn hoàn toàn quy đ ịnh. Cho P thuần chủng có lông dài, xo ăn lai với lông ng ắn, thẳng, đời F1 thu được toàn lông dài, xo ăn. Cho chim trống F1 lai với chim mái chưa biết kiểu gen, chim mái ở đ ời F2 xu ất hiện kiểu hình: 20 chim lông dài, xo ăn: 20 chim lông ngắn, thẳng: 5 chim lông dài, thẳng: 5 chim lông ngắn, xo ăn. Tất cả chim trống của F2 đều có lông dài, xo ăn. Biết một gen quy đ ịnh một tí nh trạng và không có tổ hợp gen gây chết. Kiểu gen của chim mái lai với F1 và tần số hoán vị gen của chim trống F1 lần lư ợt là:', 'SINGLE_CHOICE', '{"A": "XABY, f = 20%", "B": "XabY, f = 25%", "C": "Aa XBY, f = 10%", "D": "XABXab, f = 5%"}', 'A', 'Chọn đáp án AGiải thích:Ta có: lông dài &gt;&gt; lông ngắn; xoăn &gt;&gt; thẳng.&nbsp;⇒ Ở F2 có tỉ lệ phân li kiểu hình ở hai giới là khác nhau nên gen nằm trên NST giới tính X.&nbsp;Ta có:&nbsp;&nbsp;Chim mái (XY) 20 chim lông ngắn thẳng : 5 lông dài thẳng : 5 lông ngắn : xoăn&nbsp;&nbsp;Chim trống (XX) lông xoăn dài ⇒ con trống nhận kiểu gen XAB từ mẹ&nbsp;&nbsp;⇒ Chim mái có kiểu gen XBAYXBAY⇒ Hoán vị gen ở con trống cho tỉ lệ giao tử với tỉ lệ:&nbsp;&nbsp;⇒ XAB = Xab = 20 : ( 20 × 2 + 5 × 2 ) = 0,4&nbsp;&nbsp;⇒ XAb = XaB = 0,5 – 0,4 = 0,1&nbsp;&nbsp;⇒ Hoán vị gen với tần số: 0,1 × 2 = 20%.&nbsp;&nbsp;', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(551, 'Một quần thể thực vật giao phấn, alen A qui định quả đỏ trội hoàn toàn so với alen a qui định quả vàng, alen B qui định quả tròn trội hoàn toàn so với alen b qui định quả dài. Hai cặp gen này phân li độc lập. Thống kê một quần thể (P) cân bằng di truyền thu được kết quả như sau: 32,76% cây quả đỏ, tròn; 3,24% cây quả đỏ, dài; 58,24% cây quả vàng, tròn; 5,76% cây quả vàng, dài. Nếu cho tất cả các cây quả đỏ, dài tự thụ phấn thì thu được ở F1 tỉ lệ cây quả vàng, dài là bao nhiêu?', 'SINGLE_CHOICE', '{"A": "16/81", "B": "8/9", "C": "4/9", "D": "8/81"}', 'A', 'Chọn đáp án AGiải thích:A: đỏ; a: vàng; B: tròn; b: dài (phân li độc lập)P: 32,76% cây quả đỏ, tròn; 3,24% cây quả đỏ, dài; 58,24% cây quả vàng, tròn; 5,76% cây quả vàng, dài.&nbsp;32,76% A-B-: 3.24% A-bb: 58,24% aaB-: 5,76% aabbQuần thể cân bằng di truyềnTần số alen: A = 0,2; a = 0,8; b = 0,3; B = 0,7Nếu cho tất cả các cây quả đỏ, dài tự thụ phấn thì thu được F1 có tỉ lệ cây quả vàng, dài.&nbsp;Ta có: AAbb = (0,22 x 0,32)/3,24% = 1/9; Aabb = 8/9 tự thụ phấn→ F1: vàng, dài = aabb = (4/9)2 = 16/81', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(552, '$29', 'SINGLE_CHOICE', '{"A": "3", "B": "1", "C": "2", "D": "4"}', 'A', '$2a', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(553, 'Ở một loài thực vật, alen A qui định hoa đỏ trội hoàn toàn so với alen a qui định hoa trắng; tính trạng chiều cao cây được qui định bởi hai gen, mỗi gen có hai alen (B, b và D, d) phân li độc lập. Cho cây hoa đỏ, thân cao (P) dị hợp tử về 3 cặp gen trên lai phân tích, thu được Fa có kiểu hình phân li theo tỉ lệ: 7% cây thân cao, hoa đỏ : 18% cây thân cao, hoa trắng : 32% cây thân thấp, hoa trắng : 43% cây thân thấp, hoa đỏ. Biết rằng không có đột biến xảy ra. Theo lý thuyết, trong các kết luận sau đây, có bao nhiêu kết luận đúng?I. Kiểu gen của (P) là AB/ab Dd.II. Ở Fa có 8 loại kiểu gen.III. Cho (P) tự thụ phấn, theo lí thuyết, ở đời con kiểu gen đồng hợp tử lặn về 3 cặp gen chiếm tỉ lệ 0,49%.IV. Cho (P) tự thụ phấn, theo lí thuyết, ở đời con có tối đa 21 loại kiểu gen và 4 loại kiểu hình.', 'SINGLE_CHOICE', '{"A": "4", "B": "1", "C": "3", "D": "2"}', 'A', '$2b', 18);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(554, 'Một loài thực vật tính trạng màu hoa do một cặp gen quy định. Cho lai giữa cây hoa đỏ với cây hoa trắng, F1 thu được 100% cây hoa đỏ, cho cây hoa đỏ ở đời F1 lai với cây hoa trắng (P) thu được Fa. Cho các cây Fa tạp giao với nhau, ở F2 thu được tỉ lệ kiểu hình 56,55% cây hoa trắng : 43,75% cây hoa đỏ. Tính xác suất để chọn được 4 cây hoa đỏ ở đời F2 mà khi cho các cây này tự thụ phấn thì tỉ lệ hạt mọc thành cây hoa trắng chiếm 12,5%', 'SINGLE_CHOICE', '{"A": "864/2401", "B": "216/2401", "C": "1296/2401", "D": "24/2401."}', 'A', '$2c', 18);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(19, 'Thi thử tốt nghiệp THPT quốc gia môn Sinh Học online - Đề thi của trường THPT Trần Bình Trọng năm 2023', 'Sinh Học', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Sinh Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(555, 'Đâu là ý đúng: Ở ong, những trứng được thụ tinh nở thành ong cái ( gồm ong thợ và ong chúa), những trứng không được thụ tinh nở thành ong đực.&nbsp;Gen A quy định thân xám, alen a quy định thân đen. Gen B quy định cánh dài, cây b quy định cánh ngắn, Hai gen nằm trên một NST thường với khoảng cách 2 gen là 40 cM. Người ta tiến hành cho ong chúa thân xám, cánh dài giao phối với ong đực thân đen, cánh ngắn, F1&nbsp;thu được 100% thân xám, cánh dài. Lấy một con ong chúa F1&nbsp;giao phối với ong đực thân xám, cánh ngắn, được F2,&nbsp;biết tỷ lệ thụ tinh là 80%, 100% trứng nở. Theo lý thuyết, tỷ lệ kiểu hình ở đời con F2&nbsp;này là:', 'SINGLE_CHOICE', '{"A": "50% thân xám, cánh dài: 25% thân đen, cánh dài: 25% thân xám, cánh ngắn.", "B": "46% thân xám, cánh dài: 4% thân đen, cánh dài: 44% thân xám, cánh ngắn : 6% thân đen, cánh ngắn.", "C": "30% thân xám, cánh dài: 20% thân đen, cánh dài: 20% thân xám, cánh ngắn : 30% thân đen, cánh ngắn.", "D": "46% thân xám, cánh dài: 44% thân đen, cánh dài: 4% thân xám, cánh ngắn : 6% thân đen, cánh ngắn."}', 'A', 'Đáp án BP:&nbsp;\({AB \over AB} x {ab \over O} \)&nbsp;→&nbsp;\({AB \over ab} : {AB \over O} \).&nbsp;Cho ong chúa F1 giao phối với ong đực thân xám, cánh ngắn,&nbsp;\({AB \over ab} x {Ab \over O} \)&nbsp;→ F3 (0,3AB : 0,3ab : 0,2aB : 0,2Ab)Ab&nbsp;Vì tỷ lệ thụ tinh là 80% → có 80% con cái Vậy tỷ lệ ở đời sau là&nbsp; - giới đực&nbsp;: 0,2 × (0,3AB&nbsp;:0,3ab&nbsp;:0,2Ab:0,2aB) → 0,06 xám dài&nbsp;: 0,06 đen, ngắn&nbsp;: 0,04 xám ngắn&nbsp;: 0,04 đen dài - giới cái&nbsp;: 0,8 × Ab(0,3AB&nbsp;:0,3ab&nbsp;:0,2Ab:0,2aB) → 0,4 xám dài&nbsp;: 0,4 xám ngắn&nbsp; Vậy tỷ lệ kiểu hình ở đời sau là 46% thân xám, cánh dài: 4% thân đen, cánh dài: 44% thân xám, cánh ngắn : 6% thân đen, cánh ngắn', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(556, 'Đâu là ý đúng: Khi cho lai 2 cơ thể bố mẹ thuần chủng khác nhau bởi 2 cặp tính trạng tương phản, F1&nbsp;đồng tính biểu hiện tính trạng của một bên bố hoặc mẹ, tiếp tục cho F1&nbsp;lai phân tích, nếu đời lai thu được tỉ lệ 1: 1 thì hai tính trạng đó đã di truyền', 'SINGLE_CHOICE', '{"A": "tương tác gen.", "B": "liên kết hoàn toàn", "C": "hoán vị gen", "D": "phân li độc lập."}', 'A', 'Đáp án BCơ thể dị hợp 2 cặp gen khi lai phân tích cho tỷ lệ 1:1 → các gen liên kết hoàn toàn.F1&nbsp;có kiểu hình giống 1 bên bố hoặc mẹ → F1&nbsp;dị hợp đều:&nbsp;P:\({AB \over AB} x {ab \over ab}\)&nbsp;→ F1:&nbsp;\({AB \over ab}\)', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(557, 'Đâu là ý đúng: Ở một loài thực vật, khi đem lai giữa hai cây thuần chủng thân cao, hạt đỏ&nbsp;đậm với thân thấp, hạt trắng. người ta thu được F1&nbsp;toàn thân cao, hạt đỏ nhạt. Tiếp tục cho F1&nbsp;giao phấn ngẫu nhiên với nhau, thu được F2&nbsp;phân li theo tỉ lệ 1 thân cao, hạt đỏ đậm : 4 thân cao,&nbsp;hạt đỏ vừa : 5 thân cao, hạt đỏ nhạt : 2 thân cao, hạt hồng : 1 thân thấp, hạt đỏ nhạt : 2 thân thấp,&nbsp;hạt hồng : 1 thân thấp, hạt trắng. Biết rằng mọi diễn biến trong quá trình phát sinh noãn, hạt&nbsp;phấn là như nhau và không có đột biến xảy ra. Kết luận nào sau đây không chính xác?&nbsp;', 'SINGLE_CHOICE', '{"A": "Tính trạng màu sắc hạt do các gen không alen tương tác theo kiểu cộng gộp quy định.", "B": "Trong quá trình giảm phân của cây F1 xảy ra hiện tượng liên kết gen hoàn toàn.", "C": "Cho cây có kiểu hình thân thấp, hạt hồng ở F2 giao phấn ngẫu nhiên với nhau,ở thế hệ tiếp theo thu được cây có kiểu hình thân thấp, hạt trắng chiếm tỉ lệ 25%.", "D": "Cây có kiểu hình thân cao, hạt đỏ vừa ở F2 có 3 kiểu gen khác nhau."}', 'A', '$27', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(558, 'Đâu là ý đúng: Ở một loài thực vật, gen A qui định thân cao, gen a qui định thân thấp; gen B qui định quả tròn, gen b qui định quả dài; các cặp gen này cùng nằm trên 1 cặp nhiễm sắc thể thường. Cho phép lai P:&nbsp;$ {Ab \over aB} x {Ab \over ab}$. Biết các gen liên kết hoàn toàn. Tính theo lí thuyết, tỉ lệ phân li kiểu hình thân cao, quả tròn ở F1&nbsp;sẽ là', 'SINGLE_CHOICE', '{"A": "100%.", "B": "75%", "C": "50%", "D": "25%."}', 'A', 'Đáp án DTỉ lệ KG Ab/aB là 25% → Tỉ lệ KH cao, tròn =25%', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(559, 'Đâu là ý đúng:&nbsp;Ở một loài, hai gen B và D cách nhau 20 cM, quá trình giảm phân của một tế bào sinh tinh có kiểu gen Aa Bd/bDcó thể tạo ra loại giao tử ABd&nbsp;với tỉ lệ là?', 'SINGLE_CHOICE', '{"A": "30%", "B": "20%", "C": "10%", "D": "25%"}', 'A', 'Đáp án DAa&nbsp;&nbsp;→&nbsp;&nbsp;giao tử A= 0,51 tế bào&nbsp;Bd/bD→&nbsp;&nbsp;2 loại giao tử&nbsp;Bd&nbsp;=&nbsp;bD&nbsp;= 0,5&nbsp;→&nbsp;&nbsp;giao tử ABd&nbsp;có tỉ lệ: 0,5×0,5 = 0,25 = 25%', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(560, 'Phép lai&nbsp;P =&nbsp;$ {Ab \over aB} x {ab \over ab}$, thu đươc F1. Cho biết mỗi gen quy đinh môt tính trạng, các alen trội là trội hoàn toàn, không xảy ra đột biến nhưng xảy ra hoán vị gen với tần số 40%. Theo lí thuyết, F1&nbsp;có số cá thế mang kiểu hình trội về cả hai tính trạng chiếm tỉ lệ', 'SINGLE_CHOICE', '{"A": "10%", "B": "20%", "C": "40%", "D": "30%"}', 'A', 'Đáp án BP:&nbsp;\( {Ab \over aB} x {ab \over ab}\)Gp:&nbsp;Ab&nbsp;=&nbsp;aB&nbsp;= 30%&nbsp; &nbsp; &nbsp;&nbsp;AB&nbsp;=&nbsp;ab&nbsp;= 20%F1&nbsp;có số cá thể mang kiểu hình trội về cả hai tính trạng chiếm tỉ lệ là&nbsp;&nbsp;\( {AB \over ab}\)&nbsp;= 20%', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(561, 'Đâu là ý đúng:&nbsp;Ở đậu Hà Lan, thân cao (T) là trội hoàn toàn so với thân lùn (t). cái gì kiểu gen của bố mẹ về thế hệ cây có một nửa thân cao và một nửa trong số đó là cây lùn?&nbsp;', 'SINGLE_CHOICE', '{"A": "Tt×tt", "B": "Tt×Tt", "C": "TT × tt", "D": "XTXt × XTXt"}', 'A', 'Đáp án AGiải quyết vấn đề này bằng cách thực hiện ngược lại hình vuông Punnett. Đầu tiên, thiết lập các ô vuông và điền bất cứ điều gì bạn có thể về thế hệ con đã cho được mô tả trong câu hỏi. Sau đó chia ra các kiểu gen của bố mẹ ở bên ngoài Punnett quảng trường. Tính trạng không liên kết với giới tính nên không dùng kí hiệu X, Y', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(562, 'Xác định: Trường hợp nào sau đây là phép thử chéo?', 'SINGLE_CHOICE', '{"A": "Hh X Hh", "B": "Hh X HH", "C": "HH X HH", "D": "Hh X hh"}', 'A', 'Đáp án DTrong khi phép lai chéo giữa con cái với bất kỳ cặp bố mẹ nào, phép lai kiểm tra được thực hiện bằng cách lai con cái F1 với bố mẹ mang gen lặn kép.&nbsp;Những người khác là ví dụ về chéo ngược ngoại trừ tùy chọn a.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(563, 'Chọn ý đúng: Nếu cho cây đậu cao giống thật lai với cây đậu thân cao giống thật thì kiểu hình ở thế hệ F1 sẽ như thế nào?', 'SINGLE_CHOICE', '{"A": "Tất cả thấp", "B": "Tất cả cao", "C": "3 thấp : 1 cao", "D": "1 thấp : 3 cao"}', 'A', 'Đáp án BTrong trường hợp này cao là tính trạng trội.&nbsp;Khi đó tất cả các thế hệ con lai F1 sẽ là dị hợp tử trong đó kiểu hình trội được biểu hiện cao.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(564, 'Đâu là ý đúng: Số alen tối đa mà phép lai đơn tính có thể coi là bao nhiêu?', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "5", "D": "8"}', 'A', 'Đáp án BNếu một gen là dị hợp tử thì nó sẽ có hai alen khác nhau cho cùng một gen, do đó trong trường hợp phép lai đơn tính chỉ xét một gen có tối đa hai alen.&nbsp;Đối với chéo dihybrid, số sẽ là 4.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(565, 'Xác định:&nbsp;Điều nào không phải là nguyên nhân khiến Mendel không nổi tiếng ngay lập tức?', 'SINGLE_CHOICE', '{"A": "Thuyết chọn lọc tự nhiên của Darwin", "B": "Mô hình thí nghiệm của ông ấy rất hiếm", "C": "Ý tưởng sử dụng số liệu thống kê vượt xa thời đại của ông ấy", "D": "Bài báo của ông ấy được xuất bản trên tạp chí ít được biết đến hơn"}', 'A', 'Đáp án BVườn đậu là một mô hình tuyệt vời không chỉ sẵn có mà còn dễ trồng và thực hiện thí nghiệm.&nbsp;Tuy nhiên, những lý do khác như đã đề cập góp phần nghiêm trọng khiến Mendel không trở thành một thành công ngay lập tức.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(566, 'Cho biết:&nbsp;Người ta khẳng định rằng kiểu hình của chiều cao cây đậu ngắn sẽ chỉ được biểu hiện khi nào?', 'SINGLE_CHOICE', '{"A": "Cả bố và mẹ đều cao", "B": "Bố mẹ cao và cây khác thấp", "C": "Hạt được tạo ra bằng cách bán", "D": "Cả bố và mẹ đều thấp"}', 'A', 'Đáp án DCác tính trạng lặn thuần túy như chiều cao cây ngắn cũng có thể được tạo ra từ phép lai dị hợp tử, nhưng chúng ta chỉ có thể khẳng định điều này khi chúng ta lai tạo thực sự với cây bố mẹ mang tính trạng lặn.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(567, 'Cho biết mỗi cặp gen quy định một cặp tính trạng và gen trội là trội hoàn toàn; cơ thể tứ bội giảm phân chỉ sinh ra giao tử lưỡng bội có khả năng thụ tinh. Xét các phép lai sau:(1) AAaaBbbb x&nbsp;&nbsp;aaaaBBbb.(2) AAaaBBbb x AaaaBbbb.(3) AaaaBBBb x&nbsp;&nbsp;AAaaBbbb.(4) AaaaBBbb x&nbsp;&nbsp;AaBb.(5) AaaaBBbb x aaaaBbbb.&nbsp;(6) AaaaBBbb x aabb.Theo lí thuyết, trong 6 phép lai nói trên có bao nhiêu phép lai mà đời con có 12 kiểu gen, 4 kiểu hình?', 'SINGLE_CHOICE', '{"A": "1 phép lai", "B": "2 phép lai", "C": "3 phép lai", "D": "4 phép lai"}', 'A', 'Đáp án BCác phép lai cho đời con có 12 kiểu gen, 4 kiểu hình là&nbsp;:&nbsp; (1) và (4)&nbsp;Xét phép lai thứ nhất có :AAaaBbbb x &nbsp;aaaaBBbb =&nbsp; &nbsp;(AAaa x &nbsp;aaaa)(Bbbb x BBbb )-&nbsp; (AAaa x &nbsp;aaaa) ⇒ AAaa : Aaaa : aaaa&nbsp;⇒ 3 kiểu gen ; 2 kiểu hình-&nbsp; &nbsp;(Bbbb x BBbb ) ⇒ BBBb : BBbb : Bbbb : bbbb ⇒ 4 kiểu gen ; 2 kiểu hình⇒ &nbsp;Số kiểu gen được tạo ra từ phép lai trên là : 3 x 4 = 12 &nbsp;kiểu gen ; 2 x 2 = 4 kiểu hìnhXét phép lai : AaaaBBbb x &nbsp;AaBbAaaaBBbb x &nbsp;AaBb = (Aaaa x &nbsp;Aa) ( BBbb x Bb)-&nbsp; &nbsp;Aaaa x &nbsp;Aa ⇒ AAa : Aaa : aaa =&gt; 3 kiểu gen ; 2 kiểu hình-&nbsp; BBbb x Bb ⇒ BBB : BBb : Bbb : bbb ⇒ 4 kiểu gen ; 2 kiểu hình⇒&nbsp;Số kiểu gen được tạo ra từ phép lai trên là : 3 x 4 = 12&nbsp; kiểu gen ; 2 x 2 = 4 kiểu hình( Với các trường hợp khác giải tương tự và cho&nbsp; số kiểu gen và kiểu hình không thỏa mãn )⇒ Chỉ có phép lai 1 và 4 thỏa mãn', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(568, 'Xác định: Để đảm bảo rằng có cây giống thuần chủng cho các thí nghiệm, Mendel đã?', 'SINGLE_CHOICE', '{"A": "Bón phân chéo từng loại với nhau", "B": "Để mỗi giống tự thụ tinh qua nhiều thế hệ", "C": "Loại bỏ các bộ phận cái của cây", "D": "Loại bỏ các bộ phận đực của cây."}', 'A', 'Đáp án BMendel đảm bảo rằng ông đã sử dụng các cây nhân giống thuần chủng cho các thí nghiệm của mình bằng cách để mỗi giống tự thụ phấn trong vài thế hệ', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(569, 'Đâu là ý đúng: Phép lai giữa cây cao TT và cây ngắn tt đã tạo ra đời con đều là cây cao vì?', 'SINGLE_CHOICE', '{"A": "Cao là đặc điểm nổi trội", "B": "Ngắn là đặc điểm nổi trội", "C": "Cao là tính trạng lặn", "D": "Chiều cao của cây đậu không bị chi phối bởi gen ''T'' hoặc ''t''"}', 'A', 'Đáp án AỞ thế hệ F1, phép lai giữa “TT” và “tt” sẽ tạo thành tất cả các cây thân cao.&nbsp;Như vậy, chiều cao là đặc điểm hay tính cách nổi trội.&nbsp;Mỗi khi lai hai tính trạng của một tính trạng, các cây F1 chỉ biểu hiện một trong các tính trạng đó.&nbsp;Tính trạng này được gọi là tính trạng trội.&nbsp;Tính trạng còn lại (trong trường hợp này là lùn) không biểu hiện ở thế hệ F1 được gọi là tính trạng lặn.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(570, 'Đâu là ý đúng: Khi bạn xác định các tổ hợp alen cho RrAa (sử dụng FOIL), bốn tổ hợp có thể có mà bạn sẽ sử dụng cho phép lai dihybrid của mình là gì?', 'SINGLE_CHOICE', '{"A": "RA, Ra, rA, ra", "B": "RA, Rr, rA, ra", "C": "RR, Aa, ar, ra", "D": "AA, Ra, RA, rr"}', 'A', 'Đáp án APhép lai&nbsp;dihybrid là&nbsp;một thí nghiệm lai tạo giữa các sinh vật thuộc thế hệ P (thế hệ bố mẹ) khác nhau về hai tính trạng. Các cá thể trong phép lai này&nbsp;là&nbsp;đồng hợp tử về một tính trạng cụ thể hoặc chúng có chung một tính trạng. Tính trạng&nbsp;là&nbsp;những đặc điểm được xác định bởi các đoạn DNA được gọi&nbsp;là&nbsp;genF1: RrAa =&gt; Các giao tử kết hợp có thể là RA x ra; Ra x rA&nbsp;', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(571, 'Đâu là ý đúng:&nbsp;Ở người, màu mắt do 1 gen nằm trên NST thường qui định. Bố mắt nâu, mẹ mắt nâu, sinh con có đứa mắt nâu, có đứa mắt xanh, kiểu gen của bố mẹ là?', 'SINGLE_CHOICE', '{"A": "Đều dị hợp.", "B": "Đều đồng hợp trội.", "C": "Bố đồng hợp, mẹ dị hợp.", "D": "Bố dị hợp, mẹ đồng hợp."}', 'A', 'Đáp án ADo bố mắt nâu, mẹ mắt nâu, sinh con có đứa mắt nâu, có đứa mắt xanh, tức là gen qui định hình mắt xanh là gen lăn, ở đời bố mẹ không biểu hiện mà đến đười con thì biểu hiện ở trạng thái đồng hợpVậy bố, me đều dị hợp', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(572, 'Đâu là ý đúng:&nbsp;Với 2 alen A và a nằm trên nhiễm sắc thể thường. Nếu không phân biệt giới tính, trong quần thể sẽ có bao nhiêu kiểu giao phối khác nhau giữa các cá thể mang các kiểu gen của 2 alen nói trên ?', 'SINGLE_CHOICE', '{"A": "2 kiểu.", "B": "6 kiểu.", "C": "3 kiểu.", "D": "4 kiểu"}', 'A', 'Đáp án BSố KG tạo từ 2 alen là 3Số kiểu giao phối khác nhau trong quần thể là 3 x 3 – 3 = 6 kiểu', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(573, 'Đâu là ý đúng:&nbsp;Ở người nhóm máu ABO do 3 gen alen IA, IB, IO&nbsp;quy định, nhóm máu A được quy định bởi các kiểu gen IAIA, IAIO, nhóm máu B được quy định bởi các kiểu gen IBIB, IBIO, nhóm máu O được quy định bởi kiểu gen IOIO&nbsp;, nhóm máu AB được quy định bơi kiểu gen IAIB&nbsp;Người con có nhóm máu A, bố mẹ người này sẽ có:', 'SINGLE_CHOICE', '{"A": "Bố nhóm máu A, mẹ nhóm máu B", "B": "Bố nhóm máu AB, mẹ nhóm máu O", "C": "Bố nhóm máu O, mẹ nhóm máu AB", "D": "Tất cả đều đúng"}', 'A', 'Người con nhóm máu A, có thể là IAIA&nbsp;hoặc IAIOPhương án A có thể xảy ra. Bố nhóm máu A : IAIA&nbsp;hoặc IAIO&nbsp;,cho giao tử IAmẹ nhóm máu B IBIO&nbsp;cho giao tử IO&nbsp;thì con IAIO&nbsp;là nhóm máu OPhương án B có thể xảy ra: IAIB&nbsp;x IOIO&nbsp;cho con là IAIO&nbsp;có nhóm máu APhương án C tương tự phương án B, đều có thể xảy raVậy đáp án D', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(574, 'Đâu là ý đúng: Khái niệm về gen đã được MenĐen tìm ra khi thực hiện lai tạo trên đậu Hà Lan?', 'SINGLE_CHOICE', '{"A": "Là 1 đoạn ADN có chức năng di truyền.", "B": "Là nhân tố di truyền qui định tính trạng.", "C": "Là 1 đoạn NST mang thông tin di truyền.", "D": "Là các phân tử ADN nằm trong nhân tế bào."}', 'A', 'Đáp án BNhân tố di truyền qui định tính trạng là&nbsp;khái niệm về gen đã được MenĐen tìm ra khi thực hiện lai tạo trên đậu Hà Lan.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(575, 'Chọn ý đúng:&nbsp;Menden đã kiểm tra giả thuyết "mỗi tính trạng do một cặp nhân tố di truyền quy định, các nhân tố di truyền trong tế bào không hòa trộn vào nhau và phân li đồng đều về các giao tử" bằng cách cho?', 'SINGLE_CHOICE', '{"A": "F1 tự thụ phấn", "B": "F1 lai phân tích", "C": "F2 tự tụ phấn", "D": "F1 giao phấn với nhau"}', 'A', 'Đáp án BMenden đã kiểm tra giả thuyết "mỗi tính trạng do một cặp nhân tố di truyền quy định, các nhân tố di truyền trong tế bào không hòa trộn vào nhau và phân li đồng đều về các giao tử" bằng cách cho&nbsp;F1&nbsp;lai phân tích', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(576, 'Chọn ý đúng: Trong trường hợp gen trội là trội hoàn toàn, theo lí thuyết, tỉ lệ phân li kiểu hình 1: 1 ở F1 sẽ xuất hiện trong kết quả của phép lai nào sau đây?', 'SINGLE_CHOICE', '{"A": "AA x AA", "B": "AA x Aa", "C": "Aa x aa", "D": "aa x aa"}', 'A', 'Đáp án CAa x aa cho kiểu hình 1 trội : 1 lặn', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(577, 'Đâu là ý đúng: Ở một loài đậu, tính trạng hoa đỏ do gen A quy định là trội hoàn toàn so với tính trạng hoa trắng do gen a quy định. Cho đậu hoa đỏ giao phấn với đậu hoa trắng, F1 thu được 201 hạt đỏ : 199 hạt trắng. Kiểu gen của P là?', 'SINGLE_CHOICE', '{"A": "Aa × Aa", "B": "Aa × aa", "C": "AA × aa", "D": "AA × Aa"}', 'A', 'Đáp án BXét 1 loài đậu. Gen A -hoa đỏ, trội hoàn toàn so với a-hoa trắng. Đậu hoa đỏ giao phấn với hoa trắng thu được đời con có tỷ lệ: 1 đỏ: 1 trắng → Kiểu gen của P là Aa × aa.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(578, 'Đâu là ý đúng: Theo lí thuyết, phép lai cho đời con 100% kiểu gen dị hợp?', 'SINGLE_CHOICE', '{"A": "Aa × aa.", "B": "Aa × AA.", "C": "AA × aa.", "D": "Aa × Aa."}', 'A', 'Đáp án CAA × aa cho đời con 100% Aa', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(579, 'Đâu là ý đúng: Đậu Hà lan là loài thực vật sinh sản bằng tự thụ phấn được Menđen sử dụng trong nghiên cứu di truyền. Ở loài đậu này, tính trạng màu hạt do một cặp gen quy định, trong đó A quy định hạt vàng trội hoàn toàn so với a quy định hạt xanh. Lấy hạt phấn của cây hạt vàng thuần chủng thụ phấn cho cây hạt xanh được F1, sau đó F1 sinh sản ra F2, F2 sinh sản ra F3, F3 sinh sản ra F4. Theo lí thuyết, ở các cây F3, loại cây vừa có hạt màu vàng vừa có hạt màu xanh chiếm tỉ lệ', 'SINGLE_CHOICE', '{"A": "100%.", "B": "12,5%.", "C": "25%.", "D": "0%."}', 'A', 'Đáp án C- Loại cây vừa có hạt màu vàng vừa có hạt màu xanh là cây có kiểu gen dị hợp Aa.- P: AA × aaF1: Aa- Từ F1&nbsp;đến F3&nbsp;đã trải qua 2 thế hệ tự thụ phấn do đó tỉ lệ cây vừa có hạt màu xanh vừa có hạt màu vàng ở F3&nbsp;là (1/2)2&nbsp;× 100% = 25%.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(580, 'Cho biết ý nào đúng:&nbsp;Tính trạng chiều cao thân do một cặp gen quy định. Cho các cây thân cao có kiểu gen khác nhau tự thụ phấn, thu được F1 có 93,75% cây cao, 6,25% cây thấp. Lấy 2 cây thân cao F1, xác suất để được 2 cây thuần chủng là?', 'SINGLE_CHOICE', '{"A": "1/9", "B": "9/16", "C": "169/225", "D": "9/25"}', 'A', 'Đáp án DCác cây thân cao&nbsp;: A-P : (AA,&nbsp; Aa) x (AA,&nbsp; Aa)F1&nbsp;: thấp aa = 6,25% = 1/16Cây thấp aa chỉ có thể được tạo ra từ phép lai : Aa x AaCó aa = 1/16=&gt; &nbsp;Mỗi bên P cho giao tử a = 1/4=&gt; &nbsp;Vậy tỉ lệ Aa trong các cây thân cao A- là&nbsp;:&nbsp; 1/4 x 2&nbsp; =&nbsp;Vậy P&nbsp;: ( 1/2 AA&nbsp;: 1/2 Aa )F1&nbsp;: 9/16AA&nbsp;: 6/16Aa&nbsp;: 1/16 aaLấy 2 cây thân cao F2, xác suất để 2 cây thuần chủng là&nbsp;: 9/15&nbsp; x 9/15 = 9/25', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(581, 'Chọn ý đúng: Trong một lần thúc đẻ cho cá trắm cỏ có khối lượng trung bình, người ta thu được 8000 hợp tử, về sau nở thành 8000 cá con. Biết rằng hiệu suất thụ tinh của trứng là 50%, của tinh trùng là 25%.Số tế bào sinh tinh trùng và sinh trứng cần thiết để hoàn tất quá trình thụ tinh là:', 'SINGLE_CHOICE', '{"A": "24000; 16000", "B": "8000; 24000", "C": "16000; 8000", "D": "8000; 16000"}', 'A', 'Đáp án D- Số trứng đã thụ tinh = số tinh trùng đã thụ tinh = số hợp tử tạo thành = 8000.Hiệu suất thụ tinh của trứng là 50% nên số trứng cần thiết =&nbsp;&nbsp;\( {8000 x 100 \over 50}\)&nbsp;= 16000 trứng.1 tế bào sinh trứng chỉ tạo ra 1 trứng nên số tế bào sinh trứng cần thiết = số trứng cần thiết = 16000 tế bào.- Hiệu suất thụ tinh của tinh trùng là 25% nên số tinh trùng cần thiết =&nbsp;\( {8000 x 100 \over 25}\)&nbsp;= 32000 tinh trùng.Vì mỗi tế bào sinh tinh sinh ra 4 tinh trùng nên số tế bào sinh tinh trùng cần thiết =&nbsp;\( {32000 \over 4}\)&nbsp;= 8000 tế bào.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(582, 'Chọn ý đúng: Có 120 tế bào sinh trứng tham gia giảm phân. Biết không có đột biến xảy ra, hiệu suất thụ tinh của trứng là 50%. Số hợp tử được tạo thành là?', 'SINGLE_CHOICE', '{"A": "480", "B": "120", "C": "240", "D": "60"}', 'A', 'Đáp án D120 tế bào sinh trứng → 120 trứngHiệu suất thụ tinh là 50% → số hợp tử là 120 × 0,5 = 60 hợp tử', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(583, 'Cho biết: Sự thụ tinh giữa 2 giao tử (n+1) sẽ tạo nên?', 'SINGLE_CHOICE', '{"A": "thể tam bội", "B": "Thể ba nhiễm, thể bốn nhiễm", "C": "thể tứ bội hoặc thể song nhị bội.", "D": "Thể ba nhiễm kép hoặc thể bốn nhiễm."}', 'A', 'Đáp án DSự thụ tinh giữa 2 giao tử (n+1) sẽ tạo nên thể ba nhiễm kép hoặc thể bốn nhiễm.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(584, 'Chọn ý đúng nhất: Khi các cá thể của một quần thể giao phối (quần thể lưỡng bội) tiến hành giảm phân hình thành giao tử đực và cái, ở một số tế bào sinh giao tử, một cặp nhiễm sắc thể thường không phân li trong giảm phân I, giảm phân II diễn ra bình thường. Sự giao phối tự do giữa các cá thể có thể tạo ra các kiểu tổ hợp về nhiễm sắc thể là:&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;', 'SINGLE_CHOICE', '{"A": "2n+1; 2n-1-1-1; 2n.", "B": "2n; 2n-1; 2n+1; 2n-2; 2n+2.", "C": "2n+1; 2n-2-2; 2n; 2n+2.", "D": "2n-2; 2n; 2n+2+1."}', 'A', 'Đáp án BTrong quá trình phát sinh giao tử, một cặp nhiễm sắc thể thường không phân li trong giảm phân I, giảm phân II diễn ra bình thường tạo ra các loại giao tử n + 1 và n – 1.Quá trình giảm phân nếu xảy ra bình thường tạo ra giao tử n.Vậy các kiểu tổ hợp về NST có thể tạo ra là: 2n (n + n), 2n + 1 (n + n+1), 2n – 1 (n + n-1), 2n – 2 (n-1 + n-1), 2n + 2 (n+1 + n+1).', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(585, 'Chọn ý đúng: Một tế bào sinh dục sơ khai của ruồi giấm (2n = 8) tiến hành nguyên phân liên tiếp một số lần tạo ra số tế bào mới ở thế hệ cuối cùng có 512 NST ở trạng thái chưa nhân đôi. Các tế bào mới được tạo thành nói trên đều trở thành tế bào sinh trứng. Khi tế bào sinh trứng giảm phân thì lấy nguyên liệu từ môi trường nội bào tạo ra bao nhiêu NST đơn?', 'SINGLE_CHOICE', '{"A": "500", "B": "512", "C": "572", "D": "600"}', 'A', 'Đáp án BỞ ruồi giấm bộ NST lưỡng bội 2n= 8Gọi k là số lần phân bào ( k nguyên dương,&nbsp; k &gt; 0). Theo giả thiết, ta có:&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;2k.&nbsp;2n = 512 ↔ 2k. 8&nbsp;&nbsp; =512→ k = 6. Vậy tế bào sinh dục sơ khai nói trên tiến hành 6 đợt phân bào.Mỗi&nbsp; tế bào sinh trứng có 2n = 8 NST đơn, trước khi giảm phân tạo trứng thì đều nhân đôi NST đơn thành NST kép tức là tạo thêm 8 NST đơn từ nguyên liệu của môi trường nội bào.Tổng số tế bào sinh trứng được tạo ra sau 6 đợt phân bào là 26= 64 tế bàoVậy các tế bào sinh trứng đã lấy nguyên liệu từ môi trường nội bào để tạo ra số NST đơn là&nbsp; 8.64 = 512 NST đơn.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(586, 'Chọn ý đúng:&nbsp;Một cá thể ở một loài động vật có bộ nhiễm sắc thể 2n = 12. Khi quan sát quá trình giảm phân của 2000 tế bào sinh tinh, người ta thấy 20 tế bào có cặp nhiễm sắc thể số 1 không phân li trong giảm phân I, các sự kiện khác trong giảm phân diễn ra bình thường; các tế bào còn lại giảm phân bình thường. Theo lí thuyết, trong tổng số giao tử được tạo thành từ quá trình trên thì số giao tử có 5 nhiễm sắc thể chiếm tỉ lệ:', 'SINGLE_CHOICE', '{"A": "1%", "B": "0,5%", "C": "0,25%", "D": "2%"}', 'A', 'Đáp án BGiao tử có 5 NST tức chỉ chứa n -1 NST này được tạo ra từ qua trình giảm phân không bình thường của 20 tế bào, mỗi tế bào cho ra 2 giao tử n - 1 và &nbsp;2 giao tử n + 1Do đó có 40 giao tử n - 1Tổng số giao tử tạo ra là: 2000 x 4 = 8000Vậy tỷ lệ giao tử &nbsp;n-1 là: 40/8000 = 0,5%', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(587, 'Xác định ý đúng: Hợp tử được hình thành trong trường hợp nào sau đây có thể phát triển thành thể ba?', 'SINGLE_CHOICE', '{"A": "Giao tử n kết hợp với giao tử n + 1.", "B": "Giao tử n kết hợp với giao tử n - 1.", "C": "Giao tử 2n kết hợp với giao tử 2n.", "D": "Giao tử n kết họp với giao tử 2n."}', 'A', 'Đáp án AGiao tử n kết hợp với giao tử n + 1 tạo hợp tử 2n + 1.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(588, 'Đâu là ý đúng:&nbsp;Một tế bào sinh dục đực sơ khai của 1 loài nguyên phân 5 đợt liên tiếp. 1/4 số tế bào con được tạo ra tiến hành giảm phân tạo giao tử. Tổng số NST đơn môi trường cung cấp cho quá trình hình thành giao tử là 96. Giả sử hiệu suất thụ tinh của tinh trùng là 50%, của trứng là 25%. Bộ nhiễm sắc thể 2n của loài và số tế bào trứng tạo thành là:', 'SINGLE_CHOICE', '{"A": "6 và 64", "B": "12 và 64", "C": "12 và 32", "D": "6 và 32"}', 'A', 'Đáp án BSố TB sinh dục được tạo ra = 25&nbsp;= 32Số TB tham gia GP = 8Ta có: 8.2n = 96→&nbsp;2n = 12Số tinh trùng tạo ra = 8.4 = 32Hiệu suất 50%&nbsp;à&nbsp;số tinh trùng được thụ tinh = 16 = số trứng thụ tinhHiệu suất thụ tinh của trứng = 25%&nbsp;à&nbsp;số trứng tạo ra thỏa mãn = 64 trứng.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(589, 'Chọn ý đúng: Một tế bào sinh dục sơ khai của gà (2n = 78 NST), sau một số đợt nguyên phân liên tiếp được môi trường cung cấp nguyên liệu tương đương với 19890 NST. Các tế bào con sinh ra đều trở thành tế bào sinh trứng và giảm phân cho trứng. Hiệu suất thụ tinh của trứng là 25%. Số lượng hợp tử hình thành là:', 'SINGLE_CHOICE', '{"A": "128 hợp tử.", "B": "64 hợp tử.", "C": "16 hợp tử.", "D": "32 hợp tử."}', 'A', 'Đáp án B2n(2k&nbsp;-1) = 19890 → k =8 → Tổng số giao tử tạo ra là 28&nbsp;= 256.Các tế bào sinh trứng đều giảm phân tạo thành trứng → tạo thành 256 trứng.Hiệu suất thụ tinh là 25% → có 0,25 × 256 = 64 trứng dc thụ tinh → số hợp tử là&nbsp; 64 hợp tử.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(590, 'Đâu là ý đúng:&nbsp;Xét 5 tế bào sinh dục sơ khai tại vùng sinh sản đều nguyên phân liên tiếp số đợt bằng nhau, môi trường cung cấp nguyên liệu tương đương 1200 NST đơn. 25% số tế bào con sinh ra tham gia quá trình giảm phân. Quá trình thụ tinh của số giao tử này có hiệu suất 12,5% đã hình thành 10 hợp tử. Số lền nguyên phân của mỗi tế bào sinh dục sơ khai và giới tính của cá thể là đực hay cái?', 'SINGLE_CHOICE', '{"A": "6 đợt, giới tính đực.", "B": "4 đợt, giới tính cái.", "C": "4 đợt, giới tính đực.", "D": "6 đợt, giới tính cái."}', 'A', 'Đáp án CGọi số lần nguyên phân của mỗi tế bào bằng k, bộ nST lưỡng bội của loài bằng 2n.Số NST môi trường cung cấp = 5 x 2n x (2k&nbsp;– 1) = 1200.Số tế bào con tham gia vào giảm phân là: 5 x 2k&nbsp;x 25%Số loại giao tử theo đề bài = 10 : 12,5% = 80.- Nếu đây là cơ thể đực, số giao tử tạo ra: 4 x 5 x 2k&nbsp;x 25% = 80 → k = 4, 2n = 16.- Nếu đây là cơ thể cái, số giao tử tạo ra: 5 x 2k&nbsp;x 25% = 80 → k = 6, 2n lẻ →&nbsp; loại.Vậy đây là tế bào đực, số lần nguyên phân bằng 4, 2n = 16.', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(591, 'Chọn ý đúng:&nbsp;Xét 7 tế bào sinh dục đực sơ khai nguyên phân liên tiếp 7 đợt, 50% số tế bào con trải qua giảm phân. Hiệu suất thụ tinh của tinh trùng là 3,125%. Số hợp tử được hình thành bằng bao nhiêu?', 'SINGLE_CHOICE', '{"A": "28 hợp tử.", "B": "56 hợp tử.", "C": "42 hợp tử.", "D": "7 hợp tử."}', 'A', 'Đáp án BSau nguyên phân, số tế bào con sinh ra là 7x 27&nbsp;= 896Số tế bào tham gia giảm phân 896 x 0,5 = 448Số tinh trùng sinh ra là 448 x 4 = 1792Số hợp tử hình thành 1792 x 0,03125 = 56', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(592, 'Cho biết:&nbsp;20 tế bào sinh dục sơ khai đực đều nguyên phân 7 đợt, 25% số tế bào con trở thành tế bào sinh tinh. Quá trình thụ tinh hình thành 40 hợp tử. Hiệu suất thụ tinh của tinh trùng là:', 'SINGLE_CHOICE', '{"A": "1,5625%.", "B": "3,125%.", "C": "6,25%.", "D": "12,5%."}', 'A', 'Đáp án ASố tế bào con sinh ra sau nguyên phân là 20 x 27&nbsp;= 2560Số tế bào con trở thành tế bào sinh tinh là 2560 x 0,25 = 640Số tinh trùng sinh ra là 640 x 4 = 2560Hiệu suất thụ tinh là 40: 2560 = 1,5625%', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(593, 'Cho biết: Xét các loại đột biến, những dạng đột biến nào làm thay đổi độ dài phân tử ADN trên nhiễm sắc&nbsp;thể?(1). Mất đoạn nhiễm sắc thể. (2). Lặp đoạn nhiễm sắc thể. (3). Chuyển đoạn không tương hỗ.(4). Đảo đoạn nhiễm sắc thể. (5). Đột biến thể một. (6). Đột biến thể ba', 'SINGLE_CHOICE', '{"A": "(1), (2), (5), (6).", "B": "(1), (2), (3), (6).", "C": "(1), (2), (3).", "D": "(2), (3), (4), (5)."}', 'A', 'Đáp án CCác đột biến 5 và 6 làm thay đổi số lượng nstĐột biến đảo đoạn coi như ko làm thay đổi chiều dài phân tử DNA', 19);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(594, 'Xác định:&nbsp;Ở cà độc dược, bộ nhiễm sắc thể 2n = 24. Một tế bào sinh dưỡng nguyên phân không bình thường khi có một nhiễm sắc thể kép không phân li, kết thúc quá trình nguyên phân này sẽ tạo ra:', 'SINGLE_CHOICE', '{"A": "2 tế bào con, trong đó có 1 tế bào lưỡng bội và 1 tế bào thể 1", "B": "2 tế bào con, trong đó có 1 tế bào thể 3 và 1 tế bào lưỡng bội", "C": "2 tế bào con đều bị đột biến thừa 1 nhiễm sắc thể", "D": "2 tế bào con, trong đó có 1 tế bào thể 3 và 1 tế bào thể 1"}', 'A', 'Đáp án DKhi nguyên phân thì ở kì sau nếu 1 chiếc NST kép không phân li thì sẽ dẫn đếm hình thành hai tế bào con có bộ NST 2n +1 và 2n - 1', 19);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(20, 'Đề thi thử học kỳ 2 môn Sinh Học lớp 10 online - Mã đề 03', 'Sinh Học', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Sinh Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(595, 'Chọn ý đúng:Hệ gen của virut được nhận xét là gì?', 'SINGLE_CHOICE', '{"A": "ADN", "B": "ARN", "C": "Lipit", "D": "ADN hoặc ARN"}', 'A', 'Hệ gen của virut có thể là ADN (ví dụ như virut đậu mùa, viêm gan B,…) hoặc ARN (ví dụ virut cúm, virut sốt xuất huyết Dengi,…)Đáp án cần chọn là: D', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(596, 'Xác định ý đúng: Virion là từ dùng để chỉ loại virut nào?', 'SINGLE_CHOICE', '{"A": "Virut có vỏ capsit", "B": "Virut sống tự do", "C": "Virut ở ngoài tế bào vật chủ", "D": "Virut sống kí sinh bắt buộc trong tế bào chủ."}', 'A', 'Virut ở ngoài tế bào chủ được gọi là hạt virut hay virion.Đáp án cần chọn là: C', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(597, 'Chọn ý đúng: Vì sao để nhân lên, virut được nhận xét bắt buộc phải kí sinh nội bào?', 'SINGLE_CHOICE', '{"A": "Vì lõi axit nucleic của virut ngắn, không có khả năng tự sao chép.", "B": "Vì virut có cấu tạo đơn giản, chưa có bộ máy tự nhân lên nên phải nhờ bộ máy tổng hợp của tế bào.", "C": "Đê virut không tốn năng lượng cho quá trình nhân lên, tập trung năng lượng cho các hoạt động sống khác.", "D": "Vì ở ngoài môi trường, virut sẽ bị phá hủy bởi các yếu tố bất lợi."}', 'A', '- Virut có cấu tạo đơn giản, chỉ gồm 2 thành phần chính là lõi axit nucleic và vỏ protein, chưa có các hệ enzim để thực hiện các quá trình sinh tổng hợp.- Vì vậy, để có thể nhân lên về số lượng, virut phải nhờ bộ máy tổng hợp của tế bào nên sống kí sinh nội bào bắt buộc.Đáp án cần chọn là: B', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(598, 'Chọn ý đúng: Tại sao virut phải kí sinh nội bào được nhận xét bắt buộc?', 'SINGLE_CHOICE', '{"A": "Có cấu tạo chưa phân hóa", "B": "Có kích thước siêu nhỏ", "C": "Khi nhân lên, virut phải nhờ vào bộ máy tổng hợp prôtêin của tế bào chủ", "D": "Cấu tạo đơn giản nên không thể thực hiện trao đổi chất với môi trường"}', 'A', 'Virut không có khả năng tự nhân lên. Do đó, virut phải nhờ vào bộ máy của tế bào chủ tổng hợp ra các vật chất chúng cần nên virut phải kí sinh nội bào bắt buộc.Đáp án cần chọn là: C', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(599, 'Chọn ý đúng: Cấu tạo nào được nhận xét đúng với vi rut?', 'SINGLE_CHOICE', '{"A": "Tế bào có màng, tế bào chất, chưa có nhân", "B": "Tế bào có màng, tế bào chất, có nhân sơ", "C": "Tế bào có màng, tế bào chất, có nhân chuẩn", "D": "Có các vỏ capxit chứa bộ gen bên trong"}', 'A', 'Virut là một dạng sống đặc biệt chưa có cấu tạo tế bào hoàn chỉnh.&nbsp;Tất cả các virut đều bao gồm 2 thành phần cơ bản: lõi axit nucleic (tức hệ gen) và vỏ prôtêin (gọi là capsit) bao bọc bên ngoài lõi axit nuclêic.Đáp án cần chọn là: D', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(600, 'Xác định ý đúng:&nbsp;Nhờ yếu tố nào mà virut có thể làm tan tế bào chủ để ồ ạt chui ra ngoài?', 'SINGLE_CHOICE', '{"A": "Nhờ virut có các gai nhọn đâm thủng tế bào vật chủ.", "B": "Nhờ virut được nhân lên ồ ạt với tốc độ nhanh chóng làm tế bào căng phồng rồi vỡ ra.", "C": "Nhờ virut tiết ra axit làm bào mòn thành tế bào vật chủ.", "D": "Nhờ virut có hệ gen mã hóa enzim lizozim làm tan thành tế bào vật chủ."}', 'A', 'Đáp án DLizozim là một enzim có khả năng phá vỡ một số liên kết hóa học và phá hủy tế bào. Ở một số phago có thể tiết ra enzim này làm tan thành tế bào vật chủ và chui ồ ạt ra ngoài.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(601, 'Xác định ý đúng:&nbsp;Bộ phận nào của virut bám đặc hiệu vào thụ thể của tế bào chủ?', 'SINGLE_CHOICE', '{"A": "gai glicoprotein", "B": "vỏ ngoài", "C": "vỏ capsit", "D": "lõi"}', 'A', 'Đáp án AGai glicoprotein của virut bám đặc hiệu vào thụ thể của tế bào chủ', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(602, 'Chọn ý đúng:&nbsp;Khi xâm nhập vào cơ thể người, HIV sẽ xâm nhập vào tế bào nào?', 'SINGLE_CHOICE', '{"A": "Hồng cầu", "B": "Limphô T", "C": "Thần kinh", "D": "Đại thực bào"}', 'A', 'Virut HIV chỉ có thể thực hiện chức năng như một cơ thể sống khi chúng kí sinh nội bào trong tế bào limpho T.Đáp án cần chọn là: B', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(603, 'Cho biết:&nbsp;Virut nào gây hội chứng suy giảm miễn dịch ở người?', 'SINGLE_CHOICE', '{"A": "Thể thực khuẩn", "B": "H5N1", "C": "HIV", "D": "Virut của E.coli"}', 'A', 'HIV là virut gây suy giảm miễn dịch ở người. Chúng có khả năng lây nhiễm và phá hủy một số tế bào của hệ thống miễn dịch (tế bào limphô T4 và đại thực bào). Sự giảm số lượng các tế bào này làm mất khả năng miễn dịch của cơ thể.Đáp án cần chọn là: C', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(604, 'Chọn ý đúng:&nbsp;Chu trình tan là chu trình?', 'SINGLE_CHOICE', '{"A": "Lắp axit nucleic vào protein vỏ.", "B": "Bơm axit nucleic vào chất tế bào.", "C": "Đưa cả nucleocapsit vào chất tế bào.", "D": "Virut nhân lên và phá vỡ tế bào."}', 'A', 'Chu trình tan (Sinh tan) là quá trình virut nhân lên và làm tan tế bào.Đáp án cần chọn là: D', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(605, 'Xác định:&nbsp;Để nuôi cấy vi rút, những quả trứng gà có khả năng sinh sản nên được ấp trong bao nhiêu ngày?', 'SINGLE_CHOICE', '{"A": "1", "B": "2-4", "C": "5-12", "D": "2-7"}', 'A', 'Đáp án CĐối với việc nuôi cấy vi rút bằng trứng gà đã được phôi thai, những quả trứng gà có khả năng sinh sản phải được ấp từ 5 đến 12 ngày sau đó có thể cấy vô trùng qua vỏ.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(606, 'Chọn ý đúng: Virus nào có tính đối xứng phức tạp?', 'SINGLE_CHOICE', '{"A": "Alphavirus", "B": "Mobillivirus", "C": "Orthopoxvirus", "D": "Parvovirus"}', 'A', 'Đáp án COrthopoxvirus có hình dạng đối xứng phức tạp và được bao bọc bởi một lớp lông.&nbsp;Nó bao gồm DNA là axit nucleic của nó.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(607, 'Chọn ý đúng:&nbsp;Bộ gen của virut được bao bọc trong một lớp áo protein là?', 'SINGLE_CHOICE', '{"A": "Capsid", "B": "Phong bì bên ngoài", "C": "Capsomere", "D": "Hạt nhân"}', 'A', 'Đáp án AVỏ bọc là vỏ bên ngoài prôtêin của virus, còn gọi là hình khối vỏ. Vỏ bọc là cách thức oligome mà do á đơn vị prôtêin của vỏ bọc của virus hình thành. Tác dụng của vỏ bọc là bao hàm vật chất di truyền của virus.&nbsp;', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(608, 'Chọn ý đúng:&nbsp;Chất nào là thuốc nhuộm acridin?', 'SINGLE_CHOICE', '{"A": "pha lê tím", "B": "xanh malachit", "C": "tryptoflavine", "D": "xanh lục rực rỡ"}', 'A', 'Đáp án CHai ví dụ về thuốc nhuộm có nguồn gốc từ acridine là acriflavine và tryptoflavine.&nbsp;Các hợp chất này thể hiện sự ức chế có chọn lọc đối với vi khuẩn, đặc biệt là tụ cầu và cầu khuẩn.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(609, 'Xác định ý đúng:&nbsp;Chất nào không phải là tác nhân hóa học để kiểm soát vi sinh vật?', 'SINGLE_CHOICE', '{"A": "Bức xạ", "B": "Thuốc kháng sinh", "C": "Thuốc sát trùng", "D": "Chất diệt khuẩn"}', 'A', 'Đáp án ABức xạ là tác nhân vật lý để kiểm soát vi sinh vật và bao gồm bức xạ ion hóa và không ion hóa để tiêu diệt vi sinh vật.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(610, 'Xác định ý đúng: Yếu tố quan trọng nhất để phân loại virus là gì?', 'SINGLE_CHOICE', '{"A": "Hình dạng của virus", "B": "Virus có bao nhiêu loại prôtêin", "C": "Bệnh do virus gây ra", "D": "Hóa học của DNA và RNA"}', 'A', 'Đáp án DSơ đồ Baltimore phân loại virus theo bộ gen DNA và RNA của chúng.&nbsp;Protein, bệnh tật và di truyền là những yếu tố quan trọng để chia nhỏ trong sơ đồ phân loại.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(611, 'Cho biết ý nào đúng: Nhờ yếu tố nào mà virut có thể làm tan tế bào chủ để ồ ạt chui ra ngoài?', 'SINGLE_CHOICE', '{"A": "Nhờ virut có các gai nhọn đâm thủng tế bào vật chủ.", "B": "Nhờ virut được nhân lên ồ ạt với tốc độ nhanh chóng làm tế bào căng phồng rồi vỡ ra.", "C": "Nhờ virut tiết ra axit làm bào mòn thành tế bào vật chủ.", "D": "Nhờ virut có hệ gen mã hóa enzim lizozim làm tan thành tế bào vật chủ."}', 'A', 'Lizozim là một enzim có khả năng phá vỡ một số liên kết hóa học và phá hủy tế bào. Ở một số phago có thể tiết ra enzim này làm tan thành tế bào vật chủ và chui ồ ạt ra ngoài.Đáp án D', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(612, 'Đâu là ý đúng: Ở giai đoạn xâm nhập của Virut vào tế bào chủ xảy ra hiện tượng?', 'SINGLE_CHOICE', '{"A": "Virut bám trên bề mặt của tê bào chủ", "B": "Axit nuclêic của Virut được đưa vào tê bào chất của tế bào chủ", "C": "Thụ thể của Virut liên kết với thụ thể của tế bào chủ", "D": "Virut di chuyển vào nhân của tế bào chủ"}', 'A', 'Ở giai đoạn xâm nhập của Virut vào tế bào chủ xảy ra hiện tượng axit nuclêic của Virut&nbsp; được&nbsp; đưa&nbsp; vào tê bào chất của tế bào chủ&nbsp;Đáp án B', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(613, 'Chọn ý đúng:&nbsp;Sự lây nhiễm của virus cúm khác virus HIV ở điểm?', 'SINGLE_CHOICE', '{"A": "RNA của virus cúm được sử dụng trực tiếp để tạo ra RNA và protein của virus mới.", "B": "Vỏ ngoài của virus được dung hợp với màng tế bào để đưa hạt virus vào trong tế bào chất.", "C": "Các hạt virus mới được lắp ráp và giải phóng ra bên ngoài tế bào bằng con đường xuất bào.", "D": "Sự hấp phụ được thực hiện nhờ các gai glycoprotein trên vỏ ngoài tương tác đặc hiệu với các thụ thể trên bề mặt của tế bào chủ."}', 'A', 'Đáp án AKhông giống với HIV, RNA của các virus cúm khi vào trong tế bào được sử dụng như mRNA để dịch mã tạo ra các protein và được dùng làm khuôn để tổng hợp nên RNA làm vật liệu di truyền của các hạt virus mới.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(614, 'Chọn ý đúng:&nbsp;Các chủng virus cúm khác nhau về?', 'SINGLE_CHOICE', '{"A": "chất cấu tạo lõi nucleic acid.", "B": "chất cấu tạo lớp vỏ ngoài.", "C": "loại enzyme phiên mã ngược.", "D": "loại tổ hợp gai glycoprotein."}', 'A', 'Đáp án DNgười ta chia virus cúm thành 16 phân nhóm khác biệt nhau bởi gai H (H1,… H16) và thành 9 nhóm khác nhau bởi gai N (N1,… N9), sự tổ hợp của các gai H và N tạo ra nhiều chủng virus cúm khác nhau.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(615, 'Chọn ý đúng:&nbsp;Virus gây hội chứng suy giảm miễn dịch mắc phải (AIDS) ở người là?', 'SINGLE_CHOICE', '{"A": "HIV.", "B": "SARS-CoV-2.", "C": "Paramyxo virus.", "D": "Aphtho type A."}', 'A', 'Đáp án AVirus gây hội chứng suy giảm miễn dịch mắc phải (AIDS) ở người là HIV.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(616, 'Chọn ý đúng:&nbsp;Các bệnh do virus thường có biểu hiện chung là?', 'SINGLE_CHOICE', '{"A": "sốt cao, đau nhức các bộ phận cơ thể.", "B": "suy giảm hệ thống miễn dịch của cơ thể.", "C": "sốt cao, tiêu chảy, đau họng.", "D": "tiêu chảy, đau nhức các bộ phận cơ thể."}', 'A', 'Đáp án ACác bệnh do virus thường có biểu hiện chung là sốt cao, đau nhức các bộ phận cơ thể. Sốt cao, đau nhức cơ thể không phải do các tế bào bị phá hủy bởi virus mà do đáp ứng của hệ thống miễn dịch của người chống lại virus.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(617, 'Chọn ý đúng:&nbsp;Miễn dịch đóng vai trò như thế nào đối với cơ thể?', 'SINGLE_CHOICE', '{"A": "Giúp virus tồn tại", "B": "Có thể có hiệu quả chống lại vi khuẩn", "C": "Luôn tẩy giun", "D": "Chịu trách nhiệm chữa lành vết thương"}', 'A', 'Đáp án BCó thể có hiệu quả chống lại vi khuẩn, giúp cơ thể thoát khỏi các bệnh.&nbsp;', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(618, 'Chọn ý đúng:&nbsp;Thuốc trừ sâu từ virus được sản xuất dựa trên cơ sở nào?', 'SINGLE_CHOICE', '{"A": "Một số loại virus mang gene kháng vi nấm gây bệnh cho cây trồng.", "B": "Một số loại virus làm vector chuyển gene kháng bệnh cho cây trồng.", "C": "Một số loại virus có khả năng tạo ra chất để tiêu hiệt sâu hại cây trồng.", "D": "Một số loại virus có khả năng xâm nhập và gây bệnh cho sâu hại cây trồng."}', 'A', 'Đáp án DThuốc trừ sâu từ virus được sản xuất dựa trên cơ sở một số loại virus có khả năng xâm nhập và gây bệnh cho sâu hại cây trồng.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(619, 'Hãy cho biết:&nbsp;Điểm khác biệt giữa interferon với vaccine là gì?', 'SINGLE_CHOICE', '{"A": "Interferon là protein do tế bào sản xuất ra, còn vaccine là kháng nguyên đã bị làm yếu đi, có nguồn gốc từ virus hoặc vi khuẩn gây bệnh.", "B": "Interferon là protein do hệ gene của virus sản xuất ra, còn vaccine là virus hoặc vi khuẩn gây bệnh đã được làm yếu đi.", "C": "Interferon là chất ức chế sự nhân lên của virus, còn vaccine có tác dụng kích thích cơ thể sản xuất kháng thể chống lại virus.", "D": "Interferon có tính đặc hiệu với virus, còn vaccine không có tính đặc hiệu với virus."}', 'A', 'Đáp án AĐiểm khác biệt giữa interferon với vaccine là: interferon là protein do tế bào sản xuất ra, còn vaccine là kháng nguyên đã bị làm yếu đi, có nguồn gốc từ virus hoặc vi khuẩn gây bệnh.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(620, 'Hãy cho biết:&nbsp;Vì sao insulin được dùng để điều trị bệnh tiểu đường?', 'SINGLE_CHOICE', '{"A": "Vì insulin có khả năng kích thích làm cho glucose chuyển hóa thành glycogen dự trữ trong gan, cơ; làm chậm quá trình phân giải glycogen; ức chế chuyển hóa amino acid và glycerol thành glucose.", "B": "Vì insulin có khả năng ức chế làm cho glucose chuyển hóa thành glycogen dự trữ trong gan, cơ; làm chậm quá trình phân giải glycogen; ức chế chuyển hóa amino acid và glycerol thành glucose.", "C": "Vì insulin có khả năng ức chế làm cho glucose chuyển hóa thành glycogen dự trữ trong gan, cơ; làm tăng quá trình phân giải glycogen; ức chế chuyển hóa amino acid và glycerol thành glucose.", "D": "Vì insulin có khả năng ức chế làm cho glucose chuyển hóa thành glycogen dự trữ trong gan, cơ; làm tăng quá trình phân giải glycogen; kích thích chuyển hóa amino acid và glycerol thành glucose."}', 'A', 'Đáp án AInsulin được dùng để điều trị bệnh tiểu đường vì insulin có khả năng kích thích làm cho glucose chuyển hóa thành glycogen dự trữ trong gan, cơ; làm chậm quá trình phân giải glycogen; ức chế chuyển hóa amino acid và glycerol thành glucose.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(621, 'Chọn ý đúng:&nbsp;Nguyên nhân nào khiến virus cúm dễ phát sinh ra những chủng virus mới?', 'SINGLE_CHOICE', '{"A": "Vật chất di truyền của chúng là DNA.", "B": "Chúng có nhiều loại vật chủ khác nhau.", "C": "Chúng không có lớp vỏ nên dễ bị đột biến.", "D": "Vật chất di truyền của chúng là RNA."}', 'A', 'Đáp án DDo vật chất di truyền của chúng là RNA nên virus cúm dễ phát sinh ra những chủng virus mới.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(622, 'Chọn ý đúng:&nbsp;Virut được sử dụng trong việc tạo các chế phẩm sinh học là nhờ?', 'SINGLE_CHOICE', '{"A": "virut có enzim đặc hiệu", "B": "khả năng chuyển hóa nhanh của virut", "C": "sử dụng axit nuclêic ở virut", "D": "sử dụng virut làm vật chuyển gen"}', 'A', 'Đáp án DMột số phagơ chứa các đoạn gen không thực sự quan trọng nên nếu cắt bỏ đi cũng không ảnh hưởng đến quá trình nhân lên của chúng. Dựa vào đặc điểm này mà người ta đã cắt bỏ một số gen để thay vào đó các gen mong muốn', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(623, 'Cho biết phát biểu nào có liên quan đến virus sởi?', 'SINGLE_CHOICE', '{"A": "Virus sởi có màng bọc ngoài, gen ARN sợi đơn", "B": "Viêm não là biến chứng thường xảy ra của bệnh sởi", "C": "Vị trí nhân lên đầu tiên của virus sởi đầu tiên ở đường tiêu hoá trên từ đó virus đến da qua đường máu.", "D": "Nhiễm trùng tiềm ẩn của virus sởi trộn lẫn gen sinh u vào AND tế bào ký chủ."}', 'A', 'Đáp án AVirus sởi&nbsp;hình cầu, đường kính 120 đến 250nm, chứa ARN sợi đơn, vỏ capsid đối xứng xoắn và có bao ngoài.&nbsp;Trong cấu trúc có thể có 6 protein cấu trúc.&nbsp;Cấu trúc vỏ bao ngoài có các hemagglutinin.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(624, 'Chọn ý đúng:&nbsp;Bệnh lây qua đường máu có nguồn truyền nhiễm từ động vật?', 'SINGLE_CHOICE', '{"A": "Viêm não Nhật Bản", "B": "Viêm gan B", "C": "Bệnh dại", "D": "Sốt xuất huyết dengue"}', 'A', 'Đáp án ABệnh lây qua đường máu có nguồn truyền nhiễm từ động vật là:&nbsp;Viêm não Nhật Bản.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(625, 'Chọn ý đúng:&nbsp;Kỹ thuật huyết thanh học có giá trị chẩn đoán chắc chắn nhiễm trùng HIV là?', 'SINGLE_CHOICE', '{"A": "ELISA", "B": "Miễn dịch phóng xạ ( RIA)", "C": "Western blot", "D": "Miễn dịch kết tủa"}', 'A', 'Đáp án BKỹ thuật huyết thanh học có giá trị chẩn đoán chắc chắn nhiễm trùng HIV là&nbsp;Western blot', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(626, 'Chọn ý đúng: Điều nào thường&nbsp;không&nbsp;liên quan đến mức độ lây lan của vi rút trong quần thể?', 'SINGLE_CHOICE', '{"A": "Vi-rút có thể truyền từ người này sang người khác dễ dàng như thế nào", "B": "Con đường lây truyền của virus", "C": "Virus có thể xâm nhập vào các mô của vật chủ dễ dàng như thế nào", "D": "Làm thế nào dễ dàng virus có thể chống lại thuốc kháng sinh"}', 'A', 'Đáp án DĐể biết&nbsp;kháng sinh có&nbsp;tác dụng với&nbsp;virus&nbsp;không thì bạn phải hiểu được&nbsp;cách&nbsp;thức hoạt động của&nbsp;kháng sinh, cũng như sự khác nhau giữa vi khuẩn và&nbsp;virus.&nbsp;', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(627, 'Chọn ý đúng:&nbsp;Bệnh truyền nhiễm lây lan qua con đường nào?', 'SINGLE_CHOICE', '{"A": "các giọt bị nhiễm bệnh trong không khí thở ra", "B": "muỗi hoặc các loại côn trùng cắn, côn trùng khác", "C": "thực phẩm bị ô nhiễm", "D": "tiếp xúc trực tiếp hoặc gián tiếp với một người bị nhiễm"}', 'A', 'Đáp án DBệnh có thể lây truyền qua tiếp xúc trực tiếp với người bị nhiễm bệnh hoặc qua tiếp xúc với một số vật dụng mà người đó sử dụng, ví dụ như khăn tắm. Tinea lây lan theo cách này', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(628, 'Chọn ý đúng:&nbsp;Đặc điểm chính của họ bunyavirus là gì?', 'SINGLE_CHOICE', '{"A": "Khuếch đại bởi sự lây nhiễm dai dẳng của muỗi vằn, muỗi, ruồi cát, bọ ve", "B": "Chủ yếu do muỗi truyền", "C": "Tái tổ hợp hoặc tái tổ hợp gen", "D": "Lây sang người qua vết cắn của chuột nhắt, chuột cống"}', 'A', 'Đáp án ASự khuếch đại xảy ra ở loài gặm nhấm và cả động vật chân đốt.&nbsp;Muỗi hầu như không liên quan nhưng vi-rút có thể lây lan từ vết cắn của loài gặm nhấm hơn là vết cắn của nước tiểu hoặc động vật chân đốt.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(629, 'Chọn ý đúng:&nbsp;Virus cúm chủ yếu được kiểm soát trong các lĩnh vực "rủi ro" đặc biệt bằng cách nào?', 'SINGLE_CHOICE', '{"A": "Vệ sinh", "B": "Tiêm phòng", "C": "Thuốc kháng virus", "D": "Kháng thể đơn dòng nhân bản"}', 'A', 'Đáp án BVắc-xin là chiến lược chính nhưng vệ sinh, thuốc kháng vi-rút và đơn dòng có vai trò nhất định.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(630, 'Chọn ý đúng:&nbsp;Sự bài tiết các kháng thể bởi các tế bào lympho B cung cấp?', 'SINGLE_CHOICE', '{"A": "miễn dịch qua trung gian tế bào", "B": "miễn dịch thụ động", "C": "miễn dịch dịch thể", "D": "miễn dịch vĩnh viễn"}', 'A', 'Đáp án CSự tiết kháng thể của tế bào lympho B cung cấp khả năng miễn dịch dịch thể.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(631, 'Xác định:&nbsp;Bệnh nào không phải là bệnh do virut?', 'SINGLE_CHOICE', '{"A": "quai bị", "B": "sởi", "C": "thủy đậu", "D": "bạch hầu"}', 'A', 'Đáp án DBệnh bạch hầu&nbsp;là một bệnh truyền nhiễm cấp tính do vi khuẩn bạch hầu gây ra.&nbsp;', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(632, 'Xác định: Biện pháp nào không&nbsp;được áp dụng để phòng tránh bệnh do virus ở cây trồng?', 'SINGLE_CHOICE', '{"A": "Sử dụng thuốc trị bệnh virus cho cây trồng.", "B": "Tiêu diệt các vật trung gian truyền bệnh.", "C": "Vệ sinh đồng ruộng đúng cách.", "D": "Tiêu hủy các cây bị nhiễm bệnh."}', 'A', 'Đáp án AHiện nay, chưa có thuốc trị bệnh virus cho cây trồng.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(633, 'Xác định ý đúng: Triệu chứng điển hình của cây trồng bị nhiễm virus là?', 'SINGLE_CHOICE', '{"A": "lá màu xanh đậm; thân cây mọc cao vống lên nhưng yếu và dễ đổ gãy.", "B": "lá bị xoăn; có những vết nâu, trắng hoặc vàng trên lá và quả; sinh trưởng chậm.", "C": "lá có màu vàng đỏ; thân cây xuất hiện nhiều u bướu nhỏ.", "D": "sinh trưởng chậm; lá cây vàng héo rồi rụng; số lượng hoa và quả đều giảm."}', 'A', 'Đáp án BTriệu chứng điển hình của cây trồng bị nhiễm virus là lá bị xoăn; có những vết nâu, trắng hoặc vàng trên lá và quả; sinh trưởng chậm.', 20);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(634, 'Chọn ý đúng:&nbsp;Vắc xin chống ung thư HPV thành công bao gồm?', 'SINGLE_CHOICE', '{"A": "Virus sống giảm độc lực bằng đột biến đặc hiệu", "B": "Vắc xin bất hoạt hóa học toàn vi rút", "C": "Protein L1 của virus tự tổng hợp thành VLP", "D": "Vắc xin vô hoạt hóa học đơn vị phụ"}', 'A', 'Đáp án CĐây là một loại vắc-xin ''sinh học phân tử'' cổ điển bao gồm vi-rút tự lắp ráp giống như các hạt (VLP).&nbsp;Phương pháp này hiện đang được áp dụng cho các loại vắc-xin mới khác bao gồm cả Zika.', 20);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(21, 'Bài tập trắc nghiệm Tiếng Anh online #7', 'Tiếng Anh', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Tiếng Anh. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(635, '“How many pages…………… so far?"', 'SINGLE_CHOICE', '{"A": "have you studied", "B": "did you study", "C": "do you study", "D": "had you studied"}', 'A', '"so far" cấu trúc thì hiện tại hoàn thành (câu nghi vấn)', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(636, 'We are too late. The plane …………… off ten minutes ago.', 'SINGLE_CHOICE', '{"A": "has taken", "B": "took", "C": "had taken", "D": "was taken"}', 'A', '"ten minutes ago" thì quá khứ đơn.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(637, '“What a lovely boat!” “I ……………half a year building this boat.”', 'SINGLE_CHOICE', '{"A": "spend", "B": "spent", "C": "spending", "D": "have spent"}', 'A', 'Thì quá khứ đơn.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(638, 'How …………since we …………school?', 'SINGLE_CHOICE', '{"A": "are you/ left", "B": "have you been/ have left", "C": "were you/ left", "D": "have you been/ left"}', 'A', 'Mệnh đề chứa "since" luôn chia thì quá khứ, vế còn lại thì hiện tại hoàn thành.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(639, '&nbsp;I think John …………..tomorrow.', 'SINGLE_CHOICE', '{"A": "would come", "B": "come", "C": "will come", "D": "comes"}', 'A', '"tomorrow": thì tương lai đơn', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(640, '&nbsp;After he ------------ his driving test he bought a car.', 'SINGLE_CHOICE', '{"A": "had passed", "B": "pass", "C": "passed", "D": "passing"}', 'A', '', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(641, 'When I got to the office, I ----------- that I had forgot to lock the door.', 'SINGLE_CHOICE', '{"A": "realized", "B": "had realized", "C": "realize", "D": "have realized"}', 'A', 'Thì quá khứ đơn', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(642, 'When she was 21 she -------------- across the United States.', 'SINGLE_CHOICE', '{"A": "drove", "B": "drive", "C": "driven", "D": "was driving"}', 'A', 'Quá khứ của "drive" là "drove"', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(643, 'He often ------------ so nervous before his exams.', 'SINGLE_CHOICE', '{"A": "feels", "B": "felt", "C": "was feeling", "D": "had felt"}', 'A', '"often" hiện tại đơn, chủ ngữ số ít "he"', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(644, '&nbsp;How long have you ------------- he was a liar.', 'SINGLE_CHOICE', '{"A": "been knowing", "B": "knew", "C": "know", "D": "known"}', 'A', 'Thì hiện tại hoàn thành chia V cột 3', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(645, '&nbsp;I’m sorry. I don’t understand what -----------------.', 'SINGLE_CHOICE', '{"A": "you say", "B": "you''re saying", "C": "you will say", "D": "you would say"}', 'A', '"Tôi xin lỗi. Tôi không hiểu bạn đang nói gì."Thì hiện tại tiếp diễn.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(646, '------------- to the radio when you get up everyday?', 'SINGLE_CHOICE', '{"A": "Do you listen", "B": "Are you listening", "C": "Was you listening", "D": "Did you listen"}', 'A', 'Thì hiện tại đơn, tương ứng với hai vế câu.', 21);
