(647, 'My sweetheart --------------- smoking next week.', 'SINGLE_CHOICE', '{"A": "will give up", "B": "is going to give up", "C": "gives up", "D": "gave up"}', 'A', 'Một kế hoạch có dự định trước, dùng cấu trúc "be going to"', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(648, 'There is no red wine? I -------------- white, then.', 'SINGLE_CHOICE', '{"A": "am going to have", "B": "have", "C": "will have", "D": "am having"}', 'A', '', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(649, 'When the phone rang she ------------ a letter.', 'SINGLE_CHOICE', '{"A": "writes", "B": "willl write", "C": "has written", "D": "was writing"}', 'A', 'Một hành động đang diễn ra, một hành động khác chen vào.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(650, 'As the sun ------------ I decided to go out.', 'SINGLE_CHOICE', '{"A": "shines", "B": "has shone", "C": "shine", "D": "was shining"}', 'A', '"The sun was shining": mặt trời đang tỏa nắng', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(651, 'I------------- your uncle tomorrow, so I’ll give him your note.', 'SINGLE_CHOICE', '{"A": "have seen", "B": "shall have seen", "C": "see", "D": "am going to see"}', 'A', 'Một dự định dùng "be going to"', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(652, '-------------- study hard when you were at school?', 'SINGLE_CHOICE', '{"A": "Must you", "B": "Had you", "C": "Did you have to", "D": "Were you"}', 'A', '"study" động từ nguyên mẫu nên ta loại B, DCâu C tương ứng với thì quá khứ trong câu và hợp nghĩa hơn.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(653, 'She is tired because she ------------- all day.', 'SINGLE_CHOICE', '{"A": "is studied", "B": "has been studying", "C": "had been studying", "D": "studied"}', 'A', 'Diễn tả hành động xảy ra xuyên suốt từ một thời điểm trong quá khứ kéo dài đến hiện tại. (all day)', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(654, 'Has your teacher ever ------------ angry with you?', 'SINGLE_CHOICE', '{"A": "get", "B": "getting", "C": "got", "D": "gets"}', 'A', 'Cấu trúc thì hiện tại hoàn thành câu nghi vấn: Has S (số ít) V3&nbsp;&nbsp;', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(655, 'He ----------', 'SINGLE_CHOICE', '{"A": "will be here soon", "B": "will here be soon", "C": "will be soon here", "D": "be soon will here"}', 'A', 'Will + VTạm dịch: Tôi sẽ sớm có mặt ở đây.', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(656, 'They ------------ to the theatre twice so far this month.', 'SINGLE_CHOICE', '{"A": "are going", "B": "go", "C": "went", "D": "have been"}', 'A', '"twice so far this month": thì hiện tại hoàn thành', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(657, 'My daughter ------------- university last June.', 'SINGLE_CHOICE', '{"A": "left", "B": "has left", "C": "leaves", "D": "was leaving"}', 'A', '"last June": thì quá khứ đơn', 21);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(658, 'He hates his boss so he ------------- his job.', 'SINGLE_CHOICE', '{"A": "leaves", "B": "has left", "C": "is leaving", "D": "left"}', 'A', 'thì hiện tại tiếp diễn dùng với ý nghĩa có kế hoạch trước.', 21);
