INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(22, 'Bài tập trắc nghiệm kiểm tra ngữ pháp Tiếng Anh online - Đề số #14', 'Tiếng Anh', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Tiếng Anh. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(660, 'There is no ______that he has been here.', 'SINGLE_CHOICE', '{"A": "evidence", "B": "evidential", "C": "evidentially", "D": "evident"}', 'A', 'Vị trí trống cần danh từ', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(661, 'My parents do not allow me______, so I had to stay at home.', 'SINGLE_CHOICE', '{"A": "to go", "B": "go", "C": "going", "D": "gone"}', 'A', 'allow sb to V (cho phép ai làm gì)', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(662, 'If there were flying saucers, there ______ traces of their landing.', 'SINGLE_CHOICE', '{"A": "would be", "B": "will be", "C": "are", "D": "is"}', 'A', 'Câu điều kiện loại 2: If + QKĐ, S + would/could/might + V.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(663, 'Do you think you will be able ______ a space trip?', 'SINGLE_CHOICE', '{"A": "to take", "B": "take", "C": "taking", "D": "taken"}', 'A', 'tobe able to V (có khả năng làm gì)', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(664, 'He won''t be happy if you ______ come!', 'SINGLE_CHOICE', '{"A": "don''t", "B": "haven''t", "C": "didn''t", "D": "won''t"}', 'A', 'Câu điều kiện loại 1: If + HTĐ, TLĐ.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(665, 'If I ______a bird, I would be a dove.', 'SINGLE_CHOICE', '{"A": "were", "B": "is", "C": "was", "D": "am"}', 'A', 'Câu điều kiện loại 2: If + QKĐ, S + would/could/might + V.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(666, 'She would come to see you if she _______ your address.', 'SINGLE_CHOICE', '{"A": "had", "B": "has", "C": "have", "D": "having"}', 'A', 'Câu điều kiện loại 2: If + QKĐ, S + would/could/might + V.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(667, 'The ________ of the volcano was predicted in advance, so no one was injured.', 'SINGLE_CHOICE', '{"A": "eruption", "B": "erupted", "C": "erupts", "D": "erupt"}', 'A', 'Vị trí trống cần danh từ', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(668, 'The public suggested that the factories ………. with waste treatment system.', 'SINGLE_CHOICE', '{"A": "would equip", "B": "would be equipped", "C": "should equip", "D": "should be equipped"}', 'A', 'suggest + O + should + V: gợi ý ai nên làm gìChuyển V sang bị động là tobe VpII', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(669, 'The local government suggested ……. a road through the Nam Cat Tien National Park.', 'SINGLE_CHOICE', '{"A": "build", "B": "to build", "C": "building", "D": "being built"}', 'A', 'suggest + Ving (gợi ý làm gì)', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(670, 'It …………that some foreigners had collected rubbish on Cat Ba Beach.', 'SINGLE_CHOICE', '{"A": "reported", "B": "was reported", "C": "could report", "D": "had been reported"}', 'A', 'Bị động ý kiến ở thì quá khứ đơn', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(671, 'He decided ____________ another language.', 'SINGLE_CHOICE', '{"A": "study", "B": "to study", "C": "studying", "D": "studied"}', 'A', 'decide to V: quyết định làm gì', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(672, 'Two months ago my brother _______ elected headmaster of his school and he _______ a vacation since then.', 'SINGLE_CHOICE', '{"A": "was-hadn’t had", "B": "was-hasn’t had", "C": "had been-didn’t have", "D": "had been-wouldn’t have"}', 'A', 'Vế trước có “ago” nên động từ chia thời quá khứ, vế sau có “since” nên động từ chia thời hiện tại hoàn thành.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(673, 'Learning English _____________ really interesting.', 'SINGLE_CHOICE', '{"A": "am", "B": "is", "C": "are", "D": "be"}', 'A', 'V-ing đầu câu động từ chia số ít', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(674, 'In this semester, we have to _____________ our major for future occupation.', 'SINGLE_CHOICE', '{"A": "choose", "B": "choosing", "C": "chosen", "D": "chose"}', 'A', 'have to V: phải làm gì', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(675, 'My uncle _______ a visit to Germany in 2005.', 'SINGLE_CHOICE', '{"A": "paid", "B": "pays", "C": "has paid", "D": "will pay"}', 'A', 'Mốc thời gian 2005 đã qua nên câu chia quá khứ.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(676, 'I felt nervous when the teacher said she __________ my school report home soon.', 'SINGLE_CHOICE', '{"A": "would send", "B": "sends", "C": "sending", "D": "sent"}', 'A', 'Câu gián tiếp thì tương lai vì có mốc thời gian “soon”', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(677, 'Would you mind _______ more clearly, please?', 'SINGLE_CHOICE', '{"A": "speak", "B": "speaking", "C": "to speak", "D": "spoke"}', 'A', 'mind + Ving: phiền, ngại làm gì', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(678, 'That girl tried to avoid _______ some of my questions.', 'SINGLE_CHOICE', '{"A": "answer", "B": "to answer", "C": "answering", "D": "answered"}', 'A', 'avoid + V-ing: tránh làm gì', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(679, 'He ____________ abroad before I met him in Sydney.', 'SINGLE_CHOICE', '{"A": "studied", "B": "study", "C": "will study", "D": "had studied"}', 'A', 'QKHT before QKĐ', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(680, 'By the end of last summer, Alexander _______ his Ph.D.', 'SINGLE_CHOICE', '{"A": "received", "B": "had received", "C": "receive", "D": "are received"}', 'A', 'By the end of + mốc quá khứ, QKHT', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(681, 'If you want to be a telephonist, you should _________ your communication skills.', 'SINGLE_CHOICE', '{"A": "practiced", "B": "practice", "C": "practicing", "D": "to practice"}', 'A', 'Sau động từ khuyết thiếu “should” là động từ nguyên thể', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(682, 'We would love _______ three cups of coffee.', 'SINGLE_CHOICE', '{"A": "have", "B": "to have", "C": "having", "D": "had"}', 'A', 'would love to V: cấu trúc đề nghị lịch sự cái gì đó.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(683, 'Earl was one of the first American artists ___________ landscapes.', 'SINGLE_CHOICE', '{"A": "painting", "B": "painted", "C": "for painting", "D": "to paint"}', 'A', 'Mệnh đề quan hệ rút gọn, sau "the first American artists" là to-V.', 22);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(684, '___________ having a private tutor, he couldn’t get good marks at school.', 'SINGLE_CHOICE', '{"A": "Because", "B": "Even though", "C": "Although", "D": "Despite"}', 'A', 'Despite + Ving: Mặc dù', 22);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(23, 'Bài tập trắc nghiệm Tiếng Anh online #2', 'Tiếng Anh', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Tiếng Anh. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(685, 'They _________ enthusiastically when their teacher ___________in.', 'SINGLE_CHOICE', '{"A": "will discuss/ will come", "B": "will have discussed/ comes", "C": "were discussing/ came", "D": "discuss/ comes"}', 'A', 'Kiến thức: Thì quá khứ tiếp diễn- Cách dùng: thì quá khứ tiếp diễn diễn tả hành động đang diễn ra trong quá khứ (chia quá khứ tiếp diễn) thì có hành động khác cắt ngang (chia quá khứ đơn)- Công thức: S + was/were +V_ing when + S + V_ed/V cột 2Tạm dịch: Họ đang thảo luận nhiệt tình khi giáo viên bước vào', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(686, 'The earthquake, and tsunami that followed, has killed over 1300 people, the majority of ________were in the city of Palu in Central Sulawesi, Indonesia.', 'SINGLE_CHOICE', '{"A": "which", "B": "them", "C": "whom", "D": "that"}', 'A', 'Kiến thức: Đại từ quan hệ&nbsp;Trong mệnh đề quan hệ:- whom: người mà =&gt; thay thế cho từ chỉ người (có thể đứng sau giới từ)Tạm dịch: Trận động đất và sóng thần xảy ra sau đó đã giết chết hơn 1300 người, phần lớn trong số họ ở thành phố Palu ở miền Trung Sulawesi, Indonesia.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(687, 'There is no excuse for your late submission! You _________ the report by last Monday.', 'SINGLE_CHOICE', '{"A": "needn’t have finished", "B": "mightn’t have finished", "C": "should have finished", "D": "must have finished"}', 'A', 'Kiến thức: Câu phỏng đoánneedn’t have done sth: lẽ ra không cần làm gì (nhưng đã làm)mightn’t have done sth: có thể đã không làm gìshould have done sth: lẽ ra nên làm gì (nhưng đã không làm)must have done sth: chắc hẳn là đã làm gìTạm dịch: Đừng lấy cớ cho việc trễ hạn nộp của bạn! Bạn lẽ ra nên hoàn thành báo cáo trước thứ Hai tuần trước.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(688, 'I don’t think Jill would be a good teacher. She’s got little patience, __________?', 'SINGLE_CHOICE', '{"A": "hasn’t she", "B": "does she", "C": "doesn’t she", "D": "has she"}', 'A', 'Kiến thức: Câu hỏi đuôiVế trước có “little” (hầu như không) mang ý nghĩa phủ định =&gt; câu hỏi đuôi sẽ là khẳng địnhĐộng từ vế trước chia thì hiện tại hoàn thành =&gt; câu hỏi đuôi: “has”Chủ ngữ là “she” =&gt; câu hỏi đuôi: “she”Tạm dịch: Tôi không nghĩ rằng Jill sẽ là một giáo viên giỏi. Cô ấy gần như không có tí kiên nhẫn nào, phải không?', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(689, 'There are billions of stars in_________ space.', 'SINGLE_CHOICE', '{"A": "a", "B": "an", "C": "the", "D": "x"}', 'A', 'Kiến thức: Mạo từa/an + danh từ số ít, chưa xác định the + danh từ đã được xác định rõ“space” ( không gian vũ trụ) =&gt; không cần mạo từ“in space”: trong không gianTạm dịch: Có hàng tỉ vì sao trong không gian.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(690, '_________ ten minutes earlier, you would have got a better seat.', 'SINGLE_CHOICE', '{"A": "If you arrived", "B": "Had you arrived", "C": "Were you arrived", "D": "If you hadn’t arrived"}', 'A', 'Kiến thức: Đảo ngữ trong câu điều kiện loại 3- Dấu hiệu: mệnh đề chính “would have got”- Câu điều kiện loại 3 diễn tả một điều kiện không có thực trong quá khứ dẫn đến kết quả trái với sự thật trong quá khứ.- Cấu trúc:&nbsp; Had + S + (not) + P2, S + would + have + P2Tạm dịch: Nếu bạn đã đến sớm hơn 10 phút, bạn có lẽ đã có một chỗ ngồi tốt hơn', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(691, 'The boys proposed that their group leader__________ a camping trip.', 'SINGLE_CHOICE', '{"A": "organize", "B": "organized", "C": "organizes", "D": "organizing"}', 'A', 'Kiến thức: Thức giả địnhCông thức: S1 + động từ giả định + that + S2 + V_nguyên thểTạm dịch: Các bạn nam đã đề xuất nhóm trưởng của họ tổ chức một buổi cắm trại.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(692, 'In some parts of the country, prices are__________ than in others.', 'SINGLE_CHOICE', '{"A": "the highest", "B": "higher and higher", "C": "highest", "D": "more and more high"}', 'A', 'Kiến thức: Cấu trúc tăng tiến- Cấu trúc: S + V + adv/adj-er + and + adv/adj-er:- “high” là tính từ ngắn =&gt; higherTạm dịch: Ở một vài nơi trên đất nước, giá cả ngày càng cao hơn ở những nơi khác.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(693, 'I deeply regret __________ to her so severely last night. She was badly hurt.', 'SINGLE_CHOICE', '{"A": "to speak", "B": "to be speaking", "C": "being spoken", "D": "having spoken"}', 'A', 'Kiến thức: to V/ V_ing&nbsp;- Dấu hiệu: “last night” (tối qua)- regret + V_ing: hối hận đã làm gìTạm dịch: Tôi rất hối hận khi đã nói nặng lời với cô ấy tối hôm qua. Cô ấy đã rất tổn thương', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(694, 'No sooner ________ than he begins to be washed.', 'SINGLE_CHOICE', '{"A": "a human being born", "B": "a human being had been born", "C": "was a human being born", "D": "is a human being born"}', 'A', 'Kiến thức: Đảo ngữCấu trúc đảo ngữ câu bị động:No sooner + tobe + S + P2 than S + V: Ngay sau khi cái gì được làm gì thì …Động từ “begins” vế sau chia hiện tại đơn =&gt; vế trước cũng chia ở hiện tạiTạm dịch: Ngay sau khi một con người được sinh ra thì cậu ta bắt đầu được tắm rửa sạch sẽ.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(695, 'Ensoleill and Sunny are talking about Ted’s accident last week.Ensoleill: “A motor bike knocked Ted down”.Sunny: “______________”', 'SINGLE_CHOICE', '{"A": "How terrific!", "B": "Poor Ted!", "C": "What it is now?", "D": "What a motor bike!"}', 'A', 'Kiến thức: Ngôn ngữ giao tiếpEnsoleill và Sunny đang nói về vụ tai nạn của Ted tuần trước.Ensoleill: “Một chiếc xe gắn máy đã đâm vào Ted.” Tim: “_________."A. Thật tuyệt!B. Tội nghiệp Ted!C. Bây giờ là cái gì nào?D. Thật là một cái xe gắn máy!Các phản hồi A, C, D không phù hợp ngữ cảnh.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(696, 'Having found guilty of racketeering, the mobster was sentenced to a number of years in prison.', 'SINGLE_CHOICE', '{"A": "Having found", "B": "of", "C": "was sentenced", "D": "a number"}', 'A', 'Kiến thức: Mệnh đề rút gọnHai mệnh đề cùng chủ ngữ =&gt; có thể rút gọn mệnh đềCâu mang nghĩa bị động, hành động vế đầu xảy ra trước hành động vế sau=&gt; rút gọn theo công thức: Having + been + P2Sửa: “Having found” =&gt; “Having been found”Tạm dịch: Bị phát hiện ra tội lừa đảo, tên cướp đã bị tuyên án một vài năm', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(697, 'Most people consider it women''s responsible to take care of children and do housework.', 'SINGLE_CHOICE', '{"A": "Most", "B": "v", "C": "responsible", "D": "do"}', 'A', 'Kiến thức: Từ loạiSau tính từ sở hữu “women’s” cần một danh từ số nhiều để chỉ chung responsible (adj): có trách nhiệm responsibility (n): trách nhiệmSửa: responsible =&gt; responsibilitiesTạm dịch: Phần lớn mọi người đều coi trách nhiệm của phụ nữ là chăm con và làm việc nhà.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(698, 'They have made a lot of progress until the country became independent.', 'SINGLE_CHOICE', '{"A": "until", "B": "a lot of", "C": "independent", "D": "became"}', 'A', 'Kiến thức: Giới từVế trước động từ chia thì hiện tại hoàn thành: “have made”=&gt; giới từ thường được sử dụng là “since + mốc thời gian” hoặc “for + khoảng thời gian” “the country became independent” (đất nước độc lập) =&gt; mốc thời gianSửa: until =&gt; sinceTạm dịch: Họ đã đạt được nhiều tiến bộ kể từ khi đất nước độc lập.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(699, 'Mary was very disappointed. However, she tried to keep calm.&nbsp;', 'SINGLE_CHOICE', '{"A": "Mary was too disappointed to keep calm.", "B": "Mary lost her temper because of her disappointment.", "C": "Disappointed as she was, Mary tried to keep calm.", "D": "Feeling disappointed, Mary tried to keep calm, but she failed."}', 'A', 'Kiến thức: Câu đồng nghĩa, đảo ngữ với “as”&nbsp;Cấu trúc đảo ngữ với “as”: Adj/Adv + as + S + V, S + VTạm dịch: Mary đã quá thất vọng. Tuy nhiên, cô ấy đã cố gắng giữ bình tĩnh.A. Mary đã quá thất vọng đến nỗi cô ấy không thể giữ bình tĩnh. =&gt; sai nghĩaB. Mary mất bình tĩnh bởi vì sự thất vọng của cô ấy. =&gt; sai nghĩaC. Mặc dù cô ấy thất vọng, Mary vẫn cố gắng giữ bình tĩnh.D. Cảm thấy thất vọng, Mary đã cố giữ bình tĩnh, nhưng cô ấy đã thất bại. =&gt; sai nghĩa', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(700, 'She gave a great performance at the festival. We now know she has artistic talent.', 'SINGLE_CHOICE', '{"A": "But for her great performance at the festival, we wouldn''t know about her artistic talent now.", "B": "Amazing as her artistic talent is, we don''t know about her great performance at the festival.", "C": "Although she gave a great performance at the festival, we know she has artistic talent.", "D": "Hardly had we know about her artistic talent when she gave a great performance at the festival."}', 'A', 'Kiến thức: Cấu trúc đồng nghĩa&nbsp;Câu điều kiện hỗn hợp diễn tả điều kiện không có thật ở quá khứ dẫn đến kết quả trái với hiện tạiCông thức: If + S + had (not) + P2, S + would + V_nguyên thểBut for = If … not : Nếu không nhờTạm dịch: Cô ấy đã có một màn trình diễn tuyệt vời ở lễ hội. Bây giờ chúng tôi biết được tài năng nghệ thuật của cô ấy.A. Nếu không nhờ màn trình diễn tuyệt vời của cô ấy ở lễ hội, bây giờ chúng tôi đã không biết về tài năng nghệ thuật của cô ấy.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(701, 'Be careful or you may get lost and run out of money.” She said.&nbsp;', 'SINGLE_CHOICE', '{"A": "She advised me to be careful or I might get lost and run out of money.", "B": "She warned me to be careful or I had to get lost and run out of money.", "C": "She ordered me to be careful and I might get lost and run out of money.", "D": "She told me to be careful if I got lost and run out of the money."}', 'A', 'Kiến thức: Lời nói gián tiếp&nbsp;“Be careful or …” : Hãy cẩn thận nếu không thì …= S + advised + S + to V_nguyên thể: Ai đó đã khuyên ai làm gìTạm dịch: “Hãy cẩn thận hoặc bạn có thể bị lạc và hết sạch tiền” Cô ấy đã nóiA. Cô ấy đã khuyên tôi nên cẩn thận nếu không tôi có thể bị lạc và hết sạch tiền.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(702, 'It isn’t necessary for us to get a visa for Singapore.', 'SINGLE_CHOICE', '{"A": "We mustn’t get a visa for Singapore.", "B": "We needn’t get a visa for Singapore.", "C": "We mayn’t get a visa for Singapore.", "D": "We shouldn’t get a visa for Singapore."}', 'A', 'Kiến thức: Động từ khuyết thiếu&nbsp;mustn’t: không được phép làm gìneedn’t: không cần làm gìmayn’t: không thể làm gìshouldn’t: không nên làm gìTạm dịch: Thật không cần thiết cho chúng tôi khi lấy visa sang Singapore.B. Chúng tôi không cần phải lấy visa sang Singapore.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(703, 'The last time I went to the museum was a year ago.', 'SINGLE_CHOICE', '{"A": "I have not been to the museum for a year.", "B": "A year ago, I often went to the museum.", "C": "My going to the museum lasted a year.", "D": "At last I went to the museum after a year."}', 'A', 'Kiến thức: Thì hiện tại hoàn thành- Cách dùng: Thì hiện tại hoàn thành diễn tả sự việc bắt đầu trong quá khứ, kéo dài đến hiện tại và có thể tiếp tục ở tương lai. Với cách dùng này thường có “since + mốc thời gian” hoặc “for + khoảng thời gian”- Công thức: S + have/has (not) + P2 + for + khoảng thời gian/since + mốc thời gian“a year” (một năm) là khoảng thời gian =&gt; dùng “for”Tạm dịch: Lần cuối tôi đi đến viện bảo tàng là một năm trước.A. Tôi đã không đi đến viện bảo tàng trong một năm rồi.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(704, 'Were it not for the money, this job wouldn’t be worthwhile.&nbsp;', 'SINGLE_CHOICE', '{"A": "Although the salary is poor, the job is worthwhile.", "B": "The only thing that makes this job worthwhile is the money.", "C": "This job is not rewarding at all, so everyone wants to get it.", "D": "This job offers a poor salary, so it is worthwhile."}', 'A', 'Kiến thức: Câu đồng nghĩaĐảo ngữ câu điều kiện loại 2: Were + S + O, S + would (not) + V_nguyên thểTạm dịch: Nếu không phải vì tiền thì công việc này sẽ không đáng để làm.B. Điều duy nhất khiến cho công việc này đáng để làm là tiền.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(705, 'The burglar was caught red-handed by the police when he broke into the flat.&nbsp;', 'SINGLE_CHOICE', '{"A": "The police caught the burglar to break into the flat.", "B": "The police caught the burglar breaking into the flat.", "C": "The police caught the burglar when breaking into the flat.", "D": "Then the burglar had broken into the flat, the police caught him at one."}', 'A', 'Kiến thức: Câu đồng nghĩacatch sb doing sth: bắt gặp ai đang làm gì= be catch red-handed: bị bắt quả tang (đang làm gì)catch sb do sth: gặp ai làm gì (quan sát hành động từ khi nó bắt đầu đến khi nó kết thúc) A. Cảnh sát bắt được tên trộm đột nhập vào căn hộ. (sai cấu trúc với “catch”)Tạm dịch: Tên trộm đã bị cảnh sát bắt quả tang khi anh ta đột nhập vào căn hộ.B. Cảnh sát bắt được tên trộm đột nhập vào căn hộ.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(706, 'He didn’t pay attention to what I said.', 'SINGLE_CHOICE', '{"A": "He had no intention of talking to me.", "B": "He didn’t hear me even though I was saying to him.", "C": "He took no notice of my words.", "D": "He didn’t pay attention because I didn’t say a word."}', 'A', 'Kiến thức: Câu đồng nghĩa&nbsp;not pay attention to sth: chú tâm, để ý, lắng nghe kĩ,…= take no notice of sthTạm dịch: Anh không chú ý đến những gì tôi nói.C. Anh ấy không chú ý đến lời nói của tôi.&nbsp;', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(707, 'Such characters as fairies or witches in Walt Disney animated cartoons are purely _________', 'SINGLE_CHOICE', '{"A": "imaginable", "B": "imaginative", "C": "imagining", "D": "imaginary"}', 'A', 'Kiến thức: Từ loạiSau tobe “are” cần một tính từ.A. imaginable (adj): giàu trí tưởng tượngB. imaginative (adj): có thể tưởng tượngC. imagining (V_ing): tưởng tượngD. imaginary (adj): tưởng tượng, hư khôngTạm dịch: Những nhân vật như tiên nữ hay phù thủy trong phim hoạt hình Walt Disney hoàn toàn là tưởng tượng.', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(708, 'Neither Mary nor her brothers _________at the party yet. They may be getting stuck in the traffic.', 'SINGLE_CHOICE', '{"A": "are arriving", "B": "have arrived", "C": "has arrived", "D": "is arriving"}', 'A', 'Kiến thức: Sự hòa hợp giữa chủ ngữ và động từNeither S1 nor S2 + V_chia theo S2: Không … cũng không …S2 là “her brothers” (những người anh của cô ấy), ngôi thứ 3 số nhiều =&gt; loại C, DCuối câu có “yet” (chưa) =&gt; dấu hiệu thì hiện tại hoàn thànhCông thức: S + have + P2Tạm dịch: Cả Mary và anh trai cô đều vẫn chưa đến bữa tiệc. Họ có thể đang bị kẹt xe', 23);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(709, 'The old market is said _________in a fire two years ago.', 'SINGLE_CHOICE', '{"A": "to be destroyed", "B": "to have destroyed", "C": "to have been destroyed", "D": "to be destroying"}', 'A', 'Kiến thức: Câu tường thuật đặc biệtDấu hiệu: “two years ago” (2 năm trước)Công thức: S + am/is/are + said + to have + P2Chủ ngữ “The old market” (Chợ cũ), động từ “destroy” (phá hủy) =&gt; câu bị độngCông thức dạng bị động: S + am/is/are + said + to have been + P2Tạm dịch: Chợ cũ được cho là đã bị phá hủy trong một vụ hỏa hoạn hai năm trước.', 23);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
