INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(732, 'Nylon ______________ in the 1930s', 'SINGLE_CHOICE', '{"A": "invented", "B": "was invented", "C": "is invented", "D": "has been invented"}', 'A', 'in the 1930s là mốc thời gian đã qua nên chia quá khứ đơn. Nylon không thể tự làm ra nó nên ta chia bị động.', 25);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
