(822, 'Sau 16 năm lãnh đạo cách mạng Việt Nam, lần đầu tiên Đảng đã tuyên bố ra hoạt động công khai và tiến hành. Đó là Đại hội lần thứ mấy?', 'SINGLE_CHOICE', '{"A": "Đại hội Đại hội Đảng toàn quốc lần thứ nhất.", "B": "Đại hội Đại hội Đảng toàn quốc lần thứ hai.", "C": "Đại hội Đại hội Đảng toàn quốc lần thứ ba.", "D": "Cả ba phương án đều sai."}', 'A', '', 28);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
