(1019, 'Miền có frông đi qua thường mưa nhiều do đâu?', 'SINGLE_CHOICE', '{"A": "dọc các frông có gió to, đẩy không khí lên cao gây mưa", "B": "frông tiêp xúc với bề mặt đất, dẫn đến nhiễu loạn không khí gây mưa", "C": "dọc các frông là nới chưa nhiều hơi nước nên gây mưa", "D": "có sự tranh chấp giữa khối khí nóng và khối khí lạnh, dẫn đến nhiễu loạn không khí gây ra mưa"}', 'D', 'Miền có frông đi qua thường mưa nhiều do có sự tranh chấp giữa khối khí nóng và khối khí lạnh, dẫn đến nhiễu loạn không khí gây ra mưaChọn D', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1020, 'Hệ quả vận động theo phương thẳng đứng là gì?', 'SINGLE_CHOICE', '{"A": "làm cho các lớp đất đá bị gãy, đứt ra rồi chuyển dịch ngược hướng nhau", "B": "làm cho đất đá bị di chuyển từ chỗ cao xuống chỗ thấp", "C": "làm cho bộ phận này của lục địa được nâng lên, bộ phận khác bị hạ xuống", "D": "làm cho các lớp đất đá bị uốn thành nếp nhưng không phá vỡ tính chất liên tục của chúng"}', 'C', 'Hệ quả vận động theo phương thẳng đứng là làm cho bộ phận này của lục địa được nâng lên, bộ phận khác bị hạ xuốngChọn C', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1021, 'Nhiệt độ không khí thay đổi theo bờ Đông và bờ Tây của lục địa là do đâu?', 'SINGLE_CHOICE', '{"A": "chế độ gió thổi ở hai bờ Đông và Tây các lục địa khác nhau", "B": "hai bờ Đông và Tây của lục địa có độ cao khác nhau", "C": "hai bờ Đông và Tây của lục địa có góc chiếu của tía bức xạ mặt trời khác nhau", "D": "ảnh hưởng của dòng biển nóng và lạnh ở hai bờ Đông và Tây khác nhau"}', 'D', 'Nhiệt độ không khí thay đổi theo bờ Đông và bờ Tây của lục địa là do ảnh hưởng của dòng biển nóng và lạnh ở hai bờ Đông và Tây khác nhauChọn D', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1022, 'Ở mỗi bán cầu, từ vĩ độ thấp lên vĩ độ cao lần lượt là các khối khí nào?', 'SINGLE_CHOICE', '{"A": "chí tuyến, cực, ôn đới, xích đạo", "B": "cực, chí tuyến, ôn đới, xích đạo", "C": "xích đạo, chí tuyến, ôn đới, cực", "D": "cực, ôn đới, chí tuyến, xích đạo"}', 'C', 'Ở mỗi bán cầu, từ vĩ độ thấp lên vĩ độ cao lần lượt là các khối khí xích đạo, chí tuyến, ôn đới, cựcChọn C', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1023, 'Do Trái Đất hình cầu và tự quay quanh trục từ Tây sang Đông nên trong cùng một thời điểm sẽ thay đổi thế nào?', 'SINGLE_CHOICE', '{"A": "Người đứng ở các vĩ tuyến khác nhau sẽ nhìn thấy mặt trời ở độ cao khác nhau", "B": "Người đứng ở các kinh tuyến khác nhau sẽ nhìn thấy mặt trời ở độ cao khác nhau", "C": "Ở phía Tây sẽ thấy Mặt Trời xuất hiện sớm hơn", "D": "Mọi nơi trên Trái Đất sẽ thấy vị trí của Mặt Trời trên bầu trời giống nhau"}', 'B', 'Do Trái Đất hình cầu và tự quay quanh trục từ Tây sang Đông nên trong cùng một thời điểm thì người đứng ở các kinh tuyến khác nhau sẽ nhìn thấy mặt trời ở độ cao khác nhauChọn B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1024, 'Một trận bóng đá diễn ra lúc 18h30 ngày 31/12/2019 tại Anh thì lúc đó, nếu chúng ta xem truyền hình trực tiếp tại Việt Nam là mấy giờ, ngày, tháng năm nào? (Biết Việt Nam ở múi giờ số 7)', 'SINGLE_CHOICE', '{"A": "1h30’ ngày 31/12/2019", "B": "11h30’ ngày 31/12/2019", "C": "1h30’ ngày 1/1/2020", "D": "11h30’ ngày 1/1/2020"}', 'C', 'Một trận bóng đá diễn ra lúc 18h30 ngày 31/12/2019 tại Anh thì lúc đó, nếu chúng ta xem truyền hình trực tiếp tại Việt Nam là 1h30’ ngày 1/1/2020Chọn C', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1025, 'Quá trình phong hóa là gì?', 'SINGLE_CHOICE', '{"A": "quá trình phá hủy, làm biến đổi các loại đá và khoáng vật", "B": "quá trình tích tụ các sản phẩm đã bị phá hủy, biến đổi", "C": "quá trình làm các sản phẩm đã bị phá hủy, biến đổi dời khỏi vị trí ban đầu", "D": "quá trình di chuyển các sản phẩm đã bị phá hủy, biến đổi từ nơi này đến nơi khác"}', 'A', 'Quá trình phong hóa là quá trình phá hủy, làm biến đổi các loại đá và khoáng vậtChọn A', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1026, 'Ở khoảng 300 vĩ Bắc và Nam, tồn tại đai khí áp nào?', 'SINGLE_CHOICE', '{"A": "Áp thấp xích đạo", "B": "Áp cao cận nhiệt", "C": "Áp cao cận cực", "D": "Áp thấp ôn đới"}', 'B', 'Ở khoảng 300 vĩ Bắc và Nam, tồn tại đai khí áp cao cận nhiệtChọn B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1027, 'Nếu ở chân sườn đón gió nhiệt độ là 300C, thì ở đỉnh núi với độ cao 2500m, nhiệt độ là bao nhiêu độ C?', 'SINGLE_CHOICE', '{"A": "10 0C", "B": "15 0C", "C": "18 0C", "D": "240C"}', 'B', 'Nếu ở chân sườn đón gió nhiệt độ là 300C, thì ở đỉnh núi với độ cao 2500m, nhiệt độ là 15 0CChọn B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1028, 'Nhận định nào sau đây không đúng về ngày, đêm theo mùa và theo vĩ độ ở bán cầu Bắc?', 'SINGLE_CHOICE', '{"A": "Mùa hạ ngày dài hơn đêm", "B": "Càng xa xích đạo chênh lệch ngày, đêm càng lớn", "C": "Càng gần cực ngày, đêm địa cực càng tăng", "D": "Ngày dài nhất trong năm là ngày Đông chí"}', 'D', 'Ngày dài nhất trong năm là ngày Đông chí là nhận định không đúng về ngày, đêm theo mùa và theo vĩ độ ở bán cầu BắcChọn D', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1029, 'Cho biểu đồ:CƠ CẤU LAO ĐỘNG ĐANG LÀM VIỆC PHÂN THEO THÀNH PHẦNKINH TẾ CỦA VIỆT NAM, NĂM 2005 VÀ NĂM 2015(Số liệu theo Niên giám thống kê Việt Nam 2016, NXB Thống kê, 2017)Theo biểu đồ, nhận xét nào sau đây đúng về sự thay đổi tỉ trọng lao động đang làm việc phân theo thành phần kinh tế của nước ta năm 2015 so với năm 2005?', 'SINGLE_CHOICE', '{"A": "Khu vực có vốn đầu tư nước ngoài tăng, kinh tế ngoài Nhà nước giảm", "B": "Khu vực kinh tế Nhà nước tăng, khu vực ngoài Nhà nước giảm", "C": "Khu vực có vốn đầu tư nước ngoài giảm, khu vực kinh tế ngoài Nhà nước tăng", "D": "Khu vực kinh tế Nhà nước giảm, khu vực ngoài Nhà nước tăng"}', 'D', 'Theo biểu đồ thì khu vực kinh tế Nhà nước giảm, khu vực ngoài Nhà nước tăng là đúngChọn D', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1030, 'Đặc điểm của gió Tây ôn đới là gì?', 'SINGLE_CHOICE', '{"A": "thổi quanh năm, độ ẩm rất cao, thường mang theo mưa", "B": "thổi vào mùa đông, gió lạnh và ẩm", "C": "thổi quanh năm, gió lạnh và độ ẩm thấp", "D": "thổi vào mùa hạ, gió nóng và ẩm"}', 'A', 'Đặc điểm của gió Tây ôn đới là thổi quanh năm, độ ẩm rất cao, thường mang theo mưa.Chọn A', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1031, 'Nhận định nào dưới đây đúng khi nói về khí áp?', 'SINGLE_CHOICE', '{"A": "Khí áp tăng khi độ ẩm không khí tăng", "B": "Khí áp giảm khi độ ẩm không khí tăng", "C": "Khí áp tăng hoặc sẽ giảm làm độ ẩm không khí tăng hoặc giảm theo", "D": "Giữa khí áp và độ ẩm không khí không có mối quan hệ nào"}', 'B', 'Khí áp giảm khi độ ẩm không khí tăng là nhận xét đúngChọn B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1032, 'Cho bảng số liệu sau:DÂN SỐ VIỆT NAM TỪ NĂM 1979 – 2014 (đơn vị: triệu tấn)Năm197919891999200920112014Dân số nông thôn42,3751,4958,5260,4459,9560,69Dân số thành thị10,0912,9218,0825,5827,8830,03Nhận xét nào sau đâu là không đúng với bảng số liệu trên?', 'SINGLE_CHOICE', '{"A": "Tỉ lệ dân thành thị tăng nhanh nhưng chiếm tỉ trọng thấp", "B": "Tỉ lệ dân nông thôn có xu hướng giảm nhưng chiếm tỉ trọng cao", "C": "Tỉ lệ dân thành thị tăng, giảm tỉ lệ dân nông thôn giảm", "D": "Tỉ lệ dân nông thôn tăng nhanh và chiếm tỉ lệ cao"}', 'D', 'Tỉ lệ dân thành thị tăng nhanh và chiếm tỉ lệ cao ⇒ D saiChọn D', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1033, 'Những dòng biển phát sinh từ hai bên xích đạo chảy theo hướng tây, gặp lục địa chuyển hướng chảy về phía cực là các dòng biển nào?', 'SINGLE_CHOICE', '{"A": "Dòng lạnh", "B": "Dòng nóng", "C": "Dòng phản lưu", "D": "Các dòng biển"}', 'A', 'Những dòng biển nóng thường phát sinh từ hai bên xích đạo chảy theo hướng tây, gặp lục địa chuyển hướng chảy về phía cực.Chọn: B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1034, 'Sóng ngắn gió thổi mạnh đập vào nhau, vỡ tung téo tạo bọt trắng tạo thành: dạng sóng gì?', 'SINGLE_CHOICE', '{"A": "Sóng lừng", "B": "Sóng bạc đầu", "C": "Sóng nhọn đầu", "D": "Sóng thần"}', 'A', 'Sóng ngắn gió thổi mạnh đập vào nhau, vỡ tung téo tạo bọt trắng tạo thành sóng bạc đầu.Chọn: B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1035, 'Dựa vào tính chất các nguồn nước người ta chia thành hai loại hồ nào?', 'SINGLE_CHOICE', '{"A": "Hồ nước ngọt và hồ nước mặn", "B": "Hồ nước ngọt và hồ nước lợ", "C": "Hồ nước trong và hồ nước đục", "D": "Hồ nước ngọt và hồ nước khoáng"}', 'A', 'Dựa vào tính chất các nguồn nước người ta chia thành hai loại hồ là: Hồ nước ngọt và hồ nước mặn.Chọn: A', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1036, 'Những hoạt động nào sau đây của con người tác động đến sự hình thành đất?', 'SINGLE_CHOICE', '{"A": "Sản xuất nông nghiệp", "B": "Hoạt động sản xuất của nhà máy", "C": "Hoạt động giao thông vận tải", "D": "Các hoạt động vui chơi, giải trí"}', 'A', 'Những hoạt động của con người tác động đến sự hình thành đất là các hoạt động sản xuất nông nghiệp. Điển hình như làm ruộng, trồng cây hoa màu,…Chọn: A', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1037, 'Các địa quyển có sự tiếp xúc với thổ nhưỡng quyển là gì?', 'SINGLE_CHOICE', '{"A": "Khí quyển, thạch quyển, sinh quyển, thủy quyển", "B": "Khí quyển, thạch quyển, sinh quyển", "C": "Khí quyển, thạch quyển, thủy quyển", "D": "Thạch quyển, sinh quyển, thủy quyển"}', 'A', 'Các địa quyển có sự tiếp xúc với thổ nhưỡng quyển là khí quyển, thạch quyển và sinh quyển.Chọn: B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1038, 'Đặc điểm tầng đất ở vùng có địa hình dốc là gì?', 'SINGLE_CHOICE', '{"A": "Mỏng", "B": "Thường bị bạc màu", "C": "Xói mòn, xâm thực mạnh", "D": "Nhiệt đới và ôn đới"}', 'A', 'Đặc điểm tầng đất ở vùng có địa hình dốc là nhiệt đới và ôn đới.Chọn: D', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1039, 'Biểu hiện của quy luật đai cao là sự thay đổi các thảm thực vật theo yếu tố nào?', 'SINGLE_CHOICE', '{"A": "Vĩ độ", "B": "Độ cao", "C": "Kinh độ", "D": "Xích đạo về cực"}', 'A', 'Biểu hiện của quy luật đai cao là sự thay đổi các thảm thực vật theo độ cao.Chọn: B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1040, 'Nông nghiệp trở thành một ngành sản xuất hàng hoá dẫn đến việc hình thành vùng nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Vùng nông nghiệp xuất khẩu", "B": "Vùng chuyên môn hoá nông nghiệp", "C": "Vùng sản xuất nông sản", "D": "Vùng thâm canh, tăng vụ"}', 'A', 'Nông nghiệp trở thành một ngành sản xuất hàng hoá dẫn đến việc hình thành các vùng chuyên môn hoá nông nghiệp.Chọn: B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1041, 'Với sự phát triển kinh tế – xã hội của một quốc gia nguồn lực có vai trò quyết định là gì?', 'SINGLE_CHOICE', '{"A": "Ngoại lực", "B": "Nội lực", "C": "Vị trí địa lí", "D": "Tài nguyên thiên nhiên"}', 'A', 'Với sự phát triển kinh tế – xã hội của một quốc gia nguồn lực có vai trò quyết định là nội lực (các nguồn tài nguyên thiên nhiên, kinh tế - xã hội, vị trí địa lí,...).Chọn: B', 34);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1042, 'Ý nào dưới đây không đúng&nbsp;về vai trò của nguồn lực tự nhiên?', 'SINGLE_CHOICE', '{"A": "Là cơ sở tự nhiên của quá trình sản xuất", "B": "Vừa phục vụ trực tiếp cho cuộc sống, vừa phục vụ phát triển kinh tế", "C": "Quyết định sự phát triển của nền kinh tế và xã hội loài người", "D": "Sự giàu có, đa dạng về tài nguyên thiên nhiên tạo lợi thế cho sự phát triển"}', 'A', 'Nguồn lực tự nhiên có vai trò là cơ sở tự nhiên của quá trình sản xuất, vừa phục vụ trực tiếp cho cuộc sống lại vừa phục vụ phát triển kinh tế và sự giàu có, đa dạng về tài nguyên thiên nhiên tạo lợi thế quan trọng cho sự phát triển.Chọn: C', 34);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(35, 'Đề thi thử THPT QG năm 2022 môn Địa Lí online - Đề thi của Trường THPT Nguyễn Trân', 'Toán', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Toán. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1043, 'Xác định Việt Nam có chung Biển Đông với bao nhiêu nước?', 'SINGLE_CHOICE', '{"A": "7 nước", "B": "9 nước", "C": "8 nước", "D": "10 nước"}', 'C', 'Việt Nam có chung biển Đông với 8 nước: Trung Quốc, Thái Lan, Campuchia, Ma-lai-xi-a, In-đô-nê-xi- a, Xin ga-po, Bru-nây, Phi-lip-pin.Chọn C.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1044, 'Em hãy xác định mưa phùn là loại mưa?', 'SINGLE_CHOICE', '{"A": "Diễn ra vào đầu mùa đông ở miền Bắc", "B": "Diễn ra ở đồng bằng và ven biển miền Bắc vào đầu mùa đông", "C": "Diễn ra vào nửa sau mùa đông ở miền Bắc", "D": "Diễn ra ở đồng bằng và ven biển miền Bắc vào nửa sau mùa đông"}', 'D', 'Mưa phùn là loại mưa diễn ra ở đồng bằng và ven biển miền Bắc vào nửa sau mùa đông.Chọn D', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1045, 'Cho biết đặc điểm nào không đúng với địa hình của đồng bằng sông Hồng?', 'SINGLE_CHOICE', '{"A": "Do phù sa sông Hồng và sông Tiền bồi đắp", "B": "Bị chia cắt mạnh bởi hệ thống để điều", "C": "Cao ở rìa phía tây và tây bắc, thấp dần ra biển", "D": "Vùng trong để không được bồi tụ phù sa, ngoài để được bồi tụ phù sa hàng năm"}', 'A', 'Đồng bằng sông Hồng được bồi đắp bởi phù sa của hệ thống sông Hồng và sông Thái Bình. Nhận định sống Tiền bồi đắp phù sa cho ĐBSH là sai.Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1046, 'Đâu là đặc trưng khí hậu từ Bạch Mã trở vào?', 'SINGLE_CHOICE', '{"A": "có hai mùa: một mùa nóng và một mùa lạnh", "B": "nhiệt độ trung bình năm trên 25°C và không có tháng nào dưới 200C", "C": "có hai mùa: mùa mưa ít và mùa mưa nhiều", "D": "không có mùa đông rõ rệt, chỉ có hai thời kỳ chuyển tiếp"}', 'B', 'Từ dãy Bạch Mã trở vào có khí hậu mang tính chất cận xích đạo nắng nóng quanh năm, nhiệt độ trung bình năm trên 25°C và không có tháng nào dưới 20°C. (SGK/48 Địa 12)Chọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1047, 'Cho biết cơ cấu GDP phân theo khu vực kinh tế của các nước phát triển có đặc điểm?', 'SINGLE_CHOICE', '{"A": "Khu vực I và III cao, khu vực II thấp", "B": "Khu vực I rất thấp, khu vực III rất cao", "C": "Khu vực Irất thấp, khu vực II và III cao", "D": "Khu vực II rất cao, khu vực I và III thấp."}', 'B', 'Cơ cấu GDP phân theo khu vực kinh tế của các nước phát triển có đặc điểm là khu vực I (nông nghiệp) chiếm tỉ trọng rất thấp, dưới 5%; khu vực III (dịch vụ) chiếm tỉ trọng rất cao, trên 70%.Chọn B.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1048, 'Để gia tăng tự nhiên dân số nước ta từ giữa thế kỉ XX trở về trước thấp là do?', 'SINGLE_CHOICE', '{"A": "tỉ suất sinh thấp, tỉ suất từ thấp", "B": "tỉ suất sinh thấp, tỉ suất tử cao.", "C": "tỉ suất tăng cơ học thấp", "D": "tỉ suất sinh cao, tỉ suất tử cũng cao"}', 'D', 'Gia tăng tự nhiên – Sinh – Tử Gia tăng tự nhiên dân số nước ta từ giữa thế kỉ XX trở về trước thấp là do đây là thời kì chiến tranh nên tỉ suất tử lớn, trong khi đó dân số vẫn tăng lên do tỉ lệ sinh cao để bù đắp và bổ sung lực lượng chiến đấu =&gt; tỉ suất sinh cao, tỉ suất tử cũng cao nên gia tăng tự nhiên thấp.Chọn D', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1049, 'Cho biết sự đối lập về mùa mưa và mùa khô của Tây Nguyên và Đông Trường Sơn là biểu hiện của sự phân hóa thiên nhiên?', 'SINGLE_CHOICE', '{"A": "theo Bắc – Nam", "B": "theo mùa", "C": "theo Đông - Tây", "D": "theo độ cao"}', 'C', 'Sự đối lập về mùa mưa và mùa khô của Tây Nguyên và Đông Trường Sơn là biểu hiện của sự phân hóa thiên nhiên theo chiều Đông - Tây: khi Đông Trường Sơn là mùa mưa vào thu đông thì Tây Nguyên là mùa khô và ngược lại (SGK/50 Địa 12)Chọn C', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1050, 'Cho biết sự phát triển của các ngành công nghiệp nào sau đây góp phần quyết định việc Trung Quốc chế tạo thành công tàu vũ trụ?', 'SINGLE_CHOICE', '{"A": "Điện, luyện kim, cơ khí", "B": "Điện, chế tạo máy, cơ khí chính xác", "C": "Điện tử, luyện kim, cơ khí chính xác", "D": "Điện tử, cơ khí chính xác, sản xuất máy móc tự động"}', 'D', 'Sự phát triển của các ngành công nghiệp kĩ thuật cao như điện tử, cơ khí chính xác, sản xuất máy móc tự động đã góp phần quyết định việc Trung Quốc chế tạo thành công tàu vũ trụ. (SGK/94 Địa 11)Chọn D.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1051, 'Xác định: Yếu tố ảnh hưởng trực tiếp khiến phần lớn sông ngòi ở nước ta mang đặc điểm nhỏ, ngắn và độ dốc lớn là?', 'SINGLE_CHOICE', '{"A": "hình dáng lãnh thổ và khí hậu", "B": "hình dáng lãnh thổ và sự phân bố địa hình", "C": "khí hậu và sự phân bố địa hình.", "D": "địa hình, sinh vật và thổ nhưỡng."}', 'B', 'Yếu tố ảnh hưởng trực tiếp khiến phần lớn sông ngòi ở nước ta mang đặc điểm nhỏ, ngắn và độ dốc lớn là hình dáng lãnh thổ và sự phân bố địa hình:- Lãnh thổ hẹp ngang, hướng nghiêng Tây Bắc - Đông Nam khiến phần lớn sông ngòi nước ta ngắn, nhỏ (chỉ có một số sông lớn).- Địa hình bị cắt xẻ mạnh, % diện tích là đồi núi nên sông ngòi có độ dốc lớn, nhiều thác ghềnh.Chọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1052, 'Cho biết các nước đang phát triển phụ thuộc vào các nước phát triển ngày càng nhiều về?', 'SINGLE_CHOICE', '{"A": "Vốn, khoa học kĩ thuật – công nghệ", "B": "Thị trường", "C": "Lao động", "D": "Nguyên liệu"}', 'A', 'Xu hướng toàn cầu hóa khiến các nước đang phát triển và các nước phát triển có cơ hội hợp tác phát triển và giao lưu kinh tế. Đặc biệt thông qua các nguồn vốn đầu tư nước ngoài (FDI, ODA) và sự đầu tư của các tập đoàn đa quốc gia tại các nước đang phát triển =&gt; Điều này cho thấy các nước đang phát triển phụ thuộc vào các nước phát triển ngày càng nhiều về nguồn vốn và khoa học – kĩ thuật .Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1053, 'Đâu là nguyên nhân cơ bản khiến tỉ lệ thất nghiệp ở khu vực thành thị nước ta còn khá cao?', 'SINGLE_CHOICE', '{"A": "tính chất mùa vụ của sản xuất nông nghiệp, nghề phụ kém phát triển", "B": "tốc độ phát triển ngành kinh tế chưa tương xứng tốc độ tăng dân số", "C": "thu nhập của người dân thấp, chất lượng cuộc sống không cao", "D": "cơ sở hạ tầng, mạng lưới giao thông kém phát triển"}', 'B', 'Nguyên nhân cơ bản khiến tỉ lệ thất nghiệp ở khu vực thành thị nước ta còn khá cao là do tốc độ phát triển ngành kinh tế chưa tương xứng tốc độ tăng dân số. Dân số thành thị tăng nhanh, trong khi cơ cấu kinh tế chuyển dịch còn chậm, tỉ trọng ngành công nghiệp - xây dựng và dịch vụ còn thấp khiến không đủ đáp ứng yêu cầu về việc làm cho nguồn lao động =&gt; dẫn đến tỉ lệ thất nghiệp tăng cao.Chọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1054, 'Cho biểu đồTỈ LỆ THẤT NGHIỆP VÀ THIẾU VIỆC LÀM CỦA CÁC VÙNG NƯỚC TA NĂM 2012Căn cứ vào biểu đồ, cho biết nhận xét nào sau đây không đúng về tỉ lệ thất nghiệp và thiếu việc làm của các vùng năm 2012?', 'SINGLE_CHOICE', '{"A": "Tây Nguyên có tỉ lệ thất nghiệp và thiếu việc làm cao hơn cả nước", "B": "Đồng bằng sông Cửu Long có tỉ lệ thiếu việc làm cao nhất cả nước", "C": "Trung du và miền núi Bắc Bộ có tỉ lệ thất nghiệp thấp nhất cả nước", "D": "Tỉ lệ thất nghiệp và thiếu việc làm khác nhau giữa các vùng."}', 'A', 'Biểu đồ cho thấy: Tây Nguyên có tỉ lệ thất nghiệp thấp hơn mức trung bình cả nước (1,47% &lt; 1,96%)=&gt; Nhận định: Tây Nguyên có tỉ lệ thất nghiệp và thiếu việc làm cao hơn cả nước là không đúng =&gt; A saiChọn A.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1055, 'Cho biết nhiệt độ Trái Đất ngày càng tăng lên là do sự gia tăng chủ yếu của chất khí nào trong khí quyển?', 'SINGLE_CHOICE', '{"A": "O3", "B": "CH4", "C": "CO2", "D": "N2O"}', 'C', 'Khí CO2 có khả năng hấp thụ nhiệt, do vậy hoạt động công nghiệp làm gia tăng chất khí CO2 trong khí quyển là nguyên nhân chủ yếu khiến nhiệt độ Trái Đất ngày càng tăng lên.Chọn C', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1056, 'Theo Atlat Địa lí Việt Nam trang 6-7, cho biết vùng nào ở nước ta có nhiều bãi cát nhất?', 'SINGLE_CHOICE', '{"A": "Bắc Trung Bộ", "B": "Đồng bằng sông Cửu Long.", "C": "Đồng bằng sông Hồng", "D": "Duyên hải Nam Trung Bộ."}', 'A', 'Dựa vào Atlat Địa lí Việt Nam trang 6-7, xác định được vùng Bắc Trung Bộ là khu vực có nhiều bãi cát nhất nước ta, khu vực này thường xuyên chịu ảnh hưởng của nạn cát bay, cát chảy.Chọn A.&nbsp;', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1057, 'Có bao nhiêu phát biểu đúng về đặc điểm dân cư - xã hội của các châu lục và khu vực1. Châu Phi có gia tăng tự nhiên cao, trình độ dân trí thấp, nhiều hủ tục, xung đột sắc tộc, đói nghèo, bệnh tật.2. Mĩ La Tinh có tỉ lệ dân cư nghèo đói cao, khu vực có sự phân hóa giàu - nghèo rất lớn, tỉ lệ dân thành thị thấp dưới 50%3. Tây Nam Á dân cư chủ yếu theo đạo Thiên Chúa, thời cổ đại xuất hiện nhiều quốc gia có nền văn minh rực rỡ.4. Trung Á là khu vực đa dân tộc, có mật độ dân số thấp, từng có “con đường tơ lụa đi qua”.', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "3", "D": "4"}', 'B', 'Xét lần lượt các nhận định:1. Châu Phi có gia tăng tự nhiên cao, trình độ dân trí thấp, nhiều hủ tục, xung đột sắc tộc, đói nghèo, bệnh tật. (SGK/21 Địa 11) =&gt; Đúng2. Mĩ La Tinh có tỉ lệ dân cư nghèo đói cao, khu vực có sự phân hóa giàu - nghèo rất lớn, tỉ lệ dân thành thị thấp dưới 50% (SGK/25 Địa 11)=&gt; Sai, vì tỉ lệ dân thành thị của Mĩ La tinh rất cao (trên 70%)3. Tây Nam Á dân cư chủ yếu theo đạo Thiên Chúa, thời cổ đại xuất hiện nhiều quốc gia có nền văn minh rực rỡ.(SGK/29 Địa 11)=&gt; Sai, vì dân cư Tây Nam Á chủ yếu theo đạo Hồi.4. Trung Á là khu vực đa dân tộc, có mật độ dân số thấp, từng có “con đường tơ lụa đi qua” (SGK/30 Địa 11)=&gt; Đúng Như vậy có 2 nhận định đúngChọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1058, 'Cho biết chất lượng nguồn lao động nước ta ngày càng được nâng cao là nhờ?', 'SINGLE_CHOICE', '{"A": "phát triển công nghiệp, dịch vụ ở nông thôn", "B": "số lượng lao động làm việc trong các công ty liên doanh tăng lên", "C": "những thành tựu trong phát triển văn hoá, giáo dục, y tế", "D": "mở thêm nhiều trung tâm đào tạo, hướng nghiệp"}', 'C', 'Chất lượng nguồn lao động nước ta ngày càng được nâng cao là nhờ những thành tựu trong phát triển văn hoá, giáo dục, y tế.Chọn C', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1059, 'Cho biết biện pháp nào sau đây nhằm nâng cao chất lượng nguồn lao động nước ta?', 'SINGLE_CHOICE', '{"A": "Nâng cao thể trạng người lao động", "B": "Bố trí lại nguồn lao động giữa các vùng cho hợp lí", "C": "Tăng cường xuất khẩu lao động", "D": "Đa dạng hóa các loại hình đào tạo người lao động"}', 'D', 'Biện pháp nhằm nâng cao chất lượng nguồn lao động nước ta là đa dạng hóa các loại hình đào tạo người lao động, nhằm nâng cao chất lượng đội ngũ lao động để họ có thể tự tạo những công việc hoặc tham gia vào các đơn vị sản xuất dễ dàng, thuận lợi hơn. (SGK/76 Địa 12)Chọn D.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1060, 'Cho biết mùa đông đỡ lạnh, mùa hạ nóng, thường có mưa to, bão là đặc điểm khí hậu của?', 'SINGLE_CHOICE', '{"A": "đảo Kiu-xiu", "B": "các đảo nhỏ phía bắc Nhật Bản", "C": "đảo Hôn – su", "D": "đảo Hô-cai-đô"}', 'A', 'Mùa đông đỡ lạnh, mùa hạ nóng, thường có mưa to, bão là đặc điểm khí hậu của đảo Kiu – xiu nằm ở phía nam lãnh thổ Nhật Bản. (SGK/76 Địa 11)Chọn A.&nbsp;', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1061, 'Xác định: Thổ nhưỡng trên các đai cao cận nhiệt đới gió mùa và ôn đới gió mùa chủ yếu ?', 'SINGLE_CHOICE', '{"A": "đất xám và đất feralit nâu đỏ", "B": "đất đen và đất phù sa cổ", "C": "đất feralit có mùn và đất mùn thô", "D": "đất feralit có mùn và đất đen"}', 'C', 'Thổ nhưỡng trên các đai cao cận nhiệt đới gió mùa và ôn đới gió mùa chủ yếu là đất feralit có mùn và đất mùn thô. (SGK/52 Địa 12)Chọn C&nbsp;', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1062, 'Theo Atlat Địa lí Việt Nam trang 15, cho biết nhận xét nào sau đây không đúng với tháp dân số của nước ta?', 'SINGLE_CHOICE', '{"A": "Tỉ lệ người trên 65 tuổi năm 2007 ít hơn năm 1999.", "B": "Cơ cấu dân số của tháp dân số năm 1999 là dân số trẻ.", "C": "Cơ cấu dân số nước ta đang có xu hướng già hóa", "D": "Tỉ lệ người từ 0 - 14 tuổi năm 1999 nhiều hơn năm 2007."}', 'A', 'Quan sát tháp dân số năm 1999 và 2007 ở Atlat Địa lí trang 15: Đỉnh tháp năm 2007 có xu hướng mở rộng hơn năm 1999 =&gt; cho thấy tỉ lệ người gia trên 65 tuổi tăng. Như vậy nhận xét tỉ lệ người trên 65 tuổi năm 2007 ít hơn năm 1999 là không đúng.Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1063, 'Cho biết: Phía Đông là hệ thống núi cao đồ sộ, phía Tây là các núi trung bình, ở giữa là các dãy núi thấp và sơn nguyên. Đó là đặc điểm địa hình của vùng?', 'SINGLE_CHOICE', '{"A": "Đông Bắc", "B": "Trường Sơn Nam", "C": "Trường Sơn Bắc", "D": "Tây Bắc"}', 'D', 'Phía Đông là hệ thống núi cao đồ sộ, phía Tây là các núi trung bình, ở giữa là các dãy núi thấp và sơn nguyên. Đó là đặc điểm địa hình của vùng Tây Bắc (SGK/30 Địa lí 12)Chọn D', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1064, 'Hãy cho biết đường biên giới của nước ta dài 4600 km giáp với các nước:', 'SINGLE_CHOICE', '{"A": "Trung Quốc, Thái Lan, Campuchia", "B": "Lào, Thái Lan, Campuchia", "C": "Trung Quốc, Campuchia, Lào", "D": "Trung Quốc, Thái Lan, Campuchia, Lào"}', 'C', 'Đường biên giới của nước ta dài 4600 km giáp với các nước: Trung Quốc (hơn 1400km), Lào (gần 2100km) và Campuchia (hơn 1100km).Chọn C.&nbsp;', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1065, 'Đâu là đặc điểm nào sau đây không phải là biểu hiện của toàn cầu hóa kinh tế?', 'SINGLE_CHOICE', '{"A": "Đầu tư nước ngoài tang nhanh.", "B": "Vai trò của các công ty xuyên quốc gia đang bị giảm sút", "C": "Thương mại thế giới phát triển mạnh", "D": "Thị trường tài chính quốc tế mở rộng"}', 'B', 'Biểu hiện của toàn cầu hóa kinh tế là đầu tư nước ngoài tăng nhanh, thương mại thế giới phát triển, thị trường tài chính quốc tế mở rộng và vai trò của các công ty xuyên quốc gia ngày càng lớn (SGK/11 Địa 11) Nhận định: Vai trò của các công ty xuyên quốc gia đang bị giảm sút là không đúngChọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1066, 'Cho biểu đồ:QUY MÔ VÀ CƠ CẤU DIỆN TÍCH LÚA THEO MÙA VỤ CỦA NƯỚC TA, GIAI ĐOẠN 1990 – 2015Căn cứ vào biểu đồ trên, hãy cho biết những nội dung nào sau đây đúng?', 'SINGLE_CHOICE', '{"A": "Tên biểu đồ", "B": "Giá trị trên biểu đồ", "C": "Chú thích", "D": "Khoảng cách năm."}', 'A', 'Dựa theo biểu đồ chú thích đúng.Đáp án C', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1067, 'Đâu là nguyên nhân chủ yếu làm cho dân số nước ta tập trung nhiều ở nông thôn?', 'SINGLE_CHOICE', '{"A": "Địa hình khá bằng phẳng, giáp biển", "B": "Trình độ phát triển kinh tế còn thấp.", "C": "Nông nghiệp thâm canh cần nhiều lao động", "D": "Đô thị chưa tạo ra được sức hút lao động"}', 'B', 'Dân số nước ta tập trung nhiều ở nông thôn, nguyên nhân chủ yếu là do trình độ phát triển kinh tế ở nông thôn còn thấp, chủ yếu là hoạt động sản xuất nông nghiệp, cần nhiều lao động.Chọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1068, 'Khu vực nào không có hiện tượng khác nhau về thời gian ngày và đêm trong năm?', 'SINGLE_CHOICE', '{"A": "chí tuyến Nam", "B": "chí tuyến Bắc", "C": "vòng cực", "D": "Xích đạo"}', 'D', 'Khu vực xích đạo không có hiện tượng khác nhau về thời gian ngày và đêm trong năm. Tại xích đạo độ dài ngày 4 đêm luôn bằng nhau ở mọi thời điểm trong năm. (SGK/24 Địa 10)Chọn D', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1069, 'Cho biết đâu là đặc điểm không đúng với hoạt động của bão ở Việt Nam là?', 'SINGLE_CHOICE', '{"A": "mùa bão thường bắt đầu từ tháng 6 và kết thúc vào tháng 11", "B": "mùa bão chậm dần từ Nam ra Bắc", "C": "70% số cơn bão trong mùa tập trung vào các tháng 8,9,10", "D": "trung bình mỗi năm có 3 - 4 con bão đổ bộ vào vùng bờ biển nước ta"}', 'B', 'Bão ở Việt Nam thường bắt đầu từ tháng 6 và kết thúc vào tháng 11, mùa bão chậm dần từ Bắc vào Nam=&gt; Nhận định B không đúngChọn B.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1070, 'Hãy cho biết người Việt Nam ở nước ngoài tập trung nhiều nhất ở các quốc gia và khu vực?', 'SINGLE_CHOICE', '{"A": "Hoa Ki, Ôxtrâylia, châu Âu", "B": "Bắc Mỹ, châu Âu, Nam Á.", "C": "Bắc Mĩ, Ôxtrâylia, Đông Á", "D": "châu Âu, Ôxtrâylia, Trung Á"}', 'A', 'Người Việt Nam ở nước ngoài tập trung nhiều nhất ở các quốc gia và khu vực là: Hoa Kì, Ôxtrâylia, châu Âu.(SGK/67 Địa 12)Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1071, 'Cho biết tỉ trọng các ngành công nghiệp nào của Hoa Kì có xu hướng tăng?', 'SINGLE_CHOICE', '{"A": "Gia công đồ nhựa, điện tử", "B": "Hàng không- vũ trụ, luyện kim", "C": "Luyện kim, gia công đồ nhựa", "D": "Hàng không - vũ trụ, điện tử"}', 'D', 'Ở Hoa Kì, tỉ trọng các ngành công nghiệp hiện đại như hàng không - vũ trụ, điện tử có xu hướng tăng lên, tỉ trọng các ngành công nghiệp truyền thống như luyện kim, dệt may, gia công đồ nhựa giảm (SGK/43 Địa 11)Chọn D.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1072, 'Đâu là đặc điểm không đúng với quá trình đô thị hoá ở nước ta?', 'SINGLE_CHOICE', '{"A": "Diễn ra chậm chạp, còn ở mức rất thấp so với các nước trên thế giới.", "B": "Diễn ra phức tạp và lâu dài.", "C": "Tỉ lệ dân thành thị thấp.", "D": "Lối sống thành thị phát triển chậm hơn tốc độ đô thị hoá."}', 'D', 'Mặc dù quá trình đô thị hóa nước ta diễn ra chậm và trình độ đô thị hóa còn thấp nhưng lối sống thành thị đã phổ biến và lan rộng khá nhanh. =&gt; nhận định lối sống thành thị phát triển chậm hơn tốc độ đô thị hoá là không đúngChọn D.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1073, 'Cho biết vùng Viễn Đông của Liên Bang Nga có đặc điểm nổi bật?', 'SINGLE_CHOICE', '{"A": "phát triển đóng tàu, cơ khí, đánh bắt và chế biến hải sản.", "B": "có dải đất đen phì nhiêu thuận lợi cho phát triển nông nghiệp", "C": "các ngành luyện kim, cơ khí, khai thác và chế biến dầu khí phát triển", "D": "một vùng kinh tế có sản lượng lương thực, thực phẩm lớn."}', 'A', 'Vùng Viễn Đông của Liên Bang Nga có đặc điểm nổi bật là phát triển các ngành: đóng tàu, cơ khí, đánh bắt và chế biến hải sản. (SGK/71 Địa 11)Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1074, '$27', 'SINGLE_CHOICE', '{"A": "Biểu đồ đường", "B": "Biểu đồ miền", "C": "Biểu đồ cột", "D": "Biểu đồ kết hợp."}', 'C', 'Đề bài yêu cầu thể hiện diện tích” (nghìn ha)- Biểu đồ cột có khả năng thể hiện giá trị, độ lớn của đối tượng=&gt; Để thể hiện diện tích rừng của nước ta trong thời gian trên, biểu đồ cột là thích hợp nhất.Chọn C', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1075, 'Theo Atlat Địa lí Việt Nam trang 10, cho biết sông Hồng có diện tích lưu vực nằm chủ yếu ở những vùng nào của nước ta?', 'SINGLE_CHOICE', '{"A": "Đồng bằng sông Hồng, Bắc Trung Bộ", "B": "Trung du miền núi bắc bộ, đồng bằng sông Hồng", "C": "Trung du miền núi bắc bộ, Bắc Trung Bộ", "D": "Bắc Trung Bộ và Duyên hải Nam Trung Bộ"}', 'B', 'Căn cứ vào Atlat Địa lí Việt Nam trang 10, sông Hồng có diện tích lưu vực nằm chủ yếu ở vùng Trung du miền núi bắc bộ, đồng bằng sông Hồng.Chọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1076, 'Cho biết nguyên nhân chủ yếu nào giúp Đông Nam Á phát triển mạnh cây lúa nước?', 'SINGLE_CHOICE', '{"A": "Khí hậu nhiệt đới gió mùa và cận xích đạo", "B": "Có nhiều cao nguyên đất đỏ badan màu mỡ", "C": "Có dân số đông, nhu cầu tiêu thụ lớn", "D": "Mạng lưới sông ngòi dày đặc với lượng nước dồi dào"}', 'A', 'Đông Nam Á có khi nhiệt đới gió mùa và cận xích đạo với nguồn nhiệt ẩm dồi dào, lượng mưa lớn rất thích hợp cho phát triển cây lúa nước.Chọn A.', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1077, 'Qua Atlat Địa lí Việt Nam trang 15, quy mô dân số đô thị ở Đông Nam Bộ năm 2007 sắp xếp theo thứ tự giảm dần?', 'SINGLE_CHOICE', '{"A": "TP. HCM, Biên Hòa, Thủ Dầu Một, Vũng Tàu", "B": "TP. HCM, Thủ Dầu Một, Biên Hòa, Vũng Tàu.", "C": "TP. HCM, Biên Hòa, Vũng Tàu, Thủ Dầu Một", "D": "TP. HCM, , Vũng Tàu, Biên Hòa, Thủ Dầu Một."}', 'C', 'Căn cứ vào Atlat Địa lí Việt Nam trang 15, quy mô dân số đô thị ở Đông Nam Bộ năm 2007 sắp xếp theo thứ tự giảm dần là TP. HCM, Biên Hòa, Vũng Tàu, Thủ Dầu Một.Chọn C', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1078, 'Qua Atlat Địa lí Việt Nam trang 9, cho biết gió tháng 7 của trạm Đà Lạt có hướng chủ yếu là hướng nào?', 'SINGLE_CHOICE', '{"A": "Tây nam", "B": "Tây", "C": "Đông Nam", "D": "Đông Bắc"}', 'B', 'Căn cứ vào Atlat Địa lí Việt Nam trang 9, xác định kí hiệu gió tháng 7 là kí hiệu các đường tia (hình pháo bông) màu đỏ =&gt; gió tháng 7 của trạm Đà Lạt có hướng chủ yếu là hướng Tây.Chọn B', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1079, 'Đâu là khó khăn của EU khi sử dụng đồng tiền chung?', 'SINGLE_CHOICE', '{"A": "Gây nên tình trạng giá hàng tiêu dùng tăng cao và dẫn tới lạm phát", "B": "Gây trở ngại cho việc chuyển giao vốn trong EU", "C": "Tăng tính rủi ro khi chuyển đổi tiền tệ", "D": "Làm phức tạp hóa công tác kế toán của các doanh nghiệp đa quốc gia"}', 'A', 'Do đồng O-rô có giá trị cao hơn so với đồng tiền của nhiều quốc gia trong khu vực nên khi đưa vào sử dụng chung sẽ khiến giá cả các mặt hàng tăng cao, đồng tiền mất giá và gây nên lạm phát.=&gt; Đây là khó khăn của EU khi sử dụng đồng tiền chung.Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1080, '$28', 'SINGLE_CHOICE', '{"A": "Giá trị xuất khẩu tăng 2,83 lần, giá trị nhập khẩu giảm 4,1 lần.", "B": "Tổng giá trị xuất nhập khẩu tăng liên tục và tăng 2,39 lần.", "C": "Từ 1990 đến 2010, cán cân xuất nhập khẩu có sự biến động,", "D": "Giá trị xuất khẩu luôn lớn hơn giá trị nhập khẩu."}', 'A', '$29', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1081, '$2a', 'SINGLE_CHOICE', '{"A": "Diện tích cao su của Đông Nam Á tăng nhanh hơn của thế giới.", "B": "Diện tích cao su của thế giới tăng mạnh.", "C": "Tốc độ tăng diện tích cao su của Đông Nam Á chậm hơn của thế giới.", "D": "Diện tích cao su Đông Nam Á tăng liên tục"}', 'A', 'Dựa vào BSL ta có 1 số nhận xét về sự thay đổi diện tích cao su của các nước Đông Nam Á và thế giới giai đoạn 1985 – 2013:Diện tích cao su của thế giới tăng mạnh (gấp 3 lần). =&gt; B đúng. Tốc độ tăng diện tích cao su của Đông Nam Á (264,7%) chậm hơn của thế giới (285,7%)=&gt;C đúng, A sai. Diện tích cao su Đông Nam Á tăng liên tục =&gt;D đúng.Chọn A', 35);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1082, 'Miền Tây Bắc và Bắc Trung Bộ không có bộ phận địa hình nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Vùng đội chuyển tiếp nhỏ hẹp.", "B": "Vùng núi cao đồ sộ nhất cả nước", "C": "Vùng núi cao đồ sộ nhất cả nước", "D": "Đồng bằng hạ lưu sông mở rộng, màu mỡ."}', 'D', 'Miền Tây Bắc và Bắc Trung Bộ không có địa hình Đồng bằng hạ lưu sông mở rộng, màu mỡ. Miền chủ yếu có các đồng bằng giữa núi, đồng bằng ven biển nhỏ, hẹp.Chọn D&nbsp;', 35);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(36, 'Đề thi thử THPT QG năm 2021 môn GDCD online - Đề thi của Trường THPT Nguyễn Thị Giang', 'Giáo Dục Công Dân', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Giáo Dục Công Dân. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1083, 'Anh B (có vợ, 2 con nhỏ, bố mẹ già), anh C (không phải nuôi ai) làm việc cùng công ty với mức lương 10 triệu đồng. Anh C phải đóng thuế thu nhập cá nhân còn anh B thì không. Việc đóng thuế của anh C thể hiện điều gì?', 'SINGLE_CHOICE', '{"A": "bình đẳng về trách nhiệm pháp lí.", "B": "bất bình đẳng về trách nhiệm pháp lí.", "C": "bất bình đẳng về thực hiện nghĩa vu trước pháp luật.", "D": "bình đẳng về thực hiện nghĩa vụ trước pháp luật."}', 'A', 'Việc đóng thuế của anh C thể hiện&nbsp;bình đẳng về thực hiện nghĩa vụ trước pháp luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1084, 'Nội dung nào sau đây biểu hiện bất bình đẳng trong hôn nhân và gia đình?', 'SINGLE_CHOICE', '{"A": "Pháp luật yêu cầu với các tài sản có giá trị khi đăng ký quyền sở hữu phải ghi tên cả vợ, chồng.", "B": "Người chồng giao hẳn mọi công việc trong gia đình cho người vợ đảm nhiệm.", "C": "Vợ chồng có quyền về tài sản riêng.", "D": "Vợ, chồng có trách nhiệm như nhau trong nuôi dưỡng và giáo dục con cái."}', 'A', 'Người chồng giao hẳn mọi công việc trong gia đình cho người vợ đảm nhiệm.&nbsp;biểu hiện bất bình đẳng trong hôn nhân và gia đình.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1085, 'Nam thanh niên đủ điều kiện theo qui định của pháp luật mà trốn nghĩa vụ quân sự là không thực hiện pháp luật theo hình thức nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Sử dụng pháp luật.", "B": "Thi hành pháp luật.", "C": "Áp dụng pháp luật.", "D": "Tuân thủ pháp luật"}', 'A', 'Nam thanh niên đủ điều kiện theo qui định của pháp luật mà trốn nghĩa vụ quân sự là không thực hiện pháp luật theo hình thức thi hành pháp luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1086, 'Trong giờ làm việc anh B bị lãnh đạo nhắc nhỡ do bỏ ra ngoài hút thuốc và làm việc riêng.Anh B đã không rút kinh nghiệm, mà anh B còn tỏ thái độ bất cần và chống đối. Anh B phải chịu trách nhiệm pháp lý nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hình sự.", "B": "Dân sự.", "C": "Kỷ luật.", "D": "Hành chính."}', 'A', 'Anh B phải chịu trách nhiệm kỷ luật.Đáp án C', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1087, 'Nội dung nào sau đây thể hiện quyền bình đẳng trong lĩnh vực hôn nhân và gia đình?', 'SINGLE_CHOICE', '{"A": "Tự do lựa chọn nghề nghiệp phù hợp với khả năng của mình.", "B": "Thực hiện đúng các giao kết trong hợp đồng lao động.", "C": "Giữa con đẻ và con nuôi có quyền và nghĩa vụ ngang nhau trong gia đình.", "D": "Đảm bảo quyền lợi hợp pháp của người lao động."}', 'A', 'Giữa con đẻ và con nuôi có quyền và nghĩa vụ ngang nhau trong gia đình&nbsp;thể hiện quyền bình đẳng trong lĩnh vực hôn nhân và gia đình.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1088, 'Hiện nay, nền kinh tế nước ta tồn tại mấy thành phần kinh tế?', 'SINGLE_CHOICE', '{"A": "3 thành phần", "B": "6 thành phần", "C": "4 thành phần", "D": "5 thành phần"}', 'A', 'Hiện nay, nền kinh tế nước ta tồn tại 5&nbsp;thành phần kinh tế.Đáp án D', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1089, 'Quyền nhân thân được hiểu là gì?', 'SINGLE_CHOICE', '{"A": "quyền của những người thân trong gia đình.", "B": "quyền về tài sản và tinh thần gắn với một người cụ thể, có thể chuyển giao.", "C": "quyền của các thành viên trong gia đình.", "D": "là quyền dân sự gắn liền với mỗi cá nhân, không thể chuyển giao cho người khác."}', 'A', 'Quyền nhân thân được hiểu là&nbsp;quyền dân sự gắn liền với mỗi cá nhân, không thể chuyển giao cho người khác.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1090, 'Học sinh tham gia tuyên truyền nâng cao ý thức bảo vệ Tổ quốc là thực hiện nội dung cơ bản của pháp luật trong lĩnh vực nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Quốc phòng, an ninh.", "B": "Kĩ thuật, quân sự.", "C": "Tiếp cận và hội nhập.", "D": "Hợp tác và phát triển."}', 'A', 'Học sinh tham gia tuyên truyền nâng cao ý thức bảo vệ Tổ quốc là thực hiện nội dung cơ bản của pháp luật trong lĩnh vực quốc phòng, an ninh.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1091, 'Nội dung nào sau đây thể hiện bình đẳng trong lao động?', 'SINGLE_CHOICE', '{"A": "Người lao động và người sử dụng lao động cùng thỏa thuận để ký hợp đồng.", "B": "Bình đẳng trong việc hưởng quyền tự do ngôn luận.", "C": "Cùng thực hiện đúng nghĩa vụ tài chính đối với Nhà nước.", "D": "Tự do lựa chọn các hình thức kinh doanh."}', 'A', 'Người lao động và người sử dụng lao động cùng thỏa thuận để ký hợp đồng&nbsp;thể hiện bình đẳng trong lao động.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1092, 'Pháp luật nước ta quy định bình đẳng giữa các tôn giáo nhằm mục đích gì?', 'SINGLE_CHOICE', '{"A": "nhà nước tập trung tạo điều kiện tốt nhất cho một số tôn giáo lớn.", "B": "hạn chế mọi người dân theo tôn giáo.", "C": "khuyến khích mọi người theo tôn giáo.", "D": "thúc đẩy tình đoàn kết keo sơn gắn bó của nhân dân Việt Nam"}', 'A', 'Pháp luật nước ta quy định bình đẳng giữa các tôn giáo nhằm&nbsp;thúc đẩy tình đoàn kết keo sơn gắn bó của nhân dân Việt Nam&nbsp;', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1093, 'Vi phạm kỉ luật là hành vi xâm phạm tới&nbsp;quan hệ nào?', 'SINGLE_CHOICE', '{"A": "quan hệ lao động và công vụ nhà nước.", "B": "quan hệ lao động và quan hệ kinh tế.", "C": "quan hệ tài sản.", "D": "quan hệ xã hội và quan hệ kinh tế."}', 'A', 'Vi phạm kỉ luật là hành vi xâm phạm tới quan hệ lao động và công vụ nhà nước.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1094, 'Vi phạm pháp luật có các dấu hiệu cơ bản nào?', 'SINGLE_CHOICE', '{"A": "Trái luật, có lỗi, do người không có năng lực trách nhiệm pháp lý thực hiện.", "B": "Trái luật, có lỗi, do người có năng lực trách nhiệm pháp lý thực hiện.", "C": "Đúng luật, có lỗi, do mọi người thực hiện.", "D": "Trái luật, có lỗi, do công dân thực hiện."}', 'A', 'Vi phạm pháp luật có các dấu hiệu cơ bản như sau:&nbsp;Trái luật, có lỗi, do người có năng lực trách nhiệm pháp lý thực hiện.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1095, 'Đối với thợ may, đâu là đối tượng lao động?', 'SINGLE_CHOICE', '{"A": "Áo, quần.", "B": "Vải.", "C": "Máy khâu.", "D": "Kim chỉ."}', 'A', 'Đối với thợ may, vải&nbsp;là đối tượng lao động.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1096, 'Trước khi lấy chồng chị S được bố mẹ cho thừa kế ngôi nhà riêng mang tên chị S. Một năm sau khi hội khuyến học của phường liện hệ với chị S muốn mượn ngôi nhà để mở xưởng sản xuất tăm tre, chị S đã đồng ý mặc dù chồng và gia đình chồng không đồng tình.Chị S không vi phạm quyền bình đẳng hôn nhân và gia đình trong quan hệ nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Tài sản.", "B": "Thân nhân.", "C": "Nhân thân.", "D": "Gia đình."}', 'A', 'Chị S không vi phạm quyền bình đẳng hôn nhân và gia đình trong quan hệ tài sản.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1097, 'Tiền tệ thực hiện chức năng thước đo giá trị khi nào?', 'SINGLE_CHOICE', '{"A": "Khi tiền dùng để chi trả sau khi giao dịch mua bán.", "B": "Khi tiền rút khỏi lưu thông và đi vào cất trữ.", "C": "Khi tiền làm phương tiện lưu thông thúc đẩy mua bán hàng hóa.", "D": "Khi tiền dùng để đo lường và biểu hiện giá trị của hàng hóa"}', 'A', 'Khi tiền dùng để đo lường và biểu hiện giá trị của hàng hóaĐáp án D.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1098, '&nbsp;Thị trường bao gồm những nhân tố cơ bản nào?', 'SINGLE_CHOICE', '{"A": "Hàng hóa, tiền tệ, người mua, người bán", "B": "Hàng hóa, người mua, người bán, siêu thị.", "C": "Hàng hóa, tiền tệ, cửa hàng, chợ.", "D": "Người mua, người bán, tiền tệ, trung tâm thương mại."}', 'A', 'Thị trường bao gồm những nhân tố cơ bản như sau: Hàng hóa, tiền tệ, người mua, người bán&nbsp;', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1099, 'Nắm bắt được tâm lý và nhu cầu của người tiêu dùng ở thời điểm cuối mùa, chị B giám đốc điều hành hãng thời trang X quần áo ấm quyết định đồng loạt giảm giá vào giữa mùa đông. Chị B đã vận dụng phù hợp chức năng nào dưới đây của thị trường?', 'SINGLE_CHOICE', '{"A": "Chức năng điều tiết, kích thích sản xuất và tiêu dùng.", "B": "Chức năng thông tin.", "C": "Chức năng quyết định.", "D": "Chức năng thực hiện giá trị sử dụng hay giá trị."}', 'A', 'Chức năng điều tiết, kích thích sản xuất và tiêu dùng.Đáp án A.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1100, 'Sản xuất của cải vật chất giữ vai trò quan trọng đối với sự phát triển của xã hội vì&nbsp;sao?', 'SINGLE_CHOICE', '{"A": "nó là nội dung tồn tại của xã hội.", "B": "đây là hình thức tồn tại của xã hội.", "C": "đây là lí do tồn tại của xã hội.", "D": "nó là cơ sở tồn tại của xã hội."}', 'A', 'Đáp án DSản xuất của cải vật chất giữ vai trò quan trọng đối với sự phát triển của xã hội vì&nbsp;nó là cơ sở tồn tại của xã hội.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1101, 'A và B là bạn cùng lớp do tò mò vì thấy A hay nhắn tin điện thoại nên B lợi dụng lúc A đi ra ngoài đã lấy trộm và cùng với C bạn cùng lớp đọc tin nhắn, không ngờ lúc đó A đi vào trong lúc hai bên cãi vã thì chiếc điện thoại rơi xuống đất và hỏng. B và C đã vi phạm quyền nào dưới đây của công dân?', 'SINGLE_CHOICE', '{"A": "Bất khả xâm phạm về sức khỏe", "B": "Được pháp luật bảo hộ về danh dự, nhân phẩm", "C": "Được bảo đảm an toàn và bí mật điện thoại, thư tín", "D": "Bất khả xâm phạm về tài sản"}', 'A', 'Được bảo đảm an toàn và bí mật điện thoại, thư tínĐáp án C', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1102, 'Tiền tệ được coi là hàng hóa đặc biệt vì sao?', 'SINGLE_CHOICE', '{"A": "nó được tách ra làm vật ngang giá chung cho tất cả mọi hàng hóa", "B": "nó là hàng hoá nhưng không đi vào tiêu dùng mà cất trữ", "C": "nó ra đời là kết quả của quá trình phát triển lâu dài của sản xuất hàng hóa.", "D": "nó chỉ xuất hiện khi sản xuất hàng hóa đã phát triển mạnh mẽ."}', 'A', 'Tiền tệ được coi là hàng hóa đặc biệt vì nó được tách ra làm vật ngang giá chung cho tất cả mọi hàng hóa.Đáp án A.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1103, 'Là bạn thân lại làm chung 1 công ty nên anh D quản đốc luôn tạo điều kiện cho anh B thường xuyên ra ngoài làm việc riêng. Quản đốc D và anh B đã vi phạm pháp luật nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Dân sự", "B": "Kỷ luật", "C": "Hình sự", "D": "Hành chính"}', 'A', 'Là bạn thân lại làm chung 1 công ty nên anh D quản đốc luôn tạo điều kiện cho anh B thường xuyên ra ngoài làm việc riêng. Quản đốc D và anh B đã vi phạm ky luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1104, 'Khi cán bộ D làm nhiệm vụ khám xét nhà đối với ông B (có hành vi vi phạm pháp luật) ông B không hợp tác mà chống đối và xúc phạm cán bộ D. Nên cán bộ D đã lăng nhục và đánh ông B sái tay, làm rơi vỡ một số vật dụng trong gia đình. Cán bộ D không vi phạm quyền nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Bất khả xâm phạm về tài sản cá nhân.", "B": "Bất khả xâm phạm về chỗ ở.", "C": "Được bảo hộ về danh dự, nhân phẩm.", "D": "Được bảo hộ về sức khỏe."}', 'A', 'Cán bộ D&nbsp;không&nbsp;vi phạm quyền bất khả xâm phạm về chỗ ở.Đáp án B', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1105, 'Pháp luật có vai trò như thế nào đối với công dân?', 'SINGLE_CHOICE', '{"A": "Bảo vệ mọi nhu cầu của công dân.", "B": "Bảo vệ quyền và lợi ích hợp pháp của công dân.", "C": "Bảo vệ quyền tự do tuyệt đối của công dân.", "D": "Bảo vệ mọi lợi ích của công dân."}', 'A', 'Vai trò của pháp luật đối với công dân:&nbsp;Bảo vệ quyền và lợi ích hợp pháp của công dân.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1106, 'Chị Xuân được nhận vào làm việc ở công ty may G. Sáng nay Giám đốc yêu cầu chị đến kí hợp đồng, khi đọc bản hợp đồng chị không thấy phần nội dung công việc mình phải làm, nên chị đang phân vân. Chị Xuân nên làm gì?', 'SINGLE_CHOICE', '{"A": "yêu cầu bổ sung và cũng không cần kí bản hợp đồng đó mà làm việc luôn.", "B": "kí bản hợp đồng và sau đó nhờ chính quyền can thiệp.", "C": "yêu cầu Giám đốc bổ sung vào bản hợp đồng nội dung còn thiếu.", "D": "chấp nhận vì dù sao chị cũng được nhận vào công ty làm."}', 'A', 'Chị Xuân nên yêu cầu Giám đốc bổ sung vào bản hợp đồng nội dung còn thiếu.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1107, 'Là hàng xóm&nbsp; nhưng quan hệ giữa gia đình bà Q và bà T không được tốt vì vậy khi thấy gia đình bà T có nuôi được đàn gà mấy chục con đang có ý định bán để lấy tiền tiêu tết.Vô tình phát hiện gia đình bà T có việc phải về quê đến muộn nên anh L con trai bà Q rủ bạn là anh B lẻn vào và bí mật bỏ thuốc chuột vào thức ăn của đàn gà, sáng mai khi thấy đàn gà nằm chết la liệt. Nghi ngờ gia đình bà Q. Bà T thuê anh V sang đập phá đồ đạc nhà bà Q và đánh anh L phải đi cấp cứu. Hành vi của những ai dưới đây đã vi phạm pháp luật?', 'SINGLE_CHOICE', '{"A": "Anh L, anh V và bà T.", "B": "Bà Q và bà T, anh V.", "C": "Anh B, anh V,anh L và bà T.", "D": "Anh B, anh V và anh L."}', 'A', 'Hành vi của anh B, anh V,anh L và bà T đã vi phạm pháp luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1108, 'Quyền bầu cử của công dân không được thực hiện theo nguyên tắc nào?', 'SINGLE_CHOICE', '{"A": "phổ thông.", "B": "công khai.", "C": "trực tiếp.", "D": "bình đẳng."}', 'A', 'Quyền bầu cử của công dân không được thực hiện theo nguyên tắc&nbsp;công khai.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1109, 'Nội dung nào sau đây không phải là bình đẳng trong hôn nhân và gia đình?', 'SINGLE_CHOICE', '{"A": "Phụ nữ đang nuôi con dưới 12 tháng được giảm giờ lao động trong một ngày.", "B": "Giấy chứng nhận quyền sử dụng đất vườn được ghi tên của cả vợ và chồng.", "C": "Phân chia tài sản thừa kế bằng nhau giữa con đẻ và con nuôi.", "D": "Ông bà nội, ông bà ngoại có quyền và nghĩa vụ ngang nhau đối với các cháu."}', 'A', 'Phụ nữ đang nuôi con dưới 12 tháng được giảm giờ lao động trong một ngày.Đáp án A.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1110, 'Giá trị sử dụng của hàng hoá nói lên điều gì?', 'SINGLE_CHOICE', '{"A": "Đặc điểm của sản phẩm", "B": "Hiệu quả của sản phẩm", "C": "Công dụng của sản phẩm", "D": "Tác dụng của sản phẩm"}', 'A', 'Giá trị sử dụng của hàng hoá nói lên công dụng của sản phẩm', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1111, 'Trong lúc làm nhiệm vụ tuần tra trên biển hai cán bộ cảnh sát biển anh G và anh Y phát hiện bắt giữ và lập biên bản tàu mang biển hiệu SH53 vận chuyển một số mặt hàng cấm. Trong lúc cán bộ G đang lập biên bản thì cán bộ Y nhận hối lộ và đề nghị cán bộ G bỏ qua. Cán bộ G cần sử dụng quyền nào dưới đây cho phù hợp với quy định của pháp luật?', 'SINGLE_CHOICE', '{"A": "Phán quyết", "B": "Điều tra", "C": "Tố cáo", "D": "Khiếu nại"}', 'A', 'Cán bộ G cần sử dụng quyền tố cáo&nbsp;cho phù hợp với quy định của pháp luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1112, 'Các cá nhân, tổ chức sử dụng đúng đắn các quyền của mình, làm những gì mà pháp luật cho phép làm. Đó là hình thức nào của thực hiện pháp luật?', 'SINGLE_CHOICE', '{"A": "Áp dụng pháp luật", "B": "Tuân thủ pháp luật", "C": "Thi hành pháp luật", "D": "Sử dụng pháp luật"}', 'A', 'Các cá nhân, tổ chức sử dụng đúng đắn các quyền của mình, làm những gì mà pháp luật cho phép làm. Đó là hình thức sử dụng pháp luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1113, 'Sự thỏa thuận giữa người lao động và người sử dụng lao động về việc làm có trả công, điều kiện lao động, quyền và nghĩa vụ của mỗi bên thể hiện quyền bình đẳng của công dân trong lĩnh vực nào?', 'SINGLE_CHOICE', '{"A": "Lĩnh vực kinh doanh", "B": "Trong quan hệ nhân thân", "C": "Trong giao kết hợp đồng lao động", "D": "Lĩnh vực gia đình"}', 'A', 'Sự thỏa thuận giữa người lao động và người sử dụng lao động về việc làm có trả công, điều kiện lao động, quyền và nghĩa vụ của mỗi bên thể hiện quyền bình đẳng của công dân trong giao kết hợp đồng lao động.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1114, 'Dịp tết Nguyên Đán sắp tới biết nhu cầu của người tiêu dùng tăng cao nên chị T và N cùng kinh doanh một số lương thực thực phẩm tại ki ốt của mình nhưng không rõ nguồn gốc xuất xứ khi cán bộ thị trường tên H kiểm tra đã lập biên&nbsp;bản và chỉ xử phạt chị N, còn chị T được bỏ qua vì đã có nhờ người quen tên P là em gái của cán bộ H giúp đỡ. Những ai dưới đây vi phạm nội dung quyền bình đẳng trong kinh doanh?', 'SINGLE_CHOICE', '{"A": "Chị T, N và P.", "B": "Chị T, N, và cán bộ H", "C": "Chị T, N, P và cán bộ H.", "D": "Chị T, P và cán bộ H."}', 'A', 'Chị T, N, và cán bộ H vi phạm nội dung quyền bình đẳng trong kinh doanh.Đáp án B', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1115, 'Do mẫu thuẫn bởi tin nhắn trên trang mạng giữa học sinh A và K nên học sinh H tỏ ra tức giận vì K là bạn trai của H. Nên H&nbsp; cùng bạn là Y tìm gặp A để hỏi, lời qua tiếng lại thấy A ra vẻ thách thức nên H và&nbsp; Y đã chủ động đợi lúc tan học đã chặn đường A và đánh dằn mặt, còn K thì đứng quay lại cảnh đánh nhau, rách áo và tung lên mạng. Quá nhục nhã nên A rơi vào khủng hoảng và đã tìm đến tử tự hậu quả A bị ảnh hưởng đến tình trạng sức khỏe nghiêm trọng. Những ai dưới đây đã vi phạm pháp luật?', 'SINGLE_CHOICE', '{"A": "Học sinh H và Y.", "B": "Học sinh K, A và Y.", "C": "Học sinh Y, H và K.", "D": "Học sinh A và K."}', 'A', 'Học sinh Y, H và K&nbsp;đã vi phạm pháp luật.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1116, 'Để chuẩn bị việc mua nhà cho con trai ở Hà Nội, vợ chồng chị B đã tích lũy&nbsp; được số tiền là 800 triệu đồng và 2 cây vàng. Vợ chồng chị B đã vận dụng chức năng nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hình thức lưu thông", "B": "Quy trình quyết toán", "C": "Phương tiện cất trữ", "D": "Tiền tệ thế giới"}', 'A', 'Phương tiện cất trữ.Đáp án C', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1117, 'So với pháp luật thì đạo đức có phạm vi điều chỉnh&nbsp;như thế nào?', 'SINGLE_CHOICE', '{"A": "hẹp hơn", "B": "rộng hơn", "C": "lớn hơn", "D": "như nhau"}', 'A', 'So với pháp luật thì đạo đức có phạm vi điều chỉnh&nbsp;rộng hơn.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1118, 'Giá trị của hàng hóa là gì?', 'SINGLE_CHOICE', '{"A": "lao động xã hội của người sản xuất ra hàng hóa", "B": "lao động các biệt của người sản xuất ra hàng hóa", "C": "lao động của người sản xuất được kết tinh trong hàng hóa.", "D": "lao động xã hội của người sản xuất được kết tinh trong hàng hóa."}', 'A', 'Giá trị của hàng hóa là lao động xã hội của người sản xuất được kết tinh trong hàng hóa.Đáp án D.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1119, 'Quyền bình đẳng giữa các tôn giáo được hiểu là&nbsp;gì?', 'SINGLE_CHOICE', '{"A": "người đã theo tôn giáo này không có quyền bỏ để theo tôn giáo khác.", "B": "các tôn giáo đều có quyền hoạt động tôn giáo tự do.", "C": "không phân biệt đối xử giữa người có đạo và không có đạo.", "D": "các tôn giáo ở Việt Nam đều có quyền hoạt động tôn giáo trong khuôn khổ của pháp luật."}', 'A', 'Quyền bình đẳng giữa các tôn giáo được hiểu là&nbsp;các tôn giáo ở Việt Nam đều có quyền hoạt động tôn giáo trong khuôn khổ của pháp luật.Đáp án D', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1120, 'Hình thức xử phạt chính đối với người vi phạm hành chính là gì?', 'SINGLE_CHOICE', '{"A": "Tước quyền sử dụng giấy phép, chứng chỉ.", "B": "Buộc khắc phục hậu quả do mình gây ra.", "C": "Tịch thu tang vật, phương tiện.", "D": "Phạt tiền, cảnh cáo."}', 'A', 'Phạt tiền, cảnh cáo là hình thức xử phạt chính đối với người vi phạm hành chính.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1121, 'Quyền khiếu nại, tố cáo là công cụ để nhân dân thực hiện hình thức dân chủ&nbsp;nào?', 'SINGLE_CHOICE', '{"A": "trực tiếp.", "B": "tập trung.", "C": "đại diện.", "D": "gián tiếp."}', 'A', 'Quyền khiếu nại, tố cáo là công cụ để nhân dân thực hiện hình thức dân chủ&nbsp;trực tiếp.', 36);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1122, 'Người chịu trách nhiệm hành chính do mọi vi phạm hành chính mà mình gây ra theo quy định của pháp luật có độ tuổi bao nhiêu?', 'SINGLE_CHOICE', '{"A": "từ đủ 16 tuổi trở lên", "B": "từ đủ 18 tuổi trở lên", "C": "người dưới 18 tuổi", "D": "từ đủ 14 tuổi trở lên"}', 'A', 'Người chịu trách nhiệm hành chính do mọi vi phạm hành chính mà mình gây ra theo quy định của pháp luật có độ tuổi từ đủ 16 tuổi trở lên.Đáp án A.', 36);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(37, 'Đề thi thử THPT QG năm 2021 môn GDCD online - Đề thi của Trường THPT Nguyễn Văn Cừ', 'Giáo Dục Công Dân', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Giáo Dục Công Dân. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1123, 'Yếu tố giữ vai trò quan trọng và quyết định nhất trong quá trình sản xuất của cải vật chất là gì?', 'SINGLE_CHOICE', '{"A": "sức lao động.", "B": "đối tượng lao động.", "C": "công cụ lao động.", "D": "tư liệu lao động."}', 'A', 'Yếu tố giữ vai trò quan trọng và quyết định nhất trong quá trình sản xuất của cải vật chất là sức lao động.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1124, 'Quyền nào dưới đây thể hiện dân chủ trong lĩnh vực văn hóa?', 'SINGLE_CHOICE', '{"A": "Quyền được hưởng lợi ích từ sáng tạo nghệ thuật của mình", "B": "Quyền được đảm bảo về mặt tinh thần khi không còn khả năng lao động", "C": "Quyền tham gia thảo luận các vấn đề chung của cả nước", "D": "Quyền được thông tin, tự do ngôn luận, tự do báo chí"}', 'A', 'Quyền được hưởng lợi ích từ sáng tạo nghệ thuật của mình thể hiện dân chủ trong lĩnh vực văn hóa.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1125, 'Theo quy định của pháp luật, bắt người trong trường hợp khẩn cấp được tiến hành khi có căn cứ cho rằng người đó đang chuẩn bị làm gì?', 'SINGLE_CHOICE', '{"A": "thực hiện tội phạm rất nghiêm trọng.", "B": "tham gia tranh chấp đất đai.", "C": "tổ chức phát tán bí mật gia truyền.", "D": "tung tin nói xấu người khác."}', 'A', 'Theo quy định của pháp luật, bắt người trong trường hợp khẩn cấp được tiến hành khi có căn cứ cho rằng người đó đang chuẩn bị&nbsp;thực hiện tội phạm rất nghiêm trọng.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1126, 'Pháp luật là hệ thống các quy tắc xử sự chung do nhà nước ban hành và bảo đảm thực hiện bằng quyền lực nào sau đây?', 'SINGLE_CHOICE', '{"A": "Nhà nước.", "B": "cộng đồng.", "C": "xã hội.", "D": "tập thể."}', 'A', 'Pháp luật là hệ thống các quy tắc xử sự chung do nhà nước ban hành và bảo đảm thực hiện bằng quyền lực Nhà nước.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1127, 'Mọi công dân có thể học tập bằng nhiều hình thức và ở các loại hình trường, lớp khác nhau là thực hiện nội dung quyền gì?', 'SINGLE_CHOICE', '{"A": "học thường xuyên, học suốt đời.", "B": "dự thi lấy chứng chỉ nghề.", "C": "đổi mới giáo trình nâng cao.", "D": "lựa chọn chương trình song ngữ."}', 'A', 'Mọi công dân có thể học tập bằng nhiều hình thức và ở các loại hình trường, lớp khác nhau là thực hiện nội dung quyền học thường xuyên, học suốt đời.&nbsp;', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1128, 'Theo quy định của pháp luật, nhân dân thực thi hình thức dân chủ gián tiếp thông qua quyền nào?', 'SINGLE_CHOICE', '{"A": "bầu cử và ứng cử.", "B": "tự do ngôn luận.", "C": "khiếu nại và tố cáo.", "D": "độc lập phán quyết."}', 'A', 'Theo quy định của pháp luật, nhân dân thực thi hình thức dân chủ gián tiếp thông qua quyền&nbsp;bầu cử và ứng cử.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1129, 'Công dân có quyền làm việc cho bất cứ ai, ở bất cứ nơi nào mà pháp luật không cấm là nội dung quyền bình đẳng trong lĩnh vực nào?', 'SINGLE_CHOICE', '{"A": "lao động.", "B": "kinh doanh.", "C": "công vụ.", "D": "hành chính."}', 'A', 'Công dân có quyền làm việc cho bất cứ ai, ở bất cứ nơi nào mà pháp luật không cấm là nội dung quyền bình đẳng trong lĩnh vực lao động.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1130, 'Quyền khiếu nại, tố cáo là công cụ để nhân dân thực hiện hình thức dân chủ nào?', 'SINGLE_CHOICE', '{"A": "trực tiếp.", "B": "chỉ định.", "C": "tập trung.", "D": "gián tiếp."}', 'A', 'Quyền khiếu nại, tố cáo là công cụ để nhân dân thực hiện hình thức dân chủ&nbsp;trực tiếp.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1131, 'Theo quy định của pháp luật, thực hiện quyền bình đẳng giữa các dân tộc là điều kiện để khắc phục sự chênh lệch về nội dung nào sau đây?', 'SINGLE_CHOICE', '{"A": "trình độ phát triển.", "B": "tập tục địa phương.", "C": "nghi lễ tôn giáo.", "D": "thói quen vùng miền."}', 'A', 'Theo quy định của pháp luật, thực hiện quyền bình đẳng giữa các dân tộc là điều kiện để khắc phục sự chênh lệch về trình độ phát triển.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1132, 'Chọn từ thích hợp hoàn thành nội dung sau: Ở phạm vi cơ sơ dân chu trực tiếp được thực hiện theo cơ chế dân biết, dân bàn, dân làm, dân ......', 'SINGLE_CHOICE', '{"A": "kiểm tra.", "B": "quản lí.", "C": "điều hành.", "D": "tự quyết."}', 'A', 'Chọn từ thích hợp hoàn thành nội dung sau: Ở phạm vi cơ sơ dân chu trực tiếp được thực hiện theo cơ chế dân biết, dân bàn, dân làm, dân kiểm tra.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1133, 'Trong nền sản xuất hàng hóa, giá cả hàng hóa là gì?', 'SINGLE_CHOICE', '{"A": "biểu hiện bằng tiền của giá trị hàng hóa", "B": "quan hệ giữa người bán và người mua", "C": "giá trị của hàng hóa", "D": "tổng chi phí sản xuất và lợi nhuận"}', 'A', 'Trong nền sản xuất hàng hóa, giá cả hàng hóa biểu hiện bằng tiền của giá trị hàng hóa', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1134, 'Hoàn thành câu sau: Vi phạm hành chính là hành vi xâm phạm các .......', 'SINGLE_CHOICE', '{"A": "nguyên tắc quản lý hành chính.", "B": "quy tắc kỉ luật lao động.", "C": "quy tắc quản lý nhà nước.", "D": "quy tắc quản lý xã hội."}', 'A', 'Vi phạm hành chính là hành vi xâm phạm các&nbsp;quy tắc quản lý nhà nước.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1135, 'Theo quy định của pháp luật, vi phạm hình sự là hành vi gì?', 'SINGLE_CHOICE', '{"A": "nguy hiểm cho xã hội.", "B": "ảnh hưởng quy tắc quản lí.", "C": "thay đổi quan hệ công vụ.", "D": "tác động quan hệ nhân thân."}', 'A', 'Theo quy định của pháp luật, vi phạm hình sự là hành vi nguy hiểm cho xã hội.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1136, 'Công dân được tự do nghiên cứu, chế tạo ra các sản phẩm khoa học là nội dung quyền nào?', 'SINGLE_CHOICE', '{"A": "sáng tạo.", "B": "phán xét.", "C": "chỉ định.", "D": "đại diện."}', 'A', 'Công dân được tự do nghiên cứu, chế tạo ra các sản phẩm khoa học là nội dung quyền&nbsp;sáng tạo.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1137, 'Chọn cụm từ điền vào chỗ trống: Mọi công dân đều được học ở các trường cao đẳng, đại học thông qua tuyển sinh là thể hiện nội dung quyền học .............&nbsp;&nbsp;', 'SINGLE_CHOICE', '{"A": "không hạn chế", "B": "trực tuyến", "C": "theo chỉ định", "D": "liên thông"}', 'A', 'Mọi công dân đều được học ở các trường cao đẳng, đại học thông qua tuyển sinh là thể hiện nội dung quyền học không hạn chế', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1138, 'Nhà nước luôn quan tâm hỗ trợ vốn đối với vùng sâu, vùng xa, vùng đặc biệt khó khăn là thể hiện nội dung quyền bình đẳng giữa các dân tộc về khía cạnh nào?', 'SINGLE_CHOICE', '{"A": "kinh tế", "B": "tín ngưỡng", "C": "truyền thông", "D": "tôn giáo"}', 'A', 'Nhà nước luôn quan tâm hỗ trợ vốn đối với vùng sâu, vùng xa, vùng đặc biệt khó khăn là thể hiện nội dung quyền bình đẳng giữa các dân tộc về khía cạnh kinh tế.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1139, 'Ở phạm vi cơ sở, quyền tham gia quản lí nhà nước và xã hội của công dân không được thực hiện theo cơ chế nào?', 'SINGLE_CHOICE', '{"A": "dân quản lí", "B": "dân bàn", "C": "dân kiểm tra", "D": "dân biết"}', 'A', 'Ở phạm vi cơ sở, quyền tham gia quản lí nhà nước và xã hội của công dân không được thực hiện theo cơ chế&nbsp;dân quản lí', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1140, 'Một trong những mục tiêu tiêu của chính sách tài nguyên và bảo vệ môi trường?', 'SINGLE_CHOICE', '{"A": "Bảo tồn đa dạng sinh học", "B": "Chủ động phòng ngừa, ngăn chặn ô nhiễm, cải thiện môi trường", "C": "Tăng tỉ lệ che phủ rừng, bảo vệ động thực vật", "D": "Xây dựng hệ thống xử lí chất thải"}', 'A', 'Một trong những mục tiêu tiêu của chính sách tài nguyên và bảo vệ môi trường là:&nbsp;Bảo tồn đa dạng sinh học', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1141, 'Một trong những phương hướng tiêu của chính sách tài nguyên và bảo vệ môi trường là gì?', 'SINGLE_CHOICE', '{"A": "thường xuyên giáo dục, xây dựng ý thức trách nhiệm bảo vệ môi trường", "B": "xây dựng nếp sống vệ sinh", "C": "đẩy mạnh phong trào quần chúng nhân dân tham gia bảo vệ môi trường", "D": "ban hành các chính sách bảo vệ môi trường"}', 'A', 'Một trong những phương hướng tiêu của chính sách tài nguyên và bảo vệ môi trường là&nbsp;thường xuyên giáo dục, xây dựng ý thức trách nhiệm bảo vệ môi trường', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1142, 'Công dân không làm những điều mà pháp luật cấm, gọi là gì?', 'SINGLE_CHOICE', '{"A": "tuân thủ pháp luật.", "B": "vận dụng chính sách.", "C": "sử dụng pháp luật.", "D": "thực hiện chính sách."}', 'A', 'Công dân không làm những điều mà pháp luật cấm, gọi là tuân thủ pháp luật.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1143, 'Pháp luật là phương tiện để công dân bảo vệ gì?', 'SINGLE_CHOICE', '{"A": "quyền và lợi ích hợp pháp của mình.", "B": "tất cả các nghi lễ tôn giáo.", "C": "mọi tập quán của vùng miền.", "D": "địa vị xã hội của toàn dân."}', 'A', 'Pháp luật là phương tiện để công dân bảo vệ quyền và lợi ích hợp pháp của mình.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1144, 'Học sinh điều khiển xe mô tô đến trường không đội mũ bảo hiểm là vi phạm gì?', 'SINGLE_CHOICE', '{"A": "hành chính.", "B": "dân sự.", "C": "quy chế.", "D": "công vụ."}', 'A', 'Học sinh điều khiển xe mô tô đến trường không đội mũ bảo hiểm là vi phạm&nbsp;hành chính.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1145, 'Một trong những đặc trưng cơ bản của pháp luật thể hiện ở tính nào sau đây?', 'SINGLE_CHOICE', '{"A": "xác định chặt chẽ về mặt hình thức.", "B": "bảo mật nội bộ.", "C": "bao quát, định hướng tổng thể.", "D": "chuyên chế độc quyền."}', 'A', 'Một trong những đặc trưng cơ bản của pháp luật thể hiện ở tính xác định chặt chẽ về mặt hình thức.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1146, 'Công dân được thực hiện quyền bầu cử trong trường hợp như thế nào?', 'SINGLE_CHOICE', '{"A": "công tác ngoài hải đảo.", "B": "chấp hành hình phạt tù.", "C": "bị tước quyền công dân.", "D": "mất năng lực hành vi dân sự."}', 'A', 'Công dân được thực hiện quyền bầu cử trong trường hợp công tác ngoài hải đảo.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1147, 'Trong sản xuất và lưu thông hàng hóa, để kịp thời đưa ra quyết định nhằm thu lợi nhuận cao, người bán hàng phải căn cứ vào chức năng nào dưới đây của thị trường?', 'SINGLE_CHOICE', '{"A": "Điều phối.", "B": "Thực hiện.", "C": "Thông tin.", "D": "Thanh toán."}', 'A', 'Trong sản xuất và lưu thông hàng hóa, để kịp thời đưa ra quyết định nhằm thu lợi nhuận cao, người bán hàng phải căn cứ vào chức năng thông tin&nbsp;của thị trường.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1148, 'Công dân không vi phạm quyền bất khả xâm phạm về chỗ ở khi tự ý vào nhà người khác để làm gì?', 'SINGLE_CHOICE', '{"A": "dập tắt vụ hỏa hoạn.", "B": "thăm dò tin tức nội bộ.", "C": "tìm đồ đạc bị mất trộm.", "D": "tiếp thị sản phẩm đa cấp."}', 'A', 'Công dân không vi phạm quyền bất khả xâm phạm về chỗ ở khi tự ý vào nhà người khác để dập tắt vụ hỏa hoạn.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1149, 'Nội dung nào dưới đây không thuộc quyền học tập của công dân?', 'SINGLE_CHOICE', '{"A": "Học theo sự ủy quyền.", "B": "Học bằng nhiều hình thức khác nhau.", "C": "Học bất cứ ngành, nghề nào phù hợp.", "D": "Học từ thấp đến cao."}', 'A', 'Học theo sự ủy quyền&nbsp;không&nbsp;thuộc quyền học tập của công dân.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1150, 'Đảng và Nhà nước ta đang có chủ trương giảm tốc độ tăng dân số, bở vì tăng dân số sẽ ảnh hưởng như thế nào?', 'SINGLE_CHOICE', '{"A": "ảnh hưởng tới sự phát triển kinh tế, văn hóa, xã hội của nhà nước", "B": "ảnh hưởng đến quá trình công nghiệp hóa đất nước", "C": "ảnh hưởng đến an ninh quốc phòng", "D": "ảnh hưởng đến chính trị, kinh tế của đất nước"}', 'A', 'Đảng và Nhà nước ta đang có chủ trương giảm tốc độ tăng dân số, bở vì tăng dân số sẽ ảnh hưởng tới&nbsp;sự phát triển kinh tế, văn hóa, xã hội của nhà nước', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1151, 'Mục tiêu phân bố dân cư hợp lí của chính sách dân số nước ta là gì?', 'SINGLE_CHOICE', '{"A": "khai thác tiềm năng và phát huy thế mạnh của từng vùng, miền", "B": "giảm sự chênh lệch lao động giữa các vùng", "C": "hạn chế tập trung đông dân cư vào đô thị lớn", "D": "giảm lao động thừa ở thành thị"}', 'A', 'Mục tiêu phân bố dân cư hợp lí của chính sách dân số nước ta là khai thác tiềm năng và phát huy thế mạnh của từng vùng, miền', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1152, 'Chị T tự ý kiểm tra điện thoại của con và phát hiện con trai thường xuyên nhắn tin hẹn bạn đi chơi điện tử nên đã đưa cho chồng xem. Chồng chị giận dữ đánh con và đập nát điện thoại đó. Vợ chồng chị T đã vi phạm quyền nào dưới đây của công dân?', 'SINGLE_CHOICE', '{"A": "Được bảo đảm an toàn và bí mật điện thoại, điện tín.", "B": "Bất khả xâm phạm về sức khỏe.", "C": "Bất khả xâm phạm về tài sản.", "D": "Được pháp luật bảo hộ về danh dự, nhân phẩm."}', 'A', 'Vợ chồng chị T đã vi phạm quyền được bảo đảm an toàn và bí mật điện thoại, điện tín.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1153, 'Ủy ban nhân dân xã Y tổ chức lấy ý kiến của người dân về kế hoạch lắp đặt hệ thống loa phát thanh ở địa phương là thực hiện nội dung quyền dân chủ nào dưới đây của công dân?', 'SINGLE_CHOICE', '{"A": "Tham gia quản lí nhà nước và xã hội.", "B": "Chủ động kiểm toán ngân sách quốc gia.", "C": "Độc lập phán quyết.", "D": "Tự do ngôn luận."}', 'A', 'Ủy ban nhân dân xã Y tổ chức lấy ý kiến của người dân về kế hoạch lắp đặt hệ thống loa phát thanh ở địa phương là thực hiện nội dung quyền tham gia quản lí nhà nước và xã hội.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1154, 'Sau khi tiếp cận được một số bí quyết kinh doanh từ công ty Z, chị L đã tìm cách hợp pháp hóa hồ sơ rồi tự mở cơ sở riêng dưới danh nghĩa của công ty này. Chị L đã vi phạm nội dung nào dưới đây của quyền bình đẳng trong kinh doanh?', 'SINGLE_CHOICE', '{"A": "Tự chủ đăng kí kinh doanh.", "B": "Chủ động liên doanh, liên kết.", "C": "Phổ biến quy trình kĩ thuật.", "D": "Độc lập tham gia đàm phán."}', 'A', 'Chị L đã vi phạm quyền bình đẳng trong kinh doanh:&nbsp;Tự chủ đăng kí kinh doanh.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1155, 'Ủy ban nhân dân xã X cấp giấy chứng nhận đăng kí kết hôn cho anh A và chị B là thực hiện pháp luật theo hình thức nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Áp dụng pháp luật.", "B": "Giáo dục pháp luật.", "C": "Tuân thủ pháp luật.", "D": "Phổ biến pháp luật."}', 'A', 'Ủy ban nhân dân xã X cấp giấy chứng nhận đăng kí kết hôn cho anh A và chị B là thực hiện pháp luật theo hình thức Áp dụng pháp luật.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1156, 'Do không hài lòng với mức tiền bồi thường đất đai sau giải tỏa, ông B nhiều lần yêu cầu được gặp lãnh đạo xã Y. Cho rằng ông B cố tình gây rối, bảo vệ Ủy ban nhân dân xã đã mắng chửivà đuổi ông về nên giữa hai bên xảy ra mâu thuẫn. Bảo vệ đã đánh ông B gãy tay và đẩy xe máy của ông xuống hồ. Bảo vệ Ủy ban nhân dân xã Y không vi phạm quyền nào dưới đây của công dân?', 'SINGLE_CHOICE', '{"A": "Bất khả xâm phạm về thân thể.", "B": "Được pháp luật bảo hộ về danh dự.", "C": "Được pháp luật bảo hộ về sức khỏe.", "D": "Bất khả xâm phạm về tài sản."}', 'A', 'Bảo vệ Ủy ban nhân dân xã Y không vi phạm quyền&nbsp;Bất khả xâm phạm về thân thể.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1157, 'Bác sĩ H được thừa kế riêng một mảnh đất kế bên ngôi nhà gia đình chị đang ở. Khi em trai kết hôn, bác sĩ H tặng lại vợ chồng người em mảnh đất đó dù chồng chị không tán thành. Bác sĩ H không vi phạm quyền bình đẳng hôn nhân và gia đình trong quan hệ nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Tài sản.", "B": "Kinh doanh.", "C": "Nhân thân.", "D": "Giám hộ."}', 'A', 'Bác sĩ H không vi phạm quyền bình đẳng hôn nhân và gia đình trong quan hệ tài sản', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1158, 'Sinh viên T điều khiển xe mô tô phóng nhanh vượt ẩu đâm vào người đi đường khiến họ tử vong thì phải chịu trách nhiệm pháp lí nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hình sự.", "B": "Kỉ luật.", "C": "Hành chính.", "D": "Dân sự."}', 'A', 'Sinh viên T điều khiển xe mô tô phóng nhanh vượt ẩu đâm vào người đi đường khiến họ tử vong thì phải chịu trách nhiệm hình sự', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1159, 'Phát hiện anh C đã tung tin đồn thất thiệt về chị T trên mạng xã hội nên chị B kể lại việc này với chị T. Sau khi yêu cầu anh C gỡ bỏ thông tin sai lệch về mình không được, chị T rất bực mình. Thương bạn, chị B đã tung tin cả nhà anh C nhiễm HIV khiến gia đình anh C bị kì thị còn anh C bị trầm cảm. Chị B đã vi phạm pháp luật nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hình sự.", "B": "Kỉ luật.", "C": "Hành chính.", "D": "Dân sự."}', 'A', 'Hành động của chị B đã gây ảnh hưởng nghiêm trọng đến gia đình anh C nên vi phạm hình sự.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1160, 'Trên đường chở bạn gái đi chơi bằng xe mô tô, do phóng nhanh vượt ẩu anh K đã va chạm vào xe của anh B đang đi ngược đường một chiều nên hai bên to tiếng với nhau. Thấy người đi đường dừng lại dùng điện thoại di động quay video, anh K và bạn gái vội vã bỏ đi. Những ai dưới đây phải chịu trách nhiệm hành chính?', 'SINGLE_CHOICE', '{"A": "Anh K và anh B.", "B": "Anh B, K và bạn gái.", "C": "Anh K, bạn gái và người quay video.", "D": "Anh K và bạn gái."}', 'A', 'Anh K phóng nhanh vượt ẩu, Anh B đi ngược đường 1 chiều la vi phạm quy tắc quản lý nhà nước.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1161, 'Giám đốc P điều động toàn bộ nhân viên đến công ty X để chuẩn bị tổ chức hội nghị khách hàng. Cuối buổi một nhân viên phát hiện mất điện thoại, giám đốc P yêu cầu bảo vệ khóa cửa ra vào rồi cùng trưởng phòng S kiểm tra tư trang của mọi người. Chồng nhân viên B đến đón vợ nhưng bị bảo vệ ngăn cản. Lời qua tiếng lại, hai bên quát nạt, mắng chửi nhau thậm tệ. Những ai dưới đây đã vi phạm quyền được pháp luật bảo hộ về danh dự, nhân phẩm của công dân?', 'SINGLE_CHOICE', '{"A": "Giám đốc P, trưởng phòng S, chồng cô B và bảo vệ.", "B": "Chồng cô B và bảo vệ.", "C": "Giám đốc P và trưởng phòng S.", "D": "Giám đốc P, trưởng phòng S, chồng cô B."}', 'A', 'Giám đốc P, trưởng phòng S, chồng cô B và bảo vệ quạt nạt chửi bới nhau thậm tệ là vi phạm quyền được pháp luật bảo hộ về danh dự nhân phẩm của công dân.', 37);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1162, 'Khi đang giúp chồng bỏ phiếu bầu cử theo đề xuất của anh thì chị A phát hiện anh D có hành vi gian lận phiếu bầu, chị A đã kể cho bạn thân của mình là anh H và anh T nghe. Vốn mâu thuẫn với D nên anh H lập tức đăng tin đồn thất thiệt bôi nhọ D trên trang tin cá nhân, còn anh T nhắn tin tống tiền D. Những ai dưới đây vi phạm nguyên tắc bầu cử?', 'SINGLE_CHOICE', '{"A": "Vợ chồng chị A và anh D.", "B": "Vợ chồng chị A, anh D, H và T.", "C": "Chị A, anh D và H.", "D": "Chồng chị A, anh D và H."}', 'A', 'Vợ chồng chị A và chị Dđã vi phạm nguyên tắc bầu cử bình đẳng, trực tiếp và bỏ phiếu kín.', 37);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(38, 'Đề thi thử THPT QG năm 2022 môn GDCD online - Đề thi của Trường THPT Nguyễn Trung Trực', 'Giáo Dục Công Dân', 50, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Giáo Dục Công Dân. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1163, 'Một trong các đặc trưng cơ bản của pháp luật thể hiện ở', 'SINGLE_CHOICE', '{"A": "tính quyền lực, bắt buộc chung.", "B": "tính cơ bản.", "C": "tính hiện đại.", "D": "tính truyền thống."}', 'A', 'Đặc trưng cơ bản của pháp luật thể hiện ở tính quy phạm phổ biến, tính quyền lực, bắt buộc chung và tính xác định chặt chẽ về mặt hình thức. Vậy đáp án của câu hỏi này là&nbsp;tính quyền lực, bắt buộc chung.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1164, 'Mỗi hành vi vi phạm pháp luật phải chịu ít nhất một loại trách nhiệm pháp lý. Phát biểu trên thể hiện nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Nghĩa vụ của công dân.", "B": "Công dân bình đẳng về trách nhiệm pháp lý.", "C": "Quyền của công dân.", "D": "Quyền và nghĩa vụ của công dân."}', 'A', 'Mỗi hành vi vi phạm pháp luật phải chịu ít nhất một loại trách nhiệm pháp lý. Điều này có nghĩa là bất kì công dân nào vi phạm pháp luật cũng bị xử lý theo quy định của pháp luật hay chính là công dân bình đẳng về trách nhiệm pháp lý.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1165, 'Vấn đề nào dưới đây được đặc biệt chú ý ở nước ta do tác động lâu dài của nó đối với chất lượng cuộc sống và phát triển bền vững?', 'SINGLE_CHOICE', '{"A": "Phát triển đô thị", "B": "Phát triển chăn nuôi gia đình", "C": "Giáo dục môi trường cho thế hệ trẻ", "D": "Giáo dục và rèn luyện thể chat cho thế hệ trẻ"}', 'A', 'Vấn đề được đặc biệt chú ý ở nước ta do tác động lâu dài của nó đối với chất lượng cuộc sống và phát triển bền vững là giáo dục môi trường cho thế hệ trẻ.Đáp án C', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1166, 'Quyền ứng cử của công dân được hiểu là', 'SINGLE_CHOICE', '{"A": "Công dân có đủ các điều kiện pháp luật quy định có quyền ứng cử đại biểu Quốc hội ở nhiều nơi.", "B": "Công dân từ đủ 18 tuổi trở lên có đủ điều kiện mà pháp luật quy định có thể được nhiều nơi giới thiệu ứng cử đại biểu Quốc hội.", "C": "Công dân có quyền tự mình ra ứng cử đại biểu Quốc hội ở nhiều nơi.", "D": "Công dân có đủ các điều kiện pháp luật quy định có quyền ứng cử đại biểu Quốc hội ở một nơi."}', 'A', 'Quyền ứng cử của công dân được hiểu là:&nbsp;Công dân có đủ các điều kiện pháp luật quy định có quyền ứng cử đại biểu Quốc hội ở một nơi.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1167, 'Nền dân chủ XHCN mang bản chất giai cấp nào?', 'SINGLE_CHOICE', '{"A": "Giai cấp công nhân và quần chúng nhân dân lao động", "B": "Giai cấp chiếm đa số trong xã hội", "C": "Giai cấp công nhân", "D": "Giai cấp công nhân và giai cấp nông dân"}', 'A', 'Nền dân chủ XHCN mang bản chất giai cấp&nbsp;công nhân.Đáp án C', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1168, 'Người kinh doanh phải thực hiện nghĩa vụ nộp thuế, thanh nhiên đủ 18 tuổi thực hiện nghĩa vụ quân sự… là hình thức', 'SINGLE_CHOICE', '{"A": "Thi hành pháp luật", "B": "Thực hiện đúng đắn các quyền hợp pháp", "C": "Không làm những điều pháp luật cấm", "D": "Thực hiện đầy đủ các nghĩa vụ pháp lí"}', 'A', 'Người kinh doanh phải thực hiện nghĩa vụ nộp thuế, thanh nhiên đủ 18 tuổi thực hiện nghĩa vụ quân sự… là hình thức thi hành pháp luật.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1169, 'Trường hợp nào sau đây thì mới được bắt, giam, giữ người?', 'SINGLE_CHOICE', '{"A": "Bắt người đang bị tình nghi có hành vi vi phạm pháp luật", "B": "Bắt, giam, giữ người khi người này đang nghiện ma túy", "C": "Bắt người phạm tội quả tang hoặc đang bị truy nã", "D": "Bắt giam người khi người này có người thân vi phạm pháp luật"}', 'A', 'Trường hợp được bắt, giam, giữ người là bắt người phạm tội quả tang hoặc đang bị truy nã.Đáp án C', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1170, 'Pháp luật không điều chỉnh quan hệ xã hội nào sau đây?', 'SINGLE_CHOICE', '{"A": "Quan hệ hôn nhân – gia đình", "B": "Quan hệ kinh tế", "C": "Quan hệ về tình yêu nam – nữ", "D": "Quan hệ lao động"}', 'A', 'Pháp luật không điều chỉnh quan hệ&nbsp;về tình yêu nam – nữ.Đáp án C', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1171, 'Quyền, nghĩa vụ của vợ, chồng chỉ phát sinh và được pháp luật bảo vệ sau khi họ', 'SINGLE_CHOICE', '{"A": "Được UBND phường, xã cấp giấy chứng nhận đăng kí kết hôn.", "B": "Hai người chung sống với nhau.", "C": "Được tòa án nhân dân ra quyết định.", "D": "Được gia đình hai bên và bạn bè thừa nhận."}', 'A', 'Quyền, nghĩa vụ của vợ, chồng chỉ phát sinh và được pháp luật bảo vệ sau khi họ được UBND phường, xã cấp giấy chứng nhận đăng kí kết&nbsp;hôn.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1172, 'Nền dân chủ XHCN dựa trên cơ sở kinh tế như thế nào?', 'SINGLE_CHOICE', '{"A": "Kinh tế xã hội chủ nghĩa", "B": "Chế độ công hữu về tư liệu sản xuất", "C": "Kinh tế nhiều thành phần", "D": "Chế độ tư hữu về tư liệu sản xuất"}', 'A', 'Nền dân chủ XHCN dựa trên chế độ công hữu về tư liệu sản xuấtĐáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1173, 'Cuộc cách mạng khoa học kĩ thuật lần thứ nhất diễn ra vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "Thế kỉ XIX.", "B": "Thế kỉ XX.", "C": "Thế kỉ XXI", "D": "Thế kỉ XVIII."}', 'A', 'Cuộc cách mạng khoa học kĩ thuật lần thứ nhất diễn ra vào thế kỉ XVIII.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1174, 'Tìm câu phát biểu&nbsp;sai?', 'SINGLE_CHOICE', '{"A": "Các tôn giáo được nhà nước công nhận đều bình đẳng trước pháp luật, có quyền hoạt động tôn giáo theo quy định của pháp luật.", "B": "Hoạt động tín ngưỡng, tôn giáo theo quy định của pháp luật được nhà nước bảo đảm; các cơ sở tôn giáo hợp pháp được pháp luật bảo hộ.", "C": "Các tôn giáo được nhà nước công nhận, được hoạt động khi đóng thuế hàng năm.", "D": "Quyền hoạt động tín ngưỡng, tôn giáo của công dân trên tinh thần tôn trọng pháp luật, phát huy giá trị văn hóa, đạo đức tôn giáo được nhà nước đảm bảo."}', 'A', 'Phát biểu&nbsp;sai là:&nbsp;Các tôn giáo được nhà nước công nhận, được hoạt động khi đóng thuế hàng năm.Đáp án C', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1175, 'Khi công dân giao kết được một hợp đồng lao động, có nghĩa là', 'SINGLE_CHOICE', '{"A": "Bắt đầu có thu nhập", "B": "Xác lập được một quan hệ xã hội do pháp luật điều chỉnh", "C": "Có vị trí đứng trong xã hội", "D": "Có việc làm ổn định"}', 'A', 'Khi công dân giao kết được một hợp đồng lao động, có nghĩa là xác lập được một quan hệ xã hội do pháp luật điều chỉnh.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1176, 'Ngày 22/5/2011, Việt Nam tiến hành bầu cử đại biểu Quốc hội và Hội đồng nhân dân các cấp.&nbsp;Công dân nào dưới đây đủ điều kiện được bầu cử khi có ngày sinh là bao nhiêu?', 'SINGLE_CHOICE', '{"A": "22/5/1993", "B": "22/5/1994", "C": "24/5/2994", "D": "26/5/1993"}', 'A', 'Ngày 22/5/2011, Việt Nam tiến hành bầu cử đại biểu Quốc hội và Hội đồng nhân dân các cấp.&nbsp;Công dân nào dưới đây đủ điều kiện được bầu cử khi có ngày sinh là&nbsp;22/5/1993.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1177, 'Quá trình chuyển đổi căn bản các hoạt động sản xuất từ sử dụng sức lao động thủ công sang sử dụng sức lao động dựa trên sự phát triển của công nghiệp cơ khí là quá trình nào sau đây?', 'SINGLE_CHOICE', '{"A": "Công nghiệp hóa", "B": "Hiện đại hóa", "C": "Cơ khí hóa", "D": "Thương mại hóa"}', 'A', 'Quá trình chuyển đổi căn bản các hoạt động sản xuất từ sử dụng sức lao động thủ công sang sử dụng sức lao động dựa trên sự phát triển của công nghiệp cơ khí là quá trình công nghiệp hóa.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1178, 'Ông A tổ chức buôn ma túy. Hỏi ông A phải chịu trách nhiệm pháp lí nào?', 'SINGLE_CHOICE', '{"A": "Trách nhiệm hình sự", "B": "Trách nhiệm kỷ luật", "C": "Trách nhiệm dân sự", "D": "Trách nhiệm hành chính"}', 'A', 'Ông A tổ chức buôn ma túy. Ông A phải chịu trách nhiệm&nbsp;hình sự.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1179, 'Trong các trường hợp sau đây, trường hợp nào được xem là theo tôn giáo?', 'SINGLE_CHOICE', '{"A": "Thờ cúng tổ tiên", "B": "Thờ cúng ông Táo", "C": "Thờ cúng các anh hùng liệt sĩ", "D": "Thờ cúng đức chúa trời"}', 'A', 'Trường hợp thờ cúng đức chúa trời được xem là theo tôn giáo.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1180, 'Quá trình ứng dụng và trang trí những thành tựu khoa học công nghệ tiên tiến hiện đại vào quá trình sản xuất, kinh doanh, dịch vụ, quản lí kinh tế - xã hội là quá trình nào sau đây?', 'SINGLE_CHOICE', '{"A": "Công nghiệp hóa", "B": "Hiện đại hóa", "C": "Cơ khí hóa", "D": "Thương mại hóa"}', 'A', 'Quá trình ứng dụng và trang trí những thành tựu khoa học công nghệ tiên tiến hiện đại vào quá trình sản xuất, kinh doanh, dịch vụ, quản lí kinh tế - xã hội là quá trình hiện đại hóa.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1181, 'Yếu tố nào dẫn đến sự thay đổi từ chế độ xã hội này bằng chế độ xã hội khác?', 'SINGLE_CHOICE', '{"A": "Phương thức sản xuất", "B": "Lực lượng sản xuất", "C": "Quan hệ sản xuất", "D": "Công cụ lao động"}', 'A', 'Yếu tố dẫn đến sự thay đổi từ chế độ xã hội này bằng chế độ xã hội khác là phương thức sản xuất.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1182, 'Nền dân chủ XHCN là nền dân chủ của ai?', 'SINGLE_CHOICE', '{"A": "Người thừa hành trong xã hội", "B": "Giai cấp công nhân và quần chúng nhân dân lao động", "C": "Giai cấp công nhân", "D": "Giai cấp công nhân và giai cấp nông dân"}', 'A', 'Nền dân chủ XHCN là nền dân chủ của giai cấp công nhân và quần chúng nhân dân lao động.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1183, 'Những yếu tố tự nhiên mà lao động của con người tác động vào nhằm biến đổi nó cho phù hợp với mục đích của con người được gọi là gì?', 'SINGLE_CHOICE', '{"A": "Đối tượng lao động", "B": "Công cụ lao động", "C": "Sản phẩm tự nhiên", "D": "Tư liệu sản xuất"}', 'A', 'Những yếu tố tự nhiên mà lao động của con người tác động vào nhằm biến đổi nó cho phù hợp với mục đích của con người được gọi là đối tượng lao động.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1184, 'Quyền bầu cử của công dân được hiểu là', 'SINGLE_CHOICE', '{"A": "Mọi người đều có quyền bầu cử", "B": "Công dân không phân biệt chủng tộc, nam nữ thành phần xã hội, tín ngưỡng, tôn giáo, trình độ văn hóa, nghề nghiệp, thời hạn cư trú, đủ 18 tuổi trở lên đều có quyền bầu cử theo quy định của pháp luật", "C": "Những người từ đủ 18 tuổi trở lên, có năng lực hành vi dân sự có quyền bầu cử", "D": "Những người từ đủ 18 tuổi trở lên có quyền bầu cử"}', 'A', 'Quyền bầu cử của công dân được hiểu là:&nbsp;Công dân không phân biệt chủng tộc, nam nữ thành phần xã hội, tín ngưỡng, tôn giáo, trình độ văn hóa, nghề nghiệp, thời hạn cư trú, đủ 18 tuổi trở lên đều có quyền bầu cử theo quy định của pháp luật.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1185, 'Mọi người đều có quyền làm việc, tự do lựa chọn việc làm và nghề nghiệp phù hợp với khả năng của mình. Điều này thể hiện', 'SINGLE_CHOICE', '{"A": "Quyền bình đẳng trong thực hiện quyền lao động", "B": "Quyền bình đẳng trong giao kết hợp đồng lao động", "C": "Quyền bình đẳng trong lao động", "D": "Quyền bình đẳng trong lao động giữa lao động nam và lao động nữ"}', 'A', 'Mọi người đều có quyền làm việc, tự do lựa chọn việc làm và nghề nghiệp phù hợp với khả năng của mình. Điều này thể hiện quyền bình đẳng trong thực hiện quyền lao động.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1186, 'Các yếu tố cơ bản của quá trình sản xuất là gì?', 'SINGLE_CHOICE', '{"A": "Sức lao động, công cụ lao động, tư liệu lao động", "B": "Sức lao động, tư liệu lao động, công cụ sản xuất", "C": "Sức lao động, đối tượng lao động, công cụ lao động", "D": "Sức lao động, đối tượng lao động, tư liệu lao động"}', 'A', 'Các yếu tố cơ bản của quá trình sản xuất là sức lao động, đối tượng lao động, tư liệu lao động.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1187, 'Thế nào là vi phạm hình sự?', 'SINGLE_CHOICE', '{"A": "Hành vi tương đối nguy hiểm cho xã hội", "B": "Hành vi rất nguy hiểm cho xã hội", "C": "Hành vi đặc biệt nguy hiểm cho xã hội", "D": "Hành vi nguy hiểm cho xã hội"}', 'A', 'Vi phạm hình sự là hành vi nguy hiểm cho xã hội.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1188, 'Lực lượng quyết định dẫn đến sự thay đổi của chế độ xã hội này bằng chế độ xã hội khác là lực lượng nào sau đây?', 'SINGLE_CHOICE', '{"A": "Phương thức sản xuất", "B": "Lực lượng sản xuất", "C": "Quan hệ sản xuất", "D": "Công cụ lao động"}', 'A', 'Lực lượng quyết định dẫn đến sự thay đổi của chế độ xã hội này bằng chế độ xã hội khác là lực lượng&nbsp;sản xuất.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1189, 'Một trong những đặc điểm để phân biệt pháp luật với quy phạm đạo đức là gì?', 'SINGLE_CHOICE', '{"A": "Pháp luật có tính chất bắt buộc chung", "B": "Pháp luật có tính quyền lực", "C": "Pháp luật có tính quy phạm", "D": "Pháp luật có tính quyền lực, bắt buộc chung"}', 'A', 'Một trong những đặc điểm để phân biệt pháp luật với quy phạm đạo đức là pháp luật có tính quyền lực, bắt buộc chung.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1190, 'Một học sinh lớp 11 (16 tuổi) chạy xe gắn máy trên 50cc ra đường chơi (có đội mũ bảo hiểm), được xem là', 'SINGLE_CHOICE', '{"A": "Vi phạm pháp luật vì chưa đủ năng lực trách nhiệm pháp lí", "B": "Không phải chịu trách nhiệm về hành vi của mình", "C": "Không vi phạm vì có đội mũ bảo hiểm theo quy định", "D": "Không vi phạm pháp luật vì thực hiện quyền tự do đi lại"}', 'A', 'Một học sinh lớp 11 (16 tuổi) chạy xe gắn máy trên 50cc ra đường chơi (có đội mũ bảo hiểm), được xem là vi phạm pháp luật vì chưa đủ năng lực trách nhiệm pháp lí.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1191, 'Vi phạm pháp luật có các dấu hiệu', 'SINGLE_CHOICE', '{"A": "Do người có năng lực trách nhiệm pháp lí thực hiện", "B": "Là hành vi trái pháp luật, có lỗi, do người có năng lực trách nhiệm pháp lí thực hiện", "C": "Lỗi của chủ thể", "D": "Là hành vi trái pháp luật"}', 'A', 'Vi phạm pháp luật có các dấu hiệu: là hành vi trái pháp luật, có lỗi, do người có năng lực trách nhiệm pháp lí thực hiện.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1192, 'Cuộc cách mạng khoa học kĩ thuật lần thứ 2 diễn ra vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "Thế kỉ XIX", "B": "Thế kỉ XX", "C": "Thế kỉ XXI", "D": "Thế kỉ XVIII"}', 'A', 'Cuộc cách mạng khoa học kĩ thuật lần thứ 2 diễn ra vào thế kỉ XIX.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1193, 'Để cạnh tranh, chị B đã thuê người phát&nbsp;tán những hình ảnh sai sự thật làm&nbsp;ảnh hưởng nghiêm trọng đến uy tín của chị H chủ cửa hàng kế bên. Phát hiện sự việc, chị H đã sỉ nhục chị B trước đông đảo khách hàng. Chị B và chị H vi phạm quyền nào dưới đây của công dân?', 'SINGLE_CHOICE', '{"A": "Bất khả xâm phạm về thân thể", "B": "Được bảo mật thông tin cá nhân", "C": "Bất khả xâm phạm về chỗ ở", "D": "Được pháp luật bảo hộ về danh dự, nhân phẩm"}', 'A', 'Để cạnh tranh, chị B đã thuê người phát&nbsp;tán những hình ảnh sai sự thật làm&nbsp;ảnh hưởng nghiêm trọng đến uy tín của chị H chủ cửa hàng kế bên. Phát hiện sự việc, chị H đã sỉ nhục chị B trước đông đảo khách hàng. Chị B và chị H vi phạm quyền được pháp luật bảo hộ về danh dự, nhân phẩm của công dân.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1194, 'Cô giáo H đã cho hội khuyến học phường X mượn ngôi nhà cô được thừa kế riêng làm địa điểm mở lớp học tình thương mặc dù chồng cô muốn ngôi nhà đó để gia đình nghỉ ngơi vào cuối tuần.&nbsp;Cô giáo H không vi phạm quyền bình đẳng hôn nhân và gia đình trong quan hệ nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Đối lập", "B": "Nhân dân", "C": "Tham vấn", "D": "Tài sản"}', 'A', 'Cô giáo H đã cho hội khuyến học phường X mượn ngôi nhà cô được thừa kế riêng làm địa điểm mở lớp học tình thương mặc dù chồng cô muốn ngôi nhà đó để gia đình nghỉ ngơi vào cuối tuần.&nbsp;Cô giáo H không vi phạm quyền bình đẳng hôn nhân và gia đình trong quan hệ tài sản.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1195, 'Hết giờ học, T mượn điện thoại của M để gọi mẹ đến đón. Vì tò mò, T đã tự ý đọc tin nhắn của M rồi phát tán nội dung lên trang thông tin cá nhân. Hôm sau, trong lúc T ra ngoài, M đã tìm cách lấy thư của T rồi đọc cho cả lớp nghe. T và M vi phạm quyền nào dưới đây của công dân?', 'SINGLE_CHOICE', '{"A": "Được đảm bảo an toàn và bí mật thư tín, điện thoại", "B": "Được pháp luật bảo hộ về thân thể", "C": "Được pháp luật bảo hộ về tài sản", "D": "Được đảm bảo an toàn về nơi cư trú hợp pháp"}', 'A', 'Hết giờ học, T mượn điện thoại của M để gọi mẹ đến đón. Vì tò mò, T đã tự ý đọc tin nhắn của M rồi phát tán nội dung lên trang thông tin cá nhân. Hôm sau, trong lúc T ra ngoài, M đã tìm cách lấy thư của T rồi đọc cho cả lớp nghe. T và M vi phạm quyền được đảm bảo an toàn và bí mật thư tín, điện thoại của công dân.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1196, 'Nhà máy A không xây dựng hệ thống xử lí chất thải khiến môi trường bị ô nhiễm nên bà con quanh vùng đã làm đơn phản ánh. Nhà máy A phải chịu trách nhiệm pháp lí nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hình sự", "B": "Hòa giải", "C": "Hành chính", "D": "Đối chất"}', 'A', 'Nhà máy A không xây dựng hệ thống xử lí chất thải khiến môi trường bị ô nhiễm nên bà con quanh vùng đã làm đơn phản ánh. Nhà máy A phải chịu trách nhiệm hành chính.Đáp án C', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1197, 'Biết mình không đủ điều kiện nên anh A lấy danh nghĩa em trai mình là dược sĩ đứng tên trong hồ sơ đăng kí làm đại lí phân phối thuốc tân dược.&nbsp;Sau đó anh A trực tiếp quản lí và bán hàng. Anh A đã vi phạm nôi dung nào dưới đây của quyền bình đẳng trong kinh doanh?', 'SINGLE_CHOICE', '{"A": "Cải tiến quy trình đào tạo", "B": "Thay đổi phương thức quản lí", "C": "Chủ động giao kết hợp đồng", "D": "Tự chủ đăng kí kinh doanh"}', 'A', 'Biết mình không đủ điều kiện nên anh A lấy danh nghĩa em trai mình là dược sĩ đứng tên trong hồ sơ đăng kí làm đại lí phân phối thuốc tân dược.&nbsp;Sau đó anh A trực tiếp quản lí và bán hàng. Anh A đã vi phạm nôi dung tự chủ đăng kí kinh doanh&nbsp;của quyền bình đẳng trong kinh doanh.Đáp án D', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1198, 'Chương trình “Vượt lên chính mình” được tổ chức trên đài truyền hình nhằm xóa nợ và hỗ trợ vốn cho các hộ nghèo là thực hiện vai trò của pháp luật đối với sự phát triển đất nước trên lĩnh vực nào?', 'SINGLE_CHOICE', '{"A": "Xã hội", "B": "Phát triển nông thôn", "C": "Quốc phòng và an ninh", "D": "Kinh doanh"}', 'A', 'Chương trình “Vượt lên chính mình” được tổ chức trên đài truyền hình nhằm xóa nợ và hỗ trợ vốn cho các hộ nghèo là thực hiện vai trò của pháp luật đối với sự phát triển đất nước trên lĩnh vực xã hội.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1199, 'Do mâu thuẫn với E nên H đã vào trang facebook của E tải một số hình ảnh nhạy cảm của E và người yêu về máy sau đó chỉnh sửa và đăng tin xúc phạm E trên facebook của mình. Hành vi của H vi phạm quyền nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Quyền bất khả xâm phạm về thân thể", "B": "Quyền được bảo hộ về danh dự, nhân phẩm của công dân", "C": "Quyền bí mật của công dân", "D": "Quyền tự do của công dân"}', 'A', 'Do mâu thuẫn với E nên H đã vào trang facebook của E tải một số hình ảnh nhạy cảm của E và người yêu về máy sau đó chỉnh sửa và đăng tin xúc phạm E trên facebook của mình. Hành vi của H vi phạm quyền&nbsp;được bảo hộ về danh dự, nhân phẩm của công dân.Đáp án B', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1200, 'Em M là học sinh lớp 1 trường tiểu học X, mới 6 tuổi em đã có năng khiếu đặc biệt là có thể nói và viết thành thạo hai ngôn ngữ Anh, Pháp. Với tài năng của em M đã được nhà nước tặng học bổng tại trường đại học Harvard (Hoa Kì). Chính sách trên của nhà nước thể hiện quyền nào của công dân?', 'SINGLE_CHOICE', '{"A": "Quyền được phát triển của công dân", "B": "Quyền được học tập của công dân", "C": "Quyền được sáng tạo của công dân", "D": "Quyền được ưu tiên của công dân"}', 'A', 'Em M là học sinh lớp 1 trường tiểu học X, mới 6 tuổi em đã có năng khiếu đặc biệt là có thể nói và viết thành thạo hai ngôn ngữ Anh, Pháp. Với tài năng của em M đã được nhà nước tặng học bổng tại trường đại học Harvard (Hoa Kì). Chính sách trên của nhà nước thể hiện quyền&nbsp;được phát triển của công dân.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1201, 'Trong cuộc họp dân phố V để lấy ý kiến người dân về mức đóng góp xây dựng nông thôn mới. Sợ kế hoạch của mình không được người dân nhất trí nên ông G tổ trưởng dân phố chỉ thông báo mức đóng góp và nói trong cuộc họp rằng mức thu này đã được HĐND xã phê duyệt. Ông G đã vi phạm quyền nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Quyền tham gia quản lí nhà nước và xã hội", "B": "Quyền tự do ngôn luận", "C": "Quyền khiếu nại, tố cáo", "D": "Quyền thanh tra, giám sát"}', 'A', 'Trong cuộc họp dân phố V để lấy ý kiến người dân về mức đóng góp xây dựng nông thôn mới. Sợ kế hoạch của mình không được người dân nhất trí nên ông G tổ trưởng dân phố chỉ thông báo mức đóng góp và nói trong cuộc họp rằng mức thu này đã được HĐND xã phê duyệt. Ông G đã vi phạm quyền&nbsp;tham gia quản lí nhà nước và xã hội.Đáp án A', 38);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1202, 'Anh M và anh N cùng nộp hồ sơ đăng kí kinh doanh karaoke trên địa bàn quận Bình Tân. Vì có mối quan hệ thân thiết với anh N nên ông H lãnh đạo cơ quan yêu cầu chị K hủy hồ sơ của anh M. Những ai đã vi phạm quyền bình đẳng trong kinh doanh?', 'SINGLE_CHOICE', '{"A": "Ông H, chị K", "B": "Ông H", "C": "Ông H, chị K và anh N", "D": "Anh M, anh N, ông H, chị K"}', 'A', 'Anh M và anh N cùng nộp hồ sơ đăng kí kinh doanh karaoke trên địa bàn quận Bình Tân. Vì có mối quan hệ thân thiết với anh N nên ông H lãnh đạo cơ quan yêu cầu chị K hủy hồ sơ của anh M. Những người vi phạm quyền bình đẳng trong kinh doanh là ông H và chị K.Đáp án A', 38);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(39, 'Đề thi thử học kỳ 1 môn Giáo Dục Công Dân lớp 11 online - Mã đề 10', 'Giáo Dục Công Dân', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Giáo Dục Công Dân. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1203, 'Những yếu tố của tự nhiên mà lao động của con người tác động vào nhằm biến đổi nó cho phù hợp với mục đích của con người được gọi là .................', 'SINGLE_CHOICE', '{"A": "Tư liệu lao động.", "B": "Cách thức lao động.", "C": "Đối tượng lao động.", "D": "Hoạt động lao động."}', 'A', 'Đối tượng lao động là những yếu tố của tự nhiên mà lao động của con người tác động vào nhắm biến đổi nó cho phù hợp với mục đích của con ngườiĐáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1204, 'Đối tượng lao động gồm mấy loại?', 'SINGLE_CHOICE', '{"A": "1", "B": "2", "C": "3", "D": "4"}', 'A', 'Đối tượng lao động có hai loại: Loại có sẵn trong tự nhiên và loại đã trải qua tác động của lao động.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1205, 'Công dụng của sản phẩm có thể thỏa mãn được nhu cầu nào đó của người sử dụng được gọi là...............', 'SINGLE_CHOICE', '{"A": "Giá trị", "B": "Giá cả", "C": "Giá trị sử dụng", "D": "Giá trị cá biệt"}', 'A', 'Giá trị sử dụng của hàng hóa là công cụ của vật chất có thể thỏa mãn nhu cầu nào đó của con người.Đáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1206, 'Nội dung nào sau đây&nbsp;không&nbsp;phải là tác động của quy luật giá trị?', 'SINGLE_CHOICE', '{"A": "Điều tiết sản xuất và lưu thông hàng hóa.", "B": "Kích thích lực lượng sản xuất phát triển.", "C": "Phân hóa giàu – nghèo.", "D": "Thu hút vốn đầu tư nước ngoài."}', 'A', 'Tác động của quy luật giá trị là: điều tiết sản xuất và lưu thông hàng hóa, kích thích lực lượng sản xuất phát triển và năng suất lao động tăng lên, phân hóa giàu nghèo giữa những người sản xuất.Đáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1207, 'Người sản xuất, kinh doanh muốn thu nhiều lợi nhuận cần tránh ...............', 'SINGLE_CHOICE', '{"A": "Giảm năng suất lao động.", "B": "Cải tiến kĩ thuật.", "C": "Nâng cao tay nghề người lao động.", "D": "Thực hành tiết kiệm."}', 'A', 'Người sản xuất, kinh doanh muốn thu nhiều lợi nhuận phải tìm cách cải tiến kĩ thuật, tăng năng suất lao động, nâng cao tay nghề của người lao động, hợp lí hóa sản xuất, thực hành tiết kiệm…làm cho giá trị hàng hóa cá biệt của họ thấp hơn giá trị xã hội của hàng hóa → làm cho kĩ thuật, lực lượng sản xuất và năng suất lao động xã hội được nâng cao.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1208, 'Nội dung nào dưới đây&nbsp;không&nbsp;phải là biểu hiện của cạnh tranh?', 'SINGLE_CHOICE', '{"A": "Giành nguồn nguyên liệu.", "B": "Giành ưu thế về khoa học công nghệ.", "C": "Giải quyết mâu thuẫn giữa các chủ thể kinh tế.", "D": "Giành ưu thế về chất lượng và giá cả hàng hóa."}', 'A', 'Giải quyết mâu thuẫn giữa các chủ thể kinh tế không phải là biểu hiện của cạnh tranh.Đáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1209, 'Trong sản xuất và lưu thông hàng hóa, khi cung lớn hơn cầu thì giá cả thị trường so với giá trị hàng hóa trong sản xuất sẽ ..............', 'SINGLE_CHOICE', '{"A": "Thấp hơn.", "B": "Cao hơn.", "C": "Bằng nhau.", "D": "Tương đương."}', 'A', 'Trường hợp cung lớn hơn cầu thì giá cả thị trường thường thấp hơn giá trị hàng hóa trong sản xuất.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1210, 'Trong sản xuất và lưu thông hàng hóa, khi cung nhỏ hơn cầu thì giá cả thị trường so với giá trị hàng hóa trong sản xuất sẽ..................', 'SINGLE_CHOICE', '{"A": "Thấp hơn.", "B": "Cao hơn.", "C": "Bằng nhau.", "D": "Tương đương."}', 'A', 'Trường hợp cung nhỏ hơn cầu thì giá cả thị trường thường cao hơn giá trị hàng hóa trong sản xuất.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1211, 'Nội dung nào dưới đây không phải là tác dụng to lớn và toàn diện của công nghiệp hóa, hiện đại hóa?', 'SINGLE_CHOICE', '{"A": "Phát triển lực lượng sản xuất và tăng năng suất lao động xã hội.", "B": "Thúc đẩy sự tăng trưởng và phát triển kinh tế, giải quyết việc làm.", "C": "Tăng thu nhập và nâng cao đời sống nhân dân.", "D": "Xóa bỏ nền văn hóa dân tộc lạc hậu."}', 'A', 'Công nghiệp hóa, hiện đại hóa tạo tiền đề hình thành và phát triển nền văn hóa mới xã hội chủ nghĩa – nền văn hóa tiên tiến, đậm đà bản sắc dân tộc.Đáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1212, 'Thành phần kinh tế nào giữ vai trò chủ đạo trong nền kinh tế nước ta?', 'SINGLE_CHOICE', '{"A": "Kinh tế nhà nước.", "B": "Kinh tế tập thể.", "C": "Kinh tế tư nhân.", "D": "Kinh tế có vốn đầu tư nước ngoài."}', 'A', 'Kinh tế nhà nước giữ vai trò chủ đạo, nắm giữ các vị trí, lĩnh vực then chốt, là lực lượng vật chất quan trọng để Nhà nước định hướng và điều tiết vĩ mô nền kinh tế thị trường ở nước ta hiện nay.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1213, 'Quỹ bảo hiểm nhà nước thuộc thành phần kinh tế nào?', 'SINGLE_CHOICE', '{"A": "Kinh tế có vốn đầu tư nước ngoài.", "B": "Kinh tế tư nhân.", "C": "Kinh tế tập thể.", "D": "Kinh tế nhà nước."}', 'A', 'Thành phần kinh tế nhà nước bao gồm: Doanh nghiệp nhà nước; quỹ dự trữ quốc gia; quỹ bảo hiểm nhà nước; các tài sản thuộc sở hữu nhà nước có thể đưa vào sản xuất kinh doanhĐáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1214, 'Đối với quy luật giá trị, sự phân hóa giàu – nghèo giữa những người sản xuất là một trong những mặt .............', 'SINGLE_CHOICE', '{"A": "Thuận lợi.", "B": "Khó khăn.", "C": "Quan trọng.", "D": "Hạn chế."}', 'A', 'Đối với quy luật giá trị, sự phân hóa giàu – nghèo giữa những người sản xuất là một trong những mặt hạn chế cần được tính đến khi vận dụng nó ở nước ta hiện nay.Đáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1215, 'Nguyên nhân dẫn đến việc phân hóa giàu – nghèo giữa những người sản xuất là do điều kiện sản xuất của từng người là ...............', 'SINGLE_CHOICE', '{"A": "Như nhau.", "B": "Khác nhau.", "C": "Giống nhau.", "D": "Bằng nhau."}', 'A', 'Nguyên nhân dẫn đến việc phân hóa giàu – nghèo giữa những người sản xuất là do điều kiện sản xuất của từng người là khác nhau.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1216, 'Để bán được hàng hóa, nhà sản xuất nên ...............', 'SINGLE_CHOICE', '{"A": "Chú ý đến số lượng hơn chất lượng.", "B": "Nâng cao chất lượng, đa dạng công dụng của hàng hóa.", "C": "Chỉ chú trọng hình thức của sản phẩm.", "D": "Tìm mọi cách để giảm giá sản phẩm."}', 'A', 'Để bán được trên thị trường, người sản xuất luôn tìm cách làm cho hàng hóa của mình có chất lượng cao và có nhiều công dụng, đáp ứng nhu cầu của người tiêu dùng.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1217, 'Đối tượng lao động nào dưới đây là đối tượng của ngành công nghiệp khai thác?', 'SINGLE_CHOICE', '{"A": "Tôm cá.", "B": "Sắt thép.", "C": "Sợi vải.", "D": "Hóa chất."}', 'A', 'Đối tượng lao động có sẵn trong tự nhiên, khai thác là dùng được =&gt; đối tượng của ngành công nghiệp khai thác (đất, tôm cá,…)Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1218, 'Nội dung nào dưới đây&nbsp;không&nbsp;phải là mặt tích cực của cạnh tranh?', 'SINGLE_CHOICE', '{"A": "Kích thích lực lượng sản xuất phát triển.", "B": "Khai thác tối đa mọi nguồn lực của đất nước.", "C": "Thúc đẩy tăng trưởng kinh tế.", "D": "Gây rối loạn thị trường."}', 'A', 'Cạnh tranh tiêu cực, các chủ thể kinh tế đầu cơ tích trữ gây rối loạn thị trường là biểu hiện mặt tiêu cực của cạnh tranh.Đáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1219, 'Trong sản xuất và lưu thông hàng hóa, giá cả và nhu cầu của người tiêu dùng ...............', 'SINGLE_CHOICE', '{"A": "Tỉ lệ thuận.", "B": "Tỉ lệ nghịch.", "C": "Bằng nhau.", "D": "Tương đương nhau."}', 'A', 'Khi giá cả giảm xuống, thì nói chung cầu có xu hướng tăng lên và ngược lại. Vì vậy, giá cả và nhu cầu của người tiêu dùng tỉ lệ nghịch với nhau.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1220, 'Nội dung nào dưới đây là nội dung cơ bản của công nghiệp hóa, hiện đại hóa ở nước ta?', 'SINGLE_CHOICE', '{"A": "Tăng cường phát triển nền kinh tế dựa trên kĩ thuật thủ công.", "B": "Phát triển mạnh mẽ lực lượng sản xuất.", "C": "Phát triển nền văn minh nông nghiệp.", "D": "Hạn chế sử dụng các công nghệ hiện đại."}', 'A', 'Nội dung cơ bản của công nghiệp hóa, hiện đại hóa ở nước ta bao gồm: phát triển mạnh mẽ lực lượng sản xuất, xây dựng cơ cấu kinh tế hợp lí, hiện đại, hiệu quả và củng cố, tăng cường địa vị chủ đạo của quan hệ sản xuất xã hội chủ nghĩa và tiến tới xác lập địa vị thống trị của quan hệ sản xuất xã hội chủ nghĩa trong nền kinh tế quốc dânĐáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1221, 'Cơ cấu kinh tế là tổng thể hữu cơ giữa cơ cấu ngành kinh tế, cơ cấu vùng kinh tế và cơ cấu thành phần kinh tế, trong đó quan trọng nhất là ...............', 'SINGLE_CHOICE', '{"A": "Cơ cấu ngành kinh tế.", "B": "Cơ cấu vùng kinh tế.", "C": "Cơ cấu thành phần kinh tế.", "D": "Các yếu tố quan trọng như nhau."}', 'A', 'Cơ cấu kinh tế là tổng thể hữu cơ giữa cơ cấu ngành kinh tế, cơ cấu vùng kinh tế và cơ cấu thành phần kinh tế, trong đó cơ cấu ngành kinh tế là quan trọng nhất vì nó là cốt lõi của cơ cấu kinh tế.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1222, 'Hợp tác xã là lực lượng nòng cốt của hình thức kinh tế nào?', 'SINGLE_CHOICE', '{"A": "Kinh tế có vốn đầu tư nước ngoài.", "B": "Kinh tế tư nhân.", "C": "Kinh tế tập thể.", "D": "Kinh tế nhà nước."}', 'A', 'Kinh tế tập thể bao gồm: nhiều hình thức hợp tác đa dạng mà hợp tác xã là nòng cốt.Đáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1223, 'Con người ngày càng tạo ra nhiều nguyên vật liệu nhân tạo có tính năng, tác dụng theo ý muốn khiến cho đối tượng lao động ngày càng ................', 'SINGLE_CHOICE', '{"A": "Hạn chế.", "B": "Thu hẹp.", "C": "Đa dạng.", "D": "Tăng lên."}', 'A', 'Đối tượng lao động ngày càng đa dạng, phong phú, con người ngày càng tạo ra nhiều nguyên vật liệu nhân tạo có tính năng, tác dụng theo ý muốnĐáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1224, 'Giá trị của hàng hóa được biểu hiện thông qua ................', 'SINGLE_CHOICE', '{"A": "Giá trị trao đổi.", "B": "Giá trị sử dụng.", "C": "Giá trị lao động.", "D": "Giá trị cá biệt."}', 'A', 'Giá trị của hàng hóa được biểu hiện thông qua giá trị trao đổi của nó. Giá trị trao đổi là một quan hệ về số lượng, hay tỉ lệ trao đổi giữa các hàng hóa có giá trị sử dụng khác nhau.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1225, 'Giá trị hàng hóa là lao động xã hội của ai kết tinh trong hàng hóa đó?', 'SINGLE_CHOICE', '{"A": "Người bán.", "B": "Người mua.", "C": "Người vận chuyển.", "D": "Người sản xuất."}', 'A', 'Giá trị hàng hóa là lao động xã hội của người sản xuất hàng hóa kết tinh trong hàng hóa đó.Đáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1226, 'Trong sản xuất và lưu thông, cạnh tranh lành mạnh, đúng pháp luật được coi là ..............', 'SINGLE_CHOICE', '{"A": "Điều tốt đẹp của nền kinh tế.", "B": "Động lực kinh tế.", "C": "Gây rối loạn thị trường.", "D": "Vi phạm quy luật tự nhiên."}', 'A', 'Cạnh tranh theo đúng pháp luật và gắn liền với các mặt tích cực là cạnh tranh lành mạnh, là động lực kinh tế của sản xuất và lưu thông.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1227, 'Cạnh tranh là quy luật kinh tế tồn tại khách quan, vừa có mặt tích cực vừa có mặt hạn chế nhưng mặt cơ bản, mang tính trội là ...............', 'SINGLE_CHOICE', '{"A": "Mặt tích cực.", "B": "Mặt hạn chế.", "C": "Cả A và B đúng.", "D": "Cả A và B sai."}', 'A', 'Cạnh tranh là quy luật kinh tế tồn tại khách quan, vừa có mặt tích cực vừa có mặt hạn chế nhưng mặt tích cực là cơ bản, mang tính trội, còn mặt hạn chế sẽ được nhà nước điều tiết thông qua giáo dục, pháp luật và các chính sách kinh tế - xã hội thích hợp.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1228, 'Trong sản xuất và lưu thông hàng hóa, giá cả và cung của nhà sản xuất .................', 'SINGLE_CHOICE', '{"A": "Tỉ lệ thuận.", "B": "Tỉ lệ nghịch.", "C": "Bằng nhau.", "D": "Tương đương nhau."}', 'A', 'Khi giá cả tăng lên, các doanh nghiệp mở rộng sản xuất, lượng cung tăng lên và ngược lại. Vì vậy, giá cả và cung tỉ lệ thuận với nhau.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1229, 'Cốt lõi của cơ cấu kinh tế là ................', 'SINGLE_CHOICE', '{"A": "Cơ cấu vùng kinh tế.", "B": "Cơ cấu thành phần kinh tế.", "C": "Cơ cấu ngành kinh tế.", "D": "Cán cân kinh tế."}', 'A', 'Cơ cấu kinh tế là tổng thể hữu cơ giữa cơ cấu ngành kinh tế, cơ cấu vùng kinh tế và cơ cấu thành phần kinh tế, trong đó cơ cấu ngành kinh tế là quan trọng nhất vì nó là cốt lõi của cơ cấu kinh tế.Đáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1230, 'Kinh tế tập thể xây dựng dựa trên nguyên tắc nào?', 'SINGLE_CHOICE', '{"A": "Tự nguyện, dân chủ.", "B": "Tự nguyện, cùng có lợi, quản lí dân chủ và có sự giúp đỡ của Nhà nước.", "C": "Tôn trọng, hợp tác đôi bên cùng có lợi.", "D": "Tự nguyện, cùng có lợi, quản lí dân chủ và phụ thuộc vào kinh tế nhà nước."}', 'A', 'Kinh tế tập thể xây dựng trên nguyên tắc tự nguyện, cùng có lợi, quản lí dân chủ và có sự giúp đỡ của Nhà nướcĐáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1231, 'Trên thị trường giả định không mua bán chịu mà mua bán trả tiền ngay. Trong điều kiện đó, khái niệm cầu được hiểu là tên gọi tắt của ................', 'SINGLE_CHOICE', '{"A": "Nhu cầu có khả năng thanh toán.", "B": "Nhu cầu của người tiêu dùng.", "C": "Mong muốn chính đáng của người dân.", "D": "Nhu cầu đúng đắn."}', 'A', 'Trên thị trường giả định không mua bán chịu mà mua bán trả tiền ngay. Trong điều kiện đó, khái niệm cầu được hiểu là tên gọi tắt của nhu cầu có khả năng thanh toán, tức là nhu cầu mà người tiêu dùng cần mua, được bảo đảm bằng số lượng tiền mà họ sẵn có tương ứng.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1232, 'Mặt hạn chế của cạnh tranh sẽ được điều tiết thông qua ................', 'SINGLE_CHOICE', '{"A": "Giáo dục và pháp luật, chính sách của Nhà nước.", "B": "Ý thức tự giác của các chủ thể kinh tế.", "C": "Dư luận xã hội lên án.", "D": "Hội nhập quốc tế."}', 'A', 'Cạnh tranh là quy luật kinh tế tồn tại khách quan, vừa có mặt tích cực vừa có mặt hạn chế nhưng mặt tích cực là cơ bản, mang tính trội, còn mặt hạn chế sẽ được nhà nước điều tiết thông qua giáo dục, pháp luật và các chính sách kinh tế - xã hội thích hợp.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1233, 'Khi năng suất lao động tăng mà giá cả hàng hóa đó trên thị trường không đổi thì lợi nhuận sẽ ...............', 'SINGLE_CHOICE', '{"A": "Tăng lên.", "B": "Không đổi.", "C": "Giảm xuống.", "D": "Ổn định."}', 'A', 'Nếu giá cả không đổi, khi năng suất lao động tăng, người sản xuất sẽ được tăng lợi nhuận.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1234, 'Một vật hay hệ thống những vật làm nhiệm vụ truyền dẫn sự tác động của con người lên đối tượng lao động, nhằm biến đổi đối tượng lao động thành sản phẩm thỏa mãn nhu cầu của con người được gọi là ..............', 'SINGLE_CHOICE', '{"A": "Đối tượng lao động.", "B": "Đối tượng sản xuất.", "C": "Tư liệu sản xuất.", "D": "Tư liệu lao động."}', 'A', 'Tư liệu lao động là một vật hay hệ thống những vật làm nhiệm vụ truyền dẫn sự tác động của con người lên đối tượng lao động, nhằm biến đổi đối tượng lao động thành sản phẩm thỏa mãn nhu cầu của con ngườiĐáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1235, 'Kết quả của quá trình phát triển lâu dài của sản xuất, trao đổi hàng hóa và các hình thái giá trị là xuất hiện ...................', 'SINGLE_CHOICE', '{"A": "Thị trường.", "B": "Hàng hóa.", "C": "Tiền tệ.", "D": "Kinh tế."}', 'A', 'Tiền tệ xuất hiện là kết quả của quá trình phát triển lâu dài của sản xuất, trao đổi hàng hóa và các hình thái giá trị. Có bốn hình thái giá trị phát triển từ thấp lên cao dẫn đến sự ra đời của tiền tệ.Đáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1236, 'Chuyển dịch cơ cấu kinh tế phải gắn với chuyển dịch cơ cấu ..............', 'SINGLE_CHOICE', '{"A": "Lao động.", "B": "Xã hội.", "C": "Đời sống.", "D": "Công nghiệp."}', 'A', 'Chuyển dịch cơ cấu kinh tế phải gắn với chuyển dịch cơ cấu lao động theo hướng công nghiệp hóa, hiện đại hóa gắn liền với phát triển tri thức.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1237, 'Kinh tế tập thể cùng kinh tế nhà nước hợp thành nền tảng vững chắc của ............', 'SINGLE_CHOICE', '{"A": "Nền kinh tế quốc dân.", "B": "Quá trình xây dựng đất nước.", "C": "Sự phát triển xã hội.", "D": "Nền kinh tế hội nhập."}', 'A', 'Kinh tế tập thể cùng kinh tế nhà nước hợp thành nền tảng vững chắc của nền kinh tế quốc dân.Đáp án cần chọn là: A', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1238, 'Những nội dung nào sau đây&nbsp;không&nbsp;phải là yếu tố của tư liệu lao động?', 'SINGLE_CHOICE', '{"A": "Công cụ lao động.", "B": "Hệ thống bình chứa.", "C": "Tư liệu sản xuất.", "D": "Kết cấu hạ tầng."}', 'A', 'Đối tượng lao động và tư liệu lao động kết hợp lại thành tư liệu sản xuấtĐáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1239, 'Những nội dung nào sau đây&nbsp;không&nbsp;phải là chức năng của tiền tệ?', 'SINGLE_CHOICE', '{"A": "Thước đo giá trị.", "B": "Phương tiện cất trữ.", "C": "Phương tiện thanh toán.", "D": "Điều tiết tiêu dùng."}', 'A', 'Tiền tệ có 5 chức năng gồm: Thước đo giá trị, phương tiện lưu thông, phương tiện cất trữ, phương tiện thanh toán, tiện tệ thế giới.Đáp án cần chọn là: D', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1240, 'Ba cửa hàng bánh sinh nhật là A, B và C có chất lượng, mẫu mã tương đương nhau. Cửa hàng A làm 1 chiếc bánh mất 3h, cửa hàng B làm 1 chiếc bánh mất 5h, cửa hàng C làm 1 chiếc bánh mất 7h. Trong khi đó, thời gian lao động xã hội cần thiết để làm ra 1 chiếc bánh là 5h. Vậy, nhà sản xuất nào sẽ thu được lợi nhuận?', 'SINGLE_CHOICE', '{"A": "Cả ba nhà sản xuất A, B và C.", "B": "Nhà sản xuất A.", "C": "Nhà sản xuất A và B.", "D": "Nhà sản xuất B và C."}', 'A', 'Cửa hàng A và B có thời gian lao động cá biệt phù hợp với thời gian lao động xã hội cần thiết, là phù hợp với quy luật giá trị nên sẽ thu được lợi nhuận.Đáp án cần chọn là: C', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1241, 'Nội dung nào dưới đây là mặt hạn chế của cạnh tranh?', 'SINGLE_CHOICE', '{"A": "Bảo vệ tài nguyên thiên nhiên.", "B": "Khai thác cạn kiệt tài nguyên.", "C": "Thúc đẩy tăng trưởng kinh tế.", "D": "Kích thích lực lượng sản xuất phát triển."}', 'A', 'Một trong những mặt hạn chế của cạnh tranh là việc các chủ thể kinh tế chạy theo lợi nhuận một cách thiếu ý thức, vi phạm quy luật tự nhiên trong khai thác tài nguyên dẫn đến tình trạng tài nguyên bị cạn kiệt.Đáp án cần chọn là: B', 39);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1242, 'Theo em, trường hợp nào sau đây có lợi cho người mua hàng trên thị trường?', 'SINGLE_CHOICE', '{"A": "Cung lớn hơn cầu.", "B": "Cung bằng cầu.", "C": "Cung nhỏ hơn cầu.", "D": "Cung gấp đôi cầu."}', 'A', 'Khi cung lớn hơn cầu, giá cả thị trường nhỏ hơn giá trị sản xuất, vì vậy người mua hàng sẽ được lợi hơn.Đáp án cần chọn là: A', 39);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(40, 'Đề thi thử học kỳ 2 môn Giáo Dục Công Dân lớp 10 online - Mã đề 10', 'Giáo Dục Công Dân', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Giáo Dục Công Dân. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1243, 'Bà A định cư ở Mỹ, nhưng hàng năm bà thường về quê hương Việt Nam để ăn tết cổ truyền của dân tộc. Việc làm của bà A thể hiện nội dung nào dưới đây của lòng yêu nước?', 'SINGLE_CHOICE', '{"A": "Tình thương yêu đồng bào, dân tộc.", "B": "Sự nhớ thương về quê hương.", "C": "Tình cảm gắn bó với quê hương đất nước.", "D": "Lòng tự hào dân tộc."}', 'A', 'Việc làm của bà A thể hiện tình cảm gắn bó với quê hương đất nước.Đáp án C.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1244, 'Là học sinh giỏi của lớp nhưng bạn H sống xa lánh với hầu hết các bạn trong lớp, vì cho rằng mình học giỏi thì chỉ cần chơi với một vài bạn học giỏi là được. Nếu là bạn của H, em sẽ chọn giải pháp nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Khuyên H nên kết bạn với nhiều người học giỏi hơn mình để được giúp đỡ.", "B": "Khuyên H cứ sống theo ý mình miễn vui là được rồi.", "C": "Khuyên H nên sống hòa nhập với mọi người để được mọi người yêu quý.", "D": "Không quan tâm đến việc làm của H vì đó là việc riêng của mỗi người."}', 'A', 'Nếu là bạn của H, em sẽ khuyên H nên sống hòa nhập với mọi người để được mọi người yêu quý.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1245, 'Phải biết vượt lên mọi khó khăn trở ngại, không ngừng học hỏi, phát huy ưu điểm, khắc phục khuyết điểm, là thể hiện nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Tự nhìn nhận, đách giá bản thân.", "B": "Tự xác định năng lực bản thân.", "C": "Tự nhận thức về bản thân.", "D": "Tự hoàn thiện bản thân."}', 'A', 'Phải biết vượt lên mọi khó khăn trở ngại, không ngừng học hỏi, phát huy ưu điểm, khắc phục khuyết điểm, là thể hiện tự hoàn thiện bản thân.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1246, 'Khi gặp những thông tin thất thiệt bôi nhọ lãnh đạo Đảng Nhà nước trên mạng Internet em sẽ chọn cách ứng xử nào sau đây?', 'SINGLE_CHOICE', '{"A": "Mặc kệ vấn đề đó không liên quan đến mình.", "B": "Quyết tâm tìm hiểu để biết rõ sự thật.", "C": "Chia sẻ thông tin đó với mọi người.", "D": "Không tin, không bình luận, không chia sẻ thông tin ấy."}', 'A', 'Khi gặp những thông tin thất thiệt bôi nhọ lãnh đạo Đảng Nhà nước trên mạng Internet em sẽ không tin, không bình luận, không chia sẻ thông tin ấy.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1247, 'Hôm nay là ngày K phải trực nhật cuối giờ học nhưng cuối buổi học K đã không hoàn thành nhiệm vụ mà ra về. Khi đó thấy rác còn trong lớp, em sẽ chọn cách ứng xử nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Gọi K lên trường trực nhật lại.", "B": "Báo cho GVCN hạ hạnh kiểm của K.", "C": "Tự giác nhặt rác, hôm sau sẽ góp ý với K.", "D": "Mặc kệ và thản nhiên ra về."}', 'A', 'Khi đó thấy rác còn trong lớp, em sẽ tự giác nhặt rác, hôm sau sẽ góp ý với K.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1248, 'L tâm sự với H mình rất thích học môn Hóa, có thể chơi được các loại nhạc cụ, tương lai muốn trở thành một nhạc công. Theo em tâm sự của L thể hiện nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Đánh giá điểm mạnh của bản thân.", "B": "Ước mơ hoài bảo của L.", "C": "Tự nhận thức về bản thân.", "D": "Tự hoàn thiện bản thân."}', 'A', 'Theo em tâm sự của L thể hiện việc tự nhận thức về bản thân.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1249, 'Nhân ngày 27/7, học sinh lớp 10A đến viếng nghĩa trang liệt sỹ ở địa phương. Hoạt động đó thể hiện trách nhiệm nào dưới đây của công dân đối với cộng đồng?', 'SINGLE_CHOICE', '{"A": "Nhân nghĩa.", "B": "Nhân ái.", "C": "Hợp tác.", "D": "Hòa nhập."}', 'A', 'Nhân ngày 27/7, học sinh lớp 10A đến viếng nghĩa trang liệt sỹ ở địa phương.=&gt; Hoạt động đó thể hiện trách nhiệm nhân nghĩa&nbsp;của công dân đối với cộng đồng.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1250, 'Quan điểm nào sau đây thể hiện đúng trách nhiệm của công dân?', 'SINGLE_CHOICE', '{"A": "Bảo vệ Tổ Quốc là trách nhiệm của công an, quân đội.", "B": "Xây dựng Tổ Quốc là trách nhiệm của những người thành niên.", "C": "Xây dựng và bảo vệ Tổ Quốc là việc làm của nhà nước.", "D": "Xây dựng và bảo vệ Tổ Quốc là trách nhiệm của mọi người."}', 'A', 'Xây dựng và bảo vệ Tổ Quốc là trách nhiệm của mọi người&nbsp;thể hiện đúng trách nhiệm của công dân.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1251, 'Để hạn chế bùng nổ dân số, chúng ta cần làm gì?', 'SINGLE_CHOICE', '{"A": "sống chung thủy một vợ một chồng.", "B": "nghiêm chỉnh thực hiện chính sách dân số, kế hoạch hóa gia đình.", "C": "thực hiện tốt chính sách phát triển kinh tế, văn hóa của đất nước.", "D": "không kết hôn và sinh con."}', 'A', 'Để hạn chế bùng nổ dân số, chúng ta cần&nbsp;nghiêm chỉnh thực hiện chính sách dân số, kế hoạch hóa gia đình.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1252, 'Ở trường, A học yếu môn Tiếng Anh. Kỳ thi học kỳ 2 sắp đến gần, A cảm thấy rất lo lắng vì mình phải đối mặt với nguy cơ có thể ở lại lớp. Nếu em là A, em sẽ chọn cách ứng xử nào sau đây?', 'SINGLE_CHOICE', '{"A": "Thôi kệ, mặc cho số phận may rủi.", "B": "Tìm cách nhìn bài bạn ngồi bên cạnh khi thi học kỳ.", "C": "Ra sức học tập để khắc phục điểm yếu.", "D": "Mang tài liệu vào phòng khi đi thi học kỳ."}', 'A', 'Ra sức học tập để khắc phục điểm yếu.Đáp án C', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1253, 'Tích cực tham gia góp phần xây dựng quê hương bằng những việc làm thiết thực, phù hợp với khả năng là thực hiện trách nhiệm nào dưới đây của học sinh?', 'SINGLE_CHOICE', '{"A": "Bảo vệ quê hương.", "B": "Xây dựng Tổ quốc.", "C": "Yêu quê hương đất nước.", "D": "Làm giàu cho quê hương."}', 'A', 'Tích cực tham gia góp phần xây dựng quê hương bằng những việc làm thiết thực, phù hợp với khả năng là thực hiện trách nhiệm xây dựng Tổ quốc.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1254, 'Để thực hiện tốt việc tự hoàn thiện bản thân chúng ta cần thực hiện nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Không chơi với những người kém cỏi.", "B": "Thường xuyên tìm đến người tài giỏi để học hỏi.", "C": "Tự tin vào bản thân và không ngừng học hỏi.", "D": "Không ngừng đánh giá cao về bản thân."}', 'A', 'Để thực hiện tốt việc tự hoàn thiện bản thân chúng ta cần tự tin vào bản thân và không ngừng học hỏi.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1255, 'Theo em, ý kiến nào sau đây là đúng?', 'SINGLE_CHOICE', '{"A": "Nhân ái là tình người trong giao tiếp.", "B": "Nhân ái là tôn trọng và sẵn sàng hi sinh vì mọi người.", "C": "Nhân ái là yêu thương con người theo đúng lẽ phải.", "D": "Nhân ái là làm tất cả mọi việc để giúp người khác."}', 'A', 'Đáp án CNhân ái là yêu thương con người theo đúng lẽ phải là ý kiến đúng về nhân ái.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1256, 'Bác Hồ đã từng bôn ba rất nhiều nơi, song dù ở đâu Bác cũng được nhân dân địa phương từ người già đến trẻ em yêu mến, gần gũi, tin cậy như một người thân trong gia đình. Điều này thể hiện phẩm chất đạo đức nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hòa nhập.", "B": "Nhân ái.", "C": "Hợp tác.", "D": "Nhân nghĩa."}', 'A', 'Bác Hồ đã từng bôn ba rất nhiều nơi, song dù ở đâu Bác cũng được nhân dân địa phương từ người già đến trẻ em yêu mến, gần gũi, tin cậy như một người thân trong gia đình.=&gt; Điều này thể hiện phẩm chất hòa nhập.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1257, 'Bạn N luôn tự ti vì hoàn cảnh gia đình, nên ít tiếp xúc với các bạn và không tham gia các hoạt động tập thể của trường, lớp. Bạn N đã không thực hiện tốt nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hòa nhập.", "B": "Hợp tác.", "C": "Bình đẳng.", "D": "Đoàn kết."}', 'A', 'Bạn N luôn tự ti vì hoàn cảnh gia đình, nên ít tiếp xúc với các bạn và không tham gia các hoạt động tập thể của trường, lớp. Bạn N đã không thực hiện tốt việc hòa nhập.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1258, 'Việc làm và biểu hiện nào dưới đây là biểu hiện lối sống hòa nhập?', 'SINGLE_CHOICE', '{"A": "Chủ động tham gia mọi hoạt động tập thể.", "B": "Thích chỉ huy người khác.", "C": "Tập trung lo tốt việc của mình.", "D": "Chỉ kết bạn và làm việc với người cùng sở thích."}', 'A', 'Chủ động tham gia mọi hoạt động tập thể là&nbsp;biểu hiện lối sống hòa nhập.Đáp án A.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1259, 'Biết tin đồng bào miền Trung bị lũ lụt và gặp nhiều khó khăn trong cuộc sống, ông Q dù không khá giả &nbsp;nhưng cũng trích một ít tiền tiết kiệm của mình để ủng hộ và vận động mọi người cùng tham gia. Ông K thấy vậy đã cho rằng ông Q nghèo mà sĩ diện. Nếu là em thì em sẽ chọn giải pháp nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Không đồng ý với việc làm của ông Q vì mình cũng không giàu có.", "B": "Không quan tâm với những vấn đề trên.", "C": "Đồng ý với ông K vì mình khó khăn thì không cần phải giúp người khác.", "D": "Đồng ý với ông Q vì đây là việc làm nhân nghĩa giúp ích cho mọi người."}', 'A', 'Nếu là em, em sẽ đồng ý với ông Q vì đây là việc làm nhân nghĩa giúp ích cho mọi người.Đáp án D', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1260, 'Bùng nổ dân số là gì?', 'SINGLE_CHOICE', '{"A": "sự gia tăng dân số một cách nhanh chóng.", "B": "sự gia tăng dân số trong một thời gian ngắn.", "C": "sự gia tăng dân số một cách quá nhanh trong một thời gian ngắn.", "D": "sự gia tăng dân số một cách đột ngột trong một thời gian ngắn."}', 'A', 'Bùng nổ dân số là sự gia tăng dân số một cách quá nhanh trong một thời gian ngắn.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1261, 'Ý kiến nào dưới đây là đúng khi nói về hợp tác?', 'SINGLE_CHOICE', '{"A": "Đèn nhà ai, nhà nấy rạng.", "B": "Chỉ hợp tác khi có lợi cho mình.", "C": "Chỉ hợp tác khi mình yếu, kém.", "D": "Đem lại hiệu quả cao hơn trong công việc."}', 'A', 'Hợp tác đem lại hiệu quả cao hơn trong công việc&nbsp;là đúng.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1262, 'Nhà ông A và nhà bà B ở gần nhau, nhà ông A làm nghề giết mổ gia cầm nên thường xuyên gây ô nhiễm môi trường, bà B nhiều lần nhắc nhở nhưng tình trạng trên vẫn diễn ra vì ông A cho rằng cơ sở của ông đã được cấp giấy phép. Nếu nhà của em ở gần nhà của ông A em chọn cách giải quyết nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Kiến nghị với chính quyền địa phương di dời cơ sở của ông A", "B": "Tìm cách phá hoại cơ sở của ông A", "C": "Không quan tâm vì không phải việc của mình.", "D": "Kêu gọi mọi người không sử dụng gia cầm của cơ sở ông A"}', 'A', 'Nếu nhà của em ở gần nhà của ông A em sẽ kiến nghị với chính quyền địa phương di dời cơ sở của ông A.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1263, 'Nhân dịp kỉ niệm ngày thành lập Quân Đội Nhân dân Việt Nam trường tổ chức hoạt động viếng nghĩa trang liệt sĩ tại địa phương, phát động mỗi lớp cử 10 HS tham gia. Là học sinh của trường em sẽ chọn cách ứng xử nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Tìm lí do để xin được nghỉ không tham gia.", "B": "Đăng kí tham gia và vận động bạn bè tham gia.", "C": "Tham gia để được tuyên dương.", "D": "Tham gia khi có chỉ định của giáo viên."}', 'A', '&nbsp;Là học sinh của trường em sẽ đăng kí tham gia và vận động bạn bè tham gia.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1264, 'Học sinh trường A tham gia hoạt động quyên góp giúp đỡ đồng bào Miền Trung bị lũ lụt là biểu hiện nào dưới đây của lòng yêu nước?', 'SINGLE_CHOICE', '{"A": "Tinh thần tương thân tương ái của dân tộc.", "B": "Tình cảm gắn bó với quê hương đất nước.", "C": "Truyền thống nhân nghĩa của dân tộc.", "D": "Tình yêu thương với giống nòi dân tộc."}', 'A', 'Học sinh trường A tham gia hoạt động quyên góp giúp đỡ đồng bào Miền Trung bị lũ lụt là biểu hiện tình yêu thương với giống nòi dân tộc.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1265, 'Câu tục ngữ nào dưới đây nói về tự hoàn thiện bản thân?', 'SINGLE_CHOICE', '{"A": "Tốt gỗ hơn tốt nước sơn.", "B": "Gần mực thì đen.", "C": "Con hơn cha nhà có phúc.", "D": "Dốt đến đâu học lâu cũng biết."}', 'A', 'Dốt đến đâu học lâu cũng biết lf câu tục ngữ nói về tự hoàn thiện bản thân.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1266, 'Lòng thương người và đối xử với người theo lẽ phải là chuẩn mực đạo đức nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Nhân văn.", "B": "Nhân đạo.", "C": "Nhân nghĩa.", "D": "Nhân phẩm."}', 'A', 'Lòng thương người và đối xử với người theo lẽ phải là chuẩn mực đạo đức nhân nghĩa.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1267, '“Sự biến đổi của các thành phần môi trường không phù hợp với tiêu chuẩn môi trường, gây ảnh hưởng xấu đến con người và sinh vật” nội dung này đề cập đến khái niệm nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Suy thoái môi trường", "B": "Ô nhiễm môi trường", "C": "Biến đổi môi trường", "D": "Sự cố môi trường"}', 'A', '“Sự biến đổi của các thành phần môi trường không phù hợp với tiêu chuẩn môi trường, gây ảnh hưởng xấu đến con người và sinh vật” nội dung này đề cập đến khái niệm&nbsp;Ô nhiễm môi trường', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1268, 'Học xong lớp 12, N thi đỗ vào đại học thì N nhận được lệnh gọi nhập ngũ. Ba mẹ của N đã tìm mọi cách để N không phải nhập ngũ. Nếu em là N em sẽ chọn giải pháp nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Không thể tham gia vì phải học đại học.", "B": "Đồng ý với việc làm của ba mẹ vì sợ tham gia sẽ cực khổ.", "C": "Bỏ trốn khỏi đại phương để không phải nhập ngũ.", "D": "Khuyên ba mẹ không làm việc đó và nghiêm chỉnh chấp hành lệnh gọi."}', 'A', 'Nếu em là N em sẽ khuyên ba mẹ không làm việc đó và nghiêm chỉnh chấp hành lệnh gọi.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1269, 'Trên đường đi học về, A phát hiện có một nhóm thanh niên tụ tập tiêm chích ma túy. Nếu em là A, em sẽ chọn cách ứng xử nào sau đây?', 'SINGLE_CHOICE', '{"A": "Quay phim và đưa lên facebook.", "B": "Mặc kệ vì không liên quan đến mình.", "C": "Khuyên nhóm thanh niên dừng việc đó.", "D": "Báo với cơ quan chức năng."}', 'A', 'Trên đường đi học về, A phát hiện có một nhóm thanh niên tụ tập tiêm chích ma túy. Nếu em là A, em sẽ báo với cơ quan chức năng.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1270, 'Để mở rộng cơ sở sản xuất, anh A đã mời anh B góp vốn cùng làm với mình. Việc làm của anh A thể hiện nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Hòa nhập.", "B": "Nhân nghĩa.", "C": "Nghĩa vụ.", "D": "Hợp tác."}', 'A', 'Để mở rộng cơ sở sản xuất, anh A đã mời anh B góp vốn cùng làm với mình. Việc làm của anh A thể hiện sự hợp tác.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1271, 'Hành động nào dưới đây không phải là sự hợp tác?', 'SINGLE_CHOICE', '{"A": "Cùng phối hợp nhịp nhàng với nhau.", "B": "Cùng nhau bàn bạc trong công việc.", "C": "Sẵn sàng giúp đỡ nhau khi cần thiết.", "D": "Nhiệm vụ của ai người nấy làm."}', 'A', '&nbsp;Nhiệm vụ của ai người nấy làm&nbsp;không&nbsp;phải là sự hợp tác.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1272, 'Ngày thế giới phòng chống AIDS là ngày nào dưới đây?', 'SINGLE_CHOICE', '{"A": "11 tháng 7.", "B": "1 tháng 12.", "C": "1 tháng 2.", "D": "2 tháng 12."}', 'A', 'Ngày thế giới phòng chống AIDS là ngày 1 tháng 12.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1273, 'A là học sinh lớp 12, mỗi lần đến lớp A chỉ mang một cuốn vở cho tất cả các môn học mà không bao giờ mang sách. Chứng kiến điều đó, B khuyên bạn không nên làm thế. A giải thích rằng mình không mang sách vì mình có trí nhớ rất tốt, học không bao giờ cần sách. Theo em việc làm của A thể hiện nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Đánh giá quá cao về bản thân.", "B": "Đánh giá đúng về bản thân.", "C": "Không tôn trọng giáo viên đứng lớp.", "D": "Là người thông minh xuất chúng."}', 'A', 'Theo em việc làm của A thể hiện việc đánh giá quá cao về bản thân.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1274, 'Hành động tìm kiếm và trao trả hài cốt những binh sĩ Mỹ hi sinh trên đất nước ta của nhà nước ta hiện nay là thể hiện điều gì dưới đây?', 'SINGLE_CHOICE', '{"A": "Truyền thống nhân nghĩa của dân tộc ta.", "B": "Không cố chấp với người có lỗi lầm.", "C": "Tình yêu thương nhân loại.", "D": "Sự hữu nghị, hợp tác với nhau."}', 'A', 'Hành động tìm kiếm và trao trả hài cốt những binh sĩ Mỹ hi sinh trên đất nước ta của nhà nước ta hiện nay là thể hiện truyền thống nhân nghĩa của dân tộc ta.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1275, 'Bạn A và B chơi thân với nhau một hôm A rủ B tham gia vào trang mạng có nội dung xuyên tạc chống phá Nhà Nước XHCN. Nếu là B em sẽ chọn giải pháp nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Cùng A tham gia vào trang mạng đó để nhận được nhiều like trên facebook.", "B": "Rủ nhiều bạn khác cùng tham gia chung cho vui.", "C": "Kiên quyết không tham gia, giải thích A hiểu đó là việc làm trái pháp luật.", "D": "Không tham gia cùng với A vì sẽ mất nhiều thời gian."}', 'A', 'Nếu là B em sẽ kiên quyết không tham gia, giải thích A hiểu đó là việc làm trái pháp luật.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1276, 'Hành vi nào dưới đây là tham gia bảo vệ môi trường?', 'SINGLE_CHOICE', '{"A": "Chôn lấp chất thải, rác thải sâu dưới đất.", "B": "Thu gom các loại rác thải và chất thải đốt đi.", "C": "Tái chế các loại chai nhựa đã qua sử dụng.", "D": "Tập kết rác thải đến các bãi đất trống."}', 'A', 'Tái chế các loại chai nhựa đã qua sử dụng&nbsp;là tham gia bảo vệ môi trường.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1277, 'Truyền thống nào sau đây là truyền thống cao quý và thiêng liêng nhất của dân tộc ta?', 'SINGLE_CHOICE', '{"A": "Uống nước nhớ nguồn.", "B": "Hiếu học.", "C": "Yêu nước.", "D": "Tôn sư trọng đạo."}', 'A', 'Truyền thống&nbsp;yêu nước&nbsp;là truyền thống cao quý và thiêng liêng nhất của dân tộc ta.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1278, 'Địa phương em tổ chức họp dân và thống nhất thành lập tổ thanh niên tự quản an ninh của phường, tham gia tuần tra đề phòng trộm cắp... Là thanh niên trong phường nhưng N tìm cách trốn tránh không tham gia. Nếu là em của N em sẽ chọn cách ứng xử nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Khuyên anh N nên tham gia cho có để khỏi bị chê cười.", "B": "Khuyên cha mẹ xin được nộp tiền để anh N không phải tham gia.", "C": "Đồng ý với anh N không tham gia vì rất nguy hiểm.", "D": "Khuyên anh N tự nguyện tham gia vì đó là trách nhiệm của công dân."}', 'A', 'Nếu là em của N em sẽ khuyên anh N tự nguyện tham gia vì đó là trách nhiệm của công dân.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1279, 'Câu tục ngữ nào dưới đây nói về sống hòa nhập?', 'SINGLE_CHOICE', '{"A": "Chia ngọt sẻ bùi.", "B": "Ngựa chạy có bầy, chim bay có bạn.", "C": "Một miếng khi đói bằng một gói khi no.", "D": "Nhường cơm sẻ áo."}', 'A', 'Ngựa chạy có bầy, chim bay có bạn là câu tục ngữ&nbsp;nói về sống hòa nhập.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1280, 'Tình cảm nào dưới đây là biểu hiện của lòng yêu nước?', 'SINGLE_CHOICE', '{"A": "Lòng vị tha, cao thượng.", "B": "Sự hợp tác với nhau.", "C": "Tình thương yêu đồng bào, dân tộc.", "D": "Quan tâm đến lợi ích của gia đình."}', 'A', 'Tình thương yêu đồng bào, dân tộc là biểu hiện của lòng yêu nước.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1281, 'Lòng yêu nước của dân tộc Việt Nam không bao gồm nội dung nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Tham gia xây dựng đất nước giàu mạnh.", "B": "Tình cảm gắn bó với quê hương đất nước.", "C": "Đề cao dân tộc mình hơn dân tộc khác.", "D": "Tham gia giúp đỡ đồng bào khó khăn."}', 'A', 'Lòng yêu nước của dân tộc Việt Nam không bao gồm việc đề cao dân tộc mình hơn dân tộc khác.', 40);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1282, 'Đời sống cộng đồng chỉ lành mạnh nếu được tổ chức và hoạt động theo nguyên tắc nào dưới đây?', 'SINGLE_CHOICE', '{"A": "Công bằng, dân chủ, kỉ luật.", "B": "Dân chủ, bình đẳng, minh bạch.", "C": "Tự do, dân chủ, công khai.", "D": "Tự nguyện, bình đẳng, hợp tác."}', 'A', 'Đời sống cộng đồng chỉ lành mạnh nếu được tổ chức và hoạt động theo nguyên tắc:&nbsp;Công bằng, dân chủ, kỉ luật.', 40);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(41, 'Thi thử trắc nghiệm ôn tập triết học Mác Lênin online - Chương 3 - Đề #55', 'Triết Học', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Triết Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1283, 'Theo V.I. Lênin, đặc trưng cơ bản nào sau đây KHÔNG thuộc về giai cấp?', 'SINGLE_CHOICE', '{"A": "Tập đoàn người có địa vị kinh tế - xã hội khác nhau.", "B": "Tập đoàn người đông đảo, không phải là những cá nhân riêng lẻ.", "C": "Tập đoàn người có tư tưởng và lối sống riêng biệt.", "D": "Tập đoàn người có vị trí, vai trò khác nhau trong một hệ thống sản xuất xã hội nhất định."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1284, 'Trong hệ thống sản xuất xã hội, yếu tố nào quyết định trực tiếp đến địa vị kinh tế - xã hội của các giai cấp?', 'SINGLE_CHOICE', '{"A": "Quan hệ sở hữu đối với tư liệu sản xuất.", "B": "Quan hệ tổ chức, quản lý sản xuất.", "C": "Quan hệ phân phối của cải xã hội.", "D": "Cả A, B và C đều đúng."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1285, 'Điều gì là nguyên nhân căn bản của mọi xung đột xã hội từ khi xã hội loài người có sự phân chia thành các giai cấp?', 'SINGLE_CHOICE', '{"A": "Sự khác nhau về địa vị xã hội.", "B": "Sự khác nhau về trình độ học vấn.", "C": "Sự đối lập về lợi ích cơ bản giữa các giai cấp.", "D": "Sự khác nhau về nguồn gốc xuất thân."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1286, 'Giai cấp chỉ mất đi khi nào?', 'SINGLE_CHOICE', '{"A": "Khi xã hội đạt đến trình độ văn minh cao.", "B": "Khi chế độ tư hữu về tư liệu sản xuất hoàn toàn bị xóa bỏ.", "C": "Khi nhà nước can thiệp vào phân phối của cải.", "D": "Khi các giai cấp tự nguyện hòa giải với nhau."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1287, 'Trong xã hội có giai cấp, yếu tố nào quy định tính tất yếu của đấu tranh giai cấp?', 'SINGLE_CHOICE', '{"A": "Tính tất yếu chính trị.", "B": "Tính tất yếu kinh tế.", "C": "Tính tất yếu văn hóa.", "D": "Tính tất yếu đạo đức."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1288, 'Thực chất của đấu tranh giai cấp trong xã hội có đối kháng giai cấp là gì?', 'SINGLE_CHOICE', '{"A": "Cuộc đấu tranh của giai cấp thống trị để duy trì quyền lực.", "B": "Cuộc đấu tranh của các tầng lớp trung gian để cải thiện địa vị.", "C": "Cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột.", "D": "Cuộc đấu tranh của các nhà tư tưởng để thay đổi ý thức xã hội."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1289, 'Điều gì là mục đích cao nhất mà một cuộc đấu tranh giai cấp cần đạt được?', 'SINGLE_CHOICE', '{"A": "Đánh đổ một giai cấp cụ thể.", "B": "Giải phóng lực lượng sản xuất khỏi sự kìm hãm của những quan hệ sản xuất đã lỗi thời.", "C": "Thiết lập một chế độ chính trị mới.", "D": "Phân phối lại của cải xã hội một cách công bằng hơn."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1290, 'Trong đấu tranh giai cấp, liên minh giai cấp có vai trò như thế nào?', 'SINGLE_CHOICE', '{"A": "Không quan trọng, vì đấu tranh giai cấp là tự phát.", "B": "Là tất yếu, để tập hợp và phát triển lực lượng.", "C": "Chỉ cần thiết trong giai đoạn đầu của cách mạng.", "D": "Chỉ mang tính sách lược tạm thời."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1291, 'Trong xã hội có giai cấp, đấu tranh giai cấp có vai trò gì đối với sự phát triển của xã hội?', 'SINGLE_CHOICE', '{"A": "Không có vai trò gì, vì sự phát triển của xã hội là tự nhiên.", "B": "Là động lực trực tiếp, quan trọng của lịch sử.", "C": "Chỉ là yếu tố gây rối loạn xã hội.", "D": "Chỉ có vai trò trong một số giai đoạn lịch sử nhất định."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1292, 'Theo C. Mác và Ph. Ăngghen, điều gì sau đây được coi là “đòn bẩy mạnh mẽ của cuộc cách mạng xã hội ngày nay”?', 'SINGLE_CHOICE', '{"A": "Đấu tranh của các dân tộc bị áp bức.", "B": "Đấu tranh của giai cấp nông dân.", "C": "Đấu tranh giai cấp giữa giai cấp tư sản và giai cấp vô sản.", "D": "Đấu tranh của các nhà khoa học và trí thức."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1293, 'Hình thức đấu tranh nào là cao nhất của giai cấp vô sản?', 'SINGLE_CHOICE', '{"A": "Đấu tranh kinh tế.", "B": "Đấu tranh chính trị.", "C": "Đấu tranh tư tưởng.", "D": "Đấu tranh văn hóa."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1294, 'Đảng của giai cấp vô sản có nhiệm vụ gì trong đấu tranh giai cấp?', 'SINGLE_CHOICE', '{"A": "Tuyên truyền, vận động quần chúng.", "B": "Đề ra đường lối chiến lược, sách lược.", "C": "Tổ chức lực lượng.", "D": "Cả A, B và C đều đúng."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1295, 'Mục đích của đấu tranh tư tưởng là gì?', 'SINGLE_CHOICE', '{"A": "Đập tan hệ tư tưởng của giai cấp tư sản.", "B": "Vũ trang cho quần chúng hệ tư tưởng cách mạng.", "C": "Giáo dục quần chúng nhân dân thấm nhuần đường lối cách mạng.", "D": "Cả A, B và C đều đúng."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1296, 'Trong thời kỳ quá độ lên chủ nghĩa xã hội, giai cấp vô sản cần làm gì để bảo vệ thành quả cách mạng?', 'SINGLE_CHOICE', '{"A": "Thực hiện đấu tranh kinh tế.", "B": "Cải tạo xã hội cũ, xây dựng xã hội mới.", "C": "Giữ vững chính quyền.", "D": "Cả B và C đều đúng."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1297, 'Đâu là nhiệm vụ cơ bản và chủ yếu nhất của giai cấp vô sản trong thời kỳ quá độ lên chủ nghĩa xã hội?', 'SINGLE_CHOICE', '{"A": "Giữ vững chính quyền.", "B": "Xây dựng thành công chủ nghĩa xã hội.", "C": "Đấu tranh chống lại giai cấp tư sản.", "D": "Phát triển kinh tế."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1298, 'Trong thời kỳ quá độ lên chủ nghĩa xã hội, đấu tranh giai cấp diễn ra như thế nào?', 'SINGLE_CHOICE', '{"A": "Ít gay go và phức tạp.", "B": "Gay go, quyết liệt và phức tạp.", "C": "Dễ dàng và nhanh chóng.", "D": "Hòa bình và hữu nghị."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1299, 'Mục tiêu của đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là gì?', 'SINGLE_CHOICE', '{"A": "Xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh.", "B": "Giữ vững độc lập dân tộc.", "C": "Thực hiện công nghiệp hóa, hiện đại hóa.", "D": "Phát triển kinh tế thị trường."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1300, 'Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, yếu tố nào đòi hỏi tất yếu phải đấu tranh chống lại khuynh hướng tự phát đi lên chủ nghĩa tư bản?', 'SINGLE_CHOICE', '{"A": "Nền kinh tế kế hoạch hóa tập trung.", "B": "Nền kinh tế thị trường định hướng xã hội chủ nghĩa.", "C": "Nền kinh tế đóng cửa, tự cung tự cấp.", "D": "Nền kinh tế có vốn đầu tư nước ngoài lớn."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1301, 'Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, cuộc đấu tranh giai cấp diễn ra trên lĩnh vực nào?', 'SINGLE_CHOICE', '{"A": "Kinh tế.", "B": "Chính trị.", "C": "Tư tưởng, văn hóa.", "D": "Trên tất cả các lĩnh vực của đời sống xã hội."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1302, 'Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, lực lượng nào trở thành giai cấp lãnh đạo sự nghiệp cách mạng?', 'SINGLE_CHOICE', '{"A": "Giai cấp nông dân.", "B": "Giai cấp công nhân.", "C": "Tầng lớp trí thức.", "D": "Quân đội nhân dân."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1303, 'Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, nhiệm vụ nào là trung tâm, xuyên suốt?', 'SINGLE_CHOICE', '{"A": "Xây dựng quân đội hùng mạnh.", "B": "Phát triển kinh tế, tạo lập cơ sở vật chất - kỹ thuật.", "C": "Củng cố chính quyền nhà nước.", "D": "Tăng cường quan hệ đối ngoại."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1304, 'Nội dung chủ yếu của cuộc đấu tranh giai cấp ở Việt Nam hiện nay là gì?', 'SINGLE_CHOICE', '{"A": "Thực hiện công nghiệp hóa, hiện đại hóa theo định hướng xã hội chủ nghĩa.", "B": "Thực hiện công bằng xã hội, chống áp bức, bất công.", "C": "Đấu tranh ngăn chặn và khắc phục những tư tưởng và hành động tiêu cực.", "D": "Cả A, B và C đều đúng."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1305, 'Để thực hiện thắng lợi cuộc đấu tranh giai cấp ở Việt Nam, cần giải quyết tốt các phương hướng và nhiệm vụ nào?', 'SINGLE_CHOICE', '{"A": "Nâng cao năng lực và sức chiến đấu của Đảng.", "B": "Đẩy mạnh toàn diện công cuộc đổi mới và sự nghiệp công nghiệp hóa, hiện đại hóa đất nước.", "C": "Phát triển văn hóa, thực hiện tiến bộ và công bằng xã hội.", "D": "Cả A, B và C đều đúng."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1306, 'Trong đấu tranh giai cấp ở Việt Nam hiện nay, cần thấu triệt quan điểm của Đảng Cộng sản Việt Nam về điều gì?', 'SINGLE_CHOICE', '{"A": "Đấu tranh giai cấp và đấu tranh dân tộc.", "B": "Xây dựng quân đội.", "C": "Phát triển kinh tế.", "D": "Phát triển văn hóa."}', 'A', '', 41);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1307, 'Hình thức cộng đồng người nào là cao nhất và phổ biến nhất của xã hội loài người hiện nay?', 'SINGLE_CHOICE', '{"A": "Thị tộc.", "B": "Bộ lạc.", "C": "Bộ tộc.", "D": "Dân tộc."}', 'A', '', 41);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(42, 'Thi thử trắc nghiệm ôn tập triết học Mác Lênin online - Đề #5', 'Triết Học', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Triết Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1308, 'Khái niệm cái đơn nhất dùng để chỉ cái…', 'SINGLE_CHOICE', '{"A": "Tồn tại ở nhiều sự vật, hiện tượng", "B": "Chỉ tồn tại ở một sự vật, hiện tượng, tuyệt đối không lặp lại sự vật hiện tượng khác", "C": "Tồn tại ở một sự vật, hiện tượng, trong một quan hệ xác định", "D": "Không có phương án nào"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1309, 'Phạm trù triết học nào dùng để chỉ những thuộc tính chung, không những có ở một kết cấu vật&nbsp;chất nhất định mà còn được lặp lại trong nhiều sự vật, hiện tượng hay quá trình riêng lẻ khác:', 'SINGLE_CHOICE', '{"A": "Cái riêng", "B": "Cái chung", "C": "Cái đơn nhất", "D": "Tất cả đều sai"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1310, 'Cái … chỉ tồn tại trong cái … thông qua cái riêng mà biểu hiện sự tồn tại của mình.', 'SINGLE_CHOICE', '{"A": "Chung/Riêng", "B": "Riêng/Chung", "C": "Chung/Đơn nhất", "D": "Đơn nhất/Riêng"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1311, 'Cái … chỉ tồn tại trong mối liên hệ với cái …', 'SINGLE_CHOICE', '{"A": "Chung/Riêng", "B": "Riêng/Chung", "C": "Chung/Đơn nhất", "D": "Đơn nhất/Riêng"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1312, 'Cái … là cái toàn bộ, phong phú hơn cái …', 'SINGLE_CHOICE', '{"A": "Chung/Riêng", "B": "Riêng/Chung", "C": "Chung/Đơn nhất", "D": "Đơn nhất/Riêng"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1313, 'Cái … là cái bộ phận, nhưng sâu sắc hơn cái …', 'SINGLE_CHOICE', '{"A": "Chung/Riêng", "B": "Riêng/Chung", "C": "Chung/Đơn nhất", "D": "Đơn nhất/Riêng"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1314, 'Cái … và cái … có thể chuyển hóa lẫn nhau trong quá trình phát triển của sự vật.', 'SINGLE_CHOICE', '{"A": "Chung/Riêng", "B": "Riêng/Chung", "C": "Chung/Đơn nhất", "D": "Đơn nhất/Riêng"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1315, 'Cái riêng và cái chung có thể chuyển hóa (liên hệ, thống nhất, quy định lẫn nhau) cho nhau&nbsp;không?', 'SINGLE_CHOICE', '{"A": "Có thế", "B": "Không thể", "C": "Vừa có thể vừa không thể", "D": ""}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1316, 'Công cuộc xây dựng chủ nghĩa xã hội trên thế giới phải xuất phát từ tình hình cụ thể của từng&nbsp;đất nước. Đó là bài học về việc…', 'SINGLE_CHOICE', '{"A": "Áp dụng cái chung phải tùy theo từng cái riêng cụ thể để vận dụng cho thích hợp.", "B": "Áp dụng cái chung phải tùy theo từng cái đơn nhất cụ thể để vận dụng cho thích hợp.", "C": "Áp dụng cái riêng phải dựa vào cái chung.", "D": ""}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1317, 'Giả sử khái niệm&nbsp; Việt Nam là một “Cái riêng” thì yếu tố nào sau đây là cái đơn nhất:', 'SINGLE_CHOICE', '{"A": "Con người.", "B": "Quốc gia.", "C": "Văn hóa.", "D": "Hà Nội."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1318, 'Triết gia nào cho rằng: “Cái chung là những ý niệm tồn tại vĩnh viễn, bên cạnh những cái riêng&nbsp;có tính chất tạm thời”.', 'SINGLE_CHOICE', '{"A": "Đêmôcrít.", "B": "Hêraclít.", "C": "Platôn.", "D": "C. Mác."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1319, 'Khi một vật, một hiện tượng mới được nảy sinh thì yếu tố nào sẽ xuất hiện đầu tiên:', 'SINGLE_CHOICE', '{"A": "Cái chung.", "B": "Cái riêng.", "C": "Cái đơn nhất.", "D": "Cái phổ biến."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1320, 'Phạm trù nhằm chỉ sự tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với&nbsp;nhau, gây ra một biến đổi nào đó, gọi là gì?', 'SINGLE_CHOICE', '{"A": "Nguyên nhân.", "B": "Kết quả.", "C": "Khả năng.", "D": "Không có đáp án nào đúng."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1321, 'Phạm trù nhằm chỉ những biến đổi xuất hiện do tác động lẫn nhau giữa các mặt trong một sự vật&nbsp;hoặc giữa các sự vật với nhau gây ra, gọi là gì?', 'SINGLE_CHOICE', '{"A": "Nguyên nhân.", "B": "Kết quả.", "C": "Khả năng.", "D": "Hệ quả."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1322, 'Nguyên nhân và kết quả, cái nào có trước?', 'SINGLE_CHOICE', '{"A": "Nguyên nhân.", "B": "Kết quả.", "C": "Cả hai xuất hiện cùng lúc.", "D": "Không có đáp án nào đúng."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1323, 'Trong các cặp khái niệm dưới đây, cặp nào (có thể) là quan hệ nhân quả.', 'SINGLE_CHOICE', '{"A": "Đông – Tây", "B": "Nghèo – Dốt.", "C": "Xuân – Hạ.", "D": "Ngày – Đêm."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1324, 'Có rất nhiều loại nguyên nhân, như: nguyên nhân cơ bản, nguyên nhân chủ yếu, nguyên&nbsp; nhân&nbsp;bên trong, nguyên nhân bên ngoài, nguyên nhân chủ quan, nguyên nhân khách quan… Điều đó chứng&nbsp;tỏ…', 'SINGLE_CHOICE', '{"A": "Một kết quả chỉ có thể do một loại nguyên nhân gây ra.", "B": "Một kết quả có thể do nhiều loại nguyên nhân gây ra.", "C": "Một kết quả có thể không cần nguyên nhân gây ra.", "D": "Không thể nhận thức được quan hệ nguyên nhân – kết quả."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1325, '“Đói nghèo” và “Dốt nát”, hiện tượng nào là nguyên nhân, hiện tượng nào là kết quả?', 'SINGLE_CHOICE', '{"A": "Đói nghèo là nguyên nhân, dốt nát là kết quả.", "B": "Dốt nát là nguyên nhân, đói nghèo là kết quả.", "C": "Cả hai đều là nguyên nhân.", "D": "Hiện tượng này vừa là nguyên nhân vừa là kết quả của hiện tượng kia."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1326, 'Mối liên hệ nhân quả có các tính chất gì?', 'SINGLE_CHOICE', '{"A": "Tính khách quan và tính phổ biến.", "B": "Tính khách quan và tính tất yếu.", "C": "Tính khách quan, tính chủ quan và tính tất yếu.", "D": "Tính khách quan, tính phổ biến và tính tất yếu."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1327, 'Có những sự vật, hiện tượng xảy ra…', 'SINGLE_CHOICE', '{"A": "Không có nguyên nhân nào.", "B": "Có nguyên nhân nhưng không thể nhận thức được.", "C": "Có nguyên nhân nhưng chưa nhận thức được.", "D": "Có nguyên nhân và luôn nhận thức được."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1328, 'Những sự vật, hiện tượng nếu có cùng một nguyên nhân, trong những điều kiện giống nhau thì&nbsp;sẽ tạo nên những kết quả như nhau. Điều này thể hiện tính chất… của mối liên hệ nhân quả.', 'SINGLE_CHOICE', '{"A": "Tính khách quan.", "B": "Tính phổ biến.", "C": "Tính tất yếu.", "D": "Tính biện chứng."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1329, 'Mối liên hệ nhân quả của các sự vật, hiện tượng là…', 'SINGLE_CHOICE', '{"A": "Phụ thuộc vào ý thức của con người.", "B": "Do thượng đế sinh ra.", "C": "Do hoạt động của con người quy định.", "D": "Tất cả điều sai."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1330, 'Ph.Ăngghen cho rằng: Đối với ai phủ nhận… thì mọi quy luật của tự nhiên đều là giải thuyết.', 'SINGLE_CHOICE', '{"A": "Vấn đề nội dung và hình thái.", "B": "Phạm trù khả năng và hiện thực.", "C": "Tính nhân quả.", "D": "Tính biện chứng."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1331, 'Quan điểm&nbsp; cho rằng: Nguyên nhân của mọi loại hiện tượng là do một thực thể tinh thần tồn tại&nbsp;bên ngoài ta tạo nên. Đó là quan điểm của trường phái triết học nào?', 'SINGLE_CHOICE', '{"A": "Chủ nghĩa duy tâm chủ quan.", "B": "Chủ nghĩa duy tâm khách quan và tôn giáo.", "C": "Chủ nghĩa Mác – Lênin.", "D": "Cả A, B, C."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1332, 'Quan điểm cho rằng mối liên hệ nhân quả bao trùm tất cả mọi hiện tượng của hiện thực, không&nbsp;trừ một hiện tượng nào. Đây là nội dung của nguyên tắc nào?', 'SINGLE_CHOICE', '{"A": "Nguyên tắc Quyết định luận.", "B": "Nguyên tắc Vô định luận.", "C": "Cả hai đều sai.", "D": "Cả hai đều đúng."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1333, 'Vật trong chân không luôn chuyển động với gia tốc 9,8 m/s2; nước ở áp suất 1 atmôtphe luôn&nbsp;sôi ở 1000C. Điều này chứng tỏ…', 'SINGLE_CHOICE', '{"A": "Giữa nguyên nhân và kết quả có mối quan hệ sản sinh.", "B": "Nguyên nhân luôn luôn có trước kết quả.", "C": "Một nguyên nhân nhất định, trong những hoàn cảnh giống nhau, sẽ tạo nên những kết quả giống nhau.", "D": "Không chứng tỏ điều gì."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1334, 'Cái do những nguyên nhân cơ bản bên trong của kết cấu vật chất quyết định và trong những&nbsp;điều kiện nhất định, nó phải xảy ra như thế chứ không thể khác được, gọi là gì?', 'SINGLE_CHOICE', '{"A": "Tất nhiên.", "B": "Ngẫu nhiên.", "C": "Hệ quả.", "D": "Khả năng."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1335, 'Cái không do mối liên hệ bản chất bên trong kết cấu vật chất, bên trong sự vật quyết định, mà&nbsp;do các nhân tố bên ngoài, do sự ngẫu hợp của nhiều hoàn cảnh bên ngoài quyết định, gọi là gì?', 'SINGLE_CHOICE', '{"A": "Tất nhiên.", "B": "Ngẫu nhiên.", "C": "Khả năng.", "D": "Không xác định"}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1336, 'Cái ngẫu nhiên là cái…', 'SINGLE_CHOICE', '{"A": "Diễn ra hoàn toàn không chịu sự chi phối của quy luật nào.", "B": "Hoàn toàn diễn ra theo quy luật.", "C": "Biểu hiện của quy luật.", "D": "Không biểu hiện của bất cứ quy luật nào."}', 'A', '', 42);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1337, 'Cái tất nhiên tuân theo loại quy luật nào sau đây?', 'SINGLE_CHOICE', '{"A": "Quy luật động lực.", "B": "Quy luật thống kê.", "C": "Quy luật khách quan.", "D": "Cả ba đều đúng."}', 'A', '', 42);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(43, 'triết học 1-27', 'Triết Học', 45, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Triết Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1338, 'Câu 1: Câu 1: Câu 1: Triết học ra đời từ thực tiễn, do nhu cầu của thực tiễn, nó có các nguồn gốc:', 'SINGLE_CHOICE', '{"A": "Nguồn gốc nhận thức và nguồn gốc xã hội.", "B": "Nguồn gốc nhận thức, nguồn gốc xã hội và nguồn gốc giai cấp.", "C": "Nguồn gốc tự nhiên, nguồn gốc xã hội và nguồn gốc tư duy.", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1339, 'Câu 2: Câu 2: Câu 2: Đối tượng nghiên cứu của triết học là:', 'SINGLE_CHOICE', '{"A": "a) Những quy luật của thế giới khách quan", "B": "b) Những quy luật chung nhất của tự nhiên, xã hội và tư duy", "C": "c) Những vấn đề chung nhất của giới tự nhiên, của xã hội và con người, mối quan hệ của con người nói chung, của tư duy con người nói riêng với thế giới xung quanh.", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1340, 'Câu 3: Câu 3: Câu 3: Triết học đóng vai trò là:', 'SINGLE_CHOICE', '{"A": "a) Toàn bộ thế giới quan", "B": "b) Toàn bộ thế giới quan, nhân sinh quan và phương pháp luận", "C": "c) Hạt nhân lý luận của thế giới quan", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1341, 'Câu 4: Câu 4: Câu 4: Vấn đề cơ bản của triết học là:', 'SINGLE_CHOICE', '{"A": "Quan hệ giữa tư duy với tồn tại và khả năng nhận thức của con người", "B": "Quan hệ giữa vật chất với ý thức, tinh thần với tự nhiên và con người có khả năng nhận thức được thế giới không?", "C": "Quan hệ giữa vật chất với ý thức; tinh thần với tự nhiên; tư duy với tồn tại và con người có khả năng nhận thức được thế giới không?", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1342, 'Câu 5: Câu 5: Câu 5: Vật chất có trước, ý thức có sau, vật chất quyết định ý thức, đây là quan điểm:', 'SINGLE_CHOICE', '{"A": "Duy vật", "B": "Duy tâm", "C": "Nhị nguyên", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1343, 'Câu 6: Câu 6: Câu 6: Ý thức có trước, vật chất có sau, ý thức quyết định vật chất, đây là quan điểm :', 'SINGLE_CHOICE', '{"A": "a) Duy vật", "B": "b) Duy tâm", "C": "c) Nhị nguyên", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1344, 'Câu 7: Câu 7: Câu 7: Vật chất và ý thức tồn tại độc lập, chúng không nằm trong quan hệ sản sinh, cũng không nằm trong quan hệ quyết định nhau, đây là quan điểm:', 'SINGLE_CHOICE', '{"A": "Duy vật", "B": "Duy tâm", "C": "Nhị nguyên", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1345, 'Câu 8: Câu 8: Câu 8: Chủ nghĩa duy vật chất phác trong khi thừa nhận tính thứ nhất của vật chất đã:', 'SINGLE_CHOICE', '{"A": "a) Đồng nhất vật chất với nguyên tử và khối lượng", "B": "b) Đồng nhất vật chất với một hoặc một số sự vật cụ thể, cảm tính", "C": "c) Đồng nhất vật chất với vật thể", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1346, 'Câu 9: Câu 9: Câu 9: Khi cho rằng:" tồn tại là được tri giác”, đây là quan điểm:', 'SINGLE_CHOICE', '{"A": "a) Duy tâm chủ quan", "B": "b) Duy tâm khách quan", "C": "c) Nhị nguyên", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1347, 'Câu 10: Câu 10: Câu 10: Khi thừa nhận trong những trường hợp cần thiết thì bên cạnh cái “ hoặc là...hoặc là...” còn có cả cái “ vừa là.. vừa là...” nữa; thừa nhận một chỉnh thể trong lúc vừa là nó vừa không phải là nó; thừa nhận cái khẳng định và cái phủ định vừa loại trừ nhau vừa gắn bó với nhau, đây là:', 'SINGLE_CHOICE', '{"A": "a) Phương pháp siêu hình", "B": "b) Phương pháp biện chứng", "C": "c) Thuyết không thể biết", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1348, 'Câu 11: Câu 11: Câu 11: Hệ thống triết học không chính thống ở Ấn Độ cổ đại bao gồm 3 trường phái:', 'SINGLE_CHOICE', '{"A": "a) Sàmkhya, Đạo Jaina, Đạo Phật", "B": "b) Lokàyata, Đạo Jaina, Đạo Phật", "C": "c) Vêdànta, Đạo Jaina, Đạo Phật", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1349, 'Câu 12: Câu 12: Câu 12: Hệ thống triết học chính thống ở Ấn Độ cổ đại bao gồm 6 trường phái :', 'SINGLE_CHOICE', '{"A": "a) Sàmkhya, Vêdànta, Mimànsà, Yoga, Lokàyata và Vai''sêsika", "B": "b) Sàmkhya, Vêdànta, Đạo Jaina, Mimànsà, Yoga và Vai''sêsika", "C": "c) Sàmkhya, Vêdànta, Mimànsà, Yoga, Nyaya và Vai''sêsika", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1350, 'Câu 13: Câu 13: Câu 13: Trường phái triết học cho rằng tồn tại tuyệt đối (Brahman) đồng nhất với “tôi” (Atman) là ý thức cá nhân thuần tuý, là trường phái:', 'SINGLE_CHOICE', '{"A": "a) Sàmkhya", "B": "b) Vêdànta", "C": "c) Nyaya", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
