(1359, 'Câu 22: Câu 22: Câu 22: Ông cho rằng sự giàu nghèo, sống chết, hoạ phúc, thành bại không phải do số mệnh quy định mà là do hành vi con người gây nên. Ông là ai?', 'SINGLE_CHOICE', '{"A": "a) Khổng Tử", "B": "b) Hàn Phi Tử", "C": "c) Mặc Tử", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1360, 'Câu 23: Câu 23: Câu 23: Ông cho rằng nguyên nhân và động lực căn bản của mọi sự biến đổi của lịch sử là do dân số và của cải ít hay nhiều. Ông là ai?', 'SINGLE_CHOICE', '{"A": "a) Khổng Tử", "B": "b) Hàn Phi Tử", "C": "c) Mặc Tử", "D": ""}', 'A', '', 43);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1361, 'Câu 24: Câu 24: Câu 24: Ông cho rằng trong tự nhiên không có ý chí tối cao, ý muốn chủ quan của con người không thể nào thay đổi được quy luật khách quan, vận mệnh của con người là do tự con người tự quyết định lấy. Ông là ai?', 'SINGLE_CHOICE', '{"A": "a) Trang Tử", "B": "b) Hàn Phi Tử", "C": "c) Mặc Tử", "D": ""}', 'A', '', 43);
