(1364, 'Câu 27: Câu 27: Câu 27: Luận điểm bất hủ:” Chúng ta không thể tắm hai lần trên cùng một dòng sông “ là của ai?', 'SINGLE_CHOICE', '{"A": "a) Aritxtốt", "B": "b) Đêmôcrít", "C": "c) Hêracolít", "D": ""}', 'A', '', 43);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(44, 'Thi thử trắc nghiệm ôn tập triết học Mác Lênin online - Chương 2 - Đề #48', 'Triết Học', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Triết Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1365, 'Theo chủ nghĩa duy vật biện chứng, bản chất của ý thức là gì?', 'SINGLE_CHOICE', '{"A": "Một dạng vật chất đặc biệt.", "B": "Sự phản ánh thụ động thế giới vật chất.", "C": "Hình ảnh chủ quan của thế giới khách quan.", "D": "Một thực thể độc lập, tiên thiên."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1366, 'Đặc tính nào sau đây KHÔNG phải là đặc tính của ý thức?', 'SINGLE_CHOICE', '{"A": "Tính tích cực, sáng tạo.", "B": "Tính chủ quan.", "C": "Tính thụ động, ngẫu nhiên.", "D": "Tính gắn bó với thực tiễn xã hội."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1367, 'Yếu tố nào sau đây đóng vai trò quan trọng nhất trong việc hình thành và phát triển ý thức?', 'SINGLE_CHOICE', '{"A": "Sự tác động của các yếu tố tâm linh.", "B": "Hoạt động thực tiễn xã hội.", "C": "Cấu trúc hoàn thiện của bộ óc.", "D": "Cả B và C đều đúng."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1368, 'Theo triết học Mác - Lênin, tri thức là gì?', 'SINGLE_CHOICE', '{"A": "Sự hiểu biết về thế giới khách quan.", "B": "Nội dung và phương thức tồn tại cơ bản của ý thức.", "C": "Sự phản ánh thế giới vào bộ óc con người.", "D": "Tất cả đáp án trên."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1369, 'Ý chí được hiểu là gì trong cấu trúc của ý thức?', 'SINGLE_CHOICE', '{"A": "Khả năng nhận thức thế giới khách quan.", "B": "Những cố gắng, nỗ lực vượt qua khó khăn để đạt mục đích.", "C": "Tình cảm và thái độ của con người đối với thế giới.", "D": "Niềm tin vào giá trị của cuộc sống."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1370, 'Tự ý thức là gì?', 'SINGLE_CHOICE', '{"A": "Ý thức của cá nhân về thế giới bên ngoài.", "B": "Ý thức hướng về nhận thức bản thân trong mối quan hệ với thế giới.", "C": "Khả năng tự đánh giá năng lực của người khác.", "D": "Sự hiểu biết về các quy luật tự nhiên."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1371, 'Điểm khác biệt giữa tiềm thức và ý thức là gì?', 'SINGLE_CHOICE', '{"A": "Tiềm thức là những hoạt động tâm lý nằm ngoài sự kiểm soát của ý thức.", "B": "Tiềm thức là ý thức đã được kiểm soát hoàn toàn.", "C": "Tiềm thức không có vai trò trong đời sống.", "D": "Tiềm thức chỉ xuất hiện ở người lớn."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1372, 'Vô thức có vai trò như thế nào trong đời sống con người?', 'SINGLE_CHOICE', '{"A": "Quyết định mọi hành vi của con người.", "B": "Giúp con người giảm bớt sự căng thẳng không cần thiết.", "C": "Không có vai trò gì cả.", "D": "Thay thế hoàn toàn ý thức."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1373, 'Nhận định nào sau đây đúng về mối quan hệ giữa ý thức và máy tính?', 'SINGLE_CHOICE', '{"A": "Máy tính có ý thức giống như con người.", "B": "Máy tính là sản phẩm của ý thức con người.", "C": "Ý thức và máy tính là hai quá trình giống nhau về bản chất.", "D": "Máy tính có khả năng sáng tạo lại hiện thực."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1374, 'Theo triết học Mác - Lênin, mối quan hệ giữa vật chất và ý thức là gì?', 'SINGLE_CHOICE', '{"A": "Vật chất quyết định ý thức.", "B": "Ý thức quyết định vật chất.", "C": "Vật chất và ý thức độc lập với nhau.", "D": "Vật chất và ý thức tác động qua lại biện chứng, trong đó vật chất quyết định ý thức."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1375, 'Điều gì chứng minh vật chất quyết định nguồn gốc của ý thức?', 'SINGLE_CHOICE', '{"A": "Ý thức xuất hiện trước vật chất.", "B": "Ý thức tồn tại độc lập với bộ óc con người.", "C": "Ý thức xuất hiện gắn liền với sự xuất hiện của con người.", "D": "Ý thức là sản phẩm của thế giới tâm linh."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1376, 'Yếu tố nào quyết định nội dung của ý thức?', 'SINGLE_CHOICE', '{"A": "Cảm xúc của con người.", "B": "Thế giới khách quan, đặc biệt là hoạt động thực tiễn.", "C": "Những ý tưởng chủ quan.", "D": "Sự tác động của các lực lượng siêu nhiên."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1377, 'Bản chất của ý thức được quyết định bởi yếu tố nào?', 'SINGLE_CHOICE', '{"A": "Phản ánh và sáng tạo.", "B": "Chỉ phản ánh.", "C": "Chỉ sáng tạo.", "D": "Cảm tính."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1378, 'Điều gì quyết định sự vận động, phát triển của ý thức?', 'SINGLE_CHOICE', '{"A": "Sự thay đổi của thế giới tâm linh.", "B": "Sự biến đổi của vật chất, của thực tiễn.", "C": "Những ý tưởng chủ quan của con người.", "D": "Các yếu tố ngẫu nhiên."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1379, 'Trong xã hội, vai trò của vật chất đối với ý thức được biểu hiện như thế nào?', 'SINGLE_CHOICE', '{"A": "Kinh tế quyết định chính trị.", "B": "Chính trị quyết định kinh tế.", "C": "Ý thức xã hội quyết định tồn tại xã hội.", "D": "Văn hóa quyết định kinh tế."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1380, 'Tính độc lập tương đối của ý thức thể hiện ở điểm nào?', 'SINGLE_CHOICE', '{"A": "Ý thức hoàn toàn không phụ thuộc vào vật chất.", "B": "Ý thức có ''đời sống'' riêng, có quy luật vận động riêng.", "C": "Ý thức luôn thay đổi nhanh hơn vật chất.", "D": "Ý thức không có khả năng tác động trở lại vật chất."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1381, 'Ý thức tác động đến vật chất thông qua yếu tố nào?', 'SINGLE_CHOICE', '{"A": "Suy nghĩ.", "B": "Hoạt động thực tiễn.", "C": "Tưởng tượng.", "D": "Cảm xúc."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1382, 'Điều gì xảy ra khi ý thức phản ánh sai lệch hiện thực?', 'SINGLE_CHOICE', '{"A": "Hoạt động của con người luôn thành công.", "B": "Ý thức không có tác động gì đến hiện thực.", "C": "Hoạt động của con người có thể thất bại.", "D": "Sức mạnh vật chất được nhân lên gấp bội."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1383, 'Nguyên tắc phương pháp luận rút ra từ mối quan hệ giữa vật chất và ý thức là gì?', 'SINGLE_CHOICE', '{"A": "Chỉ tôn trọng tính khách quan.", "B": "Chỉ phát huy tính năng động chủ quan.", "C": "Tôn trọng tính khách quan kết hợp với phát huy tính năng động chủ quan.", "D": "Phủ nhận cả tính khách quan và tính chủ quan."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1384, 'Theo chủ nghĩa duy vật biện chứng, nguồn gốc của ý thức là:', 'SINGLE_CHOICE', '{"A": "Do Thượng Đế tạo ra.", "B": "Do bộ óc người phản ánh thế giới khách quan.", "C": "Do cảm giác của con người.", "D": "Do sự vận động của các hạt vật chất."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1385, 'Chủ nghĩa duy tâm sai lầm ở điểm nào khi bàn về ý thức?', 'SINGLE_CHOICE', '{"A": "Coi ý thức là thứ yếu, vật chất là quyết định.", "B": "Tuyệt đối hóa vai trò của vật chất.", "C": "Phủ nhận vai trò của ý thức.", "D": "Coi ý thức là lực lượng tiên thiên, quyết định vật chất."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1386, 'Chủ nghĩa duy vật siêu hình có hạn chế gì khi xem xét mối quan hệ vật chất và ý thức?', 'SINGLE_CHOICE', '{"A": "Phủ nhận vai trò của vật chất.", "B": "Phủ nhận vai trò của ý thức.", "C": "Tuyệt đối hóa vai trò của ý thức.", "D": "Tuyệt đối hóa vai trò của vật chất, xem nhẹ tính năng động của ý thức."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1387, 'Vì sao nói ý thức có tính sáng tạo?', 'SINGLE_CHOICE', '{"A": "Vì ý thức có thể tạo ra vật chất.", "B": "Vì ý thức có thể phản ánh lại thế giới vật chất một cách chính xác như gương.", "C": "Vì ý thức có thể tạo ra cái mới trên cơ sở cái đã có, định hướng cho hoạt động thực tiễn.", "D": "Vì ý thức là một bản năng của con người."}', 'A', '', 44);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1388, 'Trong hoạt động nhận thức và thực tiễn, chúng ta cần tránh điều gì?', 'SINGLE_CHOICE', '{"A": "Tránh tuyệt đối hóa vai trò của vật chất.", "B": "Tránh tuyệt đối hóa vai trò của ý thức.", "C": "Tránh rơi vào chủ nghĩa chủ quan, duy ý chí.", "D": "Cả A, B và C."}', 'A', '', 44);
