(45, 'Thi thử trắc nghiệm ôn tập triết học Mác Lênin online - Chương 3 - Đề #59', 'Triết Học', 30, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Triết Học. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1389, 'Theo quan điểm của các nhà kinh điển Mác - Lênin, yếu tố nào sẽ mất dần theo sự phát triển và tiến bộ của xã hội?', 'SINGLE_CHOICE', '{"A": "Tính nhân loại và cá nhân", "B": "Tính giai cấp và tính dân tộc", "C": "Tính cá nhân và tính giai cấp", "D": "Tính dân tộc và tính nhân loại"}', 'A', '', 45);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1390, 'Trong hoạt động nhận thức và thực tiễn, cần tránh khuynh hướng nào sau đây trong việc xem xét mối quan hệ giữa xã hội và cá nhân?', 'SINGLE_CHOICE', '{"A": "Đề cao quá mức (mặt/cái) xã hội", "B": "Đề cao quá mức (mặt/cái) cá nhân", "C": "Coi nhẹ sự khác biệt giữa cá nhân và xã hội", "D": "Cả A và B"}', 'A', '', 45);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1391, 'Theo triết học Mác, bản chất của con người được hiểu như thế nào trong tính hiện thực?', 'SINGLE_CHOICE', '{"A": "Là tổng hòa các mối quan hệ cá nhân", "B": "Là tổng hòa các quan hệ xã hội", "C": "Là sự kết hợp giữa yếu tố sinh học và xã hội", "D": "Là yếu tố chủ quan, độc lập với xã hội"}', 'A', '', 45);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1392, 'Nguyên tắc nào cần được tuân thủ khi xem xét con người trong đời sống xã hội?', 'SINGLE_CHOICE', '{"A": "Nguyên tắc duy tâm", "B": "Nguyên tắc trừu tượng", "C": "Nguyên tắc lịch sử - cụ thể và nguyên tắc toàn diện", "D": "Nguyên tắc chủ quan"}', 'A', '', 45);
