(1393, 'Theo triết học Mác, quần chúng nhân dân được định nghĩa như thế nào?', 'SINGLE_CHOICE', '{"A": "Là những người có địa vị cao trong xã hội", "B": "Là tập hợp đông đảo những người hoạt động trong một không gian và thời gian xác định", "C": "Là những người lãnh đạo các phong trào xã hội", "D": "Là những người có ảnh hưởng lớn đến tư tưởng của xã hội"}', 'A', '', 45);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1394, 'Trong quan điểm của triết học Mác - Lênin, mối quan hệ giữa vai trò của quần chúng nhân dân và cá nhân lãnh tụ được thể hiện như thế nào?', 'SINGLE_CHOICE', '{"A": "Quần chúng nhân dân là yếu tố quyết định, còn lãnh tụ chỉ là hình thức", "B": "Lãnh tụ là người duy nhất định hướng sự phát triển của xã hội", "C": "Quần chúng nhân dân là nhân tố quyết định sự biến đổi xã hội dưới sự lãnh đạo của các tổ chức hoặc cá nhân", "D": "Lãnh tụ và quần chúng nhân dân hoàn toàn độc lập, không ảnh hưởng lẫn nhau"}', 'A', '', 45);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1395, 'Theo triết học Mác - Lênin, yếu tố nào là lực lượng căn bản, chủ chốt của quần chúng nhân dân?', 'SINGLE_CHOICE', '{"A": "Những người lao động sản xuất ra của cải vật chất và tinh thần", "B": "Những người thuộc tầng lớp trí thức", "C": "Những người có địa vị cao trong xã hội", "D": "Những người hoạt động trong lĩnh vực chính trị"}', 'A', '', 45);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1396, 'Khái niệm ''cá nhân'' nhấn mạnh điều gì trong triết học Mác?', 'SINGLE_CHOICE', '{"A": "Tính phổ biến của bản chất con người", "B": "Tính đơn nhất về mặt sinh học", "C": "Tính đặc thù riêng biệt của mỗi cá thể về phương diện xã hội", "D": "Sự độc lập với các quan hệ xã hội"}', 'A', '', 45);
