INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1426, 'Bản chất của chủ nghĩa t­ư bản "là một con đĩa có 1 cái vòi bám vào giai cấp vô sản ở chính quốc và 1 cái vòi khác bám vào giai cấp vô sản ở thuộc địa. Nếu muốn giết con vật ấy, ngư­ời ta phải đồng thời cắt cả hai vòi. Nếu người ta chỉ cắt một vòi thôi thì cái vòi còn lại kia vẫn tiếp tục hút máu của giai cấp vô sản, con vật vẫn tiếp tục sống và cái vòi bị cắt đứt lại sẽ mọc ra" câu nói đó từ trong tác phẩm nào của Nguyễn Ái Quốc?', 'SINGLE_CHOICE', '{"A": "Con rồng tre", "B": "Bản án chế độ thực dân Pháp", "C": "Đư­ờng cách mệnh", "D": "Lênin và các dân tộc phương Đông"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1427, 'Nguyễn Ái Quốc tham gia tổ chức "Hội liên hiệp các dân tộc bị áp bức" vào năm nào?', 'SINGLE_CHOICE', '{"A": "1921", "B": "1922", "C": "1925", "D": "1927"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1428, 'Nguyễn Ái Quốc tổ chức "Hội liên hiệp các dân tộc bị áp bức" khi đang ở đâu?', 'SINGLE_CHOICE', '{"A": "Cao Bằng, Việt Nam", "B": "Paris, Pháp", "C": "Quảng Châu, Trung Quốc", "D": "U Đon, Thái Lan"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1429, 'Tại Quảng Châu, Trung Quốc, Nguyễn Ái Quốc đã mở nhiều lớp huấn luyện đào tạo cán bộ cho cách mạng Việt Nam, đó là vào những năm nào?', 'SINGLE_CHOICE', '{"A": "1923-1924", "B": "1924-1926", "C": "1925-1927", "D": "1927-1929"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1430, 'Các bài giảng của Nguyễn Ái Quốc tại các lớp huấn luyện cán bộ được Bộ tuyên truyền của Hội liên hiệp các dân tộc bị áp bức tập hợp lại và xuất bản thành tác phẩm gì?', 'SINGLE_CHOICE', '{"A": "Bản án chế độ thực dân Pháp", "B": "Lênin và Phương Đông", "C": "Con Rồng tre", "D": "Đường kách mệnh"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1431, 'Nguyễn Ái Quốc đã trích dẫn luận điểm nổi tiếng của Lênin: "không có lý luận cách mệnh thì không có cách mệnh vận động ... chỉ có theo lý luận cách mệnh tiền phong, Đảng cách mệnh mới làm nối trách nhiệm cách mệnh tiền phong" câu nói đ­ược ghi ở trang đầu tiên của cuốn sách nào?', 'SINGLE_CHOICE', '{"A": "Bản án chế độ thực dân Pháp", "B": "Đường cách mạng", "C": "Nhật ký trong tù Việt Nam", "D": "Lênin và các dân tộc thuộc địa"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1432, '"Công nông là gốc cách mệnh, còn học trò, nhà buôn nhỏ, địa chủ nhỏ, ... là bầu bạn cách mệnh của công nông". Nguyễn Aí Quốc viết câu đó trong tác phẩm nào?', 'SINGLE_CHOICE', '{"A": "Bản án chế độ thực dân Pháp", "B": "Nông dân Trung Quốc", "C": "Lênin và Phương Đông", "D": "Đường cách mệnh"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1433, '"Chúng ta làm cách mệnh thì cũng phải liên lạc tất cả những đảng cách mệnh trong thế giới để chống lại tư­ bản và đế quốc chủ nghĩa". Câu nói đó đ­ược Nguyễn Ái Quốc viết trong tác phẩm nào?', 'SINGLE_CHOICE', '{"A": "Bản án chế độ thực dân Pháp", "B": "Đường cách mệnh", "C": "Lênin và các dân tộc thuộc địa", "D": "Trung Quốc và Thanh niên Trung Quốc"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1434, '"Tr­ước hết phải có Đảng cách mệnh để trong thì vận động và tổ chức dân chúng, ngoài thì liên lạc với dân tộc bị áp bức và vô sản giai cấp mọi nơi." Câu nói đó đ­ựơc Nguyễn Ái Quốc viết trong tác phẩm nào?', 'SINGLE_CHOICE', '{"A": "Đường cách mệnh", "B": "Sửa đổi lối làm việc", "C": "Đây “công lý” của thực dân Pháp ở Đông Dương", "D": ""}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1435, '"Hai trăm thanh niên trong 1 tỉnh ở Nam kỳ biểu tình trước đồn cảnh sát đòi thả 2 người bạn của họ bị bắt... họ đã thắng lợi. Lần đầu tiên việc đó đ­ược thấy ở Đông D­ương. Đó là dấu hiệu của thời đại." Câu đó đư­ợc Nguyễn Aí Quốc viết trong báo cáo hay tác phẩm nào?', 'SINGLE_CHOICE', '{"A": "Bản án chế độ thực dân Pháp", "B": "Đư­ờng cách mệnh", "C": "Báo cáo về tình hình Đông Dương tháng 11 và tháng 12 năm 1924.", "D": "Thư gửi Đoàn Chủ tịch Quốc tế Nông dân"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1436, 'Nguyễn Ái Quốc mở lớp huấn luyện chính trị tại số nhà bao nhiêu phố Văn Minh (Quảng Châu)?', 'SINGLE_CHOICE', '{"A": "Số 13/1", "B": "Số 15/1", "C": "Số 20/1", "D": "Số 22/1"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1437, 'Tuần báo Thanh Niên, cơ quan trung ­ương của tổng bộ Việt Nam cách mạng thanh niên do Nguyễn Ái Quốc sáng lập ra số đầu tiên vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "Ngày 21-6-1924", "B": "Ngày 21-6-1926", "C": "Ngày 21-6-1925", "D": "Ngày 21-6-1927"}', 'A', '', 46);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1438, 'Nguyễn Ái Quốc mang tên Lý Thụy vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "7-1922", "B": "7-1924", "C": "7-1925", "D": "7-1943"}', 'A', '', 46);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(47, 'Thi thử trắc nghiệm ôn tập môn Tư tưởng Hồ Chí Minh online - Đề #11', 'Tư tưởng Hồ Chí Minh', 25, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Tư tưởng Hồ Chí Minh. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1439, 'Các hoạ sĩ Tô Ngọc Vân, Nguyễn Đỗ Cung, Nguyễn Thị Kim vẽ chân dung và nặn tượng Hồ Chí Minh khi người làm việc ở đâu?', 'SINGLE_CHOICE', '{"A": "Bắc Bó", "B": "Tân Trào", "C": "Vạn Phúc", "D": "Bắc Bộ phủ"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1440, 'Những câu nói sau đây, câu nào là của Hồ Chí Minh:', 'SINGLE_CHOICE', '{"A": "\"Muốn được dân yêu, muốn đợc lòng dân, trước hết phải yêu dân, phải đặt quyền lợi của dân trên hết thảy, phải có một tinh thần chí công vô tư\"", "B": "\"Chúng ta đã xây dựng nên nước Việt nam Dân chủ Cộng hòA. Nhưng nếu nước độc lập mà dân không hưởng hạnh phúc tự do, thì độc lập cũng chẳng có nghĩa lý gì\"", "C": "\"Chính phủ nhân dân bao giờ cũng phải đặt quyền lợi dân lên trên hết thảy. Việc gì có lợi cho dân thì làm. Việc gì có hại cho dân thì phải tránh\"", "D": "Tất cả các câu nói trên"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1441, 'Chọn phương án trả lời đúng với tư tưởng Hồ Chí Minh', 'SINGLE_CHOICE', '{"A": "Bài nói chuyện với cán bộ tỉnh Thanh Hóa", "B": "Tác phẩm \"Đời sống mới\"", "C": "Thư gửi các đồng chí Bắc bộ", "D": "Sửa đối lối làm việc"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1442, '"Phê bình mình cũng như phê bình người phải ráo riết, triệt để, thật thà, không nể nang, không thêm bớt. Phải vạch rõ ưu điểm và khuyết điểm. Đồng thời, chớ dùng những lời mỉa mai, chua cay, đâm thọC. Phê bình việc làm, chứ không phải phê bình người”. Câu nói trên của Hồ Chí Minh chỉ cho chúng ta biết điều gì:', 'SINGLE_CHOICE', '{"A": "Cách thức tự phê bình và phê bình", "B": "Mục đích tự phê bình và phê bình", "C": "Điều kiện để đoàn kết và thống nhất", "D": "Tất cả các đều trên"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1443, 'Chọn phương án trả lời đúng với tư tưởng Hồ Chí Minh', 'SINGLE_CHOICE', '{"A": "Đời sống lạ", "B": "Đời sống mới", "C": "Thư gửi các đồng chí Bắc bộ", "D": "Thư gửi các đồng chí tỉnh nhà"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1444, '"Đạo đức, ngày trước thì chỉ trung với vua, hiếu với cha mẹ. Ngày nay, thời đại mới đạo đức cũng phải mới. Phải trung với nước, phải hiếu với dân, với đồng bào”. Câu đó Hồ Chí Minh viết trong tác phẩm nào?', 'SINGLE_CHOICE', '{"A": "Lời căn dặn cán bộ tuyên truyền", "B": "Bài nói tại trường cán bộ tự vệ Hồ Chí Minh", "C": "Bài phát biểu tại cuộc họp đầu tiên của uỷ ban nghiên cứu kế hoạch kiến quốc", "D": "Lời khuyên anh em viên chức"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1445, '"Nền tảng của vấn đề dân tộc là vấn đề nông dân, vì nông dân là tối đại đa số trong dân tộC. Muốn kháng chiến hoàn toàn thắng lợi, thì phải thiết thực nâng cao quyền lợi kinh tế và chính trị của nông dân, phải chia ruộng đất cho nông dân". Hồ Chí Minh nói điều đó nhằm thực hiện chủ trương nào?', 'SINGLE_CHOICE', '{"A": "Đẩy mạnh kháng chiến chống thực dân Pháp", "B": "Tiến hành cải cách ruộng đất", "C": "Thủ tiêu chế độ sở hữu ruộng đất phong kiến", "D": "Tất cả các chủ trương trên"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1446, '“Đoàn viên và thanh niên ta nói chung là rất tốt, mọi việc đều hăng hái xung phong, không ngại khó khăn, có chí tiến thủ. Đảng cần phải chăm lo giáo dục đạo đức cách mạng cho họ, đào tạo họ thành những người thừa kế xây dựng chủ nghĩa xã hội vừa “hồng” vừa “chuyên”. Câu nói đó của Hồ Chí Minh trong văn kiện nào:', 'SINGLE_CHOICE', '{"A": "Đường cách mạng (1927)", "B": "Tuyên ngôn độc lập (1945)", "C": "Di chúc (1969)", "D": "Lời khai mạc Đại hội Đảng lần thứ III (1960)"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1447, '“Đoàn viên và thanh niên ta nói chung là rất tốt, mọi việc đều hăng hái xung phong, không ngại khó khăn, có chí tiến thủ. Đảng cần phải chăm lo giáo dục đạo đức cách mạng cho họ, đào tạo họ thành những người thừa kế xây dựng chủ nghĩa xã hội vừa “hồng” vừa “chuyên”. Câu nói đó của Hồ Chí Minh trong văn kiện nào:', 'SINGLE_CHOICE', '{"A": "Đường cách mạng (1927)", "B": "Tuyên ngôn độc lập (1945)", "C": "Di chúc (1969)", "D": "Lời khai mạc Đại hội Đảng lần thứ III (1960)"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1448, '“Bồi dưỡng thế hệ cách mạng cho đời sau là một việc rất quan trọng và rất cần thiết”. Câu nói đó của Hồ Chí Minh trong văn kiện nào?', 'SINGLE_CHOICE', '{"A": "Bản án chủ nghĩa thực dân Pháp (1925)", "B": "Báo cáo chính trị tại Đại hội Đảng lần thứ hai (1951)", "C": "Bài nói tại Đại hội sinh viên Việt Nam lần thứ 2 (1958)", "D": "Di chúc (1969)"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1449, '“Tự do cho đồng bào tôi, độc lập cho Tổ quốc tôi, đấy là tất cả những điều tôi muốn; đấy là tất cả những điều tôi hiểu”. Câu nói đó của Hồ Chí Minh được ghi lại trong tác phẩm nào?', 'SINGLE_CHOICE', '{"A": "Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch", "B": "Tuyên ngôn độc lập", "C": "Đời sống mới", "D": "Phát biểu với kiều bào ở Pháp"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1450, '“Cô ở ngoài này học tập một thời gian rồi về tiếp tục kháng chiến với bà con. Người cách mạng phải học suốt đời, học lý luận, học quần chúng, học thực tế. Người không học thì như đi ban đêm không có đèn, không có gậy, dễ vấp té, có phải thế không?”. Đây là lời Bác Hồ căn dặn ai?', 'SINGLE_CHOICE', '{"A": "Nguyễn Thị Chiên", "B": "Tạ Thị Kiều", "C": "Nguyễn Thị Định", "D": "Nguyễn Thị Thập"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1451, 'Chọn phương án trả lời đúng nhất', 'SINGLE_CHOICE', '{"A": "Chủ nghĩa Mác - Lênin là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng ta", "B": "Tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng ta", "C": "Cùng với chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh là nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng ta", "D": "Tất cả đều đúng"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1452, 'Theo Hồ Chí Minh, ưu điểm lớn nhất của học thuyết Khổng Tử là gì?', 'SINGLE_CHOICE', '{"A": "Tinh thần hiếu học", "B": "Tinh thần làm việc", "C": "Sự tu dưỡng đạo đức cá nhân", "D": "Quản lý xã hội bằng đạo đức"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1453, 'Theo Hồ Chí Minh, ưu điểm lớn nhất của Tôn giáo Giêsu là gì?', 'SINGLE_CHOICE', '{"A": "Đức hy sinh", "B": "Lòng nhân ái cao cả", "C": "Lòng cao thượng", "D": "Sự bao dung"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1454, 'Theo Hồ Chí Minh, ưu điểm lớn nhất của chủ nghĩa Tam dân của Tôn Trung Sơn là gì?', 'SINGLE_CHOICE', '{"A": "Chống phong kiến", "B": "Đấu tranh vì tự do, dân chủ", "C": "Phù hợp với điều kiện thực tế nước ta", "D": "Yêu nước"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1455, 'Theo Hồ Chí Minh, ưu điểm lớn nhất của chủ nghĩa Mác là gì?', 'SINGLE_CHOICE', '{"A": "Bản chất cách mạng", "B": "Chủ nghĩa nhân đạo triệt để", "C": "Bản chất khoa học", "D": "Phương pháp làm việc biện chứng"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1456, 'Theo Hồ Chí Minh, học chủ nghĩa Mác - Lênin nghĩa là gì?', 'SINGLE_CHOICE', '{"A": "Học thuộc các luận điểm lý luận", "B": "Để sống với nhau có tình, có nghĩa", "C": "Để chứng tỏ trình độ lý luận", "D": "Để làm việc"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1457, 'Tư tưởng Hồ Chí Minh hình thành và phát triển qua mấy giai đoạn?&nbsp;', 'SINGLE_CHOICE', '{"A": "3", "B": "4", "C": "5", "D": "6"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1458, 'Chọn cụm từ đúng điền vào dấu...Tháng 7 năm 1920, Hồ Chí Minh đọc ... của V.I. Lênin.', 'SINGLE_CHOICE', '{"A": "Tác phẩm \"Làm gì\"", "B": "Sơ thảo lần thứ nhất Luận cương về các vấn đề dân tộc.", "C": "Sơ thảo lần thứ nhất Luận cương về các vấn đề dân tộc và vấn đề thuộc địa", "D": ""}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1459, 'Hồ Chí Minh được UNESCO ra Nghị quyết công nhận là anh hùng giải phóng dân tộc Việt Nam và danh nhân văn hóa kiệt xuất vào năm nào?', 'SINGLE_CHOICE', '{"A": "1969", "B": "1987", "C": "1975", "D": "1990"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1460, 'Hồ Chí Minh nói câu "Không có gì quý hơn độc lập, tự do" vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "1945", "B": "1987", "C": "1975", "D": "1966"}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1461, 'Theo Hồ Chí Minh, cách mạng giải phóng dân tộc muốn giành được thắng lợi phải đi theo con đường nào?', 'SINGLE_CHOICE', '{"A": "Cách mạng tư sản", "B": "Cách mạng vô sản", "C": "Cách mạng xã hội chủ nghĩa", "D": ""}', 'A', '', 47);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1462, 'Chọn phương án trả lời đúng với tư tưởng Hồ Chí Minh', 'SINGLE_CHOICE', '{"A": "Cách mạng giải phóng dân tộc giành thắng lợi đồng thời với thắng lợi cách mạng vô sản ở chính quốc", "B": "Thắng lợi của cách mạng vô sản ở thuộc địa phải phụ thuộc vào thắng lợi của cách mạng vô sản ở chính quốc", "C": "Cách mạng giải phóng dân tộc ở thuộc địa có khả năng giành được thắng lợi trước cách mạng vô sản ở chính quốc", "D": ""}', 'A', '', 47);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(48, 'Thi thử trắc nghiệm ôn tập môn Tư tưởng Hồ Chí Minh online - Đề #42', 'Tư tưởng Hồ Chí Minh', 25, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Tư tưởng Hồ Chí Minh. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1463, 'Tìm đáp án thể hiện tư tưởng giáo dục nhân văn Hồ Chí Minh?', 'SINGLE_CHOICE', '{"A": "Tôi hiến cả đời tôi cho dân tộc tôi", "B": "Mỗi người, mỗi gia đình đều có một nỗi đau khổ riêng và gộp cả những đau khổ riêng của mỗi người, mỗi gia đình lại thì thành nỗi đau khổ của tôi", "C": "Riêng phần tôi thì làm một cái nhà nho nhỏ, nơi có non xanh nước biếc để câu cá, trồng hoa sớm chiều làm bạn với các cụ già hái củi, em trẻ chăn trâu, không dính líu gì với vòng danh lợi", "D": "Đối với những người có thói hư tật xấu, trừ hạng người phản lại Tổ quốc và nhân dân ta phải giúp họ tiến bộ bằng cách làm cho cái phần thiện trong con người nảy nở để đẩy lùi cái ác, chứ không phải đập cho tơi bời"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1464, 'Tìm nội dung chứng tỏ Hồ Chí Minh đã đánh giá đúng vai trò của chủ nghĩa dân tộc đối với cách mạng Việt Nam?', 'SINGLE_CHOICE', '{"A": "Cuộc đấu tranh giai cấp không diễn ra giống như ở phương Tây", "B": "Chủ nghĩa dân tộc là động lực lớn của đất nước", "C": "Dù sao thì cũng không thể cấm bổ sung “cơ sở lịch sử” của chủ nghĩa Mác bằng cách đưa thêm vào đó những tư liệu mà Mác ở thời kỳ mình không thể có được", "D": "Nếu nông dân gần như chẳng có gì thì địa chủ cũng không có vốn liếng gì lớn"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1465, 'Tìm nội dung xác định vai trò quyết định của đại đoàn kết dân tộc đối với sự tồn vong và phát triển của đất nước Việt Nam?', 'SINGLE_CHOICE', '{"A": "Lúc nào nhân dân ta đoàn kết muôn người như một t.hì nước ta độc lập tự do. Trái lại lúc nào dân ta không đoàn kết thì bị nước ngoài xâm lấn", "B": "Bất kỳ ai mà thật thà tán thành hòa bình, thống nhất, độc lập, dân chủ thì dù người đó trước đây chống chúng ta, bây giờ chúng ta cũng thật thà đoàn kết với họ", "C": "Ta đoàn kết để đấu tranh cho thống nhất và độc lập của Tổ quốc, ta còn phải đòan kết xây dựng nước nhà", "D": "Ai có tài, có đức, có sức,có lòng phụng sự Tổ quốc và phục vụ nhân dân thì ta đoàn kết với họ"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1466, 'Tìm nội dung trong tư tưởng Hồ Chí Minh xác định mức độ rộng rãi của khối đại đoàn kết dân tộc?', 'SINGLE_CHOICE', '{"A": "Lúc nào nhân dân ta đoàn kết muôn người như một thì nước ta độc lập tự do. Trái lại lúc nào dân ta không đoàn kết thì bị nước ngoài xâm lấn", "B": "Bất kỳ ai mà thật thà tán thành hòa bình thống nhất độc lập dân chủ thì dù người đó trước đây chống đối chúng ta, bây giờ chúng ta cũng thật thà đoàn kết với họ", "C": "Ta đoàn kết để đấu tranh cho thống nhất và độc lập của Tổ quốc, ta còn phải đoàn kết xây dựng nước nhà", "D": "Ai có tài, có đức, có sức, có lòng phụng sự Tổ quốc và phục vụ nhân dân thì ta đoàn kết với họ"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1467, 'Tìm nội dung nhấn mạnh yếu tố tình cảm nhân văn để củng cố sự đoàn kết của Đảng trong ‘‘Di Chúc’’ của Hồ Chí Minh?', 'SINGLE_CHOICE', '{"A": "Các đồng chí từ Trung ương đến các chi bộ cần phải giữ gìn sự đoàn kết nhất trí của Đảng như giữ gìn con ngươi của mắt mình", "B": "Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, là người đầy tớ trung thành của nhân dân", "C": "Đảng ta là một đảng cầm quyền. Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư", "D": "Trong Đảng thực hành dân chủ rộng rãi để củng cố và phát triển sự đoàn kết và thống nhất của Đảng. Phải có tình đồng chí thương yêu lẫn nhau"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1468, 'Tìm nội dung chứng tỏ Hồ Chí Minh đã nhấn mạnh giá trị nhân văn trong việc học tập chủ nghĩa Mác – Lênin?', 'SINGLE_CHOICE', '{"A": "Hiểu chủ nghĩa Mác Lênin tức là cách mạng phân công cho việc gì đều phải làm tròn nhiệm vụ", "B": "Không nên đào tạo ra những con người thuộc sách làu làu, cụ Mác nói thế này, cụ Lênin nói thế kia, nhưng quét nhà lại để cho nhà đầy rác", "C": "Hiểu chủ nghĩa Mác Lênin là phải sống với nhau có tình có nghĩa", "D": "Học tập những chân lý tuyệt đối của chủ nghĩa Mác - Lênin để áp dụng một cách sáng tạo vào hoàn cảnh thực tế của nước ta"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1469, 'Tìm một ý kiến viết sai nội dung tư tưởng Hồ Chí Minh về Cần, Kiệm, Liêm, Chính?', 'SINGLE_CHOICE', '{"A": "Cần là lao động cần cù, siêng năng, lao động có kế hoạch, sáng tạo, có năng suất lao động cao", "B": "Kiệm là không xa xỉ, không hoang phí, không bừa bãi", "C": "Liêm là không tham địa vị, không tham tiền tài, không tham sung sướng, không ham người tâng bốc mình", "D": "Chính là trong sạch, không tham lam đồng xu, hạt thóc của Nhà nước, của dân"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1470, 'Chỉ ra luận điểm chứng tỏ Hồ Chí Minh có tầm nhìn xa về sự cần thiết phải phát triển kinh tế nhiều thành phần?', 'SINGLE_CHOICE', '{"A": "Trong chế độ dân chủ mới, có năm loại kinh tế khác nhau (1953)", "B": "Chúng tôi chủ trương làm cho tư bản Việt Nam phát triển. Mà chỉ có độc lập thì tư bản Việt Nam mới phát triển (1947)", "C": "Nền kinh tế thịnh vượng nghĩa là các sự kinh doanh của các nhà công nghiệp, thương nghiệp thịnh vượng", "D": "Nền kinh tế thịnh vượng nghĩa là các sự kinh doanh của các nhà công nghiệp, thương nghiệp thịnh vượng"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1471, 'Tìm câu thể hiện tư tưởng Hồ Chí Minh về xây dựng kinh tế cũng đồng thời là xây dựng văn hoá?', 'SINGLE_CHOICE', '{"A": "Đảng ta là một đảng cầm quyền", "B": "Sau khi tôi qua đời, chớ nên tổ chức điều phúng linh đình để khỏi lãng phí thì giờ, tiền bạc của nhân dân", "C": "Ngay sau khi cuộc kháng chiến chống Mỹ, cứu nước của nhân dân ta hoàn toàn thắng lợi thì công việc ‘‘Đầu tiên là công việc đối với con người’’", "D": "Công việc xây dựng và khôi phục đất nước sau thắng Mỹ rất to lớn, nặng nề, phức tạp mà cũng rất vẻ vang. Đây là cuộc chiến đấu chống lại những gì đã cũ kỹ, hư hỏng, để tạo ra những cái mới mẻ, tốt tươi"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1472, 'Tìm câu thể hiện đức tính tiết kiệm vì dân của Hồ Chí Minh trong các câu dưới đây?', 'SINGLE_CHOICE', '{"A": "Bồi dưỡng thế hệ cách mạng cho đời sau là một việc rất quan trọng và rất cần thiết. Đảng phải chăm lo giáo dục đạo đức cách mạng cho họ, đào tạo họ thành những người thừa kế xây dựng chủ nghĩa xã hội “vừa hồng vừa chuyên”", "B": "Đảng ta là một đảng cầm quyền", "C": "Sau khi tôi qua đời, chớ nên tổ chức điều phúng linh đình để khỏi lãng phí thì giờ, tiền bạc của nhân dân", "D": "Ngay sau khi cuộc kháng chiến chống Mỹ, cứu nước của nhân dân ta hoàn toàn thắng lợi thì công việc ‘‘Đầu tiên là công việc đối với con người’"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1473, 'Tìm câu thể hiện tư tưởng Hồ Chí Minh về sự thống nhất giữa đức và tài trong sự nghiệp giáo dục con người?', 'SINGLE_CHOICE', '{"A": "Bồi dưỡng thế hệ cách mạng cho đời sau là một việc rất quan trọng và rất cần thiết. Đảng phải chăm lo giáo dục đạo đức cách mạng cho họ, đào tạo họ thành những người thừa kế xây dựng chủ nghĩa xã hội “vừa hồng vừa chuyên”", "B": "Đảng ta là một đảng cầm quyền", "C": "Sau khi tôi qua đời, chớ nên tổ chức điều phúng linh đình để khỏi lãng phí thì giờ, tiền bạc của nhân dân", "D": "Ngay sau khi cuộc kháng chiến chống Mỹ, cứu nước của nhân dân ta hoàn toàn thắng lợi thì công việc đầu tiên là công việc đối với con người"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1474, 'Tìm câu Hồ Chí Minh nhấn mạnh yếu tố nhân văn trong thực hiện việc xây dựng khối đại đoàn kết dân tộc?', 'SINGLE_CHOICE', '{"A": "Đại đoàn kết tức là trước hết phải đoàn kết đại đa số nhân dân, mà đại đa số nhân dân ta là công nhân, nông dân và các tầng lớp nhân dân lao động khác", "B": "Bất kỳ là ai mà thật thà tán thành hoà bình, thống nhất, độc lập, dân chủ thì dù những người đó trước đây chống chúng ta, bây giờ chúng ta cũng thật thà đoàn kết với họ", "C": "Đoàn kết của ta không những rộng rãi mà còn lâu dài", "D": "Đối với những đồng bào lạc lối lầm đường, ta phải lấy tình thân ái mà cảm hoá họ"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1475, 'Tìm câu thể hiện tư tưởng Hồ Chí Minh về mục tiêu cao cả của Chính phủ đối với dân?', 'SINGLE_CHOICE', '{"A": "Nếu nước độc lập mà dân không được hưởng hạnh phúc, tự do thì độc lập cũng chẳng có nghĩa lí gì", "B": "Chính phủ đã hứa với dân, sẽ gắng sức làm cho ai nấy đều có phần hạnh phúc", "C": "Các cơ quan của Chính phủ từ toàn quốc cho đến các làng đều là công bộc của dân", "D": "Việc gì có lợi cho dân, ta phải hết sức làm. Việc gì có hại đến dân, ta phải hết sức tránh"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1476, 'Tìm luận điểm thể hiện tư tưởng cốt lõi trong “Chiến thuật vận động” của Nghị Quyết TW 8 (tháng 5.1941)?', 'SINGLE_CHOICE', '{"A": "Những khẩu hiệu cao chưa thực hiện được trong tình thế hiện tại thì không để vào", "B": "Chiến thuật hiện tại của Đảng là phải vận dụng một phương pháp hiệu triệu hết sức thống thiết", "C": "Đánh thức được tinh thần dân tộc xưa nay trong nhân dân", "D": "Cốt yếu của cuộc vận động hiện thời là làm thế nào đánh đuổi được giặc Pháp- Nhật"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1477, 'Chỉ ra luận điểm thể hiện lý tưởng nhân văn Hồ Chí Minh?&nbsp;', 'SINGLE_CHOICE', '{"A": "Tôi chỉ có một ham muốn, ham muốn tột bậc là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành", "B": "Sau khi tôi qua đời, chớ nên tổ chức điếu phúng linh đình, để khỏi lãng phí thì giờ và tiền bạc của nhân dân", "C": "Lúc chúng ta nâng bát cơm mà ăn, nghĩ đến kẻ đói khổ, chúng ta không khỏi động lòng. Vậy tôi xin đề nghị với đồng bào cả nước, tôi xin thực hành trước: cứ 10 ngày nhịn ăn một bữa, mỗi tháng nhịn 3 bữa. Đem gạo đó (mỗi bữa một bơ) để cứu dân nghèo", "D": "Tôi tuyệt nhiên không ham muốn công danh phú quý chút nào. Bây giờ phải gánh chức Chủ tịch là vì đồng bào ủy thác thì tôi phải gánh sức làm, cũng như một người lính vâng mệnh lệnh của quốc dân ra trước mặt trận. Bao giờ đồng bào cho tôi lui, thì tôi rấ"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1478, 'Tìm đáp án đúng về các tiền đề tư tưởng - lý luận hình thành Tư tưởng Hồ Chí Minh:', 'SINGLE_CHOICE', '{"A": "Truyền thống văn hóa dân tộc", "B": "Chủ nghĩa Mác - Lênin", "C": "Tinh hoa văn hóa nhân loại", "D": "Cả a, b, c"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1479, 'Tìm một nhân tố không thuộc về phẩm chất cá nhân của Nguyễn Ái Quốc?', 'SINGLE_CHOICE', '{"A": "Là người có tư duy độc lập, tự chủ, sáng tạo và đầu óc phê phán, nhạy bén với cái mới", "B": "Là người khổ công học tập, bản lĩnh kiên cường", "C": "Là người dân của một dân tộc bị áp bức", "D": "Là một người yêu nước, thương dân"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1480, 'Các đáp án sau đây viết về xã hội Việt Nam cuối thế kỷ XIX đầu thế kỷ XX. Tìm đáp án nhầm lẫn?', 'SINGLE_CHOICE', '{"A": "Xã hội Việt Nam có nhiều biến động: chính quyền triều Nguyễn đã từng bước khuất phục trước sự xâm lược của thực dân Pháp", "B": "Nhiều quốc gia độc lập đã trở thành thuộc địa của thực dân Pháp", "C": "Tư tưởng mang ý thức hệ phong kiến của những người lãnh đạo phong trào cách mạng đã lỗi thời", "D": "Cách mạng Việt Nam khủng hoảng về đường lối cứu nước"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1481, 'Trong bài “Con đường dẫn tôi đến với chủ nghĩa Lênin” điều Nguyễn Ái Quốc muốn nghe thảo luận hơn cả là điều gì?', 'SINGLE_CHOICE', '{"A": "Thảo luận về chiến tranh thế giới thứ nhất", "B": "Thảo luận Cách mạng vô sản", "C": "Thảo luận quốc tế nào bênh vực nhân dân các nước thuộc địa", "D": "Thảo luận vận mệnh của giai cấp công nhân."}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1482, 'Theo bạn thì học chủ nghĩa Mác theo cách nào là đúng?', 'SINGLE_CHOICE', '{"A": "Học chủ nghĩa Mác là học tập cái tinh thần xử trí mọi việc, đối với mọi người và đối với bản thân mình", "B": "Học thuộc lòng một số sách vở của chủ nghĩa Mác - Lênin", "C": "Học lý luận của Mác về đấu tranh giai cấp thì mình cũng phải ra khẩu hiệu giai cấp tranh đấu", "D": "Học chủ nghĩa Mác - Lênin để tìm ra những kết luận có sẵn cho con đường giải phóng dân tộc"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1483, 'Nguyễn Ái Quốc đã tiếp nhận được giá trị tinh thần từ nền văn hóa phương Tây? Tìm đáp án không đúng?', 'SINGLE_CHOICE', '{"A": "Tư tưởng về xây dựng Nhà nước Pháp quyền của dân, do dân và vì dân", "B": "Tư tưởng tự do, bình đẳng, bác ái trong bản Tuyên ngôn Nhân quyền và Dân quyền của cách mạng Pháp 1791", "C": "Tiếp thu giá trị của tưởng nhân quyền được ghi trong Tuyên ngôn độc lập của nước Mỹ 1776", "D": "Học thuyết “Tam dân” của Tôn Trung Sơn"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1484, 'Phát hiện một luận điểm nhầm lẫn trong các câu viết sau đây?', 'SINGLE_CHOICE', '{"A": "Nguyễn ái Quốc đến với chủ nghĩa Mác - Lênin theo phương pháp nhận thức mác xít, đồng thời theo lối “đắc ý, vong ngôn''ơ", "B": "Nguyễn Ái Quốc đến với chủ nghĩa Mác - Lênin để đáp ứng nhu cầu nhận thức của mình", "C": "Trong 10 năm (1911-1920) của quá trình tìm đường cứu nước, Nguyễn Ái Quốc đã hoàn thiện cho bản thân mình bản lĩnh tư duy độc lập, tự chủ, sáng tạo, nhờ đó khi tiếp thu chủ nghĩa Mác và vận dụng chủ nghĩa Mác - Lênin không rơi vào giáo điều sao chép", "D": "Khi đến với Chủ nghĩa Mác- Lênin, Nguyễn Ái Quốc đã có một học vấn chắc chắn, năng lực trí tuệ sắc sảo"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1485, 'Nhân tố nào sau đây thuộc về phẩm chất trí tuệ đặc sắc nhất làm tiền đề cho Nguyễn ái Quốc trở thành nhà tư tưởng?', 'SINGLE_CHOICE', '{"A": "Sự khổ công học tập, tinh thần nhẫn nại quyết tâm theo đuổi mục tiêu", "B": "Tư duy độc lập, tự chủ sáng tạo, với đầu óc phê phán tinh tường, sáng suốt trong nghiên cứu lý luận và tổng kết lý luận, thực tiễn", "C": "Tình cảm mãnh liệt của một con người suốt đời yêu nước thương dân", "D": "Ý chí rất cao của một chiến sĩ cộng sản nhiệt thành cách mạng"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1486, 'Nhân tố nào sau đây là phẩm chất căn bản xuyên suốt cuộc đời hoạt động của Nguyễn Tất Thành- Nguyễn Ái Quốc- Hồ Chí Minh?', 'SINGLE_CHOICE', '{"A": "Sự khổ công học tập, tinh thần nhẫn nại quyết tâm theo đuổi mục tiêu", "B": "Tư duy độc lập, tự chủ sáng tạo, với đầu óc phê phán tinh tường, sáng suốt trong nghiên cứu lý luận và tổng kết lý luận, thực tiễn", "C": "Tình cảm mãnh liệt của một con người suốt đời yêu nước thương dân", "D": "Ý chí rất cao của một chiến sĩ cộng sản nhiệt thành cách mạng"}', 'A', '', 48);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1487, '“Một trong những nguồn gốc của tư tưởng Hồ Chí Minh là tiếp thu văn hóa phương Đông”. Tìm luận điểm viết nhầm?', 'SINGLE_CHOICE', '{"A": "Tiếp thu những mặt tích cực của Nho giáo", "B": "Kế thừa các giá trị văn hóa tiến bộ của thời kỳ Phục hưng", "C": "Tiếp thu chủ nghĩa Tam dân của Tôn Trung Sơn", "D": "Tiếp thu tư tưởng vị tha của Phật Giáo"}', 'A', '', 48);
INSERT INTO exams (id, title, subject, duration, description, created_at) VALUES 
(49, 'Thi thử trắc nghiệm ôn tập môn Tư tưởng Hồ Chí Minh online - Đề #30', 'Tư tưởng Hồ Chí Minh', 25, 'Đề thi trắc nghiệm online ôn tập kiểm tra môn Tư tưởng Hồ Chí Minh. Làm bài trực tuyến có chấm điểm và lời giải chi tiết.', CURRENT_TIMESTAMP());
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1488, 'Chọn cụm từ đúng điền vào chỗ trống: "Việt Nam muốn làm bạn với ..., không gây thù oán với một ai".', 'SINGLE_CHOICE', '{"A": "Các nước xã hội chủ nghĩa", "B": "Các dân tộc thuộc địa, bị áp bức", "C": "Mọi nước dân chủ", "D": ""}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1489, 'Chọn cụm từ đúng điền vào chỗ trống: "Toàn quốc đồng bào hãy đứng dậy.... mà tự giải phóng cho ta".', 'SINGLE_CHOICE', '{"A": "dựa vào sự giúp đỡ quốc tế", "B": "dựa vào sự đoàn kết toàn dân", "C": "dưới sự lãnh đạo của Đảng", "D": "đem sức ta"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1490, 'Hội nghị BCH Trung ương Đảng lần thứ 8, họp 5-1941 do Nguyễn Aí Quốc chủ tọa, có mặt những ai?', 'SINGLE_CHOICE', '{"A": "Tr­ường Chinh, Hoàng Văn Thụ", "B": "Nguyễn Văn Cừ, Phan Đăng Lưu", "C": "Lê Hồng Phong, Lê Hồng Sơn", "D": "Hồ Tùng Mậu, Nguyễn Lương Bằng"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1491, '“Trong lúc này, quyền lợi của dân tộc là cao hơn hết thảy”. Đó là khẳng định của Hội nghị Trương ương nào?', 'SINGLE_CHOICE', '{"A": "Hội nghị TW6 (l l/1939)", "B": "Hội nghị TW8 (5/1941)", "C": "Hội nghị TW7 (l l/1940)", "D": "Hội nghị toàn quốc của Đảng (8/1945)"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1492, 'Theo đề nghị của Nguyễn Ái Quốc, mặt trận dân tộc thống nhất Việt Nam được lấy tên là "Việt Nam độc lập đồng minh", gọi tắt là "Việt Minh". Mặt trận Việt Minh đ­ược thành lập khi nào?', 'SINGLE_CHOICE', '{"A": "19-5-1941", "B": "20-5-1941", "C": "25-10-1941", "D": "17-10-1942"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1493, 'Chọn phương án trả lời đúng với tư tưởng Hồ Chí Minh.', 'SINGLE_CHOICE', '{"A": "Cách mạng giải phóng dân tộc giành thắng lợi đồng thời với thắng lợi cách mạng vô sản ở chính quốc.", "B": "Thắng lợi của cách mạng vô sản ở thuộc địa phải phụ thuộc vào thắng lợi của cách mạng vô sản ở chính quốc.", "C": "Cách mạng giải phóng dân tộc ở thuộc địa có khả năng giành được thắng lợi trước cách mạng vô sản ở chính quốc.", "D": ""}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1494, 'Chọn cụm từ đúng điền vào dấu....Tháng 7 năm 1920, Hồ Chí Minh đọc ... của V.I. Lênin.', 'SINGLE_CHOICE', '{"A": "Tác phẩm \"Làm gì\"", "B": "Sơ thảo lần thứ nhất Luận cương về các vấn đề dân tộc", "C": "Sơ thảo lần thứ nhất Luận cương về các vấn đề dân tộc và vấn đề thuộc địa", "D": ""}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1495, 'Nguyễn Ái Quốc lấy tên mới là Hồ Chí Minh lên đ­ường đi Trung Quốc để liên lạc với các lực lư­ợng đồng minh chống chiến tranh phát xít từ lúc nào?', 'SINGLE_CHOICE', '{"A": "5/1941", "B": "8/1942", "C": "5/1943", "D": "8/1943"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1496, 'Hồ Chí Minh bị chính quyền Quốc dân Đảng Trung Hoa bắt và giam giữ trong thời gian nào?', 'SINGLE_CHOICE', '{"A": "8/1942 - 1/1943", "B": "8/1942 - 6/1943", "C": "8/1942 - 9/1943", "D": "8/1942 - 8/1944"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1497, 'Trong thời gian hơn một năm, chính quyền Tưởng Gới Thạch đã giải Hồ Chí Minh qua mấy nhà tù ở 13 huyện thuộc tỉnh Quảng Tây (Trung quốc)?', 'SINGLE_CHOICE', '{"A": "20 nhà tù", "B": "30 nhà tù", "C": "35 nhà tù", "D": "40 nhà tù"}', 'A', '', 49);
