(1498, 'Thời gian bị giam giữ trong các nhà tù ở Quảng Tây, Hồ Chí Minh đã viết tập thơ "Nhật ký trong tù''. Tập thơ đó có bao nhiêu bài?', 'SINGLE_CHOICE', '{"A": "34 bài", "B": "134 bài", "C": "234 bài.", "D": "334 bài"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1499, 'Bài thơ: "Gạo đem vào giã bao đau đớn; Gạo giã xong rồi, trắng tựa bông. Sống ở trên đời ngư­ời cũng vậy; Gian nan rèn luyện mới thành công" ở trong tác phẩm nào của Hồ Chí Minh?', 'SINGLE_CHOICE', '{"A": "\"Ca binh lính\"", "B": "\"Nhật ký trong tù''\"", "C": "\"Bài ca du kích\"", "D": "\"Ca sợi chỉ\"."}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1500, 'Ra khỏi nhà tù của Tưởng Giới Thạch, Hồ Chí Minh ở tại Trung Quốc tham gia một số hoạt động của Việt Nam Cách mạng đồng minh hội. Từ khi nào Hồ Chí Minh về Việt Nam:', 'SINGLE_CHOICE', '{"A": "Tháng 9/1944", "B": "Tháng 4/1944", "C": "Tháng 7/1944", "D": "Tháng 2/1944"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1501, '“Cơ hội cho dân ta giải phóng ở trong một năm hoặc năm r­ươĩ nữa. Thời gian rất gấp. Ta phải làm nhanh". Câu đó được Hồ Chí Minh nói vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "Tháng 10/1941", "B": "Tháng 10/1943", "C": "Tháng 10/1942", "D": "Tháng 10/1944"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1502, 'Tháng 12/1944, Hồ Chí Minh triệu tập một số cán bộ về Pác Bó để phổ biến chủ trư­ơng thành lập Quân giải phóng. Ai là ng­ười đã đ­ựơc Hồ Chí Minh chỉ định đảm nhiệm công tác này?', 'SINGLE_CHOICE', '{"A": "Vũ Anh", "B": "Hoàng Văn Thái", "C": "Võ Nguyên Giáp", "D": "Phùng Chí Kiên."}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1503, 'Đội Việt Nam tuyên truyền giải phóng quân đ­ược thành lập lúc nào?', 'SINGLE_CHOICE', '{"A": "20/12/1944", "B": "22/12/1944", "C": "30/12/1944", "D": "15/5/1945"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1504, 'Hồ Chí Minh lấy bí danh là Ông Ké từ khi nào?', 'SINGLE_CHOICE', '{"A": "Năm 1943", "B": "Năm 1944", "C": "Năm 1945", "D": "Năm 1946"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1505, 'Hồ Chí Minh bắt đầu cuộc hành trình rời Pắc bó về Tân Trào vào ngày tháng năm nào?', 'SINGLE_CHOICE', '{"A": "Ngày 4/5/1942", "B": "Ngày 4/5/1944", "C": "Ngày 4/5/1943", "D": "Ngày 4/5/1945"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1506, 'Cuộc hành trình từ Pắc bó về Tân Trào của Hồ Chí Minh và đoàn cán bộ kéo dài từ:', 'SINGLE_CHOICE', '{"A": "Ngày 4/5/1945- 21/5/1945", "B": "Ngày 4/5/1945- 19/8/1945", "C": "Ngày 4/5/1945- 13/8/1945", "D": "Ngày 4/5/1945- 30/8/1945"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1507, 'Hồ Chí Minh, Ban thường vụ TW Đảng và Tổng bộ Việt Minh đã thành lập Uỷ ban khởi nghĩa toàn quốc vào ngày tháng năm nào?', 'SINGLE_CHOICE', '{"A": "9/3/1945", "B": "13/8/1945", "C": "19/8/1945", "D": "28/8/1945"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1508, '“Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta". Lời kêu gọi đó của Hồ Chí Minh là vào thời gian nào?', 'SINGLE_CHOICE', '{"A": "5/1941", "B": "8/1945", "C": "9/1945", "D": "12/1946"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1509, 'Chủ tịch Hồ Chí Minh&nbsp; bắt đầu rời Tân Trào về Hà Nội khi nào?', 'SINGLE_CHOICE', '{"A": "Ngày 13/8/1945", "B": "Ngày 15/8/1945", "C": "Ngày 22/8/1945", "D": "Ngày 30/8/1945"}', 'A', '', 49);
INSERT INTO questions (id, question_text, question_type, options_json, correct_answer, explanation, exam_id) VALUES 
(1510, '"Phê bình mình cũng như phê bình người phải ráo riết, triệt để, thật thà, không nể nang, không thêm bớt. Phải vạch rõ ưu điểm và khuyết điểm. Đồng thời, chớ dùng những lời mỉa mai, chua cay, đâm thọC. Phê bình việc làm, chứ không phải phê bình người”. Câu nói trên của Hồ Chí Minh chỉ cho chúng ta biết điều gì:&nbsp;', 'SINGLE_CHOICE', '{"A": "Cách thức tự phê bình và phê bình", "B": "Mục đích tự phê bình và phê bình", "C": "Điều kiện để đoàn kết và thống nhất", "D": "Tất cả các đều trên"}', 'A', '', 49);
